\section{Competitiveness of \mru}\labelsec{nmru}

\mruexample 


\begin{restatable}[Block-Hit and Block-Miss Competitiveness: $\mru(k)$ vs $\lru(2)$]{theo}{blockhitmisslrutwo}\labelthm{blockhitmisslrutwo}
	For all $k \geq 2$, $\mru(k)$ is $(1, 0)$-block-hit- and block-miss-competitive relative to $\lru(2)$.
\end{restatable}
\begin{proof}
	It suffices to show that $\mru(k)$ always contains the two most-recently-used blocks, once two blocks have been accessed.
	As these are the only blocks that can be in $\lru(2)$ states, any hit in $\lru(2)$ must also be a hit in $\mru(k)$ and the theorem follows.

	By construction, the \emph{use} bit of the most-recently-used block is always set in $\mru(k)$.
	Thus, the most-recently-used block cannot be replaced upon a miss. 
	As a consequence, the second-most-recently-used block must always be in the cache.
\end{proof}

\begin{restatable}[Hit and Miss Competitiveness: $\mru(k)$ vs $\lru(2)$]{cor}{hitmisslrutwo}\labelthm{hitmisslrutwo}
	For all $k \geq 2$, $\mru(k)$ is $(1, 0)$-hit- and miss-competitive relative to $\lru(2)$.
\end{restatable}
This follows immediately from \refthm{blockhitmisslrutwo} and \reflem{blockhittohit}.


\begin{restatable}[Block-Miss Competitiveness: $\mru(k)$ vs $\lru(l)$]{theo}{blockmissmrulru}\labelthm{blockmissmrulru}
	For all $k \geq l \geq 3$, $\mru(k)$ is $(l, 0)$-block-miss-competitive relative to $\lru(l)$.
	\end{restatable}
	\begin{proof}
	Let $\sigma \in \accessSequences$ be an arbitrary access sequence, $b \in \memoryBlocks$ be an arbitrary memory block, and $p \in \cacheSetStates{\mru(k)}$ be an arbitrary state of $\mru(k)$.
	We need to show that $\misses{\mru(k),b}(p,\sigma) \leq l \cdot \misses{\lru(l),b}(\initialState{\lru(l)},\sigma)$.

	Assume $\sigma$ incurs $n$ misses to block $b$ in $\lru(l)$, \ie, $\misses{\lru(l),b}(p,\sigma) = n$.
	Then, we can partition $\sigma$ into $n+1$ subsequences $\sigma_{pre}, \sigma_1, \dots, \sigma_n$, where each $\sigma_i$ begins with the access that causes the $i^{th}$ miss to $b$ and ends right before $\sigma_{i+1}$ begins or the entire sequence ends. $\sigma_{pre}$ contains the initial accesses in $\sigma$ before the first miss to $b$, and may thus be empty.

	As $\initialState{\lru(l)}$ does not contain $b$, the first access to $b$ in $\sigma$ must cause a miss.
	Thus, $\sigma_{pre}$ cannot contain any accesses to $b$.
	So there can also not be any misses to $b$ in $\sigma_{pre}$ in $\mru(k)$.

	We argue that at most $l$ misses may happen in each subsequence $\sigma_i$ in $\mru(k)$, which implies that $\misses{\mru(k),b}(p,\sigma) \leq l \cdot n = l\cdot \misses{\lru(l),b}(\initialState{\lru(l)},\sigma)$

	To get an intuition for why there can be at most $l$ misses in each subsequence $\sigma_i$ consider \reffig{mruexample}.
	Here, block $b$ is repeatedly accessed with up to three distinct blocks in between.
	After the first miss, $b$ is in position $0$.
	After the first global bit flip, $b$ gets replaced before it is accessed again.
	Thus the next access to $b$ must be a miss, but it will be inserted at a greater position than before, as all the bits to the left of $b$'s previous position have been set.
	Eventually, $b$ will be in position $l-1$ or greater, and no more misses to $b$ can happen, because $b$ must be accessed before the $l-1$ bits to its left could have been flipped, as no additional misses to $b$ occur in $\lru(l)$.

	Let $a_{i,j}$ be the position of $b$ in $\mru(k)$ after the $j^{th}$ miss to $b$ in $\sigma_i$.
	If $a_{i,j} \geq l-1$, then no more misses to $b$ are possible within $\sigma_i$:
	As no additional misses to $b$ occur for $\lru(l)$ within~$\sigma_i$, at most $l-1$ distinct other blocks are accessed between any two accesses to $b$.
	This implies in particular that at most $l-1$ distinct other blocks are accessed after each global bit flip (including the access that causes the global bit flip) before the next access to $b$.
	Each of these accesses flips at most one of the $l-1$ bits left of $b$. 
	Thus, $b$'s bit is flipped to $1$ before it can be replaced by a miss.

	Assume that $a_{i,j} < l-1$.
	Then, we argue below that $a_{i, j+1} \geq a_{i, j}+1$.
	As a consequence, $a_{i, j} \geq j-1$ and so $a_{i, l} \geq l-1$. Thus, at most $l$ misses may occur.

	For a $(j+1)^{st}$ miss to $b$ to occur, $b$ must be replaced following its insertion at position $a_{i, j}$ upon the $j^{th}$ miss.
	As $l \leq k$, there cannot be two global bit flip between two accesses to $b$.
	If $b$ has been evicted from position $a_{i, j}$, and no additional global bit flip has happened since $b$'s eviction, then the bits of all positions before must be set.
	Thus, $b$ will be inserted $a_{i, j+1} > a_{i, j}$.\looseness=-1
	\end{proof}

	\refthm{blockmissmrulru} is strongly related to and inspired by \cite[Theorem IV.3]{Guan12}, which bounds the number of misses of \mru on accesses to a block in a strongly-connected component of the CFG, where consecutive accesses to the block are separated by at most $l-1$ distinct blocks.
	Theorem IV.3 in \cite{Guan12} can be derived from \refthm{blockmissmrulru} and the fact that such a block is persistent in $\lru(l)$, splitting the argument into a workload-independent and a workload-dependent aspect.

	Sometimes the following miss-competitiveness result may provide better guarantees than \refthm{blockmissmrulru}:
	\begin{restatable}[Miss Competitiveness: $\mru(k)$ vs $\lru(l)$]{theo}{missmrulru}\labelthm{missmrulru}
	For all $k \geq l \geq 2$, $\mru(k)$ is $\left(\frac{k-1}{k-l+1}, l-2\right)$-miss-competitive relative to $\lru(l)$.
	\end{restatable}
\begin{proof}	
	First, note that at a global bit flip, $\mru(k)$ contains the $k$ most-recently accessed blocks:
	Between any two global bit flips in $\mru(k)$, exactly $k-1$ distinct blocks are accessed: 
	The first access to each of these distinct blocks increases the number of set bits by one; initially, one bit is set. 
	A global bit flip occurs when the $k$-th bit is set.

	Also, between any two consecutive global bit flips, no block that has been accessed after the first global bit flip can be evicted before the second global bit flip as its use bit remains set. 
	Thus, at a global bit flip, $\mru(k)$ contains all blocks that have been accessed since the last global bit flip.

	Let $\sigma \in \accessSequences$ be an arbitrary access sequence, $b \in \memoryBlocks$ be an arbitrary memory block, and $p \in \cacheSetStates{\mru(k)}$ be an arbitrary states of $\mru(k)$.
	We need to show that $\misses{\mru(k)}(p,\sigma) \leq \frac{k-1}{k-l+1} \cdot \misses{\lru(l)}(\initialState{\lru(l)},\sigma) + l-2$.

	We partition $\sigma$ along the global bit flips.
	Assume $\sigma$ results in $m$ global bit flips starting from $p$.
	Then we partition $\sigma$ into $m+1$ subsequences $\sigma_1, \dots, \sigma_m, \sigma_{post}$, where each $\sigma_i$ ends with the access that causes the $i^{th}$ global bit flip and $\sigma_{post}$ contains the accesses following the final global bit flip.
	By construction, $\sigma_{post}$ may be empty.

	Let $n_i$ be the number of misses to block $b$ in $\mru(k)$ in $\sigma_i$ and let $l_i$ be the number of misses to $b$ in $\lru(l)$ in $\sigma_i$.

	We will show that 
	\begin{enumerate}
		\item[a)] $n_i \leq \frac{k-1}{k-l+1}\cdot l_i$ for all $i$, and
		\item[b)] $n_{post} \leq l_{post} + l-2$.
	\end{enumerate}
	Then, the theorem follows from the fact that 
	\begin{align*}\small
	\misses{\mru(k)}(p, \sigma) &= \left(\sum_{i=1}^{m} n_i\right) + n_{post} \\ &\leq  \left(\sum_{i=1}^{m} \frac{k-1}{k-l+1} \cdot l_i\right) + l_{post} + l-2 \\
	&\leq \frac{k-1}{k-l+1} \cdot \left(\sum_{i=1}^{m} l_i + l_{post}\right) + l-2 \\ &= \frac{k-1}{k-l+1} \cdot \misses{\lru(l)}(\initialState{\lru(l)},\sigma) + l-2.
	\end{align*}

	a) Let us now show that $n_i \leq \frac{k-1}{k-l+1}\cdot l_i$ for all $i$.

	We first consider the case that $i > 1$.	
	Exactly $k-1$ distinct blocks get accessed in subsequence~$\sigma_i$ for $i > 1$.
	As each block accessed in a subsequence misses at most once in $\mru(k)$, the number of misses $n_i$ in $\mru(k)$ is at most $k-1$.

	At the global bit flip, $\lru(l)$ contains the most-recently-used block, which causes the global bit flip, and which is not part of these $k-1$ distinct blocks.
	Thus, at most $l-1$ of these blocks may hit on their first access in $\sigma_i$ in $\lru(l)$.
	Thus, at least $k-1-(l-1) = k-l$ misses will happen in $\lru(l)$.

	We distinguish two cases:
	\begin{enumerate}
		\item $l_i \geq k-l+1$.
		\item $l_i = k-l$.
	\end{enumerate}
	In the first case, $n_i \leq k-1 \leq \frac{k-1}{k-l+1} \cdot l_i$.

	In the second case, $\sigma_i$ must contains hits to all of the contents of $\lru(l)$ at the global bit flip. 
	In particular, it must hit the least-recently-used block. 
	Thus, no miss may occur in \lru before accessing the least-recently-used block. 
	As $\mru(k)$ contains all the blocks of $\lru(l)$ at the global bit flip, the access that hits the \lru block must also hit in \mru. 
	Thus, \mru may have at most $k-2$ misses and so $n_i \leq k-2 \leq \frac{k-2}{k-l}  \cdot l_i \leq \frac{k-1}{k-l+1} \cdot l_i$.

	We now consider the case that $i=1$.
	The first subsequence $\sigma_1$ is special as it starts with the empty initial state of $\lru(l)$.
	The first accesses to all blocks in $\sigma_i$ miss in $\lru(l)$.
	Each of these blocks misses at most once in $\mru(k)$.
	Thus, $n_1 \leq l_1$.

	b) Let us now show that $n_{post} \leq l_{post} + l-2$.
	   Let $d$ be the number of distinct blocks accessed in $\sigma_{post}$.
	   At most $d$ misses may happen in $\mru(k)$.
	   As argued above, at most $l-1$ of these blocks may hit in $\lru(l)$ and thus at least $d-(l-1)$ misses must happen in $\lru(l)$.
	   We again distinguish two cases:\looseness=-1
	   \begin{enumerate}
	   	\item $l_{post} \geq d-(l-1)+1 = d-l+2$.
	   	\item $l_{post} = d-(l-1)= d-l+1$.
	   \end{enumerate} 
	   In the first case, $n_{post} \leq d \leq l_{post} + l-2$.

	   In the second case, $\sigma_{post}$ must contain hits to all of the contents of $\lru(l)$ at the global bit flip.
	   By the same reasoning as above we must then have $n_{post} \leq d-1 \leq l_{post} + l-2$.
\end{proof}

	\begin{restatable}[Block-Hit Competitiveness: $\mru(k)$ vs $\lru(l)$]{theo}{blockhitmrulru}\labelthm{blockhitmrulru}
	For all $k \geq l \geq 3$, $\mru(k)$ is not $(r, c)$-block-hit-competitive relative to $\lru(l)$ for any $r > 0$ and any~$c$.%
	\end{restatable}
	\begin{proof}
		For any state $p \in \cacheSetStates{\mru(k)}$, any block~$b$, and any number of hits~$h$, we show below how to construct a sequence $\sigma_h$, such that $\hits{\mru(k),b}(p, \sigma_h) = 0$ and $\hits{\lru(l),b}(\initialState{\lru(l)}, \sigma_h) \geq h$.\looseness=-1

		Let $r > 0$ and $c$ be arbitrary.
		Pick $h > c/r$.
		Then $\hits{\mru(k),b}(p, \sigma_h) < r \cdot \hits{\lru(l),b}(\initialState{\lru(l)}, \sigma_h) - c$, which proves the theorem.

		Let $q \in \cacheSetStates{\mru(k)}$ be arbitrary.
		Below we show how to construct a sequence $\sigma(q)$, such that $\hits{\mru(k),b}(q, \sigma(q)) = 0$ and $\hits{\lru(l),b}(\initialState{\lru(l)}, \sigma(q)) = 1$.

		We can then use this construction to build $\sigma_h$ as follows:
		\begin{itemize}
			\item $\sigma_1 = \sigma(p)$.
			\item $\sigma_{n+1} = \sigma_n \circ \sigma(q)$, where $q = \update{\mru(k)}(p, \sigma_n)$.
		\end{itemize}


		Let us now show how to construct $\sigma(q)$.

		Let $\rho = \seq{a_1, a_2, a_3, \dots}$ be an infinite sequence of ``fresh'' memory blocks, \ie, blocks not contained in state~$q$ and distinct from each other and from $b$.

		Accessing any prefix of $\rho$ from state~$q$ will result in a sequence of misses, which will cause a sequence of global bit flips.
		Eventually, a global bit flip will happen at position $k-1$.
		Pick $\sigma_{pre}$ as the shortest prefix of $\rho$ that causes a global bit flip at position $k-1$.

		Let $q'$ be the result of accessing $\sigma_{pre}$ in state $q$, \ie, $q'=\update{\mru(k)}(q,\sigma_{pre}) = \cachestatelong{a_i}0{a_{i+1}}0{a_{i+2}}0{a_{i+k-1}}1$.

			Accessing $\sigma_{mid} = \seq{a_{i+2}, \dots, a_{i+k-2}}$ in $q'$ will flip all but the first two use bits:\\
			$q'' = \update{\mru(k)}(q', \sigma_{mid}) = \cachestatelong{a_i}0{a_{i+1}}0{a_{i+2}}1{a_{i+k-1}}1$.

			Accessing $\seq{b, a_{i+1}, a_{i}}$ in $q''$ results in a miss to $b$, a hit to $a_{i+1}$ that causes a global bit flip, and a miss to $a_i$ that replaces $b$.
		Let $\sigma(q) = \sigma_{pre} \cdot \sigma_{mid} \cdot \seq{b, a_{i+1}, a_{i}, b}$.
			By construction $\hits{\mru(k),b}(q, \sigma(q)) = 0$ and $\hits{\lru(l),b}(\initialState{\lru(l)}, \sigma(q)) = 1$ as the second access to $b$ is a hit in $\lru(l)$ for $l \geq 3$.
	\end{proof}


	While \refthm{blockhitmrulru} shows that $\mru(k)$ is not \emph{block}-hit-competitive relative to $\lru(l)$ for any $l \geq 3$, we can show that $\mru(k)$ is hit-competitive relative to $\lru(l)$ for $k \geq 2l$:

	\begin{restatable}[Hit Competitiveness: $\mru(k)$ vs $\lru(l)$]{theo}{hitmrulru}\labelthm{hitmrulru}
	For all $k \geq 2l$, $\mru(k)$ is $\left(1-\frac{1}{\lceil\frac{k}{2l}\rceil}, (1-\frac{1}{\lceil\frac{k}{2l}\rceil})\cdot(l-1)\right)$-hit-competitive relative to $\lru(l)$.%
	\end{restatable}
	\vspace{-1mm}

