Given a set of memory blocks $B$, let $\hitsBoth{i}(B)$ be the set of accesses to blocks in $B$ that hit under both policies in phase~$i$.
We similarly define the restrictions of $\hitsLRU{i}$ and $\hitsNMRU{i}$ to $B$ as $\hitsLRU{i}(B)$ and $\hitsNMRU{i}(B)$, respectively.
The set of memory blocks accessed by the accesses in $\hitsLRU{i}$ and $\hitsNMRU{i}$ is denoted as $\blocksLRU{i}$ and $\blocksNMRU{i}$, respectively.

We denote the number of hits under both policies to blocks in $B$ in phase~$i$ as $\nhitsBoth{i}(B) = |\hitsBoth{i}(B)|$, the number of hits under $\lru(l)$ but not under $\mru(k)$ as $\nhitsLRU{i}(B) = |\hitsLRU{i}(B)|$, and the number of hits under $\mru(k)$ but not under $\lru(l)$ as $\nhitsNMRU{i}(B) = |\hitsNMRU{i}(B)|$.

The following lemma shows that if we can bound the number of exclusive LRU hits in phase $i+1$ in a certain way by the number of \mru hits in phase $i$, then this implies hit competitiveness of \mru relative to \lru.

\begin{restatable}[Hit Competitiveness: $\mru(k)$ vs $\lru(l)$]{lem}{hitcomp}\labellem{hitmrulru}
	Let~$\sigma$ be an arbitrary access sequence, $p \in \cacheSetStates{\mru(k)}$ be an arbitrary state of $\mru(k)$, and let $\nhitsBoth{i}(B), \nhitsLRU{i}(B), \nhitsNMRU{i}(B)$ be defined as above for any set of blocks $B$. 

	If
	\begin{align}
		\forall i \geq 1: \exists B_i, \overline{B_i}: \notag\\
		B_i \cup \overline{B_i} &= \blocksLRU{i+1}~\wedge\label{boundzero}\\
		\nhitsNMRU{i} &\geq \nhitsLRU{i+1}(B_i)~\wedge\label{boundone}\\
		\nhitsBoth{i} + \nhitsNMRU{i} &\geq x\cdot\nhitsLRU{i+1}(\overline{B_i})\label{boundtwo}
	\end{align}
	then
	\begin{eqnarray}
		\hits{\mru(k)}(p,\sigma) \geq \notag\\&\hspace{-1cm} \left(1-\frac{1}{x+1}\right)\cdot\left(\hits{\lru(l)}(\initialState{\lru(l)},\sigma) - (l-1)\right)\notag
	\end{eqnarray}
\end{restatable}
The proof of this lemma and the proof of \refthm{hitmrulru} can be found in \ifthenelse{\isundefined\istechreport}{the technical report~\cite{Kahlen2025arxiv}}{the appendix}.

