\section{Proofs}

\equivonehit*
\begin{proof}
	To show that 1) and 2) are equivalent, note that
	the number of accesses~$\maccesses{P,b}(p, \sigma)$ to a block $b$ is the sum of the number of hits and misses to $b$:
	$\maccesses{P,b}(p, \sigma) = \hits{P,b}(p, \sigma) + \misses{P,b}(p, \sigma)$.
	Also, the number of accesses to $b$ is the same for $P$ and $Q$ and independent of the initial state:
	$\maccesses{P,b}(p, \sigma) = \maccesses{Q,b}(\initialState{Q}, \sigma)$.
	Thus, 1) implies 2) as
	\begin{eqnarray*}
		\misses{P,b}(p, \sigma) &=& \maccesses{P,b}(p, \sigma) - \hits{P,b}(p, \sigma) \\
		&=& \maccesses{Q,b}(\initialState{Q}, \sigma) - \hits{P,b}(p, \sigma) \\
		&\overset{1)}{\leq}& \maccesses{Q,b}(\initialState{Q}, \sigma) - \hits{Q,b}(\initialState{Q}, \sigma) \\
		&=& \misses{Q,b}(\initialState{Q}, \sigma).
	\end{eqnarray*}
	2) implies 1) analogously:
	\begin{eqnarray*}
		\hits{P,b}(p, \sigma) &=& \maccesses{P,b}(p, \sigma) - \misses{P,b}(p, \sigma) \\
		&=& \maccesses{Q,b}(\initialState{Q}, \sigma) - \misses{P,b}(p, \sigma) \\
		&\overset{2)}{\geq}& \maccesses{Q,b}(\initialState{Q}, \sigma) - \misses{Q,b}(\initialState{Q}, \sigma) \\
		&=& \hits{Q,b}(\initialState{Q}, \sigma).
	\end{eqnarray*}
	3) and 4) can be shown to be equivalent analogously.


\end{proof}


\hitcomp*
\begin{proof}
\begin{eqnarray*}
	\hits{\lru(l)}(\initialState{\lru(l)},\sigma)  &=&  \left(\sum_{i \geq 0} \nhitsBoth{i} + \nhitsLRU{i}\right) \\
	&=& \nhitsBoth{0} + \nhitsLRU{0} + \nhitsBoth{1} + \nhitsLRU{1} + \left(\sum_{i \geq 2} \nhitsBoth{i} + \nhitsLRU{i}\right) \\
	&\overset{\nhitsLRU{0} = 0}{=}& \nhitsBoth{0} + \nhitsBoth{1} + \nhitsLRU{1} + \left(\sum_{i \geq 2} \nhitsBoth{i} + \nhitsLRU{i}\right) \\
	&\overset{\nhitsLRU{1} \leq l-1}{\leq}& \nhitsBoth{0} + \nhitsBoth{1} + (l-1) + \left(\sum_{i \geq 2} \nhitsBoth{i} + \nhitsLRU{i}\right) \\
	&=& \nhitsBoth{0} + \nhitsBoth{1} + (l-1) + \left(\sum_{i \geq 2} \nhitsBoth{i} + \nhitsLRU{i}(B_{i-1}) + \nhitsLRU{i}(\overline{B_{i-1}})\right) \\
	&\overset{(\ref{boundone})+(\ref{boundtwo})}{\leq}& \nhitsBoth{0} + \nhitsBoth{1} + (l-1) + \left(\sum_{i \geq 2} \nhitsBoth{i} + \nhitsNMRU{i-1} + \frac{1}{x}(\nhitsBoth{i-1} + \nhitsNMRU{i-1})\right) \\
	&=& \left(\sum_{i \geq 0} \nhitsBoth{i}\right) + (l-1) + \left(\sum_{i \geq 1} \nhitsNMRU{i}\right) + \left(\frac{1}{x}\sum_{i \geq 1}\nhitsBoth{i} + \nhitsNMRU{i}\right) \\
	& \leq&\left(\sum_{i \geq 0} \nhitsBoth{i}\right) + (l-1) + \left(\sum_{i \geq 1} \nhitsNMRU{i}\right) + \left(\frac{1}{x}\sum_{i \geq 1}\nhitsBoth{i}+\nhitsNMRU{i}\right) \\
	&\leq& \left(\sum_{i \geq 0} \nhitsBoth{i} + \nhitsNMRU{i}\right) + \frac{1}{x}\left(\sum_{i \geq 0}\nhitsBoth{i} + \nhitsNMRU{i}\right) + (l-1)\\	&=& \left(1+\frac{1}{x}\right)\cdot\hits{\mru(k)}(p,\sigma) + (l-1)
\end{eqnarray*}
Thus we have
\begin{eqnarray*}
	\hits{\lru(l)}(\initialState{\lru(l)},\sigma) &\leq& \left(1+\frac{1}{x}\right)\cdot\hits{\mru(k)}(p,\sigma) + (l-1)\\
	\Leftrightarrow \frac{x+1}{x}\cdot\hits{\mru(k)}(p,\sigma) + (l-1) &\geq& \hits{\lru(l)}(\initialState{\lru(l)},\sigma)\\
	\Leftrightarrow \hits{\mru(k)}(p,\sigma) + (l-1) &\geq& \frac{x}{x+1}\left(\hits{\lru(l)}(\initialState{\lru(l)},\sigma) - (l-1)\right)\\
	\Leftrightarrow \hits{\mru(k)}(p,\sigma) + (l-1) &\geq& \left(1-\frac{1}{x+1}\right)\left(\hits{\lru(l)}(\initialState{\lru(l)},\sigma) - (l-1)\right)\\
\end{eqnarray*}
\end{proof}

Let us now prove \refthm{hitmrulru} using \reflem{hitmrulru}.
\hitmrulru*
\begin{proof}
Let $\sigma$ be an arbitrary access sequence, $p \in \cacheSetStates{\mru(k)}$ be an arbitrary state of $\mru(k)$.
To prove the theorem we apply \reflem{hitmrulru} with $x = \left\lceil\frac{k}{2l}\right\rceil-1$.
To apply \reflem{hitmrulru}, we need to find sets $B_i, \overline{B_i}$ that satisfy (\ref{boundzero}), (\ref{boundone}), and (\ref{boundtwo}).

Let $B_i = \blocksLRU{i+1} \cap \blocksNMRU{i}$ and $\overline{B_i} = \blocksLRU{i+1} \setminus \blocksNMRU{i}$.

By construction $B_i \cup \overline{B_i} = \blocksLRU{i+1}$ and so (\ref{boundzero}) is satisfied. 

Next we show that $B_i$ satisfies (\ref{boundone}) of \reflem{hitmrulru}:
Note that under \mru, a block can only cause one miss in a phase.
Thus any block may contribute at most one hit to the exclusive LRU hits in any phase.
On the other hand, every block in $B_i$ must contribute at least one exclusive $\mru$ hit in phase $i$.
Thus, $\nhitsLRU{i+1}(B_i) = |B_i| \leq \nhitsNMRU{i}(B_i) \leq \nhitsNMRU{i}$.

Now let us show that $\overline{B_i}$ satisfies (\ref{boundtwo}) of \reflem{hitmrulru} for $x=\lceil\frac{k}{2l}\rceil-1$.



\newcommand{\xphasei}{0.5}
\newcommand{\xphaseii}{4.5}
\newcommand{\xphaseiii}{8.5}

\begin{figure}
\begin{centering}
\begin{tikzpicture}
	\fill[red!20, opacity=0.5] (0, -0.8) rectangle (\xphasei, 1.1);
	\fill[blue!20, opacity=0.5] (\xphasei, -0.8) rectangle (\xphaseii, 1.1);
	\fill[green!20, opacity=0.5] (\xphaseii, -0.8) rectangle (\xphaseiii, 1.1);

	\draw[dashed, red] (\xphasei, -0.8) -- (\xphasei, 1.1) node[above, xshift=6.5mm,yshift=-5mm] {Phase $i$};
	\draw[dashed, blue] (\xphaseii, -0.8) -- (\xphaseii, 1.1) node[above, xshift=9.5mm,yshift=-5mm] {Phase $i+1$};

	\draw[->] (0, 0) -- (\xphaseiii, 0);

	\foreach \x in {2.5,8,6.3} {
		\draw (\x, 0.2) -- (\x, -0.2); %
	}

	\node[below] at (2.5, -0.1) {\strut$x$};
	\node[below] at (7.8, -0.1) {\strut$x$ miss};
	\node[below] at (6.3, -0.1) {\strut$x$ evicted};

	\node[above] at (1.5, 0) {$\sigma_{i, pre}$};
	\node[above] at (3.5, 0) {$\sigma_{i, post}$};
	\node[above] at (5.4, 0) {$\sigma_{i+1, pre_1}$};
	\node[above] at (7.15, 0) {$\sigma_{i+1, pre_2}$};

	\end{tikzpicture}
	\caption{Partition of phase $i$ and phase $i+1$.}\labelfig{mruphases}
\end{centering}
\end{figure}

Let $a$ be the minimum number of accesses to blocks in $\overline{B_i}$ in phase $i$.
As all but the first of these accesses must be hits in \mru, there must be $a-1$ hits for each block in $\overline{B_i}$.

Let $x$ be a block in $\overline{B_i}$ that is accessed exactly $a$ times in phase $i$.
Let $p$ be $x$'s position after the first access to $x$ in phase~$i$.
As illustrated in \reffig{mruphases}, we partition phase $i$ into two subsequences $\sigma_{i, pre}$ and $\sigma_{i, post}$, where $\sigma_{i, pre}$ contains ends before the first access to $x$ in phase $i$ and $\sigma_{i, post}$ contains the remaining accesses of the phase.
We further partition the accesses prior to the first access to $x$ in phase $i+1$ into $\sigma_{i+1, pre_1}$ and $\sigma_{i+1, pre_2}$, where $\sigma_{i+1, pre_1}$ contains the accesses in phase $i+1$ up to and including the access that evicts $x$ from the \mru cache.\looseness=-1

By assumption $x$ is accessed $a$ times in phase $i$.
Further, it cannot be accessed in phase $i+1$ before it is evicted, otherwise it would be protected from eviction in phase~$i+1$.
Thus, there are $a-1$ accesses to $x$ in $\sigma_{i, post}\circ \sigma_{i+1, pre_1}$.
As the first access to $x$ hits in \lru in phase $i+1$, at most $l-1$ distinct blocks may be accessed between any two accesses to $x$.
Thus, we can conclude that $|B(\sigma_{i, post}\circ \sigma_{i+1, pre_1}) \setminus \{x\}| \leq (a-1)\cdot(l-1)$, where we use $B(\rho)$ to refer to the set of blocks accessed in sequence $\rho$.

\newcommand{\dotleft}{.\textit{left}}
\newcommand{\dotright}{.\textit{right}}

Given a set of blocks~$B$ accessed in phase~$i$ or $i+1$, we refer to the set of blocks that occupy positions less than or equal to $x$'s position by $B\dotleft$ and to the set of blocks that occupy positions greater than $x$'s by $B\dotright$.

Note that $B(\sigma_{i, post})\dotright \cap B(\sigma_{i+1, pre_1})\dotleft = \emptyset$.
This is because before $x$'s eviction in phase $i+1$, all blocks to its right are still cached in phase $i+1$ and still to its right.
Also, $B(\sigma_{i, post})\dotright \cup B(\sigma_{i+1, pre_1})\dotleft \subseteq B(\sigma_{i, post}\circ \sigma_{i+1, pre_1}) \setminus \{x\}$.


There are $p$ positions strictly smaller than $x$'s.
Thus, $B(\sigma_{i+1, pre_1})\dotleft \geq p + 1$, as $\sigma_{i+1, pre_1}$ evicts $x$.
So $|B(\sigma_{i, post})\dotright| \leq (a-1)\cdot(l-1) - (p + 1)$

There are $k-p-1$ positions strictly larger than $x$'s.
Thus we also have $|B(\sigma_{i, pre})\dotright \cup B(\sigma_{i, post})\dotright| \geq k - p - 1$.

Combining the two above inequalities, we get
\begin{eqnarray*}
	|B(\sigma_{i, pre})\dotright| & \geq & k - p - 1 - |B(\sigma_{i, post})\dotright|\\
								 & \geq & k - p - 1 - (a-1)\cdot(l-1) + (p + 1)\\
								 & = & k - (a-1)\cdot(l-1)
\end{eqnarray*}

$B(\sigma_{i, pre})\dotright$ may contain the block that started phase $i$ via a global bit flip.
Except for this access, all accesses in $\sigma_{i, pre}$ to the right of $x$ must be cache hits as they are to the right of the first access to $x$ but occurred before the first access to~$x$.
Thus $|B(\sigma_{i, pre})\dotright| - 1 \geq k -1 - (a-1)\cdot(l-1)$ is a lower bound on the number of hits in $\mru(k)$ in phase $i$.

To summarize, we have two lower bounds on the number of hits of $\mru(k)$ in phase $i$:
\begin{enumerate}
	\item $lb_1(a) = (a-1)\cdot \nhitsLRU{i+1}(\overline{B_i})$, and
	\item $lb_2(a) = k - 1 - (a-1)\cdot(l-1)$.
\end{enumerate}
Both lower bounds are a function of $a$, the minimum number of accesses to blocks in $\overline{B_i}$ in phase $i$.
As $a$ is unknown, we need to determine a lower bound on the maximum of the two lower bounds $lb_1(a)$ and $lb_2(a)$: $\min_{a} \max \{lb_1(a), lb_2(a)\}$.

Note that $lb_1(a)$ is increasing in $a$ and $lb_2(a)$ is decreasing in $a$, as illustrated below:
\begin{center}
\begin{tikzpicture}

    \draw[thick, blue] (0, 0.5) -- (5, 2.5) node[anchor=south west,yshift=-3mm] {$lb_1(a)$};

    \draw[thick, red] (0, 2.5) -- (5, 0.5) node[anchor=north west,yshift=3mm] {$lb_2(a)$};
\end{tikzpicture}
\end{center}

Thus for any value of $a$, the minimum of $lb_1(a)$ and $lb_2(a)$ is less than or equal to $\min_{a} \max \{lb_1(a), lb_2(a)\}$.

We pick $a = \left\lceil\frac{k}{2l}\right\rceil$ and show that both $lb_1(a)$ and $lb_2(a)$ are greater than or equal to $(\lceil\frac{k}{2l}\rceil-1)\cdot \nhitsLRU{i+1}(\overline{B_i})$.

$lb_1(a) = \left(\left\lceil\frac{k}{2l}\right\rceil-1\right)\cdot \nhitsLRU{i+1}(\overline{B_i}) \geq (\lceil\frac{k}{2l}\rceil-1)\cdot \nhitsLRU{i+1}(\overline{B_i})$.

$lb_2(a) = k - 1 - \left(\left\lceil\frac{k}{2l}\right\rceil-1\right)\cdot(l-1) \geq k - 1 - \frac{k}{2l}\cdot(l-1) = \frac{k}{2} -1 + \frac{k}{2l} \geq \frac{k}{2} = \frac{k}{2l}\cdot l \geq \frac{k}{2l}\cdot \nhitsLRU{i+1}(\overline{B_i}) \geq (\lceil\frac{k}{2l}\rceil-1)\cdot\nhitsLRU{i+1}(\overline{B_i})$.

So $\nhitsBoth{i} + \nhitsNMRU{i} \geq \min\{lb_1(a), lb_2(a)\} \geq (\lceil\frac{k}{2l}\rceil-1)\cdot\nhitsLRU{i+1}(\overline{B_i})$.
\end{proof}

