In the above rendering process, to ensure either $c_t^{min}\geq c_n^{max}$ or $c_t^{max}<c_n^{min}$, we set the scene $\mathbf{S}'$ to dark light mode. 
The dark light mode refers to the rendering condition without directional lights and point lights. In the dark light mode, parts with the same material have minimal color difference after rendering (see Fig. \ref{fig:dark_render}(b)).
Therefore, parts with different colors can still maintain their color difference after rendering, as they are not affected by reflections that may cause significant color fluctuations. 
The dark light mode ensures that different parts with the same color have minimal color difference after rendering. 
This prevents the two color ranges $(c_t^{min}, c_t^{max})$ and $(c_n^{min}, c_n^{max})$ from intersecting in the rendered results, which facilitates the generation of masks. On the contrary, adopting strong light mode would result in reflections from metallic surfaces causing highlights on car bodies, leading to the intersection of the two color ranges in the rendered results, which means $(c_t^{min}, c_t^{max})\bigcap(c_n^{min}, c_n^{max})\neq \varnothing$ (see Fig. \ref{fig:dark_render}(c)).


\begin{algorithm}[t]
   \caption{Generating the 2D adversarial texture map}

   {\textbf{Input:}}\vspace{6pt}\quad\begin{minipage}[t]{183pt}
     information of the sensor $\Theta=\{r, \theta, \varphi\}$ in every image $\mathbf{I}_{p}$ rendered by PBR, 3D model $\mathbf{M} =(\mathbf{M}_0, \mathbf{T}_0)$, and target class $y$
   \end{minipage}

   {\textbf{Output:}}\quad\begin{minipage}[t]{160pt}
    adversarial 2D texture map $\mathbf{T}_{adv}$
   \end{minipage}
   \label{algorithm}

   \quad\begin{minipage}[t]{220pt}
   \begin{algorithmic} [1]

   \State $\mathbf{T}_{adv} \gets \mathbf{T}_0$
   \For {epochs} 
   \State Match $\Theta$ to images
   \For{num of images}
      \State $\mathbf{M} \gets (\mathbf{M}_0,\mathbf{T}_{adv})$
      \State $\mathbf{I}_{d} \gets \mathcal{R}_d(\Theta, \mathbf{M}, \mathbf{S}')$
      \State Transform textures to get $\mathbf{I}_{d}'$
      % \STATE $\mathbf{I}_{d}' \gets \mathcal{E}(\mathbf{I}_{t})$
      \State $\mathbf{I}_{m} \gets \mathcal{R}_d(\Theta, (\mathbf{M}_0, \mathbf{T}_0), \mathbf{S}')$
      \State Calculate $\mathbf{P}$ with $\mathbf{I}_{m}$ by Eqns. (\ref{eq:cmid}) and (\ref{eq:P})
      \State $\mathbf{I}_{o} \gets \mathbf{I}_{d}'*\mathbf{P}+\mathbf{I}_{p}*(1-\mathbf{P})$
      \State Get scores $\mathcal{F}^{cls}, \mathcal{F}^{obj}$ by detecting $\mathbf{I}_{o}$
      \State Calculate $\mathcal{L}_{1}, \mathcal{L}_{2}, \mathcal{L}_{s}$ by Eqns.(\ref{eq:two stage}), (\ref{eq:one stage}), \\ \qquad \qquad\qquad\quad and (\ref{eq:tv})
      \State $\mathcal{L} \gets \mathcal{L}_1+ \beta \mathcal{L}_2+\gamma \mathcal{L}_{s}$
      \State Optimize $\mathbf{T}_{adv}$ by minimizing $\mathcal{L}$
      \EndFor
   \EndFor
   \end{algorithmic}

  \end{minipage}
\end{algorithm}

