\section{Complete Experimental Results}
\label{app:complete-results}


\subsection{Full List of Baselines}
The full set of baselines we used in our experiments includes 15 collaborative algorithms, most of which were also included in earlier reproducibility studies as well~\cite{ferraridacrema2020tois,ferraridacremaetal2020cikm}:

\paragraph{Non-personalized Approaches}
\begin{itemize}
    \item \textbf{Random}: A non-personalized method recommending random items the user has not yet interacted with.
    \item \textbf{TopPop}: A non-personalized method recommending the most popular items to all users that the user has not yet interacted with.
    \item \textbf{Global Effects}: A non-personalized method where the item score is the average of all ratings it has received. The denominator includes a constant term to penalize the scores of items with low support.
\end{itemize}

\paragraph{Collaborative Nearest-Neighbor Techniques}
\begin{itemize}
    \item \textbf{UserKNN}: A user-based nearest-neighbor algorithm~\cite{DBLP:conf/cscw/ResnickISBR94}, with cosine similarity and shrinkage~\cite{bell2007improved}.
    \item \textbf{ItemKNN}: An item-based nearest-neighbor algorithm~\cite{DBLP:conf/www/SarwarKKR01}, with cosine similarity and shrinkage~\cite{bell2007improved}.
\end{itemize}

\paragraph{Graph-based Approaches}
\begin{itemize}
    \item \textbf{\palpha}: A graph based algorithm modeling a random walk on the bipartite graph of user-item interactions.
    \item \textbf{\pbeta}: A graph-based method that uses a two-steps random walk from users to items and vice-versa, where transition probabilities are computed from the normalized ratings~\cite{DBLP:journals/tiis/PaudelCNB17}.
    \item \textbf{GF-CF}: A graph-based method that is based on a low-pass filter and has a closed form solution~\cite{DBLP:conf/cikm/ShenWZSZLL21}.
    \item \textbf{LightGCN}: A graph-based method that performs message passing on the user-item adjacency matrix to learn user and item embeddings with BPR~\cite{DBLP:conf/sigir/0001DWLZ020}.
\end{itemize}


\paragraph{Item-Based Machine Learning}
\begin{itemize}
    \item \textbf{\EASER}: An ``embarrassingly shallow'' linear model with strong connections with autoencoders and a closed form solution~\cite{DBLP:conf/www/Steck19}.
    \item \textbf{SLIM}: An item-based model that uses linear regression and the Elastic Net loss to compute the item similarity~\cite{DBLP:conf/icdm/NingK11}.
    \item \textbf{SLIM-BPR}: An item-based model similar to SLIM that computes the item similarity optimizing the \emph{Bayesian Personalized Ranking} (BPR) loss~\cite{DBLP:conf/uai/RendleFGS09}.
\end{itemize}

\paragraph{Matrix Factorization Techniques}
\begin{itemize}
    \item \textbf{\MFBPR}: A matrix factorization method based on the \emph{Bayesian Personalized Ranking} (BPR) loss~\cite{DBLP:conf/uai/RendleFGS09}.
    \item \textbf{MF-WARP}: A matrix factorization method based on the \emph{Weighted Approximate-Rank Pairwise} loss (WARP).
    \item \textbf{SVDpp}: A matrix factorization method for rating prediction accounting for user biases~\cite{DBLP:conf/recsys/LercheJ14}.\footnote{Note that to adapt SVDpp for the task of top-n recommendation we sample a certain quota of missing interactions and attribute them a rating of zero. The specific quota is a hyperparameter.}
    \item \textbf{PureSVD}: A matrix factorization method based on the truncated SVD decomposition of the user-item interaction matrix~\cite{DBLP:conf/recsys/CremonesiKT10}.\footnote{We use a standard SVD decomposition method provided in the \small{\texttt{scikit-learn}}  \footnotesize package for Python.}
    \item \textbf{\iALS}: A matrix factorization method for ranking tasks based on alternating least-squares~\cite{DBLP:conf/icdm/HuKV08}.

\end{itemize}

\paragraph{Autoencoders}
\begin{itemize}
    \item \textbf{MultVAE}: A variational autoencoder that assumes a multinomial likelihood for user-item interactions \cite{DBLP:conf/www/LiangKHJ18}.
\end{itemize}


The hyperparameter ranges and distributions are the same used in \cite{ferraridacrema2020tois,ferraridacremaetal2020cikm}.
Note that occasionally the results for \textbf{\EASER} and \textbf{SLIM-BPR} may be missing due to their memory requirements exceeding the 64 GB available on our server.



