\begin{proof}[Proof of Theorem \protect\ref{dis}]
Take $v\in BBG^{N}$. If $M_{i}(v) = 0$ for all \( i \in N \setminus \{b^{v}\} \), the solution is trivial, as the $\tau$-diagonal reduces to a single point. For convenience, we will set $\alpha^{v} := 1$ in this case. Now, suppose that $\sum_{i \in N \setminus \{b^{v}\}} M_{i}(v) > 0$. To select the element of $T(N,v)$ that minimizes the distance to the Shapley value, it is sufficient to solve the following optimization problem:

\[
\displaystyle \min_{x\in T(N,v)}\left\{ \sqrt{\sum_{i\in N}\left[ x_{i}-\phi _{i}(N,v)\right]^{2}}\right\}
\]

The optimum of this problem will be the same as the one we
obtain in:
\[
\displaystyle \min_{x\in T(N,v)}\left\{ \sum_{i\in N}\left[ x_{i}-\phi _{i}(N,v)\right]^{2}\right\}
\] Finally, we can simplify the optimization
problem to obtain:
\begin{eqnarray*}
\min  &&f(\rho ):=\sum_{i\in N\setminus \{b^{v}\}}\left[ \rho M_{i}(v)-\phi
_{i}(v)\right] ^{2}+\left[ v(N)-\rho \sum_{i\in N\setminus
\{b^{v}\}}M_{i}(v)-\phi _{b^{v}}(v)\right] ^{2} \\
\mbox{s.t.} &&\rho \in \lbrack 0,1],
\end{eqnarray*}%
Since $f$ is a continuous and differentiable function, and the feasible set
is compact, we are guaranteed the existence of the optimum. Therefore, $%
f^{^{\prime }}(\rho )=0$ is equivalent to: 
\fontsize{10}{10}
\begin{gather}
2\sum_{i\in N\setminus \{b^{v}\}}\left[ \rho M_{i}(v)-\phi _{i}(v)\right]
\cdot M_{i}(v)-2\left[ v(N)-\rho \sum_{i\in N\setminus
\{b^{v}\}}M_{i}(v)-\phi _{b^{v}}(v)\right] \sum_{i\in N\setminus
\{b^{v}\}}M_{i}(v)=0; \notag\\
\rho \sum_{i\in N\setminus \{b^{v}\}}M_{i}^{2}(v)-\sum_{i\in N\setminus
\{b^{v}\}}\left( \phi _{i}(v)\cdot M_{i}(v)\right) +\rho \left( \sum_{i\in
N\setminus \{b^{v}\}}M_{i}(v)\right) ^{2}-\left( v(N)-\phi
_{b^{v}}(v)\right) \sum_{i\in N\setminus \{b^{v}\}}M_{i}(v)=0;  \notag \\
\rho \sum_{i\in N\setminus \{b^{v}\}}M_{i}^{2}(v)+\rho \left( \sum_{i\in
N\setminus \{b^{v}\}}M_{i}(v)\right) ^{2}=\left( v(N)-\phi
_{b^{v}}(v)\right) \sum_{i\in N\setminus \{b^{v}\}}M_{i}(v)+\sum_{i\in
N\setminus \{b^{v}\}}\left( \phi _{i}(v)\cdot M_{i}(v)\right) ;  \notag \\
\rho ^{v}=\frac{\left( v(N)-\phi _{b^{v}}(v)\right) \cdot \left(
\sum_{i\in N\setminus \{b^{v}\}}M_{i}(v)\right) +\sum_{i\in N\setminus
\{b^{v}\}}\left( \phi _{i}(v)\cdot M_{i}(v)\right) }{\left( \sum_{i\in
N\setminus \{b^{v}\}}M_{i}(v)\right) ^{2}+\sum_{i\in N\setminus
\{b^{v}\}}M_{i}^{2}(v)}\geq 0\label{foru}
\end{gather}%
\fontsize{10}{10}
We have that $f^{^{\prime \prime }}(\rho )=2\sum_{i\in N\setminus
\{b^{v}\}}M_{i}^{2}(v)+2\left( \sum_{i\in N\setminus
\{b^{v}\}}M_{i}(v)\right) ^{2}>0,$ then $f(\rho )$ it is convex, and since
the feasible set is bounded, the optimum $\alpha ^{v}$ is located at $\alpha
^{v}:=\min \{1,\rho ^{v }\}.$
\end{proof}
