\sum\limits_{\substack{ \emptyset \neq S\subseteq N\backslash \{j,b^{v}\} \\ %
\left\vert S\right\vert \leq n-3}}\left[ s!(n-s-1)!\cdot v(S\cup \{b^{v}\})%
\right] \leq \frac{n!}{2}\sum_{\substack{ i\in N\setminus \{b^{v}\} \\ i\neq
j}}v(N\backslash \{i\})+\frac{n!\left( n-2\right) }{n-1}v(N\backslash \{j\})
\end{gather*}%
\normalsize
Finally, using:
\scriptsize 
\begin{equation*}
\sum\limits_{\emptyset \neq S\varsubsetneq N\backslash \{j,b^{v}\}}\left[
\left( s+1\right) !(n-s-2)!\cdot v(S\cup \{b^{v}\})\right] +\sum\limits
_{\substack{ \emptyset \neq S\subseteq N\backslash \{j,b^{v}\} \\ \left\vert
S\right\vert \leq n-3}}\left[ s!(n-s-1)!\cdot v(S\cup \{b^{v}\})\right]
=\sum\limits_{\substack{ \emptyset \neq S\subseteq N\backslash \{j,b^{v}\}
\\ \left\vert S\right\vert \leq n-3}}\left[ ns!(n-s-2)!\cdot v(S\cup
\{b^{v}\})\right] 
\end{equation*}
\normalsize
The initial inequality, \( \tau _{j}(v) - \phi _{j}(N,v) \leq \tau _{b^{v}}(v) - \phi _{b^{v}}(v) \), can be written as:
\scriptsize 
\begin{gather}\label{ex1}
\frac{n!\left( n-2\right) }{2}v(N)+\frac{n!}{n-1}v(\{b^{v}\})+\sum\limits
_{\substack{ \emptyset \neq S\subseteq N\backslash \{j,b^{v}\} \\ \left\vert
S\right\vert \leq n-3}}\left[ n\cdot s!(n-s-2)!\cdot v(S\cup \{b^{v}\})%
\right] \leq \frac{n!}{2}\sum_{\substack{ i\in N\setminus \{b^{v}\} \\ i\neq
j}}v(N\backslash \{i\})+\frac{n!\left( n-2\right) }{n-1}v(N\backslash \{j\})
\end{gather}%
\normalsize

The next step is to group each $v(S)$ from the first part of the inequality with $v(N)$ according to the Big Boss games property, rewritten in Proposition \ref{pa3}. That is, for each $v(\{b^{v}\})$, we need $n-2$ instances of $v(N)$, while for each $v(S \cup \{b^{v}\})$, we need $n-s-2$ due to the number of possible coalitions of that size, which is $\binom{n-2}{s}$. Specifically:

\begin{eqnarray*}
&&\frac{n!}{n-1}(n-2)+n \sum\limits_{s=1}^{n-3}\left[ s!(n-s-2)!(n-s-2)%
\binom{n-2}{s} \right]  \\
&=& \frac{n!}{n-1}(n-2)+n \sum\limits_{s=1}^{n-3}\left[ s!(n-s-2)!(n-s-2)%
\frac{(n-2)!}{s!(n-s-2)!}\right]  \\
&=& \frac{n!}{n-1}(n-2)+n(n-2)! \sum\limits_{s=1}^{n-3}(n-s-2) \\
&=& \frac{n!}{n-1}(n-2)+n(n-2)! \left[ (n-2)(n-3)-\frac{(n-3)(n-2)}{2}\right]  \\
&=& \frac{n!}{n-1}(n-2)+n(n-2)! \frac{(n-3)(n-2)}{2} =\frac{n!}{n-1}(n-2)+n! \frac{(n-3)(n-2)}{2(n-1)}\\
&=& \frac{n!(n-2)}{2}\left[ \frac{2}{n-1}+\frac{(n-3)}{n-1}\right] =\frac{n!(n-2)}{2}.
\end{eqnarray*}

This demonstrates that we can combine the coefficient of \( v(N) \) from the first part of the inequality with the coefficients of \( v(S) \) in a manner that ensures all combinations result in expressions of the form \( \left( n - s - 1 \right) v(N) + v(S) \), each multiplied by a specific factor. Formally, the first part of inequality (\ref{ex1}) can be rewritten as follows:

\small
\begin{equation*}
\frac{n!}{n-1}\left[ (n-2)v(N)+v(\{b^{v}\})\right] +\sum\limits_{\substack{ %
\emptyset \neq S\subseteq N\backslash \{j,b^{v}\} \\ \left\vert S\right\vert
\leq n-3}}\left[ n\cdot s!(n-s-2)!\cdot \left[ (n-s-2)v(N)+v(S\cup \{b^{v}\})%
\right] \right] 
\end{equation*}
\normalsize


Thanks to this, we can determine the number of such expressions and apply the result from Proposition \ref{pa3} to each of them. The reader may observe that both $\{b^{v}\}$ and $S \cup \{b^{v}\}$ do not include player $j$, which implies that every expression formed will contribute a summand $v(N \backslash \{j\})$ when the inequality is applied. The total number of such expressions is $\frac{n!}{n-1}$ for $S = \{b^{v}\}$ and  
$n \sum\limits_{s=1}^{n-3} \left[ s!(n-s-2)!\binom{n-2}{s} \right]$  
for $S \subseteq N \backslash \{j, b^{v}\}$ with $s \leq n-3$. Therefore, we obtain:

\begin{eqnarray*}
&&\frac{n!}{n-1}+n \sum\limits_{s=1}^{n-3}\left[ s!(n-s-2)! \binom{n-2}{s} \right] = \frac{n!}{n-1} + n (n-2)! \sum\limits_{s=1}^{n-3} 1  \\
&=& \frac{n!}{n-1} + n (n-2)! (n-3)=\frac{n!}{n-1} + n (n-2)! (n-3) = \frac{n!}{n-1} + \frac{n!(n-3)}{n-1}  \\
&=& \frac{n!}{n-1}(1 + (n-3)) = \frac{n!(n-2)}{n-1}
\end{eqnarray*}
The term \( v(N \backslash \{j\}) \) appears exactly as many times as dictated by expression (\ref{ex1}). Finally, we need to determine the number of occurrences of $v(N \backslash \{i\})$ with $i \neq j$ we can obtain. As in the previous case, we obtain $\frac{n!}{n-1}$ for $S=\{b^{v}\}$ and we must take into account that coalitions of the form $S \subseteq N \backslash \{j, b^{v}\}$ containing player $i$ will not produce any $v(N \backslash \{i\})$. Therefore, in this case, we will have $n \sum\limits_{s=1}^{n-3}\left[ s!(n-s-2)!\binom{n-3}{s} \right]$ for $S \subseteq N \backslash \{j, b^{v}\}$ with $s \leq n-3$. Summing both quantities, we get:
\small
\begin{eqnarray*}
&&\frac{n!}{n-1} + n \sum\limits_{s=1}^{n-3} \left[ s!(n-s-2)! \binom{n-3}{s} \right] = \frac{n!}{n-1} + n \sum\limits_{s=1}^{n-3} \left[ s!(n-s-2)! \frac{(n-3)!}{s!(n-s-3)!} \right]  \\
&=& \frac{n!}{n-1} + n (n-3)! \sum\limits_{s=1}^{n-3} (n-s-2) = \frac{n!}{n-1} + n (n-3)! \left[ (n-2)(n-3) - \frac{(n-3)(n-2)}{2} \right]  \\
&=& \frac{n!}{n-1} + n (n-3)! \frac{(n-3)(n-2)}{2} = \frac{n!}{n-1} + \frac{n!(n-3)}{2(n-1)} = \frac{2n! + n!(n-3)}{2(n-1)} = \frac{n!(n-1)}{2(n-1)} = \frac{n!}{2}
\end{eqnarray*}
\normalsize

It can be verified that the number of occurrences also matches the count given in expression (\ref{ex1}) after applying the inequality from Proposition \ref{pa3}, thereby proving the required inequality.

\end{proof}
