We conclude the section by introducing the notion of multi-simple cycle reservoirs. 
\par
\begin{definition}
\label{def.MSCR}
Given positive integer $k > 1$, a {\bf Multi-Simple Cycle Reservoir of order $k$} (MSCR) is the system $S = \left(\{\BW^{(i)}\}_{i=1}^k, \{\mathcal{W}_{in}^{(i)}\}_{i=1}^k,\s, \H, \d, \A, f, h \right)$ with dimensions $(n, k, m, d)$. The system $S$ consists of $k$ interconnected \textbf{vertex-encoders}\footnote{Also called \textbf{encoders} in ~\cite{li2022multi,li2023multi}.} 
% \textcolor{blue}{[comment by GT: smaller than what? Please reconsider this term below as well.]} \simon{SF: let's remove the ``smaller" here and replace the other ``smaller reservoir" with ``encoder"?} reservoir systems (\textbf{encoders})
, denoted by $R^{(i)} = \left(\BW^{(i)}, \s_i \cdot \mathcal{W}_{in}^{(i)}, f, h \right)$, each with dimension $n$. The system $S$ is defined with the following conditions:
\begin{enumerate}   
    \item $\s \in \mathbb{R}^k$ denotes the set of input scaling factors for the external input, where each $\s_i$ corresponds to the scaling factor associated with $R^{(i)}$.

    \item $\H \in \mathbb{M}_{k\times k}(\mathbb{R})$ represents the matrix of input scaling factors between vertex-encoder. Specifically, $\H_{ij}$ denotes the scaling factor for input from $R^{(j)}$ to $R^{(i)}$.
    % \comment{I wrote $\H$ and $\s$ separately since one is a matrix and one is a vector. Both are scalars but its tidier to keep it this way I felt.. Not sure if its too many inputs.}
    \item The connectivity between vertex-encoder is represented by a directed graph with node-adjacency matrix $\A = \left[\A_{ij}\right]_{i,j = 1}^k \in \mathbb{M}_{k \times k}(\mathbb{R})$, satisfying:
        \begin{itemize}
            \item $\A_{ii} = 0$ for all $i$, ensuring no self-loops.
            \item $\A_{ij} = 1$ if the output of the $i$-th vertex-encoder is used as input to the $j$-th vertex-encoder; otherwise, $\A_{ij} = 0$.
        \end{itemize}
    \item $\d \in \mathbb{M}_{k \times 1}\left(\left\{0,1\right\}\right)$ indicates whether each vertex-encoder receives the external input, where:
        \begin{itemize}
            \item $\d_i = 1$ if the $i$-th vertex-encoder receives the external input.
            \item $\d_i = 0$ otherwise.
        \end{itemize}

    \item Each vertex-encoder $R^{(i)} \in S$ is described as follows:
    \begin{itemize}
        \item The coupling matrix $\BW^{(i)} \in \mathbb{R}^{n \times n}$ is a contractive full-cycle permutation matrix, for $i = 1, 2, \dots, k$.
        \item The state of $R^{(i)}$ at time $t$ is denoted by $\Bx_t^{(i)}$. The input $\mathcal{U}_t^{(i)} \in \mathbb{R}^{m+n\cdot\left(k-1\right)}$ to $R^{(i)}$ at time $t$ is formed by concatenating the external input $u_t$ with the states of all \emph{other} vertex-encoders:
        \[
        \mathcal{U}_t^{(i)} = \left(u_t, \Bx_t^{(1)}, \dots, \Bx_t^{(i-1)}, \Bx_t^{(i+1)}, \dots, \Bx_t^{(k)}\right).
        \]
        \item $\mathcal{W}_{in}^{(i)}$ is a linear map that transforms $\mathcal{U}_t^{(i)}$ into the state space of $R^{(i)}$ by: 
        \begin{align*}        \mathcal{W}_{in}^{(i)}\left(\mathcal{U}_t^{(i)}\right) &= \left(\V_{in}^{(i)} \d_i \s_i u_t \right. \\
        & \quad \quad \left. + \sum_{\substack{j = 1 \\ j \neq i}}^k \BV_j^{(i)}  \H_{ji}\A_{ji} \Bx_t^{(j)} \right),
        \end{align*}
        where:
        \begin{itemize}
            \item $\V_{in}^{(i)} \in \mathbb{M}_{n \times m}\left(\{-1, 1\}\right)$ is the input-to-state coupling map of the external input.
            \item $\BV_j^{(i)} \in \mathbb{M}_{n \times n}\left(\{-1, 1\}\right)$ is the input-to-state coupling map from the state of $R^{(j)}$ to $R^{(i)}$.
        \end{itemize}
        \item Both $\V_{in}^{(i)}$ and $\BV_j^{(i)}$ are implicitly defined by $\mathcal{W}_{in}^{(i)}$.
    \end{itemize}

    \item The dynamics of the $i$-th vertex-encoder $R^{(i)}$, for $i = 1, 2, \dots, k$, are defined as:
    \begin{align*}
    \Bx^{(i)}_t &= f\left(\BW^{(i)} \Bx^{(i)}_{t-1} + \mathcal{W}_{in}^{(i)}\left(\mathcal{U}_t^{(i)}\right) \right) 
    % \\
    %  &= f\left(\BW^{(i)} \Bx^{(i)}_{t-1} + \V_{in}^{(i)} \d_i\s_i\cdot  u_t + \sum_{\substack{j = 1 \\ j \neq i}}^k \BV_j^{(i)} \H_{ji}\A_{ji} \Bx^{(j)}_t  \right)
    % \By_t &= h(\Bx_t),
    \end{align*}
    where:
    \begin{itemize}
        \item $f$ is the activation function; all vertex-encoders share the same activation function.
        % \item $\{u_t\}_{t \in \mathbb{Z}_-} \subset \mathbb{R}^m$ is the external input sequence.
        \item $\{\mathcal{U}^{(i)}_t\}_{t \in \mathbb{Z}_-}$ is the concatenated input sequence.
        \item $\{\Bx^{(i)}_t\}_{t \in \mathbb{Z}_-} \subset \mathbb{R}^n$ is the state sequence of the $i$-th vertex-encoder.
    \end{itemize}

    \item The concatenated state vector $\Bx \in \mathbb{R}^{k \cdot n}$ at time $t$ is formed by combining the states of all $k$ vertex-encoder: 
        \[
        \Bx_{t} = \left(\Bx^{(1)}_{t}, \dots, \Bx^{(k)}_{t}\right), \quad \text{where } \Bx^{(i)}_{t} \in \mathbb{R}^n.
        \]
    The system output sequence is given by $\{\By_t\}_{t \in \mathbb{Z}_-} \subset \mathbb{R}^d$. The readout function $h$ operates on the global state $\Bx_t$ or a linear combination of component states: 
    \[
    h(\Bx_t) = h\left(\sum_{i=1}^k a_i \cdot \Bx^{(i)}_t \right),
    \]
    where $a_i \in \mathbb{R}$ are mixing coefficients.
\end{enumerate}
\end{definition}

Consider a directed graph $G = (V, E)$ with $\vert V \vert = k$ and a vertex $i \in V$. Recall the \textbf{reachability matrix} $\mathcal{R} = \left[\mathcal{R}_{ij}\right]_{i,j = 1}^k$ is a $k \times k$ matrix over $\left\{0,1\right\}$ defined as:
\begin{itemize}
    \item $\mathcal{R}_{ij} = 1$ if there exists a path from node $i$ to node $j$, 
    \item $\mathcal{R}_{ij} = 0$ otherwise.
\end{itemize}

The reachability matrix $\mathcal{R}$ can be computed from the connectivity matrix $\A$ using the Floyd-Warshall algorithm \cite{warshall1962theorem} with $O(k^3)$. 

% Basically we can calculate the distance matrix between nodes using Floyd-Warshall, if the distance is infinite, then i is not reachable from j. Otherwise if i is reachable from j, this distance is less than |V| = k.

% Alternatively, if the connectivity matrix of $G$ is given by $\A$, $\mathcal{R}$ can be computed as \comment{I need to check again, nonetheless its computable $O(k^4)$.}:
% \begin{align*}
%     \mathcal{R} = I \lor \A \lor \A^2 \lor \dots \lor \A^{k-1}, 
% \end{align*}
% where $\lor$ denotes the element-wise logical OR operation.

\begin{definition}
    Given an MSCR $S = \left(\{\BW^{(i)}\}_{i=1}^k, \{\mathcal{W}_{in}^{(i)}\}_{i=1}^k, \s, \H, \d, \A, f, h \right)$ of order $k$, let $\mathcal{R}$ denote the reachability matrix corresponding to the directed graph defined by $\A$. A vertex-encoder $R^{(i)} \in S$ is \textbf{valid} if there exists $j = 1,\ldots,k$ such that:
    \begin{align*}
    \mathcal{R}_{ji} \cdot D_j = 1.
    \end{align*}
    Otherwise, a vertex-encoder is \textbf{invalid}. 
    % \comment{If you don't like the `exists' you can alternatively set $\sum_{j=1}^k \mathcal{R}_{ji}\cdot \d_j > 0$}
    \par
    The \textbf{rank} of $S$ is the number of valid vertex-encoders of the system $S$, given by:
    \begin{align*}
        \operatorname{rank}(S) := 
        \sum_{i=1}^k \mathbbm{1}\left(
        \sum_{j=1}^k \mathcal{R}_{ji}\cdot \d_j
        \right),
        % \sum_{i=1}^k \mathbbm{1}\left( \left(\mathcal{R}^\top \cdot \d\right)_i\right) = 
    \end{align*}
    where $\mathbbm{1}(x)$ is the indicator function:
    \[
    \mathbbm{1}(x) =
    \begin{cases} 
    1 & \text{if } x \neq 0, \\
    0 & \text{if } x = 0.
    \end{cases}
    \]
\end{definition}

\begin{remark}
\label{rmk:rank}
By construction an MSCR of order $k$ with rank $1$ is equivalent to a single SCR for any $k \in \mathbb{N}_+$.
\end{remark}

