\begin{corollary}\label{cor:inf}
   Let $y \in L_i$ be a point, and let $\{z_m: m\in N\} \subset L_i$ be a sequence of points. Then the condition
   $$\rho_{i}(z_m, y) \xrightarrow{m\rightarrow \infty} + \infty$$   
 is equivalent to
    $$||z_m-y||_2 \xrightarrow{m\rightarrow \infty} + \infty.$$
\end{corollary}

Now we are ready to prove a key auxiliary lemma.


\begin{lemma}\label{l:main1}
Let $i \in \{1,2\}$, and let $x',x'',y$ be distinct points in $L_i$. Then the following two conditions are equivalent.

$(\Gamma)$. For any sequence of points $z_1,z_2,... \in L_i$, such that $\rho_{i}(z_m, y) \xrightarrow{m\rightarrow \infty} + \infty$, there exists $m_0 \in \N$, such that for any $m > m_0$ we have $\min(\rho_{i}(z_m, x')$, $\rho_{i}(z_m, x''))$ $<\rho_{i}(y-z_m)$.

$(\Omega)$. The points $\pr(x'),\pr(x'')$ are distinct. The projection $\pr(y)$ lies strictly in the interior of the segment $[\pr(x'),\pr(x'')]$.
\end{lemma}

\begin{proof}
By a slight abuse of the notation, we compare points on the line $\R\times \{0\}$ as real numbers.

    \textit{Proof of the implication $(\neg\Omega)\Rightarrow(\neg\Gamma)$}. Let condition $(\Omega)$ does not hold.
    For definiteness, let $\pr(x') \leq \pr(y), \pr(x'') \leq \pr(y)$. Denote ${\textbf u}=(1,0)$ and consider the points $z_m = y + m{\textbf u}$ for $m \in \N$. Then for any $m \in \N, x \in \{x',x''\}$ we have
$$m = ||y-z_m||_2 = ||\pr(y)-\pr(z_m)||_2 = \rho_{i}(\pr(z_m), \pr(y)) \leq \rho_{i}(\pr(z_m), \pr(x)).$$
Hence, condition $(\Gamma)$ does not hold (see Fig. \ref{fig:sup_lemma_planar_1}). 

    \textit{Proof of the implication $(\Omega)\Rightarrow(\Gamma)$}.
    Let condition $(\Omega)$ holds. For definiteness, let $\pr(x') < \pr(y) < \pr(x'')$.
    Consider an arbitrary sequence $z_1,z_2,... \in L_i$, such that $\rho_{i} (z_m, y)\xrightarrow{m\rightarrow \infty} + \infty$. By Corollary \ref{cor:inf} we have $||z_m-y||_2 \xrightarrow{m\rightarrow \infty} + \infty$. Then $z_n$ contains a subsequence $\{z_{k_m}: m\in \N\}$ such that $\pr(z_{k_m}) \xrightarrow{m\rightarrow \infty} -\infty$ or $\pr(z_{k_m}) \xrightarrow{m\rightarrow \infty} +\infty$. Without loss of generality, we assume that $z_m = z_{k_m}$, and $\pr(z_m) \xrightarrow{m\rightarrow \infty} +\infty$. Then, for any sufficiently large $m$, the angle $\angle yx''z_m$ is obtuse, and $||y-z_m||_2 > ||x''-z_m||_2$.  Thus, condition $(\Gamma)$ holds (see Fig. \ref{fig:sup_lemma_planar_2}).
\end{proof}

