\center{\includegraphics[scale=0.5, width=350pt]{Fig5.eps}}
\caption{a). The case $y \in [x,z]$, $||a-x||_2 \geq ||a-y||_2$.  b) The case $f(x) \in [f(y), f(z)]$, $\max(\rho_{1}(b,f(x)), \rho_{1}(b,f(z))) < \rho_{1}(b,f(y))$}
\label{fig:y_between_xz}
\end{figure}

\begin{corollary}\label{cor:boundary}
    For any $y \in L_1$ such that $y \in \R\times\{0, \eps_1 \}$, we have $f(y) \in \R\times\{0, \eps_2 \}$.
\end{corollary}

\begin{proof}
    We have $y \in \R\times\{0, \eps_1 \}$ if and only if there are no such points $x,z \in L_1$, such that $x,y,z$ are distinct points on the same vertical line, and $y\in [x,z]$. At the same time, $f(y) \in \R\times\{0, \eps_2 \}$ if and only if there are no such points $x',z'\in L_2$, such that $x',f(y),z'$ are distinct points on the same vertical line, and $f(y)\in [x',z']$. We are only left to apply Lemma \ref{l:vert_xyz}.
\end{proof}

The following lemma shows that $f$ preserves the horizontal segments of integer length.

\begin{lemma}\label{l:horizontal}
    Let $x,y \in L_1$, and $||x-y||_2=1$. Then $x,y$ lie on the same horizontal line if and only if $f(x), f(y)$ lie on the same horizontal line.
\end{lemma}


\begin{proof}
    Note that $\rho_{1}(\pr(x),\pr(y)) = 1$ if and only if the segment $[x,y]$ is horizontal. On the other hand, $\rho_{1}(\pr(x),\pr(y)) = 1$ if and only if there are no such points $x',y'$ that $\rho_{1}(x',y')=1$ and the segment $[\pr(x'),\pr(y')]$ contains the points $\pr(x),\pr(y)$ strictly in the interior, see Fig. \ref{fig:horizontal}.


Therefore, $[x,y]$ is horizontal if and only if there are no such points $x',y'$ that $\rho_{1}(x',y')=1$ and the segment $[\pr(x'),\pr(y')]$ contains the points $\pr(x),\pr(y)$ strictly in the interior. The analogous statement also holds for $f(x),f(y)$.

    Since $f$ is an isomorphism of graphs, we have $\rho_{1}(x',y')=1$ if and only if $\rho_{1}(f(x'),f(y'))=1$. Due to Lemma \ref{l:main1} applied to $x',x,y'$ and applied to $x',y,y'$, the points $\pr(x), \pr(y)$ lie strictly in the interior of the segment $[\pr(x'),\pr(y')]$ if and only if the points $\pr(f(x)),\pr(f(y))$ lie strictly in the interior of the segment $[\pr(f(x')),\pr(f(y'))]$.

    So, the obtained criterion that the segment $[x,y]$ is horizontal is equivalent to the analogous criterion that the segment $[f(x),f(y)]$ is horizontal.
\end{proof}


\begin{figure}[ht]
\center{\includegraphics[scale=0.5, width=300pt]{Fig6.eps}}
\caption{The segment $[x,y]$ of length $1$ is horizontal if and only if there are no such points $x',y'$ that $\rho_{G_1}(x',y')=1$ and the segment $[\pr(x'),\pr(y')]$ contains the points $\pr(x),\pr(y)$ strictly in the interior}
\label{fig:horizontal}
\end{figure}

Now we are ready to introduce a construction, that differs the unit distance graphs of $L_1$ and $L_2$ in the case $\eps_1, \eps_2 < 1$.

Consider $N, M \in \N$, such that $M > N$. Consider different points $a_0, a_1,...,a_N$, different points $b_0, b_1,... b_M$, and different points $c_1, c_2,...,c_M $ in $\R\times[0,\eps]$, satisfying the following properties.

(i) $a_0, ...,a_N$ lie on the same horizontal line $l$;

(ii) $||a_0-a_1||_2=||a_1-a_2||_2=....=||a_{N-1} - a_N||_2=1$;

(iii) $a_0=b_0, a_N=b_M$;

(iv) $||b_0-c_1||_2=||c_1-b_1||_2=||b_1-c_2||_2=...=||c_N - b_N||_2=1$.

(v) For $i = 1,2,...,M-1$ the projections $\pr(b_i), \pr(c_i)$, and the projection $\pr(c_M)$ lie strictly in the interior of the segment $[a_0, a_N]$;

(vi) For $i = 1,2,...,M-1$, the projection $\pr(b_i)$ is strictly between $\pr(b_{i-1})$  and $\pr(b_{i+1})$. For $i = 1,2,...,1$, the projection $\pr(c_i)$ is strictly between $\pr(b_{i-1})$ and $\pr(b_{i})$.

We say that such points $a_0, ..., a_N, b_0,...,b_M, c_0,...c_M$ form a \textit{$(N,M)$-comb}, see Fig. \ref{fig:comb} (we do not require that the points $b_0,b_1,...b_M$ lie on the same line and that the points $c_0,c_1,...,c_M$ lie on the same line, but this case is extreme).

\begin{figure}[ht]
\center{\includegraphics[scale=0.5, width=400pt]{Fig7.eps}}
\caption{The extreme case of the $(4,5)$-comb}
\label{fig:comb}
\end{figure}

\begin{proposition}\label{prop:comb}
    Let $0 < \eps < 1$. Then the layer $\R \times [0,\eps]$ contains a $(N,M)$-comb if and only if $\eps \geq \sqrt{1-\frac{N^2}{4M^2}}$.
\end{proposition}

\begin{proof}
Let $a_0, ..., a_N, b_0,...,b_M, c_0,...c_M \in \R\times[0,\eps]$ form a comb.
The segment $[a_0,a_N]$ of this comb has length $N$. The points $\pr(b_1),\pr(b_2)$,$...$, $\pr(b_{M-1})$ divide this segment into $M$ parts. Then for at least one number $i\in [M-1]$ we have $||\pr(b_i)- \pr(b_{i+1})||_2 \leq \frac{N}{M}$. So, the triangle $b_i b_{i+1} c_{i+1}$ has two sides of length $1$ and is contained in a rectangle with length of the vertical sides $\eps$, and length of the horizontal sides at most $\frac{N}{M}$. We will find the minimum value of $\eps$ at which it is possible.

Let this rectangle be $ABCD$, and let $||A-B||_2=\eps, ||B-C||_2 \leq \frac{N}{M}$, $b_{i-1} \in AB, b_{i+1} \in CD$. By a parallel transport, we can assume without loss of generality that $b_{i-1} = A$ and $c_i$ is in the polygon $ABCb_i$. Denote by $E$ and $F$ the projections of $c_i$ onto $CD$ and $AD$, respectively; see Fig. \ref{fig:rectangle}. Then $$||D-c_i||_2 \geq \text{diam}\,EDFc_i \geq ||b_i-c_i||_2 = 1,$$ 
because $EDFc_i$ is a rectangle. Therefore,
$$||A-c_i||_2= 1, ||D-c_i||_2 \geq 1;$$
$$\min(||A-F||_2, ||F-D||_2) \leq \frac{N}{2M};$$
$$\eps = ||A-B||_2 \geq ||c_i-F||_2 \geq \sqrt{1-\frac{N^2}{4M^2}}.$$
On the other hand, obviously, the estimate $\eps = \sqrt{1-\frac{N^2}{4M^2}}$ is sufficient for the "extreme" case of comb, when $b_0,b_1,...b_M$ lies on the line $l$ and divide it into equal parts, see Fig. \ref{fig:comb}. Hence, this estimate is tight.
\end{proof}

\begin{figure}[ht]
\center{\includegraphics[scale=0.5, width=170pt]{Fig8.eps}}
\caption{The rectangle $ABCD$ containing the triangle $b_{i-1}b_ic_i$.}
\label{fig:rectangle}
\end{figure}

\begin{lemma}\label{l:eps_less_one}
    Let $\eps_1, \eps_2 < 1$. Then $L_1$ contains a $(N,M)$-comb if and only if $L_2$ contains a $(N,M)$-comb.
\end{lemma}

\begin{proof}
    Let $a_0, ..., a_N, b_0,...,b_M, c_0,...c_M \in L_1$ form a comb. The properties (ii)-(iv) hold for $f(a_0),...,f(a_N)$,$f(b_0),...,f(b_N)$, $f(c_1)$,$...$,$f(c_M)$, because $f$ is an isomorphism of unit distance graphs. The property (i) holds due to Lemma \ref{l:horizontal}. The properties (v)-(vi) hold due to Lemma \ref{l:vert}. Hence, $f(a_0),...,f(a_N)$,$f(b_0),...,f(b_N)$,$f(c_1)$,$...$, $f(c_M)\in L_2$ form $(N,M)$-comb.
\end{proof}

In the case where $\eps_1 \geq 1$ or $\eps_2 \geq 1$, we also use an additional construction to reduce the problem to the comparison of the fractional parts of $\eps_1$ and $\eps_2$. For $m \in \N$, consider the set $\{(x,y) : x \in \Z, y \in \{0,1,\dots,m\}\}$ in $\R^2$. Let us call $m$-sandwich any set obtained from the given set by a shift by a real vector, as is shown on Fig. \ref{fig:sandwich}. We say that $x$ is a \textit{border point} of a $m$-sandwich $S$, if $x \in S$, and $x$ does not lie between any other two points of $S$ that form a vertical segment.

\begin{figure}[ht]
\center{\includegraphics[scale=0.5, width=250pt]{Fig9.eps}}
\caption{An example of $3$-sandwich. The border points are colored red.}
\label{fig:sandwich}
\end{figure}

By a corollary of Lemmas \ref{l:vert}, \ref{l:vert_xyz}, \ref{l:horizontal}, and Corollary \ref{cor:boundary}, we immediately get the following observation.

\begin{observation}\label{obs:sandwich}
Let $S \subset L_1$ be a $m$-sandwich. Then $f(S) \subset L_2$ also is a $m$-sandwich, and the mutual arrangement of the points of $L_2$ in the horizontal rows and vertical columns is the same in the following sense. If $x,y,z \in S$ are different points, $x \in [y,z]$, and the segment $[y,z]$ is vertical (horizontal), then $f(x) \in [f(y), f(z)]$, and the segment $[f(y),f(z)]$ is also vertical (horizontal). In particular, if $x$ is a border point of $S$, then $f(x)$ is a border point of $f(S)$.
\end{observation}

Denote by $m_i$ and $\delta_i$ the integer part and the fractional part of $\eps_i$, respectively:
$$m_i = \lfloor\eps_i \rfloor,\; \delta_i = \eps_i - m_i.$$
Consider the sets
$$\Delta_i = \{x = (x_1,x_2) \in L_i:\; x_2 \in [0, \delta_i)\cup(m_i, \eps_i]\}.$$

\begin{lemma}\label{l:delta}
    If $x \in \Delta_1$, then $f(x) \in \Delta_2$.
\end{lemma}

\begin{proof}
    Note that $x \in \Delta_i$ if and only if $x$ is a border point of a $m_1$-sandwich in $L_1$,  such that all the points of this sandwich are not contained in $\R\times\{0,\eps_i\}$. So, it is enough to apply Corollary \ref{cor:boundary} and Observation \ref{obs:sandwich}.
\end{proof}

We say that points $a_0,a_1,...,a_N, b_0,b_1,...,b_M, c_1,...,c_M \in L_i$ form a \textit{modified $(N,M)$-comb} if they are contained in $\Delta_i$, they satisfy the statements (i)-(vi) of the definition of $(N,M)$-comb, and $c_1,...,c_M \in \R \times \{0,\eps_i\}$.

\begin{lemma}\label{l:planar_end}
    Let $a_0,a_1,...,a_N, b_0,b_1,...,b_M, c_1,...,c_M \in \Delta_i$ form a modified $(N,M)$-comb. Then

    $(\alpha)$ all these points lie in $\R\times[0,\delta_1]$ or all these points lie in $\R\times[m_1,\eps_1]$;

    $(\beta)$ the points $f(a_0),...,f(a_N),f(b_0),...,f(b_N),f(c_1),...,f(c_M) \in L_2$ satisfy the properties (i)-(vi), and $f(c_1),...,f(c_M) \in \R \times \{0,\eps_2\}$;

     $(\gamma)$ all the points $f(a_0),...,f(a_N),f(b_0),...,f(b_N),f(c_1),...,f(c_M)$ lie in $\R\times[0,\delta_2]$ or all these points lie in $\R\times[m_2,\eps_2]$.
\end{lemma}

\begin{proof}
    $(\alpha)$. 
    For definiteness, let $c_1 \in \R\times\{0\}$.

    For any point $t \in  \R\times[m_1,\eps_1]$, we have $||t-c_1||_2 > 1$. Since $||b_0 - c_1||_2 = ||b_1-c_1||_2=1$ and $b_0, b_1 \in \Delta_1$, we get $b_0,b_1 \in \R\times[0,\delta_1]$.

    For any point $t \in  \R\times\{\eps_1\}$, we have $||t-b_1||_2 > 1$. Since $||b_1 - c_2||_2 = 1$, and $c_2 \in \R\times\{0,\eps_1\}$, we get $c_2 \in \R\times\{0\}$.

    Thus, by induction on $j$ we can analogously show that all the points $b_j,c_j$ are in $\R\times\{0\}$.

    Then all the points $a_0,a_1,...,a_N$ lie in $\R\times\{0\}$, because they are on the same horizontal line.

    $(\beta)$. The properties (ii),(iii),(iv) hold for $f(a_0),...,f(a_N)$,$f(b_0),...,f(b_N)$, $f(c_1)$,$...$,$f(c_M)$, because $f$ is an isomorphism of unit distance graphs. The property (i) holds due to Lemma \ref{l:horizontal}. The properties (v)-(vi) hold due to Lemma \ref{l:vert}. The property $f(c_1),...,f(c_M) \in \R \times \{0,\eps_2\}$ holds due to Corollary \ref{cor:boundary}.

    $(\gamma)$ Due to $(\beta)$, the proof is the same as the proof of $(\alpha)$.
\end{proof}

Since the widths of the strip $\R\times[0,\delta_1]$ and $\R\times[m_1,\eps_1]$ are equal to $\delta_1$, Lemma \ref{l:planar_end} and Proposition \ref{prop:comb} immediately give the following corollaries.

\begin{corollary}\label{cor:planar_end_1}
    Let $m_i \geq 1, 0 < \delta_i$. Then $L_i$ contains a modified $(N,M)$-comb if and only if $\delta_i \geq \sqrt{1-\frac{N^2}{4M^2}}$.
\end{corollary}

\begin{corollary}\label{cor:planar_end_2}
    Let $m_1 = m_2 \geq 1$. Then $L_1$ contains a modified $(N,M)$-comb if and only if $L_2$ contains a modified $(N,M)$-comb.
\end{corollary}

Now we are ready to complete the proof of Theorem \ref{t:planar}. Without loss of generality, we assume that $\delta_1 \geq \delta_2$.

Case I. Let $m_1 > m_2$. That contradicts Observation \ref{obs:sandwich}, because $L_1$ contains $m$-sandwich, and $L_2$ does not.

Case II. Let $m_1 = m_2 = 0, \eps_1 > \eps_2$. Then there exist integer numbers $N,M$ such that $\eps_1 > \sqrt{1-\frac{N^2}{4M^2}} > \eps_2$. Due to Proposition \ref{prop:comb}, $L_1$ contains a $(N,M)$-comb, but $L_2$ does not. That contradicts Lemma \ref{l:eps_less_one}.

Case III. Let $m_1 = m_2 > 0, \delta_1 > \delta_2$. Then there exist integer numbers $N,M$ such that $\delta_1 > \sqrt{1-\frac{N^2}{4M^2}} > \delta_2$. Due to Corollary \ref{cor:planar_end_1}, $L_1$ contains a modified $(N,M)$-comb, but $L_2$ does not. That contradicts Corollary \ref{cor:planar_end_2}.

Therefore, we get $\eps_1 = \eps_2$, which completes the proof of Theorem \ref{t:planar}.

\section{Proof of Theorem \ref{t:main}}
Let $n,m \in \N, n \geq 2; p \in (0,+\infty); \eps_1, \eps_2 \in (0,+\infty)$. Consider the layers $L_1 = L(n, m, p, \eps_1)$, $L_2 = L(n, m, p, \eps_1)$, and denote the unit distance graphs of these layers by $G_1$ and $G_2$, respectively. Denote by $\rho_i(x,y)$ the length of shortest path between two vertices $x,y$ in the graph $G_i$. 

Suppose $f:L_1\ra L_2$ is an isomorphism of the graphs $G_1, G_2$. We will prove that this implies $\eps_1=\eps_2$.

For definiteness, we take $n$-dimensional real space $\H$, $m$-dimensional real space $\V$, and $(n+m)$-dimensional real space $\T$ such that, for $i\in \{1,2\}$,
$$L_i = \H \times [0,\eps]^m \subset \H \times \V = \T.$$

By analogy to Theorem \ref{t:planar}, we say that any subspace $P$ in $\T$ parallel to the subspace $\H$ is \textit{horizontal}, and any subspace $P$ in $\T$ parallel to the subspace $\V$ is \textit{vertical}.

\begin{proposition}\label{prop:dist2}
    Given $i\in \{1,2\}, x,y \in L_i$, we have $||x-y||_p = 2$ if and only if there exists exactly one point $z\in L_i$ such that $||x-z||_p = ||y-z||_p = 1$.

    In this case, $z$ is the middle of the segment $[x,y]$.
\end{proposition}

\begin{proof}
Note that $L_i$ is a convex set.

    If $||x-y||_p = 2$, then obviously the unique desired point is $z = \frac{x+y}{2} \in L_i$. If $||x-y||_p > 2$, then there are no such points.

    We are only left to check that if $||x-y||_p <2$ then there exist at least two points $z',z''$ such that $||x-z'||_p = ||y-z'||_p = ||x-z''||_p = ||y-z''||_p = 1$. Indeed, let us consider a horizontal $2$-dimensional plane $P$ passing through the point $\frac{x+y}{2}$ (it exists because $n\geq 2$). Then there exists a line $l \subset P$ orthogonal to the line $xy$ such that $\frac{x+y}{2} \in l$. Then $||x-\frac{x+y}{2}||_{p} = ||y-\frac{x+y}{2}||_{p} < 1$, and $\frac{x+y}{2}$ divides $l$ into two rays. So, we can symmetrically take $z',z''$  with the necessary property on these rays.
\end{proof}

\begin{corollary}\label{cor:distk}
    For any $k \in \N$ and $x,y\in L_1$, we have $||x-y||_p=k$ if and only if $||f(x)-f(y)||_p=k$.
\end{corollary}

\begin{proof}
For $k = 0,1$ the statement obviously holds because $f$ is an isomorphism of the graphs $G_1,G_2$. For $k=2$ it holds due to Proposition \ref{prop:dist2}.

    Let $k>2$. If $||x-y||_p=k$, then there exists a sequence $x_0= x, x_1,x_2,...,x_k = y$ of points on the same line in $L_1$ that satisfy $||x_i-x_{i+1}||_p=1$ for $i=0,1,...,k-1$. For any $i \in \{0,1,...,k-2\}$, we have $||x_i-x_{i+2}||_p = 2$. Then $x_{i+1}$ is the unique point $z$ such that $||x_i-z||_p=||x_{i+2}-z||_p=1$. Since $f$ is an isomorphism of the graphs $G_1,G_2$, $f(x_{i+1})$ is the unique point $z$ such that $||f(x_i)-z||_p=||f(x_{i+2})-z||_p=1$. Hence, by Proposition \ref{prop:dist2}, $f(x_{i+1})$ is the middle of the segment $[f(x_i) f(x_{i+2})]$, and $||f(x_i)-f(x_{i+1})||_p = ||f(x_{i+1})-f(x_{i+2})||_p = 1$ for $i=0,1,...,k-2$. Therefore, $||f(x)-f(y)||_p = ||f(x_0)-f(x_k)||_p = k$.
\end{proof}

\begin{corollary}\label{cor:horizontal2}
Let $a,b \in L_1$ be two different points such that the line $ab$ is horizontal. Then the line $f(a)f(b)$ is horizontal.
\end{corollary}

\begin{proof}
 For any $i \in \{1,2\}$, $\textbf h \in \H$, $\textbf v \in \V \setminus \{0\}$, there exists a sufficiently large $c \in \R$ such that $c\textbf v \notin [0,\eps]^m$, and consequently, $\textbf h+\textbf v \notin L_i$. Hence, if $x_1,x_2,...,x_k,...\in L_i$ is a sequence of different points with the property
$$(*) \forall j \in \N \; \exists! x = x_{j+1} \text{\;such that\;} ||x_j - x||_p = ||x_{j+2}-x||_p = 1,$$
then, due to Proposition \ref{prop:dist2}, all the points $x_j$ lie on the same horizontal line.

\begin{figure}[ht]
\center{\includegraphics[scale=0.5, width=250pt]{Fig10.eps}}
\caption{The condition of horizontality of a segment $ab$ in $L_1$.}
\label{fig:dist2}
\end{figure}

Since $n \geq 2$, there exists a horizontal $2$-dimensional plane $P\subset L_1$ containing $a,b$. Thus,
there exists $k \in \N$ and two sequences of different points $\{x_1=a,x_2,...,x_k, x_{k+1},..\}$, $\{y_1=b, y_2,..,y_k=x_k, y_{k+1},...\}$ on $P$, such that $(*)$ holds for the sequence of $x_j$ and holds for the sequence of $y_j$ (see Fig. \ref{fig:dist2}). Since $f$ is an isomorphism of graphs, $(*)$ also holds for the sequence of $f(x_j)$ and for the sequence of $f(y_j)$.
Hence, the lines $f(x_1)f(x_2)$ and $f(y_1)f(y_2)$ are horizontal, and, consequently, $f(a)f(b)$ is also horizontal.
\end{proof}

For $x\in L_j$ denote by $\pr(x)$ the orthogonal projection of $x$ onto the subspace $\H$. Also denote by $H_x$ ($V_x$) the unique horizontal (vertical) $n$-dimensional ($m$-dimensional) subspace in $L_2$ passing through $x$. Note that for any $x \in L_i$ we have $H_x \subset L_i$, but $V_x \not\subset L_i$.
Denote by $(\cdot, \cdot)$ the standard Euclidean scalar product in the spaces $\H, \V, \T$.

The following lemma is a multidimensional analogue of Lemma \ref{l:main1}.

\begin{lemma}\label{l:main2}
    Let $x_1,...,x_{n+1}, y \in L_i$ be different points. Then the implications $(\widehat\Omega) \Leftrightarrow (\widehat\Gamma) \Leftrightarrow (\widehat \Gamma')$
    %and $\neg(\widehat\Omega) \Leftrightarrow (\widehat\Gamma^-)$
    hold for the following conditions.

    $(\widehat\Gamma)$ For any horizontal ray $l \subset L_i$  from the point $y$, there exist $r > 0$ and $k \in [n+1]$, such that for any $z \in l$ with $||z-y||_p>r$ we have $||z-x_k||_{p} < ||z-y||_{p}$.

    $(\widehat\Gamma')$ There exists a constant $r > 0$ such that for any $z \in \H_y$ with $||z-y||_p>r$ we have $\min\limits_{k\in[n+1]}||z-x_k||_{p} < ||z-y||_{p}$.

    %$(\widehat\Gamma^-)$ There exists a horizontal ray $l \subset L_i$ from the point $y$, and a sequence of different points $z_0 = y, z_1,z_2,... \in l$, such that for any $i \in \N$ we have $||z_i-z_{i+1}||_{p}=1$, and $\min\limits_{k\in [n+1]}||z_i-x_k||_{p} > ||z_i-y||_{p}$.

    $(\widehat \Omega)$. The interior of the convex hull of the points $\pr(x_1),...\pr(x_{p_j+1})$ in the space $\H$ is not empty and contains $\pr(y)$.
\end{lemma}
\begin{proof}[Proof of Lemma \ref{l:main2}.]

\textit{Part 1. The implications $(\widehat\Omega) \Leftrightarrow (\widehat\Gamma)$}.


 As is shown in the proof of Corollary \ref{cor:horizontal2}, any straight line $l \subset L_j$ is horizontal, and, consequently, is contained in $\H_y$. Consider the $(n-1)$-dimensional surface $S_{1,\H} = \{\textbf u \in \H: ||\textbf u||_{p} = 1 \}$ in the space $\H$. Any horizontal ray from $y$ can be represented as $\{y+R \textbf u: R\geq 0\}$ for some $\textbf u \in \H$.
  Thus,
$$\big(I\big).\; (\widehat\Gamma) \Leftrightarrow \forall \textbf u \in S_{1,\H}\;  \exists k \in [n+1]\; \exists r>0 \; \forall R>r:$$
$$||x_k-(y+R\textbf u)||_{p}<||y-(y+R\textbf u)||_p.$$

Consider the $(n+m-1)$-dimensional closed set $B_1 = \{\textbf u \in \T: ||u||_{p} \leq 1\}$ (the unit ball generated by the $l_p$-norm) in the space $\T$. Since $l_p$ is a smooth convex linear norm ($p \in (1,+\infty)$), the ball $B_{1}$ is a convex set with a smooth boundary $\partial B_{1}$.
Hence, for any $\textbf u \in S_{1,\H}$, there exists an unique $(n+m-1)$-dimensional supporting hyperplane $P_{\textbf u}$ to $\partial B_{1}$ at the point $\textbf u$.


The ball $B_1$ of the $l_p$-norm is a symmetric set with respect to the hyperplane $\H$. Then, since $n \geq 2$, the set $\pr(B_1)$ is a convex set in $\H$ with a smooth boundary $\partial (\pr(B_1))$, and $\pr(P_{\textbf u}) \subset \H$ is a $(n-1)$-dimensional supporting hyperplane to the surface $\partial (\pr(B_1)) = S_{1,\H}$ in the space $\H$.

Hence, there exists $s_{\textbf u} \in \H$ such that
$$P_{\textbf u} = \{p \in \T: (s_{\textbf u},p-s_{\textbf u})_E = 0\}.$$

The hyperplane $P_{\textbf u}$ divides the space $\T$ into two half-spaces $\T_{\textbf u}^+$, $\T_{\textbf u}^-$ such that $0 \in \T_{\textbf u}^-$, and
$$\T_{\textbf u}^+ =  \{\textbf w \in \T: (s_{\textbf u}, \textbf w-s_{\textbf u})_E \geq 0\};$$
$$\T_{{\textbf u}}^- =  \{\textbf w \in \T: (s_{\textbf u}, \textbf w-s_{\textbf u})_E < 0\}.$$

The subspace $\pr(P_{\textbf u})$ divides the space $\H$ into two parts $\pr(\T_{{\textbf u}}^+), \pr(\T_{\textbf u}^-)$. For any ${\textbf u}\in S_{1,\H}$ and $\textbf w \in \T$ represented as $\textbf w = \textbf h+\textbf v, \textbf h \in \H, \textbf v \in \V$, we have 
 $$(s_{\textbf u},\textbf w-s_{\textbf u})_E = (s_{\textbf u},\textbf h+\textbf v-s_{\textbf u})_E = (s_{\textbf u},\textbf h-s_{\textbf u})_E + (s_{\textbf u},\textbf v)_E = (s_{\textbf u},\textbf h-s_{\textbf u})_E,$$ because $s_{\textbf u} \in \H$ and $\textbf v \in V$ are orthogonal vectors. Hence, 
$$\big(II\big).\;\textbf w \in \H_{\textbf u}^+ \Leftrightarrow \pr(\textbf w) \in \pr(H_{\textbf u}^+).$$

For any $\textbf u \in S_{1,\H}, a \in \T$, we have: 
$$\big(III\big).\; \forall r>0 \; \exists R>r\;\; \textbf u+\frac{a}{R} \notin B_1 \Leftrightarrow a \in \T_{\textbf u}^+.$$
For $k \in [n+1]$, denote the vector $y-x_k$ by $\textbf a_k$. Any point $z \in \H_y \setminus \{y\}$ can be represented as $z = y+r_z \cdot \textbf u_z$, where $\textbf u_z \in S_{1,\H}, r_z > 0$. Then
$$\big(IV\big).\; ||x_k-z||_{p}>||y-z||_{p} \Leftrightarrow||y-(z+\textbf a_k)||_{p} > ||y-z||_{p} \Leftrightarrow$$
$$\Leftrightarrow r_z \textbf u_z+\textbf a_k \notin r_z \cdot B_1 \Leftrightarrow \textbf u_z+\frac{\textbf a_k}{r_z} \notin B_1.$$

Condition $(\widehat \Omega)$ is equivalent to the following (see Fig. \ref{fig:lemma_main2_omega} for an illustration):
$$\big(V\big). \;(\widehat\Omega) \Leftrightarrow \forall \textbf u \in S_{1,\H}\; \exists k \in [n+1]:\; (\pr(\textbf a_k), \textbf u) < 0.$$


\begin{figure}[ht]
\center{\includegraphics[scale=0.5, width=250pt]{Fig11.eps}}
\caption{a) The case $n = 2$, $(\Omega)$ holds. b) The case $n = 2$, $(\Omega)$ does not hold.}
\label{fig:lemma_main2_omega}
\end{figure}

Thus,
$$\neg(\widehat\Gamma) \Leftrightarrow \text{ by $(I)$ } \Leftrightarrow$$
$$\Leftrightarrow \exists \textbf u \in S_{1,\H}\;  \forall k \in [n+1]\; \forall r>0 \; \exists R>r:$$
$$||x_k-(y+R\textbf u)||_{p}<||y-(y+R\textbf u)||_p\Leftrightarrow$$
$$\Leftrightarrow \text{ by $(IV)$ } \Leftrightarrow  \exists \textbf u \in S_{1,\H}\;  \forall k \in [n+1]\; \forall r>0 \; \exists R>r:\; \textbf u+\frac{\textbf a_k}{R} \notin B_1\Leftrightarrow $$
$$\Leftrightarrow \text{ by $(III)$ } \Leftrightarrow \exists \textbf u \in S_{1,\H}\;\forall k \in [n+1]:\; \textbf a_k \in \T_{\textbf u}^+\Leftrightarrow $$
$$\Leftrightarrow \text{ by $(II)$ } \Leftrightarrow \exists \textbf u \in S_{1,\H}\;\forall k \in [n+1]:\; \pr(\textbf a_k) \in \pr(\T_{\textbf u}^+)\Leftrightarrow$$
$$\Leftrightarrow \exists \textbf u \in S_{1,\H}\;\forall k \in [n+1]:\; (\pr(\textbf a_k),\textbf u)_E \geq 0 \Leftrightarrow \text{ by $(V)$ } \Leftrightarrow\neg(\widehat\Omega).$$

