\caption{The case $n = 2$, $(\widehat\Omega), (\widehat\Gamma)$ hold.}
\label{fig:main_lemma_2_example_1}
\end{figure}

\begin{figure}[ht]
\center{\includegraphics[scale=0.5, width=290pt]{Fig13.eps}}
\caption{The case $n = 2$, $\neg(\widehat\Omega), (\widehat\Gamma^-)$ hold.}
\label{fig:main_lemma_2_example_2}
\end{figure}

Therefore, $(\widehat\Omega) \Leftrightarrow (\widehat\Gamma)$
(see Figs. \ref{fig:main_lemma_2_example_1}, \ref{fig:main_lemma_2_example_2} for an illustration of the key idea).
%Since conditions $(\widehat\Gamma)$ and $(\widehat\Gamma^-)$ are mutually exclusive, we are only left to verify the implication $\neg(\widehat\Omega) \Rightarrow (\widehat\Gamma^-)$.


\textit{Part 2. The implications $(\widehat\Gamma) \Leftrightarrow (\widehat\Gamma')$}.

The implication $(\widehat\Gamma') \rightarrow (\widehat\Gamma)$ is obvious.

Let $(\widehat\Gamma)$ holds. Then, for any fixed $\textbf{u} \in S_{1,\H}$ and horizontal ray $l_{\textbf u} = \{y+R\textbf{u} \in \H_y :\; R \geq 0\}$, there exists a non-empty set $\mathcal R_\textbf{u}$ of constants $r > 0$ such that for any $z \in l_{\textbf u}$ with $||z-y||_p > r$ we have
$$\min\limits_{k\in[n+1]} ||z-x_k||_p < ||z-y||_p.$$

Denote $r(\textbf{u}) = \inf\limits_{r \in \mathcal{R}_\textbf{u}} r$. By the construction of $\mathcal{R}_\textbf{u}$, we have $r(\textbf{u}) \in \mathcal{R}_\textbf{u}$.

Obviously, $z \in \H_y$ if and only if there exists ${\textbf u} \in S_{1,\H}$ such that $z \in l_{\textbf u}$.

Since the functions $||z-y||_p$ and $||z-x_k||_p$ for $k \in [n+1]$ are continuous, the function $r(\textbf{u})$ is also continuous on the set $S_{1,\H}$. Then, due to compactness of $S_{1,\H}$, there exists $r = \max\limits_{\textbf{u} \in S_{1,\H}} r(\textbf{u}) < +\infty$. Then $(\widehat\Gamma')$ holds.
%This completes the proof (see Figs. \ref{fig:main_lemma_2_example_1}, \ref{fig:main_lemma_2_example_2} for an illustration of the key idea).

\end{proof}

Now we will prove an analogue of Proposition \ref{prop:eq}.

\begin{proposition}\label{prop:C}
     Given $i\in \{1,2\}$, there exists a constant $C_i=C_i(\eps_i)>0$, such that for any $a,b \in L_i$, if $\rho_{i}(a,b) > C_i$ then $\rho_{i}(a,b)=\left\lceil ||a-b||_{p}\right\rceil$.
\end{proposition}

\begin{proof}
If $||a-b||\in \N$, then the statement is obvious.

Let $||a-b||_p = m+\delta, m\in \N, m>10, \delta \in (0, 1)$.

Consider the set $S = \{x \in L_i: ||x-a||_p=1\}$.

Let $x_1 = [a,b] \cap S$. We have $||x_1-b||_p = m-1+\delta < m$.

Denote by $B = \{x \in \T: ||x||_p=1 \}$ the unit ball in the metric $l_p$ with center $0$ and radius $1$. Denote by $\partial B$ its boundary, it is a smooth surface. For any $u \in \partial B$ consider the maximal angle $\theta(u) \in (0,\pi)$ between the vector $-u$ and a ray $l$ from the point $u$ such that $l$ is contained in the supporting hyperplane to $\partial B$ at the point $u$ (the maximum exists due to compactness reasoning). Since $\partial B$ is compact, the number $\theta = \sup_{u \in \partial B} \theta(u)$ is well defined and is less than $\pi$.

Consider the ball
$$B_{b,a} = \{x \in \T: ||x-b||_p \leq ||a-b||_p\} = ||a-b||_p\cdot B+b.$$ 
By construction of the number $\theta$, for any $x \in \T$ we have
$$\angle bax > \theta \Rightarrow x \notin B_{b,a} \Rightarrow ||b-x||_p>||b-a||_p>m.$$

For any sufficiently large $m$, the angle between the line $ab$ and the subspace $\H_a$ is less than $\pi-\theta$. Thus, there exists a ray $l\subset \H_a$ from the point $a$ such that $\angle bax > \theta$. Take the point $x_2 = l \cap S$ (it exists because $\H_a \subset L_i$). We have $\angle bax_2 > \theta \Rightarrow ||b-x_2||_p > m$.

Therefore, we have two points $x_1,x_2 \in S = \{x \in L_i: ||x-a||_p=1\}$, such that
$$||x_1-b||_p < m < ||x_2-b||_p.$$

Since $n\geq 2$, the set $S$ is connected. The function $\lambda(x) = ||x-a||_p$ is continuous on the set $S$, and $\lambda(x_1) < m < \lambda(x_2)$. Hence, there exists a point $x_3 \in S \subset L_i$, such that $\lambda(x_3)=m$.

Then 
$$\rho_{i}(a,b) \geq \rho_{i}(b,x_3)+\rho_{i}(a,x_3)=||b-x_3||_p + ||a-x_3||_p = m+1;$$
$$\rho_{i}(a,b) \leq ||b-a||_p = m+\delta.$$

Hence, $\rho_{i}(a,b) = m+1  = \left\lceil ||a-b||_{p}\right\rceil$.
\end{proof}

\begin{corollary}\label{cor:C}
    There exists a constant $C=C(\eps_1,\eps_2)=\max(C_1,C_2)>0$, such that for any $i\in \{1,2\}, a,b \in L_i$, if $\rho_{i}(a,b) > C$ then $\rho_{i}(a,b)=\left\lceil ||a-b||_{p}\right\rceil$.
\end{corollary}

By Corollaries \ref{cor:horizontal2} and \ref{cor:C}, we immediately get the following corollary.

\begin{corollary}\label{cor:gamma}
    Let $x_1,...,x_{n+1},y \in L_1$ be different points. Then condition $(\widehat\Gamma')$ of Lemma \ref{l:main2} holds for $x_1,...,x_{n+1},y $ if and only if it holds for $f(x_1),...,f(x_{n+1}),f(y)$.
\end{corollary}

Thus, we can show that $f$ preserves the "vertical" sets $V_x$.

\begin{lemma}\label{l:vert2}
Given $x_1,x_2 \in L_1$, we have $x_2 \in V_{x_1}$ if and only if $f(x_2) \in V_{f(x_1)}$.
\end{lemma}

\begin{proof}
Since $x_2 \in V_{x_1}$, we get $\pr(x_1) = \pr(x_2)$. Then there are no such points $x_3,...,x_{n+1}$ that the interior of the convex hull of $x_1,...,x_{n+1}$ in $\H$ is not an empty set. This implies that there are no points $x_3,...,x_{n+1},y \in L_1$ such that condition $(\widehat\Omega)$ of Lemma \ref{l:main2} holds for $x_1,...,x_{n+1},y$. Then, by Lemma \ref{l:main2}, there are no such points $x_3,...,x_{n+1},y\in L_1$ that condition $(\widehat\Gamma')$ holds for $x_1,...,x_{n+1},y$. Hence, due to Corollary \ref{cor:gamma}, there are no such points $x_3,...,x_{n+1},y\in L_1$ that condition $(\widehat\Gamma')$ holds for $f(x_1),...,f(x_{n+1})$, $f(y)$. Hence, there are no such points $x'_3,...,x'_{n+1},y' \in L_2$ that $(\widehat\Omega)$ holds for $f(x_1)$, $f(x_2)$, $x_3'$, $...,x_{n+1}',y'$, and consequently $\pr(f(x_1)) = \pr(f(x_2))$. Then $f(x_2) \in V_{f(x_1)}$.
\end{proof}

Now we can also show that $f$ preserves the horizontal lines and the order of the points on the horizontal lines.

\begin{lemma}\label{l:hor_line}
    Let $x_1,x_2,x_3 \in L_1$ be different points on the same horizontal line, and let $y \in (x,z)$. Then $f(x_1),f(x_2),f(x_3) \in L_2$ are different points on the same horizontal line and $f(x_2) \in (f(x_1),f(x_3))$.
\end{lemma}

\begin{proof}
The projections $\pr(x_1),\pr(x_2), \pr(x_3)$ are pairwise different because $x_1,x_2,x_3$ are different points on the same $n$-dimensional horizontal hyperplane $H_{x_1}$. Corollary \ref{cor:horizontal2} shows that $f(x_2),f(x_3) \in H_{f(x_1)}$. Due to Lemma \ref{l:vert2}, the projections $\pr f(x_1),\pr f(x_2),\pr f(x_3)$ are different. 

Since $x_1,x_2,x_3$ are on the same line $l$, then $\pr(x_1),\pr(x_2), \pr(x_3)$ are on the same horizontal line. Then there are no such points $x_4,...,x_{n+1}\in L_1$ that the interior of the convex hull of $x_1,...,x_{n+1}$ in $\H$ is an empty set (in the case $n=2$, the interior of the convex hull of $x_1,...,x_3$ in $\H$ is an empty set). Then there are no points $x_4,...,x_{n+1},y\in L_1$ such that condition $(\widehat\Omega)$ of Lemma \ref{l:main2} holds for $x_1,...,x_{n+1},y$. Then, by Lemma \ref{l:main2}, there are no points $x_4,...,x_{n+1},y\in L_1$ such that condition $(\widehat\Gamma')$ of Lemma \ref{l:main2} holds for $x_1,...,x_{n+1},y$. Due to Corollary \ref{cor:gamma}, there are no points $x_4,...,x_{n+1},y\in L_1$ such that condition $(\widehat\Gamma')$ of Lemma \ref{l:main2} holds for $f(x_1),...,f(x_{n+1}),f(y)$. Hence, there are no such points $x'_4,...,x'_{n+1},y'\in L_2$ that condition $(\widehat\Omega)$ of Lemma \ref{l:main2} holds for $f(x_1),f(x_2),f(x_3),x'_4,...,x'_{n+1},y'$. Hence, $f(x_1),f(x_2),f(x_3)$ are on the same horizontal line.

Now we will prove that $f(x_2)\in [f(x_1),f(x_3)]$.

Take the constant $C$ as guaranteed by Corollary \ref{cor:C}.

Denote the set
$$W_{x_1,x_2,x_3} = \{w \in l: \min_{i \in \{1,2,3\}}\rho_1(w,x_i) > \max_{i<j;\, i,j \in \{1,2,3\}} \rho_1(x_i,x_j)+C+1 \}.$$

For any $w \in W_{x_1,x_2,x_3}$ and $i \in \{1,2,3\}$ we have $\rho_1(w,x_i) > C$. Then, by Corollary \ref{cor:C},
$$\forall w \in W_{x_1,x_2,x_3}:\; ||w-x_i||_p \geq \rho_1(w,x_i)-1 \geq$$
$$\geq \max_{i<j;\, i,j \in \{1,2,3\}} \rho_1(x_i,x_j)+C \geq \max_{i<j;\, i,j \in \{1,2,3\}} ||x_i-x_j||_p+C.$$

Hence, any point $w \in W_{x_1,x_2,x_3}$ is not contained in the segment $[x_1,x_3]$.

Thus, by obvious geometric reasoning,
$$\forall w \in W_{x_1,x_2,x_3}:\; ||w-x_2||_p \geq \min_{i\in\{1,3\}} ||w-x_i||_p;$$
$$\forall w \in W_{x_1,x_2,x_3}:\; ||w-x_2||_p > C.$$

Hence, due to Corollary \ref{cor:C},
$$(*)\forall w \in W_{x_1,x_2,x_3}:\; \rho_1(w,x_2) \geq \min_{i\in\{1,3\}} \rho_1(w,x_i).$$

The first part of this proof shows that the set $f(l)$ is a horizontal line in $L_2$. Analogously to $W_{x_1,x_2,x_3}$, denote the set
$$\; W'_{x_1,x_2,x_3} = \{w \in f(l): \min_{i \in \{1,2,3\}}\rho_2(w,f(x_i)) > $$
$$>\max_{i<j;\, i,j \in \{1,2,3\}} \rho_2(f(x_i),f(x_j))+C+1 \}.$$

Since $f$ is an isomorphism of the graphs $G_1,G_2$, for any $ a,b \in \T$ we have $\rho_1(a,b) = \rho_2(f(a),f(b))$. Then
$$f(W_{x_1,x_2,x_3}) = W'_{x_1,x_2,x_3};$$
$$(*')\; \forall w \in W'_{x_1,x_2,x_3}:\; \rho_2(w,f(x_2)) \geq \min_{i\in\{1,3\}} \rho_2(w,f(x_i)).$$

Assume that $f(x_2) \notin [f(x_1),f(x_3)]$. Take a point $w \in f(W_{x_1,x_2,x_3})$ such that $f(x_2) \in [f(x_1),w]\cap [f(x_3),w]$, and $||w-f(x_2)||_p \in \N$, see Fig. \ref{fig:order_on_hor_line}. Then $\rho_2(w,f(x_2)) = ||w-f(x_2)||_p < \min(\rho_2(w,f(x_1)), \rho_2(w,f(x_3))).$ This contradicts $(*')$.

Hence, $f(x_2)\in [f(x_1),f(x_3)]$.
\end{proof}

