\center{\includegraphics[scale=0.5, width=250pt]{Fig14.eps}}
\caption{The point $w \in f(W_{x_1,x_2,x_3})$ such that $f(x_2) \in [f(x_1),w]\cap [f(x_3),w]$, and $||w-f(x_2)||_p \in \N$.}
\label{fig:order_on_hor_line}
\end{figure}

The following lemma shows that $f$ preserves the distances on the horizontal lines.

\begin{lemma}\label{l:ratio}
    Let $x,y \in L_1$ be on the same horizontal line, and let $||x-y|| \in \Q$. Then $||x-y||_p$ = $||f(x)-f(y)||_p$.
\end{lemma}

\begin{proof}
Due to Proposition \ref{prop:dist2}, $f$ preserves the integer distances on the horizontal lines.

    Let $x,z$ be on the same horizontal line $l$, let $y\in [x,z]$, and let $\frac{||x-y||_p}{||z-y||_p} = \frac{r}{q}$. Take a horizontal plane $P$ such that $l \in P$ (it exists because $n\geq 2$.
    Then, by elementary geometric reasoning, there exist different horizontal lines $l_x,l_y,l_z \subset P$ and different points $x_0=x,x_1,...,x_r, z_0=z,z_1,...,z_q \in P$, such that:

    $(i)$ $l\notin \{l_x,l_y,l_z\}$;

    $(ii)$ $\forall i \in [r]:\; ||x_i - x_{i+1}||_p = 1$;

    $(iii)$ $\forall i \in [q]:\; ||z_i - z_{i+1}||_p = 1$;

    $(iv)$ $x_r, z_q, y \in l_y$;

    $(iv)$ $y \in [x_r,z_q]$;

    $(vi)$ $l_x \cap l_z = \varnothing$,

    as is shown in Fig. \ref{fig:ratio}. 

    Then, due to Lemma \ref{l:hor_line}, we get the analogous properties $(i)-(vi)$ for $f(l_x),f(l_y),f(l_z)$, $f(l),f(x_i),f(z_i)$. Hence, $\frac{||f(x)-f(y)||_p}{||f(z)-f(y)||_p} = \frac{r}{q} = \frac{||x-y||_p}{||z-y||_p}$.

    Then $f$ preserves the rational distances on the horizontal lines (that is, if $||x-y||_p \in \Q$, then $||f(x)-f(y)||_p \in \Q$). Due to Lemma \ref{l:hor_line}, $f$ preserves the order of points on the horizontal lines. Therefore, $f$ preserves all the real distances on the horizontal lines.
\end{proof}


