\caption{The points $x,y,z$ are on the same horizontal line, $\frac{||x-y||_p}{||z-y||_p} = \frac{5}{3}$}.
\label{fig:ratio}
\end{figure}

Now we can introduce a simple construction that distinguishes $\eps_1\neq\eps_2$, instead of $(N,M)$-comb in the proof of Theorem \ref{t:planar}.

Let $d_{m,p}$ be the diameter of the metric space on $[0,1]^m$ with $l_p$-metric.
\begin{lemma}\label{l:final}
    The condition $\eps_i \geq \eps$ holds if and only if there exist points $x,y,z \in L_i$ and numbers $k \in \N, \delta \in \R$ such that $y \in V_x, z\in H_x, ||y-z||_p = k, ||z-x||_p = \delta$, and $k^p - \delta^p \geq \eps^p\cdot d_{m,p}^p$.
\end{lemma}

\begin{proof}
The diameter of the set $H_x$ in $L_i$ is equal to $\eps\cdot d_{m,p}$.
    Since $\T = \H \times \V$, it is enough to apply the equality
    $$||y-z||_p = \left(||x-y||_p^p+||x-z||_p^p \right)^{1/p}.$$
\end{proof}

\begin{corollary}\label{cor:final}
    $\eps_1 \geq \eps$ if and only if $\eps_2 \geq \eps$.
\end{corollary}

\begin{proof}
    By Lemma \ref{l:final}, if $\eps_1 \geq \eps$, then there exist points $x,y,z \in L_1$ and numbers $k \in \N, \delta \in \R$ such that $y \in V_x, z\in H_x, ||y-z||_p \leq k, ||z-x||_p = \delta$, and $k^p - \delta^p \geq \eps^p\cdot d_{m,p}^p$. 

    Due to Lemma \ref{l:hor_line}, the line $f(x)f(z)$ is horizontal because $xz$ is horizontal. Then $f(z) \in H_{f(x)}$. Due to Lemma \ref{l:vert2}, $f(y) \in V_{f(x)}$, because $y \in V_x$. Due to Lemma \ref{l:ratio}, we have $||f(z)-f(x)||_p = ||z-x||_p = \delta$. Due to Proposition \ref{cor:distk}, we have $||f(y)-f(z)|| = ||y-z||=k$.

    So, there exist points $f(x),f(y),f(z) \in L_2$ and numbers $k \in \N, \delta \in \R$ such that $f(y) \in V_{f(x)}, f(z)\in H_{f(x)}, ||f(y)-f(z)||_p \leq k, ||f(z)-f(x)||_p = \delta$, and $k^p - \delta^p \geq \eps^p\cdot d_{m,p}^p$. Then, due to Lemma \ref{l:final}, $\eps_2 \geq \eps$.
\end{proof}

Hence, by Corollary \ref{cor:final}, we get $\eps_1=\eps_2$, which completes the proof of Theorem \ref{t:main}.

\section{Appendix: proof of Theorem \ref{t:appendix}}

Theorem \ref{t:appendix} is a simple corollary of the proof of Theorem \ref{t:main}.

Let $\phi$ be an automorphism of the unit distance graph $G$ of layer $L = L(n,1,2,\eps) = \R^n \times [0,\eps]$.

    Due to Lemmas \ref{l:vert2}, \ref{l:hor_line}, Lemma \ref{l:ratio} applied to $L_1=L_2 = L, f=\phi$, the map $\phi$ preserves the horizontal lines, the vertical segments, and the distances on the horizontal lines.

    Let $x,y \in L$ form a vertical segment and let $||x-y||_2=\alpha$. There exist $z \in L$ and $k \in \N$ such that $z \in H_x, ||z-x||_2 = \sqrt{k^2-\alpha^2}, ||z-y||_2=k$. Then $\phi(z) \in H_{\phi(x)}$, $\phi(y) \in V_{\phi(x)}$, $||z-y||_2 = ||\phi(z)-\phi(y)||_2 = k$, and $||\phi(z)-\phi(x)||_2 = ||z-x||_2 = \sqrt{k^2-\alpha^2}$. Hence,    
    $$||\phi(x)-\phi(y)||_2 = \sqrt{||\phi(z)-\phi(y)||_2^2 - ||\phi(z)-\phi(x)||_2^2} = \alpha.$$

     Thus, $\phi$ preserves the lengths of the vertical segments and the horizontal segments. Since $||\cdot||_2$ is the standard Euclidean norm, $\phi$ is an isometry.

