	\section{Prisms and Anti-prisms}
	\label{app:C}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	In this appendix, we provide details about the equilibria of the electrostatic potential for unit point charges placed at the vertices of regular prisms and anti-prisms.
	After introducing the building blocks of the analysis, we focus on the square and triangular anti-prisms.

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\subsection{Regular polygons}
	\label{app:C.1}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	Let $V_0$ be the electric potential generated by unit point charges located at the vertices of a regular $N$-gon centered at the origin, $0 \in \R^3$, and placed on the horizontal plane spanned by the first two coordinate vectors. 
	Denote by $R$ the radius of the circle that passes through its vertices, and by $\alpha = \frac{2\pi}{N}$ the smallest angle that is a rotation symmetry of the $N$-gon.
	We start by proving that the partial derivatives are symmetric with respect to the horizontal plane, and they all vanish at the origin.
	\begin{lemma}
		\label{lem:derivatives_for_prism}
		Let $V_0 \colon \R^3 \to \R$ be the electrostatic potential of unit point charges at the vertices of a regular $N$-gon, as described, and write $x=(x_1,x_2,x_3)$ for a point with its Cartesian coordinates in $\R^3$.
		Then
		\begin{align}
			\frac{\partial V_0}{\partial x_3} (x_1,x_2,x_3) = - \frac{\partial V_0}{\partial x_3} (x_1,x_2,-x_3)
			\mbox{\rm ~~and~~}
			\frac{\partial V_0}{\partial x_1} (0,0,x_3) &= \frac{\partial V_0}{\partial x_2} (0,0,x_3) = 0.
		\end{align}
	\end{lemma}
	\begin{proof}
		The configuration is invariant by reflection through the $x_3=0$ plane, which contains the $N$-gon.
		Hence, $V_0(x_1,x_2,x_3) = V_0(x_1,x_2,-x_3)$ and differentiating with respect to $x_3$ gives the first relation.
		To see the second relation, note that the invariance of the $N$-gon under rotations of the horizontal plane by an angle $\alpha$ implies
		\begin{align} 
			V_0(x_1,x_2,x_3) &= V_0(x_1 \cos{\alpha} + x_2 \sin{\alpha}, -x_1 \sin{\alpha} + x_2 \cos{\alpha} , x_3),
		\end{align}
		for all $x=(x_1,x_2,x_3) \in \R^3$. 
		Differentiating with respect to $x_1$ and $x_2$, respectively, and evaluating at $x_1 = x_2 = 0$ yields
		\begin{align}
			\frac{\partial V_0}{\partial x_1} (0,0,x_3) &= \cos{\alpha} \frac{\partial V_0}{\partial x_1} (0,0,x_3) - \sin{\alpha} \frac{\partial V_0}{\partial x_2} (0,0,x_3) ; \\
			\frac{\partial V_0}{\partial x_2} (0,0,x_3) &= \sin{\alpha} \frac{\partial V_0}{\partial x_1} (0,0,x_3) + \cos{\alpha} \frac{\partial V_0}{\partial x_2} (0,0,x_3) .
		\end{align}
		This gives a system of linear equations for $\frac{\partial V_0}{\partial x_1} (0,0,x_3)$ and $\frac{\partial V_0}{\partial x_1} (0,0,x_3)$ whose only solution is when both vanish, as claimed.
	\end{proof}

	It will also be useful to have the second partial derivative at the origin in vertical direction.
	\begin{lemma}
		\label{lem:eigenvalue_for_prism}
		For $V_0 \colon \R^3 \to \R$ as before and all $x_3 \in \R$, we have 
		\begin{align}
			\frac{\partial^2 V_0}{ (\partial x_3)^2} (0,0, x_3 ) &= - \frac{N}{(R^2+x_3^2)^{5/2}}\left( R^2 - 2 x_3^2 \right).
			\label{eqn:E2}
		\end{align}
	\end{lemma}
	\begin{proof}
		Denote the vertices of the $N$-gon by $A_i = (a_{i,1},a_{i,2},0)$, for $i=1,2, \ldots , N$, and write $r_i$ for the distance of $A_i$ from a point $x = (x_1, x_2, x_3)$.
		Then the first and second partial derivatives along the vertical direction are
		\begin{align}
			\frac{\partial V_0}{ \partial x_3} 
			&= -\sum_{i=1}^N \frac{1}{r_i^{2}} \frac{\partial r_i}{\partial x_3} 
			= -\sum_{i=1}^N \frac{x_3}{r_i^{3}} ; \\
			\frac{\partial^2 V_0}{(\partial x_3)^2} 
			&= -\sum_{i=1}^N \left( \frac{1}{r_i^{3}} - 3\frac{x_3}{r_i^{4}} \frac{\partial r_i}{\partial x_3} \right)
			= -\sum_{i=1}^N \left(  \frac{1}    {r_i^{3}} - 3 \frac{x_3^2}{r_i^{5}} \right)
			= -\sum_{i=1}^N \frac{1}{r_i^{5}}\left( r_i^2 - 3 x_3^2 \right).
		\end{align}
		Evaluating the second partial derivative at $(0,0,x_3)$, we have $r_i^2=R^2+x_3^2$ independent of $i$, which implies \eqref{eqn:E2}.
	\end{proof}

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\subsection{Rotated prisms}
	\label{app:C.2}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	We get a prism by connecting a regular $N$-gon with a copy of itself translated in an orthogonal direction.
	If we first rotate the copy by an angle $\beta$---around its center and within its plane---we call the convex hull of the two $N$-gons a \emph{$\beta$-rotated prism}.
	For $\beta = \frac{\alpha}{2}$, this is an anti-prism.
	Its \emph{axis} is the line that passes through the centers of the two $N$-gons, its \emph{radius} is the distance of the vertices from this line, and its \emph{height} is the distance between the planes that contain the two $N$-gons.
	We now consider the electrostatic potential obtained by placing unit point charges at the vertices of such a $\beta$-rotated prism.
	Supposing the $N$-gons lie in horizontal planes at distance $\frac{h}{2}$ above and below the origin, the electrostatic potential is
	\begin{align}
		V(x_1,x_2,x_3) &= V_0(x_1,x_2,x_3+\tfrac{h}{2}) \nonumber \\
		&+ V_0(x_1 \cos{\beta} + x_2 \sin{\beta}, -x_1 \sin{\beta} + x_2 \cos{\beta} ,x_3-\tfrac{h}{2}) .
		\label{eqn:beta-potential}
	\end{align}
	Not surprisingly, the type of the equilibrium at the origin depends on the height, but with the exception of a particular height, it does not depend on the angle of the rotation.
	\begin{theorem}\label{thm:center_of_prism}
		Let $\beta \in \R / 2 \pi \Z$, $R>0$, and $h>0$. 
		Consider the electrostatic potential generated by unit point charges at the vertices of a $\beta$-rotated prism with radius $R$ and height $h$. 
		Then, its center is a non-degenerate equilibrium iff $h \neq \sqrt{2}R$, in which case the center is a $1$-saddle if $h < \sqrt{2} R$ and a $2$-saddle if $h > \sqrt{2} R$.
		Moreover, in the latter case there are two additional $1$-saddles along the axis of the $\beta$-rotated prism.
	\end{theorem}
	\begin{proof}
		To use the form of the potential in \eqref{eqn:beta-potential}, we assume that the two $N$-gons of the $\beta$-rotated prism lie in horizontal planes and its center is the origin in $\R^3$.
		We start by confirming that the origin is always an equilibrium.
		Using Lemma~\ref{lem:derivatives_for_prism}, we obtain
		\begin{align}
			\frac{\partial V}{\partial x_i} (0,0,0) & = \frac{\partial V_0}{\partial x_i} (0,0,\tfrac{h}{2}) + \frac{\partial V_0}{\partial x_i} (0,0,- \tfrac{h}{2}) = 0 ,
		\end{align}
		which for $i = 1, 2$ is true because both partial derivatives vanish, and for $i = 3$ follows from the symmetry across the horizontal coordinate plane.
		Next we investigate the Hessian at the origin.
		By differentiating the identity $\frac{\partial V_0}{\partial x_3} (x_1,x_2,x_3) = - \frac{\partial V_0}{\partial x_3} (x_1,x_2,-x_3)$ with respect to $x_1$, $x_2$, and $x_3$, we obtain 
		\begin{align}
			\frac{\partial^2 V_0}{\partial x_i \partial x_3} (x_1,x_2,x_3) & = - \frac{\partial^2 V_0}{\partial x_i \partial x_3} (x_1,x_2,-x_3) ; \\
			\frac{\partial^2 V_0}{(\partial x_3)^2} (x_1,x_2,x_3) & = \frac{\partial^2 V_0}{ (\partial x_3)^2} (x_1,x_2,-x_3),
		\end{align}
		for $i = 1,2$.
		Hence, using the first of these identities, we have
		\begin{align}
			\frac{\partial^2 V}{\partial x_i \partial x_3}(0,0,0) = \frac{\partial^2 V_0}{\partial x_i \partial x_3} (0,0, \tfrac{h}{2}) + \frac{\partial^2 V_0}{\partial x_i \partial x_3} (0,0, -\tfrac{h}{2}) =0.
		\end{align}
		This shows that $\lambda_3 = \frac{\partial^2 V}{(\partial x_3)^2}(0,0,0)$ is an eigenvalue of the Hessian at the origin.
		Using the second identity above, we see that this eigenvalue satisfies
		\begin{align}
			\lambda_3 &= \frac{\partial^2 V}{(\partial x_3)^2}(0,0,0) = \frac{\partial^2 V_0}{\partial x_i \partial x_3} (0,0, \tfrac{h}{2}) + \frac{\partial^2 V_0}{\partial x_i \partial x_3} (0,0, -\tfrac{h}{2}) = 2 \frac{\partial^2 V_0}{(\partial x_3)^2} (0,0, \tfrac{h}{2}).
		\end{align}
		The rotational symmetry by $\beta \neq 0$ then implies that the remaining two eigenvalues must coincide: $\lambda_1 = \lambda_2 = \lambda$.
		Furthermore, since $V$ is harmonic, we have $\lambda = -\frac{\partial^2 V_0}{(\partial x_3)^2} (0,0, \frac{h}{2})$. 
		%
		It remains to compute this quantity and show it vanishes precisely when $h = \sqrt{2} R$ as claimed in the statement. 
		This can be done by making use of Lemma \ref{lem:eigenvalue_for_prism} to obtain
		\begin{align}
			\frac{\partial^2 V}{(\partial x_3)^2}(0,0,0) = - \frac{2N}{(R^2+x_3^2)^{5/2}}\left( R^2 - \tfrac{h^2}{2} \right),
		\end{align}
		which vanishes iff $h=\sqrt{2}R$.
		Furthermore, the eigenvalues of the Hessian at the origin are   
		\begin{align}
			\lambda_3 & = - \frac{2N}{(R^2+x_3^2)^{5/2}}\left( R^2 - \tfrac{h^2}{2} \right) ; \\
			\lambda_1 = \lambda_2 & = \frac{N}{(R^2+x_3^2)^{5/2}}\left( R^2 - \tfrac{h^2}{2} \right) .
		\end{align}
		We therefore conclude that for $h<\sqrt{2}R$ we have $\lambda_1=\lambda_2>0$ and $\lambda_3<0$, so the origin is a $1$-saddle. On the other hand, if $h>\sqrt{2}R$ we have $\lambda_1=\lambda_2<0$ and $\lambda_3>0$, and so the origin is a $2$-saddle.
		However, in this case there are at least two additional equilibria along the axis of the $\beta$-rotated prism, which by construction is the $x_3$-axis.
		To prove their existences, we compute the derivatives of $V$ along this axis:
		\begin{align}
			\frac{\partial V}{\partial x_i} (0,0,x_3) & = \frac{\partial V_0}{\partial x_i} (0,0,x_3+\tfrac{h}{2}) + \frac{\partial V_0}{\partial x_i} (0,0,x_3- \tfrac{h}{2}) = 0 +0 =0 ,
		\end{align}
		for $i=1,2$. 
		Hence, we need only look for zeroes of $\frac{\partial V}{\partial x_3} (0,0,x_3)$, which we compute as
		\begin{align}
			\frac{\partial V}{\partial x_3} (0,0,x_3) &= \frac{\partial V_0}{\partial x_3} (0,0,x_3+\tfrac{h}{2}) + \frac{\partial V_0}{\partial x_3} (0,0,x_3- \tfrac{h}{2}) .
		\end{align}
		To compute the two terms on the right-hand side, we use Lemma \ref{lem:eigenvalue_for_prism} and find that $\frac{\partial V_0}{ \partial x_3} = -\sum\nolimits_{i=1}^N \frac{x_3}{r_i^{3}}$, where $r_i(x_1,x_2,x_3)^2=(x_1+a_{i1})^2+(x_2-a_{i2})^2+x_3^2$.
		From this it follows that
		\begin{align}
			\frac{\partial V}{\partial x_3} (0,0,x_3) &=  -\sum\nolimits_{i=1}^N \frac{x_3+\frac{h}{2}}{r_i^{3}(0,0,x_3+\frac{h}{2})}  -\sum\nolimits_{i=1}^N \frac{x_3- \frac{h}{2}}{r_i^{3}(0,0,x_3-\frac{h}{2})} \\
			&=  -N \frac{x_3+\frac{h}{2}}{\left(  R^2 + (x_3+\frac{h}{2})^2 \right)^{3/2}}  - N \frac{x_3- \frac{h}{2}}{\left(  R^2 + (x_3-\frac{h}{2})^2 \right)^{3/2}} .
		\end{align}
		Evaluating this at the top and bottom of the $\beta$-rotated prism, we obtain
		\begin{align}
			\frac{\partial V}{\partial x_3} (0,0,\tfrac{h}{2})=-\frac{h}{(R^2+h^2)^{3/2}} <0 \mbox{\rm ~~and~~} \frac{\partial V}{\partial x_3} (0,0,-\tfrac{h}{2})=\frac{h}{(R^2+h^2)^{3/2}}>0.
		\end{align}
		On the other hand, further differentiating with respect to $x_3$, as in the proof of Theorem \ref{thm:center_of_prism}, we find that
		\begin{align}
			\frac{\partial^2 V}{\partial x_3^2}(0,0,0) = - \frac{2N}{(R^2+x_3^2))^{5/2}}\left( R^2 - \tfrac{h^2}{2} \right),
		\end{align}
		which is positive when $h>\sqrt{2}R$. 
		Hence, there exists $\ee>0$, such that $\frac{\partial V}{\partial x_3} (0,0,t)$ is positive for $t \in (0,\ee)$ and negative for $t\in (-\ee,0)$. 
		Combining this with the previously computed values of $\frac{\partial V}{\partial x_3}$ at the centers of the two $N$-gons, the intermediate value theorem implies that $\frac{\partial V}{\partial x_3} $ has two additional zeroes along the $x_3$-axis.

		\smallskip
		We now characterize these equilibria by showing that they are $1$-saddles. 
		At both, $V(0,0,x_3)$ increases on the left and decreases on the right, so they are local maxima of the potential restricted to the $x_3$-axis. 
		Given that the potential is harmonic, at least one of the remaining eigenvalues of the Hessian must be positive, and by rotational symmetry so must the other. 
		As the Hessian has a single negative eigenvalue, both equilibria are $1$-saddles.
	\end{proof}

	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\subsection{Existence results for equilibria in ati-prisms}
	\label{app:C.3}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	We shall consider an anti-prims whose top and bottom faces are $N$-gons and denote their minimum angle of symmetry by $\alpha=\frac{2\pi}{N}$. We shall let $R>0$ be the radius of these $N$-gons and $h>0$ the height of the anti-prism, then its relative height is defined by $\frac{h}{R}$.

	Identify $\mathbb{R}^3 \cong \mathbb{C} \times \mathbb{R}$, then for $\ell \in \{ 1, \ldots ,N \}$ we shall denote the vertices of the top $N$-gon as $A_\ell=(Re^{i (\ell \alpha + \frac{\alpha}{4})} , \frac{h}{2})$ and those at the bottom $N$-gon as $B_\ell=(Re^{-i (\ell \alpha + \frac{\alpha}{4})} , -\frac{h}{2})$. Then, the electric potential generated by placing unit point charges at the vertices of this anti-prism is
	$$V(x)=V_u(x)+V_d(x),$$
	where 
	$$V_u(x)=\sum_{\ell=1}^N\frac{1}{|x-A_\ell|} , \ \  V_d(x)=\sum_{\ell=1}^N\frac{1}{|x-B_\ell|}.$$ 
	We shall now state and prove the following result.

	\begin{theorem}
		Let $V$ be the electric potential generated by placing unit point charges at the vertices of an anti-prism as above and suppose its relative height satisfies $\frac{h}{R} < \sqrt{2}$. Then, there are electrostatic points located along the line segments connecting the center of the anti-prism to the midpoints of its lateral edges. 
	\end{theorem}

	\begin{proof}
		We shall consider the case of the line segment connecting the center to the midpoint of the edge connecting $A_N$ to $B_N$. The remaining cases can be handled similarly.

		The midpoint between $A_N$ and $B_N$ is $\frac{A_N+B_N}{2}=(R \cos(\frac{\alpha}{4}) , 0 , 0)$ and we can parametrize the segment that connects the origin to it using $t \in [0,1] \mapsto (t R \cos(\frac{\alpha}{4}) , 0 , 0)$. The derivatives of $V(x)$ in the normal directions $n_1=(0,1,0)$ and $n_2=(0,0,1)$ are given by
		\begin{align*}
			\langle \nabla V , n_1 \rangle & = \frac{\partial V_u}{\partial x_2} + \frac{\partial V_d}{\partial x_2} \\
			\langle \nabla V , n_2 \rangle & = \frac{\partial V_u}{\partial x_3} + \frac{\partial V_d}{\partial x_3}.
		\end{align*}
		Now, we compute each of the terms in the rights hand side in turn. We start with
		\begin{align*}
			\frac{\partial V_u}{\partial x_2} & = -\sum_{\ell=1}^N\frac{(x_2-R\sin(\ell \alpha + \frac{\alpha}{4}))}{|x-A_\ell|^3}  \\
			\frac{\partial V_d}{\partial x_2} & = -\sum_{\ell=1}^N\frac{(x_2+R\sin(\ell \alpha + \frac{\alpha}{4}))}{|x-B_\ell|^3} ,
		\end{align*}
		on the other hand, along the line connecting $0$ to $\frac{A_N+B_N}{2}$, we have $x_2=0=x_3$ and
		\begin{align*}
			|x-A_\ell| & = |(x_1-R\cos(\ell \alpha + \tfrac{\alpha}{4}) , R\sin(\ell \alpha + \tfrac{\alpha}{4}) , 0 )| \\
			& = |(x_1-R\cos( - \ell \alpha - \tfrac{\alpha}{4}) ,  R\sin( - \ell \alpha - \tfrac{\alpha}{4}) , 0 )| \\
			&  = |x-B_\ell| .
		\end{align*} 
		which shows that along such a line
		\begin{align*}
			\frac{\partial V_u}{\partial x_2} =  - \frac{\partial V_d}{\partial x_2} .
		\end{align*}
		On the other hand,
		\begin{align*}
			\frac{\partial V_u}{\partial x_3} & = -\sum_{\ell=1}^N\frac{(x_3-\frac{h}{2})}{|x-A_\ell|^3}  \\
			\frac{\partial V_d}{\partial x_3} & = -\sum_{\ell=1}^N\frac{(x_3+\frac{h}{2})}{|x-B_\ell|^3} ,
		\end{align*}
		and, again, along the line $x=2=0=x_3$ we have
		\begin{align*}
			\frac{\partial V_u}{\partial x_3} =  - \frac{\partial V_d}{\partial x_3} .
		\end{align*}
		Hence,
		\begin{align*}
			\langle \nabla V , n_1 \rangle  = 0 = \langle \nabla V , n_2 \rangle .
		\end{align*}
		Now, we shall finally consider the directional derivative in the direction of the tangent vector to the line under consideration $v=(1,0,0)$
		\begin{align*}
			\langle \nabla V , v \rangle & = \frac{\partial V}{\partial x_1} \\
			& = \frac{\partial V_u}{\partial x_1} + \frac{\partial V_d}{\partial x_1} \\
			& = - \sum_{\ell=1}^N \left( \frac{(x_1-R\cos(\ell \alpha + \frac{\alpha}{4}))}{|x-A_\ell|^3} + \frac{(x_1-R\cos(-\ell \alpha - \frac{\alpha}{4}))}{|x-B_\ell|^3} \right).
		\end{align*}
		Furthermore, along the line $x_2=0=x_3$, we have
		\begin{align*}
			\langle \nabla V , v \rangle & =  - \sum_{\ell=1}^N \left( \frac{(x_1-R\cos(\ell \alpha + \frac{\alpha}{4}))}{|x-A_\ell|^3} + \frac{(x_1-R\cos(-\ell \alpha - \frac{\alpha}{4}))}{|x-B_\ell|^3} \right) \\
			& =- 2\sum_{\ell=1}^N  \frac{(x_1-R\cos(\ell \alpha + \frac{\alpha}{4}))}{|x-A_\ell|^3} 
		\end{align*}
		and inserting $x_1=tR \cos(\frac{\alpha}{4})$ gives
		\begin{align*}
			\langle \nabla V , v \rangle & = - \frac{2}{R^2} \sum_{\ell=1}^N  \frac{ t \cos(\frac{\alpha}{4}) - \cos(\ell \alpha + \frac{\alpha}{4}) }{\left( (t \cos(\frac{\alpha}{4}) - \cos(\ell \alpha + \frac{\alpha}{4}))^2 + (\sin(\ell\alpha + \frac{\alpha}{4}) )^2 + \frac{h^2}{4}  \right)^\frac{3}{2}} .
		\end{align*}
		Now, notice that $\cos(\frac{\alpha}{4}) \geq \cos(\ell \alpha + \frac{\alpha}{4})$ with strict inequality for $\ell \neq N$, which shows that for $t=1$ we have $\langle \nabla V , v \rangle <0$. On the other hand, for evaluating this quantity near $t=0$, we compute its Taylor series at $t=0$
		\begin{align*}
			\langle \nabla V , v \rangle & =  \frac{16}{R^2} \frac{1}{\left( (4R^2 + h^2 \right)^\frac{3}{2}} \sum_{\ell=1}^N  \cos(\ell \alpha + \frac{\alpha}{4}) \\
			& \ \ \ \ + \frac{16 t}{R^2} \frac{\cos(\frac{\alpha}{4})}{(4R^2+h^2)^{\frac{5}{2}}} \sum_{\ell=1}^N \left( 12R^2 \cos(\ell\alpha + \frac{\alpha}{4})^2 - 4R^2 -h^2 \right) + O(t^2).
		\end{align*}
		Now, using the facts that
		$$\sum_{\ell=1}^N  \cos(\ell \alpha + \frac{\alpha}{4}) = 0 , \ \ \sum_{\ell=1}^N  \cos(\ell \alpha + \frac{\alpha}{4})^2 = \frac{N}{2},$$
		we find that 
		\begin{align*}
			\langle \nabla V , v \rangle & =  \frac{16 t}{R^2} \frac{\cos(\frac{\alpha}{4})}{(4R^2+h^2)^{\frac{5}{2}}}  \left( 6N R^2  - 4NR^2 -Nh^2 \right) + O(t^2) \\
			& = \frac{16N t}{R^2} \frac{\cos(\frac{\alpha}{4})}{(4R^2+h^2)^{\frac{5}{2}}}  \left( 2 R^2 - h^2 \right) + O(t^2) .
		\end{align*}
		Hence, if $h<\sqrt{2}h$ we have that along this line $\langle \nabla V , v \rangle$ is positive for small positive $t>0$. Combining this with the previously proven fact that it is negative for $t=1$ we find, from the intermediate value theorem, that $\langle \nabla V , v \rangle$ has a zero at some $t \in (0,1)$. This finishes the proof that $\nabla V$ as a zero along the segment connecting $0$ to $\frac{A_N+B_N}{2}$.
	\end{proof}

	For $h = \sqrt{2}R$, the complexity of the degenerate equilibrium at the origin is encapsulated by the Taylor expansion of the potential at the origin in homogeneous harmonic polynomials. 
	As we shall see, not only the degree-$2$ terms vanish,\footnote{We already knew this from the vanishing of the Hessian in the proof of Theorem \ref{thm:center_of_prism}.} but also the degree-$3$ terms do.
	\begin{lemma}
		\label{lem:Taylor_expansion_square}
		Let $V \colon \R^3 \to \R$ be the electrostatic potential generated by unit point charges placed at the vertices of the square anti-prism as specified at the beginning of this subsection.
		For $h=\sqrt{2}R$, its Taylor series at the origin is given by
		\begin{align}
			V(x_1, x_2, x_3) &= \tfrac {8 \sqrt {6}}{3} \left( 1  - \tfrac{7}{108} (x_1^4 + x_2^4) - \tfrac{14}{81} x_3^4 - \tfrac{7}{54} x_1^2x_2^2 + \tfrac{14}{27} x_3^2 (x_1^2 + x_2^2) \right) + \ldots ,
		\end{align}
		with terms of order exceeding $4$ not shown.
	\end{lemma}

	Again, we compute the Taylor expansion at the origin as a way to understand the degenerate critical point there for $h=\sqrt{2}R$.
	\begin{lemma}
		\label{lem:Taylor_expansion_triangle}
		Let $V \colon \R^3 \to \R$ be the electrostatic potential generated by unit point charges placed at the vertices of the triangular anti-prism as specified at the beginning of this subsection.
		For $h=\sqrt{2}R$, its Taylor series at the origin is given by
		\begin{align}
			\sqrt{3} - \tfrac{7\sqrt{3}}{216}\left( \tfrac{x_1^4}{8} + \tfrac{x_2^4}{8} + \tfrac{x_3^2}{3} + \tfrac{x_1^2x_2^2}{4} -x_1^2x_3^2 -x_2^2x_3^2 + \tfrac{5\sqrt{2}}{2} x_2x_3 ( x_2^2 - x_1^2 ) \right) + \ldots ,
		\end{align}
		with terms of order exceeding $4$ not shown.
	\end{lemma}







	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	\section{Proofs of Propositions~\ref{prop:no_maxima} and \ref{prop:octahedron}}
	\label{app:D}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	We first prove that, when $p \geq 1$, the function $V_p \colon \R^3 \setminus \{A_1,A_2,\ldots,A_n\} \to \R$ defined in \eqref{eqn:Vp} has no local maxima if all charges are positive.

	\begin{proof}[Proof of Proposition~\ref{prop:no_maxima}]
		The case $p=1$ follows immediately from the fact that $V_1=V$ is harmonic. 
		Hence, it suffices to consider the case $p>1$. 
		For this, we show that the Laplacian satisfies $\Delta V_p > 0$.
		Since it is the trace of the Hessian and thus the sum the diagonal eigenvalues, there must be at least one positive eigenvalue, which is incompatible with the existence of a maximum.
		%
		To carry out the computation of $\Delta V_p$, we write $r_i(x) = \dist{x}{A_i}$ and thus $V_p(x) = \sum_{i=1}^n \zeta_i^p / r_i(x)^p$.
		Let $x_1, x_2, x_3$ be the coordinates in $\R^3$ and $A_i = (a_{i1}, a_{i2}, a_{i3})$.
		Then, using $\frac{\partial r_i}{\partial x_j} (x) = \frac{x_j-a_{ij}}{r_i}$, we compute 
		\begin{align}
			\frac{\partial V_p}{\partial x_j} 
			&= -p\sum\nolimits_{i=1}^n \frac{\zeta_i^{p}}{r_i^{p+1}} \frac{\partial r_i}{\partial x_j} 
			= -p\sum\nolimits_{i=1}^n \frac{\zeta_i^{p}}{r_i^{p+2}} (x_j-a_{ij}); \\
			\frac{\partial^2 V_p}{\partial x_j^2} 
			&= -p\sum\nolimits_{i=1}^n \zeta_i^{p}\left( \frac{1}{r_i^{p+2}} - (p+2) \frac{x_j-a_{ij}}{r_i^{p+3}} \frac{\partial r_i}{\partial x_j} \right) \\
			&= -p\sum\nolimits_{i=1}^n \zeta_i^{p}\left(  \frac{1}{r_i^{p+2}} - (p+2) \frac{(x_j-a_{ij})^2}{r_i^{p+4}}  \right) \\
			&= -p\sum\nolimits_{i=1}^n \frac{\zeta_i^{p}}{r_i^{p+2}}\left( 1 - (p+2) \frac{(x_j-a_{ij})^2}{r_i^{2}}  \right).
		\end{align}
		Finally, summing over the three coordinate directions, we find that
		\begin{align}
			\Delta V_p &= \sum\nolimits_{j=1}^3 \frac{\partial^2 V_p}{\partial x_j^2}
			= -p \sum\nolimits_{i=1}^n \frac{\zeta_i^{p}}{r_i^{p+2}} \left( 3 - (p+2) \sum\nolimits_{j=1}^3 \frac{(x_j-a_{ij})^2}{r_i^{2}}  \right) \\
			&= -p \sum\nolimits_{i=1}^n \frac{\zeta_i^{p}}{r_i^{p+2}} \left( 3 - (p+2) \right)
			= p (p-1) \sum\nolimits_{i=1}^n \frac{\zeta_i^{p}}{r_i^{p+2}} ,
		\end{align}
		which is positive if all $\zeta_i$ are positive.
	\end{proof}

	\begin{remark}
		\label{rem:no_maxima_no_minima}
		If one trades the assumption that $p \geq 1$ for $p \leq 1$ we can actually conclude, from the same proof, that there are no maxima.
		On the other hand, if one continues to assume that $p \geq 1$, but that instead that all $\zeta_i^p$ are negative, then the same proof shows that there are no minima when $p \geq 1$.
		%
		These conclusions are particular cases of the following more general statement which can be inferred from the same proof. Suppose that $p>0$, then:
		\begin{itemize}
			\item if $(p-1)\zeta_i^p >0$ for all $i \in \{ 1, 2, \ldots , n \}$, then there are no local maxima;
			\item if $p=1$, then there are neither local minima nor minima;
			\item if $(p-1)\zeta_i^p <0$ for all $i \in \{ 1, 2, \ldots , n \}$, then there are no local minima.
		\end{itemize}
	\end{remark}

	Next, we shall prove that for $p>1$ the potentials $V_p$ can have minima when all the charges are positive. 
	This will be done by exploring the example given by placing the charges at the vertices of an octahedron. 
	\begin{proof}[Proof of Proposition~\ref{prop:octahedron}]
		With no loss of generality, we can choose the vertices of the octahedron at the points $(\pm 1, 0, 0)$, $(0,\pm 1,0)$, $(0,0,\pm 1)$, in which case the center of the octahedron coincides with the origin, $(0,0,0)$. 
		Then, using the computations carried out in the proof of Proposition~\ref{prop:no_maxima}, we find that
		\begin{align}
			\frac{\partial^2 V_p}{\partial x_i \partial x_j} (0,0,0) &= 0, \\
			\frac{\partial^2 V_p}{\partial x_i^2}(0,0,0) &= 2p (p-1),
		\end{align}
		for $i \neq j$ and $i \in \{ 1,2,3 \}$, respectively.
		Hence, the Hessian of $V_p$ at the origin is positive definite whenever $p>1$ and the result follows.
	\end{proof}


