	\section{Proof of Theorem~\ref{thm:1D_slices}}
	\label{app:E}
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
	%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

	We start by recollecting some basic definitions from complex analysis. 
	Denote the complex plane by $\C$, an open subset by $\Omega \subseteq \C$, and write $\ii = \sqrt{-1}$. 
	Recall that a complex function $f \colon \Omega \to \C$ is \emph{holomorphic} if for all $z_0 \in \C$, there is an open neighborhood of $z_0$ on which the function $f$ can be written as a convergent Taylor series centered at $z_0$, i.e.
	\begin{align}
		f(z) &= \sum\nolimits_{n=0}^{\infty} a_n (z-z_0)^n.
	\end{align}
	Furthermore, if $\Omega=\C$, i.e.\ $f \colon \C \to \C$ is holomorphic, then it can be written as a globally convergent Taylor series centered at any $z_0 \in \C$. In particular, if $f$ has a zero at $z_0$, then $a_0=0$ and there is $d \in \N$ such that
	\begin{align}
		f(z) &= \sum\nolimits_{n=d}^{\infty} a_n (z-z_0)^n,
	\end{align}
	with $a_d \neq 0$, in which case $d$ is called the \emph{order} or the \emph{degree} of the zero.
	%
	A complex-valued function is said to be \emph{meromorphic} if it is holomorphic on the complement of a set of isolated points, $\{ z_i \}_{i \in I}$, in an open subset $\Omega \subseteq \C$. Then, in neighborhoods around points $z_0 \in \Omega \setminus \{ z_i \}_{i \in I}$, we can write $f$ as a Taylor series. On the other hand, in a punctured neighbourhood around $z \in \lbrace z_i \rbrace_{i \in I}$, we can write $f$ as a Laurent series, i.e.
	\begin{align}
		f(z) &= \sum\nolimits_{n=-\infty}^{\infty} a_n (z-z_0)^n.
	\end{align}
	Such a $z_0$ is called a \emph{pole} if the portion of the sum with negative index, $n \in \Z$, is finite and an essential singularity otherwise. 
	In the case of a pole, we can write 
	\begin{align}
		f(z) &= \sum\nolimits_{n=-d}^{\infty} a_n (z-z_0)^n,
	\end{align}
	with $a_{-d} \neq 0$ and in this case, $d$ is called the order (or degree) of the pole.
	%
	A particularly interesting result that we shall need is a consequence of the Residue Theorem, called \emph{Cauchy's argument principle} (Theorem 18, Page 152 in \cite{Ahl66}). 
	For $\gamma \subseteq \C$ a Jordan curve and $f$ a meromorphic function on the complex plane, it states that
	\begin{align}
		\label{eq:Cauchy argument}
		2\pi \ii (Z - P) &= \int_{\gamma} \frac{f'(z)}{f(z)} \diff z ,
	\end{align}
	where $Z$ and $P$ respectively denote the total number of zeros and poles of $f$, weighted by their order, within the bounded region enclosed by $\gamma$.
	%
	We will now recall the statement of Theorem~\ref{thm:1D_slices}.
	Let $p > 0$ be an even integer, and
	\begin{align}
		V_p(x) &= \sum\nolimits_{i=1}^n \frac{\zeta_i^p}{\| x-A_i \|^p},
	\end{align}
	as defined in Section~\ref{sec:3}, Equation~\eqref{eqn:Vp}.
	The claim is that the number of equilibria of the restriction of $V_p$ to any line in $\R^3$ is at most $p(n-1)+2n-1$.
	In lieu of requiring that all $\xi_i$ are positive, we will work with the weaker assumption that the sum of the $\zeta_i^p$ does not vanish.
	\begin{proof}
		It suffices to prove the claim for the $z$-axis.
		Then, we write $x=(w,z) \in \R^2 \times \R$ and $A_i=(w_i,z_i)\in \R^2 \times \R$ for $1 \leq i \leq n$. 
		Along the $z$-axis, where $w=0$, we find
		\begin{align}
			\frac{\partial V_p}{\partial z} &= - 2q \sum\nolimits_{i=1}^n  \frac{\zeta_i^{2q}(z-z_i)}{\left( |w_i|^2 + (z-z_i)^2 \right)^{q+1}} ,
		\end{align}
		in which $q=\sfrac{p}{2}$ is a positive integer since $p > 0$ is even. 
		The analytic continuation of the function on the right-hand side extends to a meromorphic function on the complex plane, $\C$, denoted
		\begin{align}
			F_q(z) &= - 2q \sum\nolimits_{i=1}^n  \frac{\zeta_i^{2q}(z-z_i)}{\left( |w_i|^2 + (z-z_i)^2 \right)^{q+1}} .
		\end{align}
		Its zeros can be counted, with multiplicity, by making use of Cauchy's argument principle which we described in \eqref{eq:Cauchy argument}:
		\begin{align}
			2\pi \ii (Z_{q} - P_{q}) = \lim_{r \to \infty} \int_{C_r} \frac{F_q'(z)}{F_q(z)} \diff z ,
		\end{align}
		where $Z_{q}$ and $P_{q}$ denote the total number of zeros and poles of $F_q$, respectively, both counted with multiplicity, and $C_r$ denotes a circle of radius $r$. 
		Hence, we need the total number of poles, counted with multiplicity, as well as the contour integral on the right-hand side.

		\smallskip
		We start with the poles, which occur precisely at the locations along which the denominators vanish. Furthermore, the denominators can be factored as
		\begin{align}
			\left( |w_i|^2 + (z-z_i)^2 \right)^{q+1} &= \left( z- (z_i + \ii\, |w_i| )  \right)^{q+1} \cdot \left( z- (z_i -\ii\, |w_i| )  \right)^{q+1} .
		\end{align}
		Hence, the $i$-th term in the sum contributes two poles of order $q+1$ each, located at $z = z_i \pm \ii\, |w_i|$. This implies $P_{q} = 2n(q+1)$. 
		To compute the contour integral, we first obtain asymptotic expressions in $|z|$ for both $F_q'(z)$ and $F_q(z)$. 
		We start by computing
		\begin{align}
			F_q'(z) &= -2q \sum\nolimits_{i=1}^n \left[ \frac{\zeta_i^{2q}}{\left( |w_i|^2 + (z-z_i)^2 \right)^{q+1}} - (2q+2) \frac{\zeta_i^{2q} (z-z_i)^2}{\left( |w_i|^2 + (z-z_i)^2 \right)^{q+2}} \right] \\
			&= -2q \sum\nolimits_{i=1}^n  \frac{\zeta_i^{2q}}{\left( |w_i|^2 + (z-z_i)^2 \right)^{q+1}} \left[ 1 - (2q+2) \frac{ (z-z_i)^2}{ |w_i|^2 + (z-z_i)^2 } \right] \\
			&= -2q \sum\nolimits_{i=1}^n  \frac{\zeta_i^{2q}}{\left( |w_i|^2 + (z-z_i)^2 \right)^{q+2}} \left[ |w_i|^2 - (1+2q)  (z-z_i)^2 \right] .
		\end{align}
		Then, in terms of $z-z_i$, we can write
		\begin{align}
			F_q(z) &= -2q \sum\nolimits_{i=1}^n  \frac{\zeta_i^{2q}}{(z-z_i)^{2q+1}} \left[ 1 + \frac{|w_i|^2}{(z-z_i)^2} \right]^{-(1+q)} , \\
			F_q'(z) &= -2q \sum\nolimits_{i=1}^n  \frac{\zeta_i^{2q}}{(z-z_i)^{2q+2}} \frac{ - (1+2q) + \frac{|w_i|^2}{(z-z_i)^2}}{\left( 1 + \frac{|w_i|^2}{(z-z_i)^2} \right)^{q+2}} .
		\end{align}
		Using $z = re^{2\pi \ii \theta}$, this leads to the following asymptotic expansions in terms of $r=|z|$:
		\begin{align}
			F_q(z) &= -2q \sum\nolimits_{i=1}^n  \frac{\zeta_i^{2q}}{r^{2q+1}e^{(2q+1) \ii \theta}} \left[ 1 + O(r^{-1}) \right] ,\\
			F_q'(z) &= -2q \sum\nolimits_{i=1}^n  \frac{\zeta_i^{2q}}{r^{2q+2} e^{ (2q+2) \ii \theta}}  \left[ - (1+2q) + O(r^{-2}) +\right] .
		\end{align}
		Hence, if $\sum_{i=1}^n \zeta_i^{2q} \neq 0$, we find that
		\begin{align}
			\int_{C_r} \frac{F_q'(z)}{F_q(z)} \diff z  = - \int_0^{2\pi} \frac{ (1+2q)  \sum_{i=1}^n  \frac{\zeta_i^{2q}}{r^{2q+2}} }{ \sum_{i=1}^n  \frac{\zeta_i^{2q}}{r^{2q+1}} } \frac{1}{e^{\ii \theta}}  r e^{ \ii \theta}  \ii \diff \theta  = - 2\pi \ii (1+2q) .
		\end{align}
		Inserting this and $P_{q}=2n(q+1)$ into Cauchy's argument principle \eqref{eq:Cauchy argument}, leads to $- 2\pi \ii (1+2q) = 2\pi \ii \left( Z_{q} - 2n(q+1) \right)$, which can be rearranged to read as
		\begin{align}
			Z_{q} &= 2n(q+1)- (1+2q) = 2q (n-1) + (2n-1).
		\end{align}
		In terms of $p=2q$, this is the upper bound in the statement. The statement follows by noticing that the number of zeros of $\partial_z V_p$ for $z \in \R$ is at most those of its analytic continuation to the complex plane.
	\end{proof}

	\begin{remark}
		\label{rem:equilibria_on_line}
		The number of equilibria of $V_p$ that lie on a line is at most that of the number of equilibria of the restriction of $V_p$ to said line. 
		Hence, Theorem~\ref{thm:1D_slices} also gives an upper bound on the total number of equilibria of $V_p$ that lie on a line.
	\end{remark}

	\begin{remark}
		\label{rem:vanishing_sum_of_charges}
		If $\sum_{i=1}^n \zeta_i^p =0$ but $\sum_{i=1}^n z_i \zeta_i^p \neq 0$, then a similar but more involved computation of the asymptotic expansions for $F_q$ and $F_q'$ leads to the conclusion that
		\begin{align}
			\int_{C_r} \frac{F_q'(z)}{F_q(z)} &= - 2 \pi \ii (2q+2),
		\end{align}
		where $p=2q$ as in the proof of Theorem~\ref{thm:1D_slices}. 
		Then, the same argument leads to the upper bound $(2q+2)(n-1)=(p+2)(n-1)$.
	\end{remark}

	\begin{remark}
		\label{rem:one_point_charge} 
		For $n=1$, the above bound on the number of equilibria of $V_p$ restricted to a line is $1$, which is tight.
		Indeed, given any line that avoids $A_1$, the restriction of $V_p$ has a critical point at the point closest to $A_1$.
	\end{remark}
