\begin{equation} \label{eq:xe1}
\vect X_{b,j}^{(\e,2)} :  = \vect S_{b,j}^{(2)} (m_{\e}, s )- \alss  \vect X_{b,j}^{(\s,2)}
\end{equation}
 lies in the set $\mathcal D \left (\ell \bss(1-\bc) \P, \zeta_{\s,2}\right)$
