\subsubsection{Decoding of URLLC Messages} At the end of each block~$b \in [\eta]$, the UE observes the channel outputs $\vectsf Y_{b,c}$:
\begin{IEEEeqnarray}{rCl}
\vectsf Y_{b,c} = \begin{cases} 
( \vectsf X_{b}^{(\e,1)} + \vectsf X_{b}^{(\s,1)}) \vectsf H_{b,c}+ \vectsf N_{b,c} \quad & \text{if}\; b \notin \Barr  \\
(\vectsf X_{b}^{(\U)} + \vectsf X_{b}^{(\e,2)} + \vectsf X_{b}^{(\s,2)})\vectsf H_{b,c}+ \vectsf N_{b,c} \quad & \text{o.w.} 
 \end{cases}\notag  \\
\end{IEEEeqnarray}
%with $\vect Z_b \sim \mathcal N(0, I_{\Nu})$. 
%Define the information density metric between $\vect Y_b$ and $\vect V_b$ by:
Define the information density metric between $\vectsf y_{b,c}$ and $\vectsf v_b: = [\vect v_{b,1}, \ldots, \vect v_{b,q}]$ by:
\begin{equation} \label{eq:ibu}
i^{(\U)}_b  (\vectsf v_b; \vectsf y_{b,c} ) := \log \frac{f_{\vectsf Y_{b,c}| \vectsf V_{b}} (\vectsf y_{b,c}| \vectsf v_{b})}{f_{\vectsf Y_{b,c}}(\vectsf y_{b,c})}. 
\end{equation}


The UE  then chooses  the pair
\begin{equation}
(m^*,v^*) =\text{arg} \max_{ m, v}  i^{(\U)}_b  (\vectsf v_b; \vectsf y_{b,c} ).
\end{equation}
Given a threshold $\delta_{\U}$, if for this pair 
\begin{equation}
 i^{(\U)}_b  (\vectsf v_b; \vectsf y_{b,c} ) > \delta_{\U}
 \end{equation}
 the UE chooses $(\hat m_{b,\U},\hat v)= (m^*,v^*)$. Otherwise the UE declares that no URLLC message has been received and indicates it by setting $\hat m_{b,\U}=0$. %  is a threshold that we set in Section~\ref{}.  
%In each Block $b \in [\eta]$, set $\abd = 1$ if the Rx detects a URLLC message in this block, otherwise set $\abd = 0$. 
Define
\begin{IEEEeqnarray}{rCl} 
\mathcal B_{\text{detect}} &:=& \{b \in [\eta]: \hat m_{b,\U} \neq 0\}, \label{eq:bdet}\\
\mathcal B_{\text{decode}} &: =& \{b \in \mathcal B_{\text{detect}}: \hat m_{b,\U} = m_{b,\U}\},\label{eq:bdec}
\end{IEEEeqnarray}
where $\Bdet$ denotes the set of blocks in which a URLLC message is detected and $\Bdec$ denotes the set of blocks in which a URLLC message is decoded correctly. 
