\subsubsection{Decoding the eMBB Message under the TIN Approach} \label{sec:eMBBTIN}
The UE decodes its eMBB message based on the output of the entire $\eta$ blocks. Let $\vectsf Y_c : = [\vectsf Y_{1,c}, \ldots, \vectsf Y_{\eta, c}]$. Given that the URLLC messages interfere on the eMBB transmissions, under this approach, the UE treats URLLC transmissions as noise. Therefore, the decoding of the eMBB message depends on the detection of URLLC messages sent over the $\eta$ blocks. Let $B_{\text{dt}}$ be the realization of the set $ \mathcal B_{\text{detect}}$ defined in \eqref{eq:bdet}. Also, let $\vectsf s_{\e,1} : =  \{\vectsf s_{b}^{(1)}\}_{b \notin B_{\text{dt}} }$, and $\vectsf s_{\e,2} : =  \{\vectsf s_{b}^{(2)}\}_{b \in  B_{\text{dt}} }$. Given $B_{\text{dt}}$, the UE decodes its eMBB message based on the outputs of the entire $n$ channel uses by  looking for an index pair $(m',s')$ such that its corresponding codewords $\left \{ \vectsf s_{\e,2} (m',s'),  \vectsf s_{\e,1} (m',s') \right \}$ maximize 
\begin{IEEEeqnarray}{rCl}
\lefteqn{i^{(\e)}_{\text{TIN}} \left ( \vectsf s_{\e,2} ,  \vectsf s_{\e,1} ;  \vectsf y_c| \mathcal B_{\text{detect}} = B_{\text{dt}} \right):=}\notag \\ &&
 \log \hspace{-0.15cm}\prod_{b\notin  B_{\text{dt}}  }\hspace{0cm}  \frac{f_{\vectsf Y_{b,c}| \vectsf S_{b}^{(1)}} (\vectsf y_{b,c}| \vectsf s_{b}^{(1)})}{f_{\vectsf Y_{b,c}}(\vectsf y_{b,c})} +  \log \hspace{-0.15cm}\prod_{b\in  B_{\text{dt}} } \hspace{0cm}  \frac{f_{\vectsf Y_{b,c} | \vectsf S_{b}^{(2)}} (\vectsf y_{b,c}| \vectsf s_{b}^{(2)})}{f_{\vectsf Y_{b,c}}(\vectsf y_{b,c})}   \IEEEeqnarraynumspace
\end{IEEEeqnarray}
among all codewords
$\left \{ \vectsf s_{\e,2} (m',s'),  \vectsf s_{\e,1} (m',s') \right \}$.


\subsubsection{Decoding the eMBB Message under the SIC Approach} \label{sec:eMBBTIN}
%The UE decodes its eMBB message based on the output of the entire $\eta$ blocks. Let $\vectsf Y_c : = [\vectsf Y_{1,c}, \ldots, \vectsf Y_{\eta, c}]$. 
Under this approach, before decoding the eMBB message, the UE first mitigates the interference of correctly decoded URLLC messages over the $\eta$ blocks. Therefore, the decoding of the eMBB message depends on both the detection of URLLC messages sent over the $\eta$ blocks and the decoding of such messages. Let $\Bdc$ be the realization of the set $ \Bdec$ defined in \eqref{eq:bdet}. Also, let $\vectsf s_{\e,1} : =  \{\vectsf s_{b}^{(1)}\}_{b \notin B_{\text{dt}} }$, and $\vectsf s_{\e,2} : =  \{\vectsf s_{b}^{(2)}\}_{b \in  B_{\text{dt}} }$. Given $\Bdt$ and $\Bdc$, the UE decodes its eMBB message based on the outputs of the entire $n$ channel uses by  looking for an index pair $(m',s')$ such that its corresponding codewords $\left \{ \vectsf s_{\e,2} (m',s'),  \vectsf s_{\e,1} (m',s') \right \}$ maximize 
\begin{IEEEeqnarray}{rCl}
\lefteqn{i^{(\e)}_{\text{SIC}} \left ( \vectsf s_{\e,2} ,  \vectsf s_{\e,1} ;  \vectsf y_c| \Bdet = \Bdt, \Bdec = \Bdc \right):=}\notag \\ &&
 \log \hspace{-0.15cm}\prod_{b\notin  \Bdt  }\hspace{0cm}  \frac{f_{\vectsf Y_{b,c}| \vectsf S_{b}^{(1)}} (\vectsf y_{b,c}| \vectsf s_{b}^{(1)})}{f_{\vectsf Y_{b,c}}(\vectsf y_{b,c})} +  \log \hspace{-0.15cm}\prod_{b\in  \Bdt \backslash \Bdc } \hspace{0cm}  \frac{f_{\vectsf Y_{b,c} | \vectsf S_{b}^{(2)}} (\vectsf y_{b,c}| \vectsf s_{b}^{(2)})}{f_{\vectsf Y_{b,c}}(\vectsf y_{b,c})} \notag \\
 && +  \log \hspace{-0.15cm}\prod_{b\in \Bdc } \hspace{0cm}  \frac{f_{\vectsf Y_{b,c} | \vectsf S_{b}^{(2)}, \vectsf V_b} (\vectsf y_{b,c}| \vectsf s_{b}^{(2)}, \vectsf v_b)}{f_{\vectsf Y_{b,c}| \vectsf V_b}(\vectsf y_{b,c}|\vectsf v_b)} \IEEEeqnarraynumspace
\end{IEEEeqnarray}
among all codewords
$\left \{ \vectsf s_{\e,2} (m',s'),  \vectsf s_{\e,1} (m',s') \right \}$.

\subsection{Target Detection}
Following the proposed encoding and decoding schemes, the received signal at the SR in the alternative hypothesis in \eqref{eq:H1} can be reformulated as 
\begin{IEEEeqnarray}{rCl}
 \vectsf Y_{b,s} = \begin{cases} 
   (\vectsf X_{b}^{(\e,1)}+ \vectsf X_{b}^{(\s,1)} )  \vectsf H_{b,s}  + \vectsf N_{b,s}, & b \notin \Barr \\
  (\vectsf X_b^{(\U)} + \vectsf X_{b}^{(\e,2)}+ \vectsf X_{b}^{(\s,2)} )  \vectsf H_{b,s}  + \vectsf N_{b,s}, &\text{o.w.}
\end{cases} \IEEEeqnarraynumspace
\end{IEEEeqnarray}
In each block, the SR has the knowledge of the sensing signal  but  treats the interference of the communication signal as noise. 
