\subsection{URLLC Decoding Error Probability Analysis}
When channel state is known at both the BS and the UE, then by performing a singular value decomposition,  the MIMO channel in \eqref{eq:channel} is transferred into the following set of $q:=\min \{t,r\}$ parallel channels 
\begin{IEEEeqnarray}{rCl}
\vect Y_{b,c,j} = \vect X_{b,j} \sqrt{\lambda_{b,j}} + \vect N_{b,c,j},
\end{IEEEeqnarray}
for each $j \in [q]$ and each $b \in [\eta]$. Here, $\lambda_{b,1} \ge \lambda_{b,2} \ge \ldots \ge \lambda_{b,q}$ are the largest $q$ eigenvalues of $\vectsf H_{b,c} \vectsf H_{b,c}^H$ and $\vect N_{b,c,j} \sim \mathcal{N}(\vect 0, \vectsf I_{\ell \times \ell})$ are independent noise vectors.  Let $\vect \lambda_b := [\lambda_{b,1}, \ldots, \lambda_{b,q}]$. 
%We further assume that the encoders $f_{\e}$ and $f_{b}$ in Definition~\ref{def:code} act on $\vect \lambda_b$ instead of $\vectsf H_{b,c}$.
Also, let  $\vectsf X_b : = [\vect X_{b,1}, \ldots, \vect X_{b,q}]$. 
%The power constraint \eqref{eq:1} applies that
%\begin{equation}
%\sum_{j = 1}^q ||\vect X_{b,j}||^2 \le \ell \P. 
%\end{equation} 
In each block~$b \in \Barr$, we have the following URLLC decoding error events:
\begin{eqnarray}
\mathcal E_{\U,1}&:=& \{b \notin \Bdet | b \in \Barr \}, \label{eq:eu1}\\
\mathcal E_{\U, 2}&:=& \{b \notin \Bdec | b \in \Bdet,  b \in \mathcal B_{\text{arrival}}\}, \label{eq:eu2}
\end{eqnarray}
which indicate a missed-detection event. Specifically, $\mathcal E_{\U,1}$ happens when the transmitted URLLC message is not detected and $\mathcal E_{\U,2}$ happens when the decoded URLLC message does not match the transmitted one. 
In each block $b \notin \Barr$, we have the following error event:
\begin{eqnarray}
\mathcal E_{\U,3}&:=& \{b \in \Bdet | b \notin \Barr \}, \label{eq:eu3}
\end{eqnarray}
which indicates a false-alarm event. More specifically, $\mathcal E_{\U,3}$ happens when the UE incorrectly declares the detection of a URLLC message in a block with no URLLC. 
The URLLC decoding error probability thus is bounded as 
\begin{eqnarray}
\epsilon_{b,\U} \le P_{b-1, \D} \left (\Pr [\mathcal E_{\U,1}] + \Pr [\mathcal E_{\U,2}] \right)+ (1- P_{b-1, \D} ) \Pr [\mathcal E_{\U,3}], \label{eq:57}
\end{eqnarray}
where $P_{b-1, \D}$ is the target detection probability in the previous block $b-1$ and is calculated in Lemma~\ref{lemma1}. 
In Appendix~\ref{App:B}, we analyze each error event which results in Lemma~\ref{lemma2}.% on the average URLLC decoding error probability.  %For each $b \in [\eta]$, let $\lambda_{b,1} \ge \lambda_{b,2} \ge \ldots \ge \lambda_{b,q}$ be the $q$ largest eigenvalues of $\vectsf H_{b,c}^H \vectsf H_{b,c} $. 
%We have the following lemma on the URLLC decoding error probability.% and on the eMBB transmission rate. 
\begin{lemma} \label{lemma2}
The average URLLC decoding error probability is upper bounded as
\begin{eqnarray}\label{eq:boundu}
\epsilon_{b,\U} \le  P_{b-1, \D} P_{\U,1}   + (1-P_{b-1, \D})P_{\U,2}
\end{eqnarray}
where 
\begin{eqnarray}
P_{\U,1}&: =& \tepf+ (\tepf) ^{M_{\U} M_v}+\teps,\\
P_{\U,2}&: =& 1 - \left (1-\frac{\teps}{M_{\U}M_{v}}\right)^{M_{\U} M_v} ,
\end{eqnarray}
%with
\begin{IEEEeqnarray}{rCl}
\tilde \epsilon_{\U,1} &: =& Q \left (\frac{ \ell \C_{\U}-\log(M_{\U} M_v)  - K_{\U} \log (\ell)}{\sqrt{\ell \mathsf V_{\U}}} \right) + \frac{B}{\sqrt{\ell} }, \IEEEeqnarraynumspace \label{eq:tepf} \\
\tilde \epsilon_{\U,2} &:=& \frac{2}{\ell^{K_{\U} }} \left ( \frac{\log 2}{\sqrt{2\pi \ell}} + \frac{2B } {\sqrt{\ell}}\right),\label{eq:teps}
\end{IEEEeqnarray}
 for some $K_{\U}>0$ and $B >0$ and where $Q(x) = \frac{1}{\sqrt{2\pi}} \int_{x}^{\infty} \exp \left (-\frac{t^2}{2}\right) dt$ is the Q-function and
\begin{IEEEeqnarray}{rCl}\label{eq:CuVu}
\C_{\U} : =  \sum_{j = 1}^q \C(\Omega_{b,j}),\quad 
\mathsf V_{\U} := \sum_{j = 1}^q \mathsf V(\Omega_{b,j}),
\end{IEEEeqnarray}
with $\C(x) = \frac{1}{2} \log (1+x)$, $\mathsf V(x): = \frac{x(2+x)}{2(1+x)^2}$ 
%and 
%\begin{equation} \label{eq:Vuj}
%\mathsf V_{\U,j} = \Psi(||\vect V_{b,j}||^2/\ell, \alss(1-\alss)(1-\bss),\Omega_{b,j}, \sigyvj )
%\end{equation}
%where 
%\begin{equation}\label{eq:Psi}
%\Psi(a, b, \Omega, \sigma) = \frac{2\lambda_{b,j}  a + \Omega^2 (2(\sigma -1)(1-2b)+1)}{2 \sigma_{y,j}^4}
%\end{equation}
with
\begin{IEEEeqnarray}{rCl}
\Omega_{b,j}&: =& \frac{\sigy - \sigyvj }{\sigyvj}, \label{eq:omegabj} \\
\sigy &:=& 1+\lambda_{b,j} \P, \label{eq:sigy}\\
\sigyvj &:=& 1+\lambda_{b,j}(1-\alc^2)(1-\bc)\P. \label{eq:sigyvj}
\end{IEEEeqnarray}
%and $\alc$ is set such that 
%\begin{equation} \label{eq:psi1}
%\Psi(2\lambda_{b,j} ||\vect V_{b,j}||^2/\ell, \Omega_{b,j}, \sigyvj ) = 0
%\end{equation}

\end{lemma}
\begin{IEEEproof}
See  Appendix~\ref{App:B}. 
\end{IEEEproof}
\begin{remark}\label{rem2}
Under the assumption that $\Pr[\mathcal E_{\U,1}] \to 0$ and $\Pr[\mathcal E_{\U,3}] \to 0$, i.e., when the probability that all the URLLC messages are detected correctly is almost $1$, then for sufficiently large $\ell$,
\begin{IEEEeqnarray}{rCl}
\epsilon_{b,\U} &\le&  P_{b-1, \D} (\tepf + \teps) \notag \\
&=& P_{b-1, \D} Q \left (\frac{ \ell \C_{\U}-\log(M_{\U} M_v)  - O( \log (\ell))}{\sqrt{\ell \mathsf V_{\U}}} \right),
\end{IEEEeqnarray}
 where $\C_{\U}$ and $\mathsf V_{\U}$ are defined in \eqref{eq:CuVu}. This result is consistent with the FBL analysis of decoding error probability of parallel AWGN channels proposed in \cite[Theorem~78]{YuryThesis}. 
\end{remark}
\begin{remark}\label{rem3}
In the single-input single-output (SISO) case, the bound on the URLLC decoding error probability can be recovered from Lemma~\ref{lemma2} by setting $q = 1$ and replacing $\lambda_{b,j}$ with $\lambda_b$ for all $j \in [q]$. In this case, under the assumptions of Remark~\ref{rem2}, we have 
\begin{IEEEeqnarray}{rCl}
\epsilon_{b,\U} &\le&  P_{b-1, \D} Q \left (\frac{ \ell \C(\Omega_{b,j})-\log(M_{\U} M_v)  -  O( \log (\ell))}{\sqrt{\ell \mathsf V(\Omega_{b,j})}} \right), \IEEEeqnarraynumspace
\end{IEEEeqnarray}
\end{remark}
where $\C(x) = \frac{1}{2} \log (1+x)$, $\mathsf V(x): = \frac{x(2+x)}{2(1+x)^2}$. This result is consistent with the FBL analysis of decoding error probability of point-to-point single AWGN channels proposed by Polyanskiy, Poor and Verdú in \cite[Theorem~54]{Yuri2012}.
