\subsection{eMBB Transmission Rate Analysis Under the TIN Approach} 
The eMBB message is decoded at the end of the entire $n$ channel uses. Under this approach, the UE treats URLLC transmissions as noise. Therefore, the decoding of the eMBB message depends on the detection of URLLC messages sent over the $\eta$ blocks. We have the following two eMBB decoding error events:
\begin{eqnarray}
\mathcal E_{\e,1} &: =& \{\Bdet \neq \Barr\}, \label{eq:Ee1} \\
\mathcal E_{\e,2} &: =& \{\hat m_{\e} \neq m_e | \Bdet = \Barr\}, \label{eq:Ee2}
\end{eqnarray}
where $\mathcal E_{\e,1} $ happens when the UE does not successfully detect all the transmitted URLLC messages, and $\mathcal E_{\e,2}$ happens when the UE successfully detects all the transmitted URLLC messages but the decoded eMBB messages does not match the transmitted one. 

 Recall the definition of $B_{\text{dt}}$ as  the realization of the set $ \mathcal B_{\text{detect}}$. The average eMBB decoding error probability is bounded by
\begin{IEEEeqnarray}{rCl} \label{eq:51}
\epsilon_{\e, \text{TIN}}^{(n)} &\le&
\sum_{B_{\text{dt}}} \Pr [\Bdet = B_{\text{dt}}] \notag \\
&& \Big ( \Pr [\mathcal E_{\e,1}| \Bdet = B_{\text{dt}}] + \Pr [\mathcal E_{\e,2} | \Bdet = B_{\text{dt}}] \Big).
\end{IEEEeqnarray}
In Appendix~\ref{App:C}, by analyzing the occurrence probability of each error event, we calculate the right-hand side (RHS) of \eqref{eq:51}.  We then use  the Berry-Esseen central limit theorem (CLT) for functions \cite[Proposition~1]{MolavianJaziArXiv} to upper bound the eMBB transmission rate which results in the following lemma. 


%The following lemma is on the eMBB transmission rate under the TIN approach.
\begin{lemma}\label{lemma3}
Under the TIN approach, the eMBB transmission rate $\R_{\e}:= \frac{\log M_{\e}}{n}$ is upper bounded as
\begin{eqnarray}
\R_{\e} \le  {\C}_{\e} - \sqrt{ \frac{ \mathsf V_{\e}}{n}}Q^{-1}(\epsilon_{\e}-\Delta_{\e}) - K_{\e} \frac{\log (n)}{n} - \frac{\log(M_{\s})}{n}
\end{eqnarray}
for some $K_{\e} > 0$ and where 
\begin{IEEEeqnarray}{rCl}
\C_{\e} &:=&\sum_{\Bdt} \P_{\text{dt}}^{|\Bdt|} (1-\P_{\text{dt}})^{\eta-|\Bdt|} \tilde {\C}_{\e}, \label{eq:Ce}\\
\mathsf V_{\e} &:=& \sum_{\Bdt} \P_{\text{dt}}^{|\Bdt|} (1-\P_{\text{dt}})^{\eta-|\Bdt|} \tilde {\mathsf V}_{\e}, \label{eq:Ve}\\
\tilde{\C}_{\e}&:=&\frac{1}{\eta}\sum_{j = 1}^q \left (\sum_{b \notin \Bdt} \C(\Omega_{b,j}^{(1)}) + \sum_{b \in \Bdt} \C( \Omega_{b,j}^{(2)})\right),\label{eq:tce}\\
\tilde{\mathsf V}_{\e}&:=&\frac{1}{\eta} \sum_{j = 1}^q \left (\sum_{b \notin \Bdt} \mathsf V(\Omega_{b,j}^{(1)}) + \sum_{b \in \Bdt} \mathsf V(\Omega_{b,j}^{(2)})\right),\label{eq:tve}
\end{IEEEeqnarray}
where $\C(x) = \frac{1}{2} \log (1+x)$, $\mathsf V(x): = \frac{x(2+x)}{2(1+x)^2}$,
\begin{IEEEeqnarray}{rCl}
\P_{\text{dt}}&: =& P_{b-1,\D} (1- (\hat \epsilon_{\U,1})^{M_{\U}M_v}) +  (1-P_{b-1,\D}) P_{\U,2}, \label{eq:Pdtn}\\
\Delta_{\e}&:=& 1 + \frac{\tilde B}{\sqrt{n}}\left ( 1 + \frac{4}{n^{K_{\e}}}\right)  +\frac{2\log 2}{n^{K_{\e}}\sqrt{2n\pi}}\notag \\
&&-\sum_{\Bdt} \left (P_{b-1, \D}(1-(\tepf)^{M_{\U}M_v})\right)^{|\Bdt|}\notag \\
&& \hspace{1cm} \times \left ((1-P_{b-1, \D}) (1-P_{\U,2}) \right)^{\eta - |\Bdt|}, \label{eq:Deltae} \IEEEeqnarraynumspace\\
\Omega_{b,j}^{(1)}&: =& \frac{\sigy - \sigysfj}{\sigysfj},\quad 
\Omega_{b,j}^{(2)} := \frac{\sigy - \sigyssj}{\sigyssj}, \label{eq:Omegas}
\end{IEEEeqnarray}
 with $\hat \epsilon_{\U,1}:= \tepf - \frac{2\tilde B}{\sqrt{\ell}}$, and where $\tepf$ and $\teps$ are defined in \eqref{eq:tepf} and \eqref{eq:teps}, respectively, and
\begin{IEEEeqnarray}{rCl} 
\sigysfj &:=&1 + \lambda_{b,j} (1-\alsf^2)(1-\bsf) \P, \label{eq:sigysfj} \\
\sigyssj &:=& 1 + \lambda_{b,j} \P\Big(1-(1-\alc)^2(1-\bc)\notag \\
&&\hspace{1.5cm} (1-(1-\alss^2)(1-\bss))\Big). \label{eq:sigyssj} \IEEEeqnarraynumspace
\end{IEEEeqnarray}
%where  $\alsf$ is set such that 
%\begin{equation} \label{eq:psi2}
%\Psi \left(\frac{2||\sbjf||^2}{\ell}, \Omega_{b,j}^{(1)}, \sigysfj \right) =0,
%\end{equation}
% and $\alss$ is set such that 
% \begin{equation} \label{eq:psi3}
% \Psi \left(\frac{2(1-\alc)^2||\sbjs||^2}{\ell}, \Omega_{b,j}^{(2)}, \sigyssj \right) =0,
% \end{equation} 
%  with $\Psi(\cdot, \cdot, \cdot)$ defined in \eqref{eq:Psi}. 
  \end{lemma}
\begin{IEEEproof}
See  Appendix~\ref{App:C}.
\end{IEEEproof}
