\end{equation}
for some $K_{\e} > 0$ and where 
\begin{IEEEeqnarray}{rCl}
\C_{\e,2} &:=& \sum_{\Bdt}\sum_{\Bdc} \mathcal A (\P_{\text{dt}}, \P_{\text{dc}})\tilde {\C}_{\e,2}, \label{eq:Ce2}\\ 
\mathsf V_{\e,2} &:=& \sum_{\Bdt}\sum_{\Bdc} \mathcal A (\P_{\text{dt}}, \P_{\text{dc}})\tilde {\mathsf V}_{\e,2},\label{eq:Ve2} \\
\tilde{\C}_{\e,2}&:=&\frac{1}{\eta}\sum_{j = 1}^q \hspace{-0.1cm} \left (\hspace{-0.05cm} \sum_{b \notin \Bdt} \hspace{-0.15cm}\C(\Omega_{b,j}^{(1)}) +\hspace{-0.3cm} \sum_{b \in \Bdt \backslash \Bdc} \hspace{-0.3cm}\C( \Omega_{b,j}^{(2)}) + \hspace{-0.15cm}  \sum_{b \in \Bdc} \hspace{-0.15cm}  \C( \Omega_{b,j}^{(3)})\right),\label{eq:tce2} \notag \\ \\
