\end{IEEEeqnarray}
where $\C(x) = \frac{1}{2} \log (1+x)$, $\mathsf V(x): = \frac{x(2+x)}{2(1+x)^2}$,
\begin{equation}
\mathcal A (a, b)  := a^{|\Bdt|} (1-a)^{\eta-|\Bdt|} b^{|\Bdc|} (1-b)^{|\Bdt|- |\Bdc|},
\end{equation}
and 
\begin{IEEEeqnarray}{rCl}
\P_{\text{dc}}&: =& 1- \tepf - \teps,\\
%\Delta_{\e}&:=&\Bigg [ 1 + \frac{\tilde B}{\sqrt{n}}\left ( 1 + \frac{4}{n^K_{\e}}\right)  +\frac{2\log 2}{n^{K_{\e}}\sqrt{2n\pi}} \notag \\
%&& \hspace{0.2cm}- \frac{(\P_{b-1, \D} - \kappa_{\e})^{|\Bdt|} (( \tepf)^{M_{\U} M_v} - \kappa_{\e})^{\eta -|\Bdt|} }{\P_{\text{det}}^{|\Bdt|} (1-\P_{\text{det}} )^{\eta-|\Bdt|}}\Bigg], \label{eq:Deltae} \IEEEeqnarraynumspace\\
\Omega_{b,j}^{(3)}&: =& \frac{\sigyvj - \sigysvj}{\sigysvj} \label{eq:Omega3}
\end{IEEEeqnarray}
with
\begin{IEEEeqnarray}{rCl} 
\lefteqn{\sigysvj} \notag \\
 &:=&1 + \lambda_{b,j} (1-\alc)^2(1-\alsf)^2(1-\bc)(1-\bsf) \P, \label{eq:sigysvj}
\end{IEEEeqnarray}
and $\tepf$ and $\teps$ are defined in \eqref{eq:tepf} and \eqref{eq:teps}, respectively. 
\end{lemma}
\begin{IEEEproof}
See  Appendix~\ref{App:D}.
\end{IEEEproof}

\begin{remark}\label{rem5}
In Lemma~\ref{lemma4},  $P_{\text{dc}}$ can be interpreted as the probability of correctly decoding a URLLC message in each block~$b$. In the case where $\lambda_{b,j} = \lambda$ for all $b \in [\eta]$ and all $j \in [q]$, the capacity and the channel dispersion terms can be simplified  as
\begin{IEEEeqnarray}{rCl}
{\C}_{\e,2} &=& q  (1-P_{\text{dt}}) \C(\Omega^{(1)}) \notag \\
&& + q P_{\text{dt}} \left ((1-P_{\text{dc}}) \C(\Omega^{(2)}) + P_{\text{dc}} \C(\Omega^{(3)}) \right), \\
\mathsf V_{\e,2} &=& q  (1-P_{\text{dt}}) \mathsf V(\Omega^{(1)}) \notag \\
&& + q P_{\text{dt}} \left ((1-P_{\text{dc}}) \mathsf V(\Omega^{(2)}) + P_{\text{dc}} \mathsf V(\Omega^{(3)} \right), 
\end{IEEEeqnarray} 
where $\Omega^{(1)}$, $\Omega^{(2)}$ and $\Omega^{(3)}$ are obtained from \eqref{eq:Omegas} and \eqref{eq:Omega3} by replacing $\lambda_{b,j}$ with $\lambda$. 
As a result, under the SIC approach, the eMBB transmission channel is interpreted as $q$ parallel AWGN channels where in each channel, with probability $1- P_{\text{dt}}$, no URLLC message is detected, with probability $P_{\text{dt}}P_{\text{dc}}$ a URLLC message is correctly detected and decoded, and with probability  $P_{\text{dt}}(1-P_{\text{dc}})$ the correctly detected URLLC message is missed decoded.  
\end{remark}

\subsection{Target Detection Probability Analysis}
Given that the sensing channel state is known at the SR, the MIMO channel in \eqref{eq:H1} is transferred into the following set of $q$ parallel channels 
\begin{IEEEeqnarray}{rCl}
\vect Y_{b,s,j} = \vect X_{b,j} \sqrt{\gamma_{b,j}} + \vect N_{b,s,j},
\end{IEEEeqnarray}
for each $j \in [q]$ and each $b \in [\eta]$. 
%The SR treats the interference of the communication signal as noise. At each block~$b \notin \Barr$, the communication signal only carries eMBB traffic, i.e.,  $\vectsf X_{b,c} = \vectsf X_{b}^{(\e,1)}$, whereas, at each block $b \in \Barr$, the communication signal carries both eMBB  and URLLC traffic, i.e.,  $\vectsf X_{b,c} = \vectsf X_b^{(\U)} + \vectsf X_{b}^{(\e,2)}$.
Here, $\gamma_{b,1} \ge \gamma_{b,2} \ge \ldots \ge \gamma_{b,q}$ are the $q$ largest eigenvalues of $\vectsf H_{b,s}^H \vectsf H_{b,s} $.  The LRT test in each block~$b \in [\eta]$  is defined in \eqref{eq:test}. 
