%%& = &\log  \prod_{j = 1}^{q} \frac{\exp \left( -||\vect Y_{b,s,j} - \vect X_{b,j} \sqrt{\gamma_{b,j}}||^2\right)}{ \exp \left( -||\vect Y_{b,s,j}||^2 \right)} \underset{{\mathcal H_0}}{\overset{\mathcal H_{1}}{\gtrless}} \delta \IEEEeqnarraynumspace
%\end{IEEEeqnarray} 
Given that $\vect N_{b,s,j} \sim \mathcal N(0, \vectsf I_{\ell \times \ell})$, thus $f\left(\vect Y_{b,s,j}  | \mathcal H_0\right)$ is a Gaussian distribution. However, due to our power-shell code construction, this is not the case for $f\left(\vect Y_{b,s,j}  | \mathcal H_1\right)$. Hence, we take a change of metric measurement approach by introducing the following new LRT test: 
\begin{equation}\label{eq:test2}
\tilde T_b := \log  \left ( \prod_{j = 1}^{q} \frac{Q\left (\vect Y_{b,s,j}  | \mathcal H_1\right)}{f\left(\vect Y_{b,s,j}  | \mathcal H_0\right)} \right) \underset{{\mathcal H_0}}{\overset{\mathcal H_{1}}{\gtrless}} \delta,
\end{equation}
where $Q\left(\vect Y_{b,s,j}  | \mathcal H_1\right)$ is a Gaussian distribution and $\vect y_{b,s,j}| \mathcal H_1 \sim \mathcal N(\vect \mu_{b,j}, \sigbj \vect I_{\ell})$ with 
\begin{IEEEeqnarray}{rCl}
\vect \mu_{b,j} &:=& \begin{cases}
\sqrt{\gamma_{b,j}}(1-\alsf)\vect x_{b,j}^{(\s,1)}, \quad & b \notin \Barr \\
\sqrt{\gamma_{b,j}}(1-\alc)(1-\alss)\vect x_{b,j}^{(\s,2)}, \quad & \text{o.w.}
\end{cases} \IEEEeqnarraynumspace\\
\sigbj &:=& 1+ \gamma_{b,j}\kappa_2 (1-\kappa_1) \P \label{eq:sigbj}
\end{IEEEeqnarray}
where
\begin{IEEEeqnarray}{rCl}
\kappa_1&:=& \begin{cases} (1-\alsf^2)(1-\bsf), & b \notin \Barr \\
(1-\alss^2)(1-\bss),  & \text{o.w.}
\end{cases}\label{eq:kappa1}\\
\kappa_2&:=& \begin{cases} 1 , & b \notin \Barr \\
(1-\bc)(1-\alc)^2,  & \text{o.w.}
\end{cases}\label{eq:kappa2}
\end{IEEEeqnarray}

