\subsection{Rate-Reliability-Detection Trade-off}
By combining Lemmas~\ref{lemma2}, \ref{lemma3} and \ref{lemma1} with Proposition~\ref{prop1}, we have the following theorem on the rate-reliability-detection trade-off under the TIN approach.
\begin{theorem}\label{th1}
Given $n$ and $\P$, the rate-reliability-detection trade-off under the TIN approach is given by 
\begin{subequations}
\begin{IEEEeqnarray}{rCl}
\max_{\vect \beta, \vect \alpha} \;&& \C_{\e} - \sqrt{ \frac{\mathsf V_{\e}}{n}}Q^{-1}(\epsilon_{\e} - \Delta_{\e}) - K_{\e} \frac{\log (n)}{n} - \frac{\log(M_{\s})}{n}\label{eq:embb}\\ \notag \\
\text{s.t.:}\;  && P_{b-1, \D} P_{\U,1}   + (1-P_{b-1, \D})P_{\U,2} \le \epsilon_{\U}, \quad \forall b \in [\eta], \label{eq:urllc}\IEEEeqnarraynumspace\\ \notag \\
&& 1- F_{\tilde{\mathcal X_2}} (F^{-1}_{\tilde{\mathcal X_1}} (1-P_{\text{FA}})) \ge \P_{\D}, \quad \forall b \in [\eta ], \label{eq:pdt}
\end{IEEEeqnarray}
\end{subequations}
where $\vect \beta:=\{\bc, \bsf,\bss\}$ and $\vect \alpha:=\{\alc,\alsf,\alss\}$.  %is defined in \eqref{eq:1}. $P_{\text{FA}}$ is the desired false alarm probability, 
\end{theorem}

By combining Lemmas~\ref{lemma2}, \ref{lemma4}, and \ref{lemma1} with Proposition~\ref{prop1}, we have the following theorem on the rate-reliability-detection trade-off under the SIC approach.
\begin{theorem}\label{th2}
Given $n$ and $\P$, the rate-reliability-detection trade-off under the SIC approach is given by 
\begin{subequations}
\begin{IEEEeqnarray}{rCl}
\max_{\vect \beta, \vect \alpha} \;&& \C_{\e,2} - \sqrt{ \frac{\mathsf V_{\e,2}}{n}}Q^{-1}(\epsilon_{\e} - \Delta_{\e,2}) - K_{\e,2} \frac{\log (n)}{n} - \frac{\log(M_{\s})}{n} \notag \\ \\
\text{s.t.:}\;  && \text { \eqref{eq:urllc} and \eqref{eq:pdt}}
\end{IEEEeqnarray}
\end{subequations}
where $\vect \beta:=\{\bc, \bsf,\bss\}$ and $\vect \alpha:=\{\alc,\alsf,\alss\}$.  %is defined in \eqref{eq:1}. $P_{\text{FA}}$ is the desired false alarm probability, 
\end{theorem}
%Given that the optimization problem in Theorem~\ref{th1} is non-convex and also the closed form of the  CDF of a generalized chi-square distribution (i.e., $F_{\tilde {\mathcal X}_1} (\cdot)$ and  $F_{\tilde {\mathcal X}_2} (\cdot)$) is not known, therefore, in the following section we numerically evaluate the corresponding rate-reliability-detection trade-off.
