Recall the definition of $\mathcal E_{\U,1}$, $\mathcal E_{\U,2}$ and $\mathcal E_{\U,3}$ from \eqref{eq:eu1}, \eqref{eq:eu2} and \eqref{eq:eu3}, respectively. 
\subsubsection{Analyzing $\Pr [\mathcal E_{\U,1}]$} This is equivalent to the probability that for all $v \in [ M_{v}]$ and for all $m \in [M_{\U}]$ there is no codeword $ \vectsf V_b(m,v)$ such that $\tilde i^{(\U)}_b  (\vectsf V_b; \vectsf Y_{b,c} ) > \delta_{\U}$. Hence, 
\begin{eqnarray}
\Pr [\mathcal E_{\U,1}] = \left (\Pr [ \tilde i^{(\U)}_b  (\vectsf V_b; \vectsf Y_{b,c} ) \le \delta_{\U} ] \right)^{M_{\U} M_{v}}. \label{eq:58}
\end{eqnarray}
\subsubsection{Analyzing $\Pr [\mathcal E_{\U,2}]$}
This is equivalent to the probability that the UE has detected a URLLC message but the decoded one does not match the transmitted one.  To evaluate this probability, we use the threshold bound for maximum-metric decoding. I.e., for any given threshold $\delta_{\U}$: 
\begin{IEEEeqnarray}{rCl}
\Pr [\mathcal E_{\U,2}] &\le& \Pr [\tilde i^{(\U)}_b  (\vectsf V_b(m_{b,\U}, v); \vectsf Y_{b,c} ) \le \delta_{\U} ] \notag \\
&& + (M_{\U} M_v -1)  \Pr [\tilde i^{(\U)}_b  (\bar {\vectsf V}_b(m', v'); \vectsf Y_{b,c} ) > \delta_{\U} ] \label{eq:59} \IEEEeqnarraynumspace
\end{IEEEeqnarray}
where $m' \in [M_{\U}]$, $v' \in [M_v]$ and $(m_{b,\U}, v) \neq (m', v')$ and $\bar {\vectsf V}_b \sim f_{\vectsf V_b}$ and is independent of $\vectsf V_b$ and $ \vectsf Y_{b,c} $. 

\subsubsection{Analyzing $\Pr [\mathcal E_{\U,3}]$} This is equivalent to the probability that no URLLC message has been sent over block~$b$ but there is at least one codeword $\bar {\vectsf V}_b$ such that $\Pr [\tilde i^{(\U)}_b  (\bar{\vectsf V}_b; \vectsf Y_{b,c} ) > \delta_{\U}]$.  Hence,  
\begin{eqnarray}
\Pr [\mathcal E_{\U,3}] = 1 - \left (\Pr [\tilde i^{(\U)}_b  (\bar{\vectsf V}_b; \vectsf Y_{b,c} ) \le \delta_{\U}]\right )^{M_{\U} M_{v}}. \label{eq:60}
\end{eqnarray}
Combining \eqref{eq:57}, \eqref{eq:58}, \eqref{eq:59} and \eqref{eq:60}, we have
\begin{IEEEeqnarray}{rCl}
\epsilon_{b,\U}
&\le& P_{b-1, \D} \Big( \Pr [ \tilde i^{(\U)}_b  (\vectsf V_b; \vectsf Y_{b,c} ) \le \delta_{\U} ]^{M_{\U} M_{v}} \notag \\
&& \hspace{1.25cm}+ \Pr [\tilde i^{(\U)}_b  (\vectsf V_b; \vectsf Y_{b,c} ) \le \delta_{\U} ] \notag \\
&&\hspace{1.5cm}+ (M_{\U} M_v -1)  \Pr [\tilde i^{(\U)}_b  (\bar {\vectsf V}_b; \vectsf Y_{b,c} ) > \delta_{\U} ]\Big)\notag \\
&&\hspace{-0.7cm}+ (1- P_{b-1, \D} )\left(1 - \left (\Pr [\tilde i^{(\U)}_b  (\bar{\vectsf V}_b; \vectsf Y_{b,c} ) \le \delta_{\U}]\right )^{M_{\U} M_{v}}\right) . \label{eq:euf}\IEEEeqnarraynumspace
%& = & 1 - (1-2P_{b-1, \D} )  \left (1-\Pr [i^{(\U)}_b  (\bar{\vectsf V}_b; \vectsf Y_{b,c} ) > \delta_{\U}]\right )^{M_{\U} M_{v}}.
%&&- P_{b-1, \D}\left (1- \Pr [i^{(\U)}_b  (\vectsf V_b; \vectsf Y_{b,c} ) \le \delta_{\U} ] - (M_{\U} M_v -1)  \Pr [i^{(\U)}_b  (\bar {\vectsf V}_b; \vectsf Y_{b,c} ) > \delta_{\U} ] \right)
\end{IEEEeqnarray}

For some $K_{\U} > 0$, set 
\begin{eqnarray}
\delta_{\U} := \log(M_{\U}M_v)+ K_{\U} \log (\ell).
\end{eqnarray}
To evaluate  $\Pr [i^{(\U)}_b  (\bar {\vectsf V}_b; \vectsf Y_{b,c} ) > \delta_{\U} ]$ we follow \cite[Lemma 47]{Yuri2012} which results in 
\begin{eqnarray} \label{eq:98}
\Pr [\tilde i^{(\U)}_b  (\bar {\vectsf V}_b; \vectsf Y_{b,c} ) > \delta_{\U} ] \le \frac{2}{M_{\U} M_{v} \ell^{K_{\U} }} \left ( \frac{\log 2}{\sqrt{2\pi\ell}} + \frac{2B} {\sqrt{\ell}}\right).
\end{eqnarray}

Given that $\tilde i^{(\U)}_b  (\vectsf V_b(m_{b,\U}, v); \vectsf Y_{b,c} )$ follows a Gaussian distribution (as shown in Lemma~\ref{lemma5}), thus  we employ  the Berry-Esseen CLT for functions \cite[Proposition~1]{MolavianJaziArXiv} to bound the following probability:
\begin{IEEEeqnarray}{rCl} \label{eq:99}
\lefteqn{\Pr [\tilde i^{(\U)}_b  (\vectsf V_b; \vectsf Y_{b,c} ) \le \delta_{\U}  ]} \notag \\
& \le& Q \left (\frac{-\log(M_{\U} M_v) + \ell \C_{\U} - K_{\U} \log (\ell)}{\sqrt{\ell \mathsf V_{\U}}} \right) + \frac{B}{\sqrt{\ell} }, \IEEEeqnarraynumspace
\end{IEEEeqnarray}
where $B > 0$ is a constant.
