\tilde i_{\U} (\vbj; \ybcj ) \sim \mathcal N \left (\ell \C(\Omega_{b,j}), \ell \mathsf V(\Omega_{b,j})\right) 
\end{IEEEeqnarray}
which consequently proves Lemma~\ref{lemma5}. To this end, recall the definition of $Q_{\ybcj|\vbj} (\vect y_{b,c,j}| \vect v_{b,j})$ and $Q_{\ybcj}(\vect y_{b,c,j})$ from \eqref{eq:qy} and \eqref{eq:qyv}, respectively. Denote 
\begin{equation}
\tilde {\vect Z}_j = \lambda_{b,j} (1-\alc)(\sbjs + (1-\alss)\xbjs) + \nbcj.
\end{equation}
According to the definition of $Q_{\ybcj|\vbj} (\vect y_{b,c,j}| \vect v_{b,j})$,  $\tilde {\vect Z}_j $ follows an i.i.d Gaussian distribution with zero mean and variance $\sigyvj \vectsf I_{\ell \times \ell}$.   
 We thus have
\begin{IEEEeqnarray}{rCl}
\lefteqn{\tilde i_{\U} (\vbj; \ybcj ) = \log \frac{Q_{\ybcj|\vbj}(\vect y_{b,c,j}| \vect v_{b,j})}{Q_{\ybcj}(\vect y_{b,c,j})}} \\
&=& \log \frac{\left (\frac{1}{\sqrt{2\pi \sigyvj}}\right)^{\ell} \exp [-\frac{||\ybcj - \sqrt{\lambda_{b,j}}\vbj||^2}{2\sigyvj}]}{\left (\frac{1}{\sqrt{2\pi \sigy}}\right)^{\ell} \exp [-\frac{||\ybcj ||^2}{2\sigy}]} \\
%& = & \frac{\ell}{2} \log \frac{\sigy}{\sigyvj} \notag \\
%&& + \frac{||\ybcj ||^2}{2\sigy} - \frac{||\ybcj - \sqrt{\lambda_{b,j}}\vbj||^2}{2\sigyvj} \\
& = & \ell \C(\Omega_{b,j}) +  \frac{1}{2\sigy}\Big (||\ybcj||^2 -\frac{\sigy}{\sigyvj}||\tilde {\vect Z}_j||^2 \Big) \\
%& = & \ell \C(\Omega_{b,j}) + \frac{1}{2\sigy} \left (1-\frac{\sigy}{\sigyvj}\right) ||\nbcj||^2\notag \\
%&&  +\frac{\lambda_{b,j}}{2\sigy} \left ( \ell \P - \frac{\sigy}{\sigyvj} (1-\alc)^2 (1-\bc) \ell \P\right)   \notag \\
%&& + \frac{\sqrt{\lambda_{b,j}}(1-\alc)}{\sigy} \left (1-\frac{\sigy}{\sigyvj}\right ) \notag \\
%&&\cdot  \langle \sbjs + (1-\alss) \xbjs, \nbcj \rangle \notag \\
%&& + \frac{\sqrt{\lambda_{b,j}}}{\sigy} \langle \vbj, \nbcj \rangle \\
& = &  \ell \C(\Omega_{b,j}) + \frac{1}{2\sigy} \left (\sigy -\sigyvj \right) \left ( \ell -  \frac{||\tilde {\vect Z}_j||^2}{\sigyvj} \right)\notag \\
%&& + \frac{\sqrt{\lambda_{b,j}}(1-\alc)}{\sigy}\left (1-\frac{\sigy}{\sigyvj}\right ) \langle \sbjs, \nbcj \rangle \notag \\
%&& + \frac{\sqrt{\lambda_{b,j}}(1-\alc)(1-\alss)}{\sigy} \left (1-\frac{\sigy}{\sigyvj}\right ) \langle \xbjs, \nbcj \rangle \notag \\
&& + \frac{\sqrt{\lambda_{b,j}}}{\sigy} \langle \vbj,  \tilde {\vect Z}_j\rangle \\
& = &  \ell \C (\Omega_{b,j})  \notag \\
&& + \frac{1}{2\sigy}\Big (c_1 (\ell - ||\tilde {\vect Z}_j||^2) + c_2 \langle  \tilde {\vect Z}_j, \vbj \rangle \Big)\label{eq:131}
\end{IEEEeqnarray}
where 
\begin{IEEEeqnarray}{rCl}
c_1 &:=& \Omega_{b,j} \sigyvj,\\
c_2 &:=& 2 \sqrt{\lambda_{b,j}}.
%c_3 &:=& - 2 \sqrt{\lambda_{b,j}} (1-\alc) \Omega_{b,j}, \\
%c_4 &:=& - 2 \sqrt{\lambda_{b,j}} (1-\alc)(1-\alss) \Omega_{b,j}.
\end{IEEEeqnarray}
 The summands in \eqref{eq:131} are not independent, since
  $\vbj$  are not independent across time. One can however express independent uniform random variables on the power shell as a functions of independent Gaussian random variables. To this end,  
 let $\vect W_1 \sim \mathcal N (0, I_{\ell})$ be i.i.d Gaussian random variables independent of the noise $\tilde {\vect Z}_j$. Inputs $V_{b,j,t}$ with $t \in [\ell]$ thus can be expressed as
 \begin{IEEEeqnarray}{rCl}
 V_{b,j,t} & = & \sqrt{\ell (\bc + \alc^2 (1-\bc) )\P}\frac{W_{1,t}}{||\vect W_1||}.%\\
% S_{b,j,t}^{(2)} & = & \sqrt{\ell (1-\bc) (\bss + \alss^2 (1-\bss) )\P}\frac{W_{2,t}}{||\vect W_2||}, \IEEEeqnarraynumspace\\
% X_{b,j,t}^{(\s,2)} & = & \sqrt{\ell (1-\bc)(1-\bss)\P}\frac{W_{3,t}}{||\vect W_3||}.
 \end{IEEEeqnarray}
 To apply the CLT for functions proposed in \cite[Proposition~1]{MolavianJaziArXiv}, we consider the sequence $\{\vect U_t : = (U_{1,t}, U_{2,t}, U_{3,t})\}_{t = 1}^{\infty}$ whose elements are defined as 
 \begin{IEEEeqnarray}{rCl}
 U_{1,t} &: =& 1 - \frac{\tilde Z_{j,t}^2}{\sigyvj}, \\
 U_{2,t}&:=&  \sqrt{(\bc + \alc^2 (1-\bc) )\P \sigyvj}W_{1,t} \tilde Z_{j,t},  \\
  %U_{3,t}&: =& \sqrt{ (1-\bc) (\bss + \alss^2 (1-\bss) )\P} W_{2,t} N_{b,c,j,t}, \IEEEeqnarraynumspace\\
 % U_{4,t}&: =&  \sqrt{(1-\bc)(1-\bss)\P}W_{3,t} N_{b,c,j,t}, \\
   U_{3,t}&: =& W_{1,t}^2 -1,  \;
    % U_{6,t}: = W_{2,t}^2 -1, \; U_{7,t}: = W_{3,t}^2 -1.
 \end{IEEEeqnarray}
 Note that this random vector has an i.i.d. distribution across time $t = 1, \ldots, n$ and its moments can be easily verified to satisfy $\mathbb E [\vect U_1] = 0$ and $\mathbb E[||\vect U_t||_2^3] < \infty$. 
 The covariance matrix of this vector is given by 
 \begin{equation}
 \text{Cov} (\vect U) = \text{Diag} \left [2, (\bc + \alc^2 (1-\bc) )\P \sigyvj, 2\right ].
 \end{equation}
%
%
Next, we define the function $f$ as 
\begin{IEEEeqnarray}{rCl}
f(\vect u) = c_1u_1 + \frac{c_2 u_2}{\sqrt{1+u_3}}. 
\end{IEEEeqnarray}
Notice that $f(\vect 0) = 0$, and all the first and second order partial derivatives of $f$ are continuous in a neighborhood of $\vect u = 0$. The Jacobian matrix $\{\pdv{f(\vect u)}{u_j}\}_{1\times 3}$ at $\vect u = 0$ thus is given by 
\begin{equation}
\mathrm{J} \big |_{\vect u = 0} = [c_1 \; c_2 \; 0 ]. 
\end{equation}
Furthermore,  
\begin{IEEEeqnarray}{rCl}
\lefteqn{f\left (\frac{1}{\ell} \sum_{t = 1}^{\ell} \vect U_t \right) } \notag \\
 &= &\frac{c_1}{\ell} \sum_{t = 1}^{\ell} \left (1-\frac{\tilde Z_{j,t}^2}{\sigyvj}\right)\notag \\
 &&  + \frac{\frac{c_2}{\ell}\sum_{t = 1}^{\ell} \frac{\sqrt{(\bc + \alc^2 (1-\bc) )\P \sigyvj}}{\sqrt{\ell}} W_{1,t} \tilde Z_{j,t}}{\sqrt{1+\frac{1}{\ell} \sum_{t=1}^{\ell}(W_{1,t}^2-1)}}  \notag \\
% && \hspace{0.5cm}+ \frac{\frac{c_3}{\ell}\sum_{t = 1}^{\ell} \frac{||\sbjs||}{\sqrt{\ell}} W_{2,t} N_{b,c,j,t}}{\sqrt{1+\frac{1}{\ell} \sum_{t=1}^{\ell}(W_{2,t}^2-1)}}  \notag  \\
% && \hspace{1cm}+ \frac{\frac{c_4}{\ell}\sum_{t = 1}^{\ell} \frac{||\xbjs||}{\sqrt{\ell}} W_{3,t} N_{b,c,j,t}}{\sqrt{1+\frac{1}{\ell} \sum_{t=1}^{\ell}(W_{3,t}^2-1)}}\\
& = & \frac{1}{\ell} \Big (c_1 (\ell - ||\tilde {\vect Z}_j||^2) + c_2 \langle  \tilde {\vect Z}_j, \vbj \rangle \Big)%&& \hspace{1cm}+ c_2 \langle \xfs, \zfs \rangle + c_3\langle \xsf, \zfs \rangle  \Big ].
\end{IEEEeqnarray}
From the CLT in \cite[Proposition~1]{MolavianJaziArXiv}, we now conclude that the random variable $\tilde i_{\U} (\vbj; \ybcj )$ converges in distribution to a Gaussian distribution with mean $\ell \C(\Omega_{b,j})$ and variance 
\begin{IEEEeqnarray}{rCl}
\lefteqn{\frac{\ell}{4 \sigma_{y,j}^4} [c_1 \; c_2\;   0\; 0 ]  \text{Cov} (\vect U) [c_1 \; c_2\; 0 ]^T } \notag \\
&=& \frac{\ell}{4 \sigma_{y,j}^4} \left [2\Omega_{b,j}^2\sigma_{y|v,j}^4  + 4\lambda_{b,j} (\bc + \alc^2 (1-\bc) )\P \sigyvj  \right]  \notag  \\
& = & \ell \frac{\Omega_{b,j}(2+ \Omega_{b,j})}{2(1+\Omega_{b,j})^2} = \mathsf V(\Omega_{b,j})
\end{IEEEeqnarray}
%where $\mathsf V_{\U,j}$ is defined in \eqref{eq:Vuj}.
%the last equality is by setting $\alc$ such that 
%$\Psi(2\lambda_{b,j} ||\vect V_{b,j}||^2/\ell, \Omega_{b,j}, \sigyvj ) = 0
%$ where $\Psi ( \cdot, \cdot, \cdot)$ is defined in \eqref{eq:Psi}. 
This concludes the proof. 

