%LSTM is a type of recurrent neural networks (RNNs) which is capable of capturing long term time dependencies. The defining feature of the LSTM architecture is that it consists of \emph{memory cells} that can be used to store activations arbitrarily long. Each memory cell is a combination of a  constant error carrousel (CES) unit with input, output and forget cells. CEC units have linear activation functions which do not decay over time and thus enforce constant error  backpropagation flow. To prevent the CECs from filling up with useless information, the access to such units is regulated by specialized multiplicative unites called \emph{input gates}. The input gates learn to open and close access to the CECs at appropriate moments. Access from the activations of the CECs to the output units is controlled by \emph{output gates}. Such gates learn when the time is right to send the information stored in CECs to the outside of the network. Finally, \emph{forget gates} learn to reset the activation of CECs once the stored information is no longer useful.  At all (or some) time steps, the output units of the network make prediction error that are propagated just one step back in time through all units except the CECs. Errors are however backpropagated through CECs for an indefinite amount of time using an activation variation of real-time recurrent learning (RTRL) \cite{}. The weights are updated at every time step. 




\section{Problem Setup} \label{sec:setup}

Consider the point-to-point setup in Figure~\ref{fig1} where a dual function ISAC transmitter (Tx) wishes to communicate the message $M \in [1:2^{n\R}]$ to a receiver (Rx) over  a state-dependent channel with memory and simultaneously estimates the channel state from the generalized feedback. 
More specifically, 
 at a given time $i \in \{1, \ldots, n\}$, after observing the feedback sequence $Z^{i-1}$, the Tx encodes its message using a codeword
\begin{equation}
X_i = f_i(M, Z^{i-1}, X^{i-1})
\end{equation}
where $f_i$ is an encoding function on appropriate domains. 

At each time $i$, the Tx also  estimates the channel state.  The channel  estimation is a function of $X^{i-1}$ and $Z^{i-1}$, i.e., 
\begin{equation}
\hat S_i= g_i(X^{i-1}, Z^{i-1}). 
\end{equation}
 The  average per-block distortion thus is 
\begin{IEEEeqnarray}{rCl}
\Delta^{(n)} : = \frac{1}{n} \sum_{i = 1}^n \mathbb E [d(S_i, \hat S_i)] 
%\Delta_r^{(n)} : = \mathbb E [d(S_2^n; \hat S_2^n) ] &=& \frac{1}{n} \sum_{i = 1}^n \mathbb E [d(S_{2,i}, \hat S_{2,i}| \hat S_2^{i-1})]
\end{IEEEeqnarray}  
 where  $d(\cdot, \cdot)$  is a given bounded per-symbol distortion function. For this setup, the optimal estimator is
 \begin{IEEEeqnarray}{rCl} \label{eq:Dismin}
 \lefteqn{\min_{P_{\hat S_i|X^{i-1} Z^{i-1}}} \;  \mathbb E [d(S_i, \hat S_i)]} \\
 % & = &\min_{P_{\hat S_i|X^{i-1} Z^{i-1}}} \sum_{\hat u} \sum_{u} \sum_{x^{i-1} z^{i-1}} P_{X^{i-1}Z^{i-1}}(x^{i-1}, z^{i-1})\notag \\
  %&& \hspace{0cm} P_{S_i|X^{i-1}Z^{i-1}}(S_i|x^{i-1},z^{i-1}) P_{\hat S_i|X^{i-1}Z^{i-1}}(\hat S_i|x^{i-1},z^{i-1})d(S_i, \hat S_i)  \\
  & = & \sum_{x^{i-1}} \sum_{z^{i-1}} P_{X^{i-1}Z^{i-1}}(x^{i-1}, z^{i-1}) \notag \\
  &&\cdot \sum_u P_{S_i|X^{i-1}Z^{i-1}}(s_i|x^{i-1},z^{i-1}) d(s_i, \hat s^* (x^{i-1},z^{i-1})) 
 \end{IEEEeqnarray}
  where 
  \begin{IEEEeqnarray}{rCl} \label{eq:ustar}
 \lefteqn{ \hat s^* (x^{i-1},z^{i-1}) } \notag \\
 &: =& \underset{\hat s}{\mathrm{argmin}} \sum_{s}  P_{S_i|X^{i-1}Z^{i-1}}(s_i|x^{i-1},z^{i-1}) d(s_i, \hat s).
  \end{IEEEeqnarray}

%The communication channel is a time-invariant finite state channel in a way that 
%\begin{equation}
%P(y_i, S_i| x^i, u^{i-1}, z^{i-1}) = P(y_i, S_i| x_i, S_{i-1}).
%\end{equation}
%At each time $i$,  $S_{i}$ and $S_{t,i}$  are distributed according to an arbitrary distribution $P_{SS_t}$. 
The Rx has no knowledge of the state. After observing the channel outputs $Y^n$,  the receiver decodes the message $M$ by
\begin{IEEEeqnarray}{rCl}
\hat M &=& \phi(Y^n),
%\hat S_2^n &=& h_s(Y^n, S_1^n) 
\end{IEEEeqnarray} 
where $\phi$ is a decoding function on appropriate domains. 
The error probability of decoding message $M$ at the receiver is given by 
\begin{equation}
\epsilon^{(n)} : = \Pr [ \hat M \neq M]. 
\end{equation}



\begin{definition}
A rate-distortion pair $(\R, \D)$ is said to be achievable if there exists a sequence (in $n$) of $(2^{n\R},n)$ codes and encoding, estimation and decoding  functions $f_1, \ldots, f_n, g_1, \ldots. g_n, \phi$ that simultaneously satisfy 
\begin{IEEEeqnarray}{rCl}
\lim_{n \to \infty} \epsilon^{(n)} &=& 0, \\
\lim_{n \to \infty} \Delta^{(n)} & \le & \D.
%\lim_{n \to \infty} \Delta_r^{(n)} & \le & \Dr. 
\end{IEEEeqnarray}
The capacity-distortion trade-off $\mathsf C (\D)$ is the largest rate $\R$ such that the rate-distortion tuple $(\R, \D)$ is achievable.
\end{definition}

\begin{definition}
Define the information-theoretic capacity-distortion trade-off $\mathsf C (\D)$ by 
\begin{IEEEeqnarray}{rCl} \label{eq:C}
\mathsf C(\D) = \lim_{n \to \infty} \frac{1}{n}\; && \max_{\prod_{i=1}^n P_{X_i|X^{i-1} Z^{i-1}}}\;  \sum_{i = 1}^n I(X^i; Y_i | Z^{i-1}), \IEEEeqnarraynumspace \\
&& \text{s.t.: } \; \;  \frac{1}{n} \sum_{i = 1}^n \mathbb E [ d(S_i, \hat S_i)  \le \D,
\end{IEEEeqnarray}
where the optimal estimator  $\mathbb E [ d(S_i, \hat S_i) $ is defined in \eqref{eq:Dismin}. 
\end{definition}

\section{Unifilar Finite State Channels}
\begin{definition} \label{def3}
A finite state channel (FSC)  is a channel that has the following property 
\begin{IEEEeqnarray}{rCl}
P(s_i, y_i| x^i, z^{i-1}, s^{i-1}) = P(s_i |y_i, x_i, s_{i-1} ) P(y_i| x_i, s_{i-1}). \IEEEeqnarraynumspace
\end{IEEEeqnarray}
A FSC is called unifilar if the new channel state at time $i$ is a time-invariant function of the input and output at time $i$ and the state and time $i-1$. I.e., 
\begin{equation}
s_i = f(x_i, s_{i-1}, y_i).
\end{equation}
%defined by the triplet $(\mathcal X  \mathcal S, P(s', y|x, s), \mathcal S \mathcal Y)$, where $X$ is the channel input, $Y$ is the channel output, $S$ is the channel state at the beginning of the transmission, and $S'$ is the channel state at the end of the transmission. Also, the cardinalities X,Y,S are assumed to be finite. 
%At each time $t$, the channel has the memory-less property, that is,
\end{definition}

% The feedback capacity of a unifilar finite state channel is presented in the following theorem. 
% \begin{theorem}{\cite[Theorem 1]{Permuter2008}}
% The feedback capacity of a connected unifilar finite state channel, where the initial state $s_0$ is available to both the encoder and decoder, is given by 
% \begin{IEEEeqnarray}{rCl}
% \lefteqn{\C_{\text{FB}} =}  \\
% && \lim_{n \to \infty} \max_{\{P_{X_i|S_{i-1}Y^{i-1}}(x_i|s_{i-1}, y^{i-1})\}_{i = 1}^n} \frac{1}{n}\sum_{i = 1}^n I(X_i, S_{i-1};Y_i|Y^{i-1}).\notag
% \end{IEEEeqnarray}
% \end{theorem}
We have the following theorem on the capacity-distortion trade-off of Unifilar FSCs. 
\begin{theorem}\label{th1}
 Given $\D$ the  capacity-distortion trade-off of a connected unifilar FSC, where the initial state $s_0$ is available to both the encoder and decoder, is given by the following optimization problem:
 \begin{IEEEeqnarray}{rCl} 
 &&\C(\D) = \lim_{n \to \infty} \max_{\{P_{X_i|S_{i-1}Z^{i-1}}\}_{i = 1}^n} \frac{1}{n}\sum_{i = 1}^n I(X_i, S_{i-1};Y_i|Z^{i-1})\IEEEeqnarraynumspace \label{eq:13}\\
  &&\text{s.t.:}  \lim_{n \to \infty} \frac{1}{n} \sum_{i = 1}^n \sum_{z^{i-1},x_i,s_{i-1}} \hspace{-0.5cm}P_{X_i S_{i} Z^{i-1}} (x_i,s_{i},z^{i-1}) d(s_i,  s_i^*) \le \D \label{eq:14n}  \IEEEeqnarraynumspace
 \end{IEEEeqnarray}
 where 
 \begin{equation}
s_i^* = \arg \min_{\hat s_i} \sum_{s_i} P_{S_{i}| X_i Z^{i-1}}(s_{i}|x_i, z^{i-1}) d(s_i,\hat s_i).
\end{equation}
 \end{theorem}
 \begin{IEEEproof}
 The term in \eqref{eq:13} is equivalent to the capacity of a unifilar FSC and has been proved in \cite[Theorem~1]{Permuter2008}. The condition in \eqref{eq:14n} is the optimal estimator presented in \eqref{eq:Dismin} tailored to the unifilar FSCs. 
 \end{IEEEproof}


