\section{Example: Binary Channel with Multiplicative Bernoulli State}
%\subsubsection{Memoryless Case}
Consider the channel 
\begin{equation} \label{eq:channel}
Y_i = S_iX_i, \quad i \in \{1, \ldots, n\}
\end{equation}
with binary alphabets $\mathcal X = \mathcal S = \mathcal Y \in \{0,1\}$. Assume that  the feedback is perfect, i.e., $Z_i = Y_i$. We consider the Hamming distortion measure $d(s, \hat s) = s \oplus \hat s$.  At each time $i$, let
\begin{IEEEeqnarray}{rCl}
% r_i ^{(\ell)}&=& I( X_{i-\ell}^{i}; Y_i|Y_{i-\ell}^{i-1}) - \beta \mathbb E (S_i; \hat S_i) 
S_i = S_{i-1} \oplus \tilde S_i 
 %&=&H_b(q \alpha) - \alpha H_b(q)
 \end{IEEEeqnarray}
 where  $\tilde S_i$ is i.i.d Bernoulli$(p)$. Assume $S_0 = 0$. 

 Given that the feedback is perfect, when $X_{i-1} = 1$, the transmitter has full knowledge of the state at time $i-1$, i.e., $S_{i-1}$. In this case,  the channel in \eqref{eq:channel} is a Z channel where its crossover $1 \to 0$ probability  depends on the channel state at time $i-1$. More specifically,  when $S_{i-1} = 1$, the channel is equivalent to a Z  channel with the crossover $1 \to 0$ probability $p$ and when $S_{i-1} = 0$ the channel is equivalent to a Z channel with the crossover $1 \to 0$ probability $1-p$. However, when $X_{i-1} = 0$, the transmitter has no information about the channel state at time $i-1$. In this case, the solution is to look for the last time that bit $1$ has been sent. Let $\ell_i$ be the index of the last bit $1$ that has been sent over the channel, i.e., $X_{i-\ell_i} = 1, X_{i+1- \ell_i}=\ldots=X_{i-1} = 0$. Also let $S_{i-\ell_i}$ to be the corresponding state at time $i-\ell_i$. When $S_{i-\ell_i} = 0$, then the channel is equivalent to a Z channel with the crossover $1 \to 0$ probability 
 \begin{equation}\label{eq:pli}
 p_{\ell_i}: = \Pr [\tilde S_{i-\ell_i+1} \oplus \tilde S_{i-\ell_i + 2} \oplus \ldots \oplus \tilde S_i  = 1]. 
 \end{equation}
 When $S_{i-\ell_i} = 1$, then the channel is equivalent to a Z channel with the crossover $1 \to 0$ probability $1- p_{\ell_i}$. %See Fig.~\ref{fig2n}.
 \begin{lemma}\label{lem1}
 One can prove that
 \begin{IEEEeqnarray}{rCl}\label{eq:pli2}
 \pli = \frac{1}{2} - \frac{1}{2} (1-2p)^{\ell_i}, \end{IEEEeqnarray}
  for  $\ell_i = 1, 2, \ldots n-1$.
 \end{lemma}
 \begin{IEEEproof}
 See Appendix~\ref{App:A}.
 \end{IEEEproof}





 %This new channel is a unifilar finite state channel by introducing a new variable 





%\subsection{Capacity-Distortion Trade-off}

Following a similar procedure, we next evaluate  the expected distortion for this channel.  
 At each time $i$, if $X_i = 1$ then due to the perfect feedback, the distortion is zero.  We only have distortion if $X_i = 0$. When $X_i = 0$ and $X_{i-1} = 1$, then the encoder has full knowledge of $S_{i-1}$. In this case, the encoder chooses the most likely state symbol, i.e., when $S_{i-1} = 1$, then $\hat s_i = 0$ if $p \ge \frac{1}{2}$ and $\hat s_i = 1$ if $p < \frac{1}{2}$, and when $S_{i-1} = 0$, then $\hat s_i = 1$ if $p \ge \frac{1}{2}$ and $\hat s_i = 0$ if $p < \frac{1}{2}$.  When $X_i = 0$ and $X_{i-1}=0$, then the solution again is to look for the last time that bit $1$ has been sent. Recall the definition of $\ell_i $ and $S_{i-\ell_i}$ as mentioned earlier. 
 %Let $\ell_i$ be the index of the last bit $1$ that has been sent over the channel, i.e., $X_{i-\ell_i} = 1, X_{i+1- \ell_i}=\ldots=X_{i-1} =0$. Also let $S_{i-\ell_i}$ to be the corresponding state at time $\ell_i$. 
 In this case, when $S_{i-\ell_i} = 1$, then $\hat s_i = 0$ if $\pli \ge \frac{1}{2}$ and $\hat s_i = 1$ if $\pli < \frac{1}{2}$, and when $S_{i-\ell_i} = 0$, then $\hat s_i = 1$ if $\pli \ge \frac{1}{2}$ and $\hat s_i = 0$ if $\pli < \frac{1}{2}$. 
% Also define
% \begin{equation}
% T_{\ell_i} : = \{X_{i-1} = X_{i-2} = \ldots = X_{i-\ell+1} = 0, X_{i-\ell_i} = 1, \{X_{i-\ell-j}\}_{j=1}^{\ell_i-1} \in \mathcal X\} 
% \end{equation}
 For each $i \in \{1, \ldots, n\}$, we now introduce the variable 
 \begin{equation}\label{eq:si}
 U_{i-1} := (\ell_i, S_{i-\ell_i}).
 \end{equation}

 With this new variable, we transfer the channel in \eqref{eq:channel}  into a new channel with input $X_i$, output $Y_i$ and the state $U_{i-1}$ at each time $i$. According to Definition~\ref{def3}, this new channel is a unifilar finite state channel. Following the capacity-distortion trade-off of unifilar FCSs proved in Theorem~\ref{th1}, we have the following theorem on the capacity-distortion trade-off of this channel. 

 \begin{theorem}\label{th2}
Given $\D$, the capacity-distortion trade-off of the binary channel with multiplicative state in \eqref{eq:channel} is given by the following optimization problem:
\begin{IEEEeqnarray}{rCl} \notag
\C(\D) &&= \lim_{n \to \infty} \max_{\mathcal P} \frac{1}{n}\sum_{i = 1}^n \sum_{\ell = 1}^{i-1} \sum_{s \in \{0,1\}}  H_b(\alpha_i) - |\Bdt|_i H_b(p_{\ell}),  \\
\text{s.t.:} &&\;  \sum_{i = 1}^n \sum_{ \ell = 1}^{i-1}  \Pr [X_i = 0, \ell_i = \ell ]\min\{p_{\ell}, 1-p_{\ell} \}\le n \D. \notag
\end{IEEEeqnarray}
where $H_b(\cdot)$ is the binary entropy function and
\begin{IEEEeqnarray}{rCl}
\mathcal P & : = & \{P_{X_i|U_{i-1}Y^{i-1}}(x_i|u_{i-1}, y^{i-1})\}_{i = 1}^n,\\
|\Bdt|_i & : =&  \Pr [X_i = 1, U_{i-1} = (\ell_i = \ell, S_{i-\ell_i} = s) ], \label{eq:kappai} \\
\alpha_i & :=&   \Pr [X_i = 0, U_{i-1} = (\ell_i = \ell, S_{i-\ell_i} = s) ]  \notag \\
&+&  \Pr [X_i = 1, U_{i-1} = (\ell_i = \ell, S_{i-\ell_i} = 1) ]\cdot p_{\ell}  \notag \\
&+&   \Pr [X_i = 1, U_{i-1} = (\ell_i = \ell, S_{i-\ell_i} = 0) ] \cdot(1-p_\ell). \label{eq:alphai}
\end{IEEEeqnarray}
%where  $p_{\tilde \ell}$ is defined in \eqref{eq:pli2}.
\end{theorem}
\begin{IEEEproof}
The proof follows by specializing the capacity-distortion trade-off in Theorem~\ref{th1} to this channel. More specifically, at each time~$i$, the directed information is given by 
\begin{IEEEeqnarray}{rCl}
\lefteqn{I(X_i, U_{i-1}; Y_i|Y^{i-1})} \notag \\
 &=& H(Y_i | Y^{i-1}) - H(Y_i|X_i, U_{i-1},Y^{i-1}) \\
& = & H_b(\Pr [Y_i = 0| Y^{i-1} = y^{i-1}]) \notag \\
&-&  \sum_{\ell = 1}^{i-1} \sum_{s \in \{0,1\}}  \Pr [X_i = 1, U_{i-1} = (\ell_i = \ell, S_{i-\ell_i} = s) ] H_b (p_{\ell}) \IEEEeqnarraynumspace\\
 & = & \sum_{\ell = 1}^{i-1} \sum_{s \in \{0,1\}}  H_b(\alpha_i) - |\Bdt|_i H_b(p_{\ell}), \label{eq:comm2}
\end{IEEEeqnarray}
where $\alpha_i$ and $|\Bdt|_i$ are defined in \eqref{eq:alphai} and \eqref{eq:kappai}, respectively. Similarly, at each time ~$i$, the expected distortion is given by  
\begin{IEEEeqnarray}{rCl}
\lefteqn{\mathbb E[d(u_i, \hat u_i)]} \notag
\\ &=&   \sum_{u_i, \hat u_i} P_{U_i\hat U_i} (u_i,\hat u_i) d(u_i,\hat u_i) \\
& = & \sum_{x^i, u_i, \hat u_i} P_{X^i}(x^i) P_{U_i\hat U_i|X^i} (u_i,\hat u_i|x^i) d(u_i,\hat u_i) \\
%& = & \sum_{x^i, u_i} P_{X^i}(x^i) P_{U_i|X^i} (u_i|x^i) \min\{p_{\ell}, 1-p_{\ell}\} \\
& = & \sum_{\ell = 1}^{i-1} \Pr[X_i = 0, \ell_i = \ell] \min\{p_{\ell}, 1-p_{\ell}\}. \label{eq:sens2}
\end{IEEEeqnarray}
Combining \eqref{eq:comm2} and \eqref{eq:sens2} concludes the proof. 
\end{IEEEproof}
