\title{Cognitive Synergy Architecture: SEGO for Human-Centric Collaborative Robots}

\author{Jaehong Oh,~\IEEEmembership{},\\
Department of Mechanical Engineering, Soongsil University, Seoul, Korea}

\begin{document}
