      \node (zm) at (0.9,-2.1) {};

      \tikzset{every node/.append style={draw=myred}}
      \node (w2) at ($(w1)+(0,-2)$) {};
      \node (w2p) at ($(w1p)+(0,-2)$) {};
      \node (b) at (3.5,-1.7) {};

      % Le cycle          
      \tikzset{every path/.style={draw=mygreen,semithick}}
      \draw (u) to [bend left=10] (w1) ;
      \draw[dashed] (w1) to [bend left=10] (a);
      \draw[dashed] (a) to [bend left=20] (w1p);
      \draw (w1p) to [bend left=10] (v);
      \draw[dashed](z) to [bend left=10] (zm);
      \draw[dashed](zm) to [bend left=10] (y);
