      \draw (u) to [bend right=10] (w2) ;
      \draw[dashed] (w2) to [bend right=20] (b) ;
      \draw[dashed] (b) to [bend right=10] (w2p);
      \draw (w2p) to [bend right=10] (v);
      \draw[dashed] (b) to [bend left=10] (z);

