      \label{fig:cyclereduccontracnot}
  \end{myfigure}

  Since $P$ passes successively through vertices $x, w_1, u, w_2, b, z, y$, we have:
  \[
      d(x,w_1) + d(w_1,u) + d(u,w_2) + d(w_2,b) + d(b,z) + d(z,y) ~\le~ |P| ~.
  \]
  The quantity $d(w_1,u) + d(u,w_2)$ is equal to $2$, since $w_1,u,w_2$ are consecutive in $P$. On the other hand, $|P| \le d + 1$ by definition of $P$. By the triangle inequality between $x$ and $y$, $d = d(x,y) \le d(x,w_1) + d(w_1,a) + d(a,z) + d(z,y)$. Therefore:
  \begin{align}
   d(x,w_1) + 2 + d(w_2, b) + d(b,z) + d(z,y) &\le d(x,w_1) + d(w_1,a) + d(a, z) + d(z,y) + 1 \nonumber\\
  \Rightarrow\quad 1 + d(w_2, b) + d(b,z) &\le d(w_1,a) + d(a, z) \label{eq:abz}
  \end{align}

  In fact, we will show that:
  \begin{claim}\label{claim:abz}
      $d(w_1,a) + d(a, z) \le d(w_2, b) + d(b,z)$.
  \end{claim}

  Before presenting its proof, observe that the inequality of \cref{claim:abz} contradicts \cref{eq:abz}, and the fact that some distance between two vertices of the same tree, namely $x$ and $y$, is shortened in $\sU'$. So $\sU'$ is universal-isometric for $\set{A_1,A_2}$, and thus $\sU$ cannot be minimum, and thus does not contain any cycle.

  \begin{proof}%[Proof of \cref{claim:abz}]
  We will actually prove a stronger statement which is:
  \[
      d(w_1,a) = d(w_2, b) \quad\mbox{and}\quad d(a, z) = d(b,z) ~.
  \]

  We first remark that vertex $z\in A_1\cap A_2$. Indeed, we have $z\in A_1$. If $z\notin A_2$, then the edge $z-z'$ on the path $P$ from $z$ to $b$ is not in $A_2$. So, $z-z' \in A_1$, which implies $z'\in A_1$: a contradiction with the fact that $z$ is the first vertex on $P$ from $b$ to $y$ that is in $P_1$. So $z \in A_1\cap A_2$.

  As a preliminary step, let us show that $d(u,a) =  d(u,b)$, cf. \cref{eq:ua_ub} hereafter. Recall that $u,v,z \in A_1 \cap A_2$, and that distances in $A_i$ coincide with distances in $\sU$.

  By definition, $a$ is on the path from $u$ to $z$ in $A_1$. Thus
  \begin{align*}
      \dist_{A_1}(u, z) &= \dist_{A_1}(u, a) + \dist_{A_1}(a, z) \\
      \Rightarrow\quad d(u, z) &= d(u, a) + d(a, z)
  \end{align*}
  Similarly for $b$, which is on the path in $A_2$ from $u$ to $z$, we have $d(u, z) = d(u, b) + d(b, z)$. Combining these two equations, we get:
  \begin{align}
      d(u, a) + d(a, z) = d(u, b) + d(b, z) \label{eq:zaau_zbbu}
  \end{align}

  We use the following fact:

  \begin{fact}%  \textbf{Fact.}
  For any three vertices in a tree, the three paths between them have
  exactly one vertex in common.
  \end{fact}

  In particular, whenever applied to $u,v$ and $z$ in $A_1$, pairwise connected by the three tree paths $P_{uv}, P_{vz}, P_{uz}$ in $A_1$, the fact implies the last vertex of $P_{uz}$ that is on $P_{uv}$ is also the last vertex of $P_{vz}$ that is on $P_{uv}$. From this, we deduce that $a$ is on the path from $v$ to $z$ in $A_1$. Thus $d(v, z) = d(v, a) + d(a, z)$. With the same argument applied to the same vertices but in $A_2$, we deduce that $b$ is on the shortest path in $A_2$ from $v$ to $z$, we have $d(v, z) = d(v, b) + d(b, z)$. Therefore:
  \begin{align}
      d(v, a) + d(a, z) = d(v, b) + d(b, z)
    \label{eq:zaav_zbbv}
  \end{align}
  By subtracting \cref{eq:zaav_zbbv} from \cref{eq:zaau_zbbu}, we have:
  \begin{align}
          && (d(u, a) + d(a, z)) - (d(v, a) + d(a, z)) &= (d(u, b) + d(b, z)) - (d(v, b) + d(b, z)) \nonumber\\
          \Rightarrow&& d(u, a) - d(v, a) &= d(u, b) - d(v, b) \label{eq:ua=ub}
  \end{align}
  Note that $P_1$ and $P_2$ are paths of $A_1$ and $A_2$ respectively, thus they are shortest paths in $\sU$. Since $a$ and $b$ are on $P_1$ and $P_2$ respectively, we have $d(u,v) = d(u,a) + d(a,v) = d(u,b) + d(b,v)$. And by adding to \cref{eq:ua=ub}, we get:
  \begin{align}
      d(a,u) = d(b,u) \label{eq:ua_ub}
  \end{align}
  as claimed.

  We now show that:
  \begin{align}   
      d(a,w_1) = d(b,w_2) \label{eq:w1a_w2b}
  \end{align}
  Indeed, either $d(a,u) = d(b,u) = 0$, i.e., $a = u = b$, and thus $d(a,w_1) = d(u,w_1) = 1 = d(u,w_2) = d(b,w_2)$. Or, $d(a,u) = d(b,u) > 0$, and thus $w_1$ is on the path from $u$ to $a$ on $P_1$, and $w_2$ is on the path from $u$ to $b$ on $P_2$. This implies $d(u,w_1) + d(w_1,a) = d(u,w_2) + d(w_2,b)$, and thus $d(w_1,a) = d(w_2,b)$.

  Furthermore, applying \cref{eq:ua_ub} on \cref{eq:zaau_zbbu} gives that:
  \begin{equation}
      d(a,z) = d(b,z) \label{eq:az_bz}
  \end{equation}
  \cref{eq:w1a_w2b} and \cref{eq:az_bz} completes the proof of \cref{claim:abz}.
  \end{proof}
  This completes the proof of \cref{th:2trees}.
  \end{proof}

  This structural result allows us to predict that every minimum isometric-universal graph of two trees $\set{T_1,T_2}$ either is a tree, or contains an isometric-universal graph for $\set{T_1,T_2}$ as a subgraph (only by removing edges). However, as the proof of
  \cref{th:2treesalgo} will explain, if we can compute a tree that contains $T_1$ and $T_2$ as subgraphs, then we can compute a minimum isometric-universal graph for $\set{T_1,T_2}$. More precisely:

  \begin{theorem}\label{th:2treesalgo}
      A minimum isometric-universal graph for a pair of trees with at most $n$ vertices each can be computed in time $O(n^{5/2}\log{n})$.
  \end{theorem}


  \begin{proof}
      Let $T_1, T_2$ be two trees with at most $n$ vertices. From \cref{th:2trees}, there always exists a minimum isometric-universal graph of two trees that is a tree itself. Thus, any algorithm that computes a minimum isometric-universal tree for $\set{T_1, T_2}$ computes a minimum isometric-universal graph for $\set{T_1, T_2}$ too. 

      In a tree there exists only one path connecting any pair of vertices. Thus, every tree that contains $T_1$ and $T_2$ as subgraphs (such a tree is called a \emph{supertree} under graph isomorphism in \cite{GN98}) is also an isometric-universal tree. According to Gupta and Nishimura~\cite[Theorem~9.6]{GN98}, a minimum supertree of two trees can be computed in time  $O(n^{5/2}\log{n})$.

      From the above discussion, the minimum supertree for $T_1,T_2$ is a minimum isometric-universal tree and also a minimum isometric-universal graph for $\set{T_1,T_2}$, which concludes the proof.
   \end{proof}

