\subsection{KKT Necessary condition}
%\vspace{0.5\baselineskip}
%\noindent\textbf{Necessary condition.}
We start by giving closed-form derivatives of $T$.
Our analysis follows \cite{gallager1977minimum} and makes non-trivial extensions to data and result flows, as well as in-network computation.

For $(i,j) \in \mathcal{E}$ and $(d,m) \in \mathcal{T}$, the marginal cost due to the increase of $\phi_{ij}^-(d,m)$ consists of two components, (1) the marginal communication cost on link $(i,j)$, and (2) the marginal cost of increasing exogenous input rate $r_j(d,m)$.
Formally, for $j \neq 0$,
\begin{subequations}
\begin{equation}
    \frac{\partial T}{\partial \phi_{ij}^-(d,m)} =  t_i^-(d,m) \left(L_{m}^{-}D_{ij}^\prime(F_{ij}) + \frac{\partial T}{\partial r_j(d,m)}\right).
\end{equation}
Similarly, the marginal cost of increasing $\phi_{i0}^-(d,m)$ consists of the marginal computation cost at $i$, and the marginal cost of increasing result traffic $t_i^+(d,m)$.
Formally,
\begin{equation}
     \frac{\partial T}{\partial \phi_{i0}^-(d,m)}= t_i^-(d,m) \left( w_{im} C_i^\prime(G_i) + \frac{\partial T}{\partial t_i^+(d,m)} \right).
\end{equation}
\label{partial_D_phi-}
\end{subequations}

Following similar reasoning, the marginal cost of increasing $\phi_{ij}^+(d,m)$ is decomposed by 
\begin{equation}
     \frac{\partial T}{\partial \phi_{ij}^+(d,m)} = 
     t_i^+(d,m) \left(L_{m}^{+}D_{ij}^\prime(F_{ij}) + \frac{\partial T}{\partial t_j^+(d,m)} \right).\label{partial_D_phi+}
\end{equation}
In the above, term $\partial T/\partial r_i(d,m)$ can be recursively expressed as a weighted sum of marginal costs for out-going links and local computation unit, namely,
\begin{equation}
    \begin{aligned}
         \frac{\partial T}{ \partial r_i(d,m)} &= \sum_{j \in \mathcal{N}_i} \phi_{ij}^-(d,m) \left(L_{m}^{-}D_{ij}^\prime(F_{ij}) + \frac{\partial T}{ \partial r_j(d,m)}\right)
    \\ &+ \phi_{i0}^-(d,m) \left(w_{im}C_i^\prime(G_i) + \frac{\partial T}{\partial t_i^+(d,m)}\right).
    \end{aligned}
    \label{partial_D_r}
\end{equation}
Similarly, the term $\partial T/\partial t_i^+(d,m)$ is given by
\begin{align}
    \frac{\partial T}{\partial t_i^+(d,m)} = \sum_{j \in \mathcal{N}_i} \phi_{ij}^+(d,m) \left(L_m^+D_{ij}^\prime(F_{ij}) +  \frac{\partial T}{\partial t_j^+(d,m)}\right).
    \label{partial_D_t}
\end{align}
One could calculate $\partial T/\partial r_i(d,m)$ and $\partial T/\partial t_i^+(d,m)$ recursively by \eqref{partial_D_r} and \eqref{partial_D_t}, since the result flow does not introduce any marginal cost at the destination, i.e., $\partial T/\partial t_d^+(d,m) = 0$.
With the presence of computation offloading, the rigorous proof of \eqref{partial_D_phi-}, \eqref{partial_D_phi+}, and \eqref{partial_D_r} is a straightforward extension of \cite{gallager1977minimum} Theorem 2, in which a pure routing problem is considered.

A set of KKT necessary conditions for the optimal solution to \eqref{JointProblem_nodebased} is given in Lemma \ref{Lemma_Necessary}.

\begin{lem}
\label{Lemma_Necessary}
Let $\boldsymbol{\phi}$ be a global optimal solution to \eqref{JointProblem_nodebased}, then for all $i \in \mathcal{V}$, $(d,m) \in \mathcal{T}$ and $j\in\left\{0\right\} \cup \mathcal{N}_i$,
\begin{equation*}
    \frac{\partial T}{ \partial \phi_{ij}^-(d,m)}  
    \begin{cases}
     = \min\limits_{k \in \left\{0\right\} \cup \mathcal{N}_i } \frac{\partial T}{ \partial \phi_{ik}^-(d,m)} , \quad \text{if } \phi_{ij}^-(d,m) >0,
    \\ \geq \min\limits_{k \in \left\{0\right\} \cup \mathcal{N}_i } \frac{\partial T}{ \partial \phi_{ik}^-(d,m)} ,  \quad \text{if } \phi_{ij}^-(d,m) =0,
    \end{cases}
\end{equation*}
and for all $j \in \mathcal{N}_i$,
\begin{equation*}
    \frac{\partial T}{ \partial \phi_{ij}^+(d,m)}  
     \begin{cases}
     = \min\limits_{k \in \mathcal{N}_i } \frac{\partial T}{ \partial \phi_{ik}^+(d,m)} , \quad \text{if } \phi_{ij}^+(d,m) >0,
    \\ \geq \min\limits_{k \in \mathcal{N}_i } \frac{\partial T}{ \partial \phi_{ik}^+(d,m)}, \quad \text{if } \phi_{ij}^+(d,m) =0.
    \end{cases}
\end{equation*}
\end{lem}
%The proof is omitted.
\begin{proof}
    See Appendix \ref{Proof:Lem_Necessary}.
\end{proof}

The KKT conditions given in Lemma \ref{Lemma_Necessary} are not sufficient for global optimality \cite{gallager1977minimum}. %Examples of such non-sufficiency are provided in 
As a matter of fact, forwarding strategies $\boldsymbol{\phi}$ satisfying the KKT conditions may perform arbitrarily worse compared to the global optimal solution.
\begin{prop}
\label{prop_arbitrarily_worse}
   For any $0<\rho<1$, there exists a scenario (i.e., network $\mathcal{G}$, tasks $\mathcal{T}$, cost functions $F_{ij}(\cdot)$, $G_i(\cdot)$, and input rates $\boldsymbol{r}$) such that $\frac{T(\boldsymbol{\phi}^*)}{T(\boldsymbol{\phi})} = \rho$, where $\boldsymbol{\phi}$ is feasible to \eqref{JointProblem_nodebased} and satisfies the condition in Lemma \ref{Lemma_Necessary}, and $\boldsymbol{\phi}^*$ is an optimal solution to \eqref{JointProblem_nodebased}.
\end{prop}
\begin{proof}
To see this, we next construct a scenario satisfying that $T(\boldsymbol{\phi}^*)/T(\boldsymbol{\phi}) = \rho$ for an arbitrarily given $ 0<\rho<1$.
Consider the simple example in Fig. \ref{fig_kkt_suboptimal}, where only one task $(d,m)$ exists with $(d,m) = (4,1)$. 
Exogenous input data occurs only at node $1$, and the computation unit is only equipped at node $4$.
For simplicity, we assume all cost functions are linear with their marginals shown in the figure. We focus solely on the communication cost by letting $C^\prime_4 = 0$.
Consider the strategy $\boldsymbol{\phi}$ shown in the figure, where the data flow is routed directly from node $1$ to node $4$, and no traffic goes through node $2$.
It can be easily verified that the condition in Lemma \ref{Lemma_Necessary} holds for the given $\boldsymbol{\phi}$, with the total cost $T(\boldsymbol{\phi}) = 1$.
However, consider another forwarding strategy $\boldsymbol{\phi}^*$: the entire data traffic is routed along path $1 \to 2 \to 3 \to 4$, incurring a total cost of $\rho$.
It is evident that $\boldsymbol{\phi}^*$ reaches the global optimum for the given network scenario, implying $T(\boldsymbol{\phi^*})/T(\boldsymbol{\phi}) = \rho$.
The ratio of $T(\boldsymbol{\phi^*})$ and $T(\boldsymbol{\phi})$ can be arbitrarily small as $\rho$ varies, that is, the KKT condition yields arbitrarily suboptimal solutions.
\end{proof}

