\subsection{Sufficient condition}
%\noindent\textbf{Sufficient condition.}
We now address the non-sufficiency of the KKT condition.
Inspired by \cite{gallager1977minimum}, we introduce a modification to the KKT condition that leads to a sufficient condition for optimality in \eqref{JointProblem_nodebased}.
%Similar trick was first introduced by \cite{gallager1977minimum} for the multi-commodity routing problem.
Observing that for any $i$ and $(d,m)$, the traffic terms $t_i^-(d,m)$ and $t_i^+(d,m)$ repeatedly appears in RHS of \eqref{partial_D_phi-} and \eqref{partial_D_phi+} respectively for all $j \in \{0\} \cup \mathcal{V}$. 
%Therefore, when $t_i(a,k) = 0$, it always holds that $\phi_{ij}(a,k) = 0$. 
Therefore, following \cite{gallager1977minimum}, we remove the traffic terms in the conditions given by Lemma~\ref{Lemma_Necessary}.
Such modification provably leads to a set of sufficient optimality conditions that globally solves \eqref{JointProblem_nodebased}.

\begin{theo} \label{Thm_Sufficient}
Let $\boldsymbol{\phi}$ be feasible for (\ref{JointProblem_nodebased}).  
If for all $i \in \mathcal{V}$, $(d,m) \in \mathcal{T}$ and $j\in\left\{0\right\} \cup \mathcal{N}_i$, it holds% w.r.t data flow or $j\in\mathcal{O}(i)$ w.r.t. result flow,
\begin{subequations}
\label{Condition_sufficient}
\begin{equation}
    \delta_{ij}^-(d,m) \begin{cases}
    = \min\limits_{k \in \left\{0\right\}  \cup \mathcal{N}_i} \delta_{ik}^-(d,m), \quad \text{if } \phi_{ij}^-(d,m) >0,
    \\ \geq \min\limits_{k \in \left\{0\right\}  \cup \mathcal{N}_i} \delta_{ik}^-(d,m), \quad \text{if } \phi_{ij}^-(d,m) =0,
    \end{cases}
\end{equation}
and for all $j \in \mathcal{N}_i$,
\begin{equation}
     \delta_{ij}^+(d,m) \begin{cases}
    = \min\limits_{k \in \mathcal{N}_i} \delta_{ik}^+(d,m), \quad \text{if } \phi_{ij}^+(d,m) >0,
    \\ \geq \min\limits_{k \in \mathcal{N}_i} \delta_{ik}^+(d,m),  \quad \text{if } \phi_{ij}^+(d,m) =0,
    \end{cases}
\end{equation}
\end{subequations}
then $\boldsymbol{\phi}$ is a global optimal solution to \eqref{JointProblem_nodebased},

where %the \emph{augmented marginals} 
$\delta_{ij}^-(d,m)$ and $\delta_{ij}^+(d,m)$ are defined as
\begin{equation}
\begin{aligned}
    \delta_{ij}^-(d,m) &= 
    \begin{cases}
    L_m^-D_{ij}^\prime(F_{ij}) + \frac{\partial T}{\partial r_j(d,m)}, &\text{if } j \neq 0,
    \\ w_{im} C_i^\prime(G_i) + \frac{\partial T}{\partial t_i^+(d,m)} , & \text{if } j =0,
    \end{cases} %\label{delta_ij-}
    \\ \delta_{ij}^+(d,m) &=  L_m^+D_{ij}^\prime(F_{ij}) +  \frac{\partial T}{\partial t_j^+(d,m)}.%\label{delta_ij+}
\end{aligned}\label{delta}
\end{equation}
%then $(\boldsymbol{\phi}^-,\boldsymbol{\phi}^+)$ is a global optimal solution to (\ref{JointProblem_nodebased}).
\end{theo}

\begin{proof}
    See Appendix \ref{proof:thm_sufficient}.
\end{proof}

To see the difference between the KKT necessary condition given by Lemma \ref{Lemma_Necessary} and the sufficient condition given by Theorem \ref{Thm_Sufficient}, consider again the example in Fig. \ref{fig_kkt_suboptimal}.
For any $\boldsymbol{\phi}$ satisfying \eqref{Condition_sufficient}, it must hold that $\phi_{12}(4,1) = 1$, $\phi_{23}(4,1) = 1$ and $\phi_{34}(4,1) = 1$, precisely indicating the shortest path $1 \to 2 \to 3 \to 4$ as expected.
Intuitively, $\delta_{ij}^-(d,m)$ and $\delta_{ij}^+(d,m)$ represent the marginal cost for node $i$ to handle a unit-rate increment of data and result traffic through forwarding to $j$, respectively. Condition \eqref{Condition_sufficient} suggests that each node handles incremental arrival flow in the way that achieves its minimum marginal cost -- either by forwarding to neighbors, or to its local CPU.

\subsection{Robustness}

We remark that condition \eqref{Condition_sufficient} is sufficient but not necessary for the global optimality of problem \eqref{JointProblem_nodebased}, i.e., \eqref{Condition_sufficient} characterizes a subset of optimal solutions to \eqref{JointProblem_nodebased}.
To see this, suppose $\boldsymbol{\phi}$ satisfies \eqref{Condition_sufficient} with $t_i^-(d,m) = 0$ for some $i$ and $(d,m)$.
In this case, forwarding variables $[\phi_{ij}^-(d,m)]_{j \in \{0\}\cup\mathcal{V}}$ can be arbitrarily perturbed without affecting feasibility or optimality, and the modified strategy may no longer satisfy \eqref{Condition_sufficient}.

Nevertheless, we argue that compared to an arbitrary optimal solution to \eqref{prop_arbitrarily_worse}, the network operator often prefers to operate at a solution that satisfies condition \eqref{Condition_sufficient} due to a practical consideration. 
This is because the input rate $\boldsymbol{r}$ is typically estimated from real-time network measurements and may vary gradually over time. In such settings, the forwarding strategy should respond smoothly to small perturbations in $\boldsymbol{r}$ while maintaining optimality. The set of strategies satisfying \eqref{Condition_sufficient} possesses this robustness property, which we next formalize as \emph{lower hemicontinuity} (LHC).
% which is formally captured in Theorem \ref{thm:stability}.

%For analytical simplicity, we assume the network and application pattern are quasi-static. 
%The topology and task input rates are treated unchanged on small time scale, whereas we defer the discussion of slowly varying parameters to Section \ref{Section:algorithm} where an adaptive algorithm is proposed.
Recall that cost functions $D_{ij}(\cdot)$ and $C_i(\cdot)$ can represents link or computation capacity constraints, we denote the region of feasible link flows and workloads by
\begin{align*}
    \mathcal{D}_{F} = \bigg\{ F_{ij}, G_i \Big| &D_{ij}(F_{ij}) < \infty, \, \forall  (i,j) \in \mathcal{E}  \\&\text{ and } C_i(G_i) < \infty,\, \forall i \in \mathcal{V}\bigg\}.
\end{align*}

Let $\boldsymbol{F}(\boldsymbol{r},\boldsymbol{\phi}) = ([F_{ij}]_{(i,j)\in\mathcal{E}},[G_i]_{i \in \mathcal{V}})$ be the link flows and computation workloads for input rates $\boldsymbol{r}$ and strategy $\boldsymbol{\phi}$.
We denote the stability region of the strategy by
\begin{align*}
    \mathcal{D}_{\boldsymbol{\phi}}(\boldsymbol{r}) = \left\{\boldsymbol{\phi}\Big| \text{ \eqref{FlowConservation} holds, and } \boldsymbol{F}(\boldsymbol{r},\boldsymbol{\phi}) \in \mathcal{D}_{F}\right\}.
\end{align*}
The region of input rate $\boldsymbol{r}$ that the network can be stabilized is thus given by
\begin{align*}
    \mathcal{D}_{\boldsymbol{r}} = \left\{ \boldsymbol{r} \geq \boldsymbol{0} \Big| \mathcal{D}_{\boldsymbol{\phi}}(\boldsymbol{r}) \neq \emptyset \right\}.
\end{align*}
We assume $\mathcal{D}_{\boldsymbol{r}}$ has non-empty interior.
%Without ambiguity, we abbreviate $\mathcal{D}_{\boldsymbol{\phi}}(\boldsymbol{r})$ by $\mathcal{D}_{\boldsymbol{\phi}}$.
For $\boldsymbol{r} \in \mathcal{D}_{\boldsymbol{r}}$, let a set-valued mapping $F_{\text{opt}}: \mathcal{D}_{\boldsymbol{r}}\rightrightarrows[0,1]^{\text{dim}(\boldsymbol{\phi})}$ be $F_{\text{opt}}(\boldsymbol{r}) = \left\{\boldsymbol{\phi}:\boldsymbol{\phi} \text{ optimally solves \eqref{JointProblem_nodebased}}\right\}$; let set-valued mapping $F_{\text{suff}}: \mathcal{D}_{\boldsymbol{r}}\rightrightarrows[0,1]^{\text{dim}(\boldsymbol{\phi})}$ be $F_{\text{suff}}(\boldsymbol{r}) = \left\{\boldsymbol{\phi}:\boldsymbol{\phi} \text{ satisfies \eqref{Condition_sufficient}}\right\}$.
Then we have $F_{\text{suff}}(\boldsymbol{r}) \subseteq F_{\text{opt}}(\boldsymbol{r})$.
Moreover, to characterize stability and robustness of set-valued mapping, \emph{lower hemicontinuity} (LHC) is a generalization of semicontinuity in set-valued mappings that is widely considered in optimal control \cite{bohm1975continuity}. 

\begin{defi}[Lower Hemicontinuity]
Let $F: X \rightrightarrows Y$ be a set-valued mapping. Then $F$ is \emph{lower hemicontinuous} (LHC) at $x \in X$ if for every sequence $x_n \to x$ and every $y \in F(x)$, there exists a sequence $y_n \in F(x_n)$ such that $y_n \to y$.
\end{defi}

The intuition of LHC is that, as the input has a continuous variation, the output set does not suddenly shrink, i.e., nearby inputs always have output elements close to those of the original input.\footnote{This is different from the KKT sensitivity analysis in \cite{bertsekas1997nonlinear} Prop. 4.3.3, which gives the dynamics of single KKT point under constraint perturbation.}

\begin{prop}
\label{prop_nonLHC}
     $F_{\text{opt}}$ is not necessarily LHC over $\mathcal{D}_{\boldsymbol{r}}$.
\end{prop}
\begin{proof}
As mentioned, consider case when some $t_i^-(d,m) = 0$ in the optimal solution (which implies $r_i(d,m) = 0$),
then $\left[\phi_{ij}^-(d,m)\right]_{j \in \{0\} \cup \mathcal{V}}$ can be chosen arbitrarily without affecting the optimality. 
However, we can construct a sequence $\{\boldsymbol{r}^n\} \to \boldsymbol{r}$ such that $r_i(d,m)^n > 0$ for all $n$.
Since $r_i(d,m)^n > 0$, it must hold that $t^{-}_i(d,m)^n > 0$ through the sequence, and thus $\left[\phi^-_{ij}(d,m)^n\right]_{j \in \{0\} \cup \mathcal{V}}$ cannot be arbitrarily chosen throughout the sequence.
Therefore, those $\boldsymbol{\phi} \in F_{\text{opt}} (\boldsymbol{r})$ containing the arbitrarily chosen $\left[\phi_{ij}^-(d,m)\right]_{j \in \{0\} \cup \mathcal{V}}$ may not be a limit point of any sequence $\boldsymbol{\phi}^n \in F_{\text{opt}}(\boldsymbol{r}^n)$, violating the LHC definition.
\end{proof}

Proposition \ref{prop_nonLHC} implies the potential instability for the global optima of \eqref{JointProblem_nodebased} regarding perturbation of $\boldsymbol{r}$. 
Whereas $F_{\text{suff}}$ specified by the proposed sufficient condition \eqref{Condition_sufficient} overcomes such potential instability.

\begin{theo}
\label{thm:stability}
$F_{\text{suff}}$ is LHC over $\mathcal{D}_{\boldsymbol{r}}$.
\end{theo}

We defer the proof of Theorem \ref{thm:stability} to Section \ref{Section: Algorithm}. %, as we will provide an analytical upper bound on $|\Delta\phi|$ based on the proposed algorithm.
The underlying intuition is that \eqref{Condition_sufficient} includes restrictions on forwarding variables even for nodes with zero data or result traffic.

\subsection{Perspective from geodesic convexity}
\label{sec:geodesic}
Note that although \eqref{Condition_sufficient} provides global solutions to the non-convex problem \eqref{JointProblem_nodebased}, it only contains local conditions. 
Similar sufficiency was originally discovered by Gallager \cite{gallager1977minimum} and followed by others, e.g., \cite{xi2008node}.
However, the underlying mathematical structure has not been revealed.
To address this, we provide novel theoretical insight into such sufficiency by showing that with mild additional assumptions, the objective function $T(\boldsymbol{\phi})$ is geodesically convex in $\boldsymbol{\phi}$.

%Although the sufficiency of condition \eqref{Condition_sufficient} is rigorously proved, the underlying mathematical intuition that provides the global optimal solution to non-convex problem \eqref{proof:SuffCond_obj} is yet explained.

Note that the KKT condition and condition \eqref{Condition_sufficient} coincide for $i$ and $(d,m)$ with strictly positive $t_i^-(d,m)$ and $t_i^+(d,m)$.
Therefore, if $\boldsymbol{t} \equiv [t_i^-(d,m), t_i^+(d,m)]_{i\in\mathcal{V},(d,m)\in\mathcal{T}} > \boldsymbol{0}$, i.e., $t_i^-(d,m) > 0$ and $t_i^+(d,m)>0$ for all $i$ and $(d,m)$, condition \eqref{Condition_sufficient} and the KKT condition in Lemma \ref{Lemma_Necessary} are equivalent, implying KKT condition is both necessary and sufficient for global optimality.

\begin{prop}
\label{prop:positive_input}
    If $\boldsymbol{\phi}$ satisfies Lemma \ref{Lemma_Necessary} with $\boldsymbol{t} > \boldsymbol{0}$, then $\boldsymbol{\phi}$ optimally solves \eqref{JointProblem_nodebased}.
\end{prop}
%{\color{red} Fix t}

We thus expect a stronger mathematical structure of problem \eqref{JointProblem_nodebased} beyond the general non-convexity that has not been discussed by previous works adopting similar approaches.
The concept of \emph{geodesic convex} is a natural generalization of convexity for sets and functions to Riemannian manifolds~\cite{boumal2023introduction,zhang2016first}.
In this paper, we focus solely on the case when the Riemannian manifold is a Euclidean space.\footnote{Please see Riemannian optimization textbooks, e.g., \cite{boumal2023introduction,zhang2016first}, for detailed definitions and optimization techniques of general geodesic convex functions.}
\begin{defi}[Geodesic convexity on Euclidean space]
%Let $(M,g)$ be a Riemannian manifold. 
%A subset $C$ of $M$ is a geodesically convex set if, for any two points in $C$, there is a unique minimizing geodesic contained within $C$ that joins those two points.

%A function $f: C \to \mathbb{R}$ is a geodesically convex function
Let $C \subset \mathbbm{R}^n$ be a compact convex set.
Function $f: C \to \mathbbm{R}$ is geodesically convex if for any $x_1, x_2 \in C$, there exists a geodesic $\gamma_{x_1x_2}(t)$ joining $x_1$ and $x_2$ with $\gamma_{x_1x_2}(t) \in C$ for $t \in [0,1]$, and $f(\gamma_{x_1x_2}(t))$ is convex with respect to $t$.
\end{defi}

To see the geodesic convexity of $T$ in $\boldsymbol{\phi}$ when $\boldsymbol{t} > 0$, 
we first rewrite \eqref{FlowConservation} using $f_{ij}^-(d,m)$, $f_{ij}^+(d,m)$, and $g_i(d,m)$,
\begin{equation}
\begin{aligned}
    \sum_{j \in \mathcal{N}_i} f_{ij}^-(d,m) + g_i(d,m) = \sum_{j\in\mathcal{N}_i}f_{ji}^-(d,m) + r_i(d,m),
    \\ \sum_{j \in \mathcal{N}_i} f_{ij}^+(d,m) = \begin{cases}
        0, \quad \text{if } i = d,
        \\ \sum_{j\in\mathcal{N}_i}f_{ji}^+(d,m) + g_i(d,m), \quad \text{o.w.}
    \end{cases}
\end{aligned}
\label{flowconservation_f_domain}
\end{equation}

We next consider the flow-domain feasible set, i.e.,  denote by $\boldsymbol{f} = [f_{ij}^-(d,m), f_{ij}^+(d,m), g_i(d,m)]_{i,j \in \mathcal{V},(d,m) \in \mathcal{T}}$ all link and CPU packet rates, then
\begin{equation*}
\begin{aligned}
    \mathcal{D}_{\boldsymbol{f}} = \left\{\boldsymbol{f}\big| \text{\eqref{flowconservation_f_domain} holds } \right\}.
\end{aligned}
\end{equation*}

For fixed $\boldsymbol{r}$, suppose $\boldsymbol{t} > \boldsymbol{0}$, then there exists a one-to-one mapping between set $\mathcal{D}_{\boldsymbol{\phi}}$ and $\mathcal{D}_{\boldsymbol{f}}$, where we denote the mapping $\boldsymbol{\phi} \to \boldsymbol{f}$ as $\boldsymbol{f}(\boldsymbol{\phi})$, and the mapping $\boldsymbol{f} \to \boldsymbol{\phi}$ as $\boldsymbol{\phi}(\boldsymbol{f})$.
Specifically, if we omit the task notation $(d,m)$, then
\begin{equation}
    \boldsymbol{\phi}(\boldsymbol{f}): \quad \,\,\,\phi_{ij}^- = \frac{f_{ij}^-}{t_i^-},\,\phi_{i0}^- = \frac{g_{i}}{t_i^-},\,\phi_{ij}^+ = \frac{f_{ij}^+}{t_i^+},
\end{equation}
and 
\begin{equation*}
\begin{aligned}
\boldsymbol{f}(\boldsymbol{\phi}): \quad
    &f_{ij}^- = t_i^- \phi_{ij}^-,\, g_i = t_i^- \phi_{i0}^-,\, f_{ij}^+= t_i^+ \phi_{ij}^+,
    \\\text{with}\quad &t_{i}^- = \sum_{v \in \mathcal{V}} r_v\sum_{p \in \mathcal{P}^-_{vi}}\prod_{l = 1}^{|p|-1}\phi^-_{p_l p_{l+1}},
    \\&t_{i}^+ = \sum_{v \in \mathcal{V}} g_v\sum_{p \in \mathcal{P}^+_{vi}}\prod_{l = 1}^{|p|-1}\phi^+_{p_l p_{l+1}}.
\end{aligned}
\end{equation*}
where $\mathcal{P}^-_{vi}$ and $\mathcal{P}^+_{vi}$ are the set of \emph{data paths} and \emph{result paths}\footnote{A \emph{data path} refers to a node sequence $p = (p_1, p_2, \cdots, p_{|p|})$ with $(p_l ,p_{l+1})\in\mathcal{E}$ and $\phi^-_{p_l p_{l+1}}>0$. A \emph{result path} refers to that with $\phi^+_{p_l p_{l+1}}>0$.%\emph{Extended path} generalizes the concept of path where $p_{l+1} = p_l$ is allowed if $\phi_{p_l 0} >0$ to represent computation steps. When $p_{l+1} = p_l$, we use $\phi_{p_{l}p_{l+1}}$ to represent $\phi_{p_l 0}$. 
} starting from node $v$ and ends at node $i$, respectively.

Due to the convexity of $D_{ij}(\cdot)$ and $C_i(\cdot)$, we know $T$ is convex in $\boldsymbol{f}$.
Therefore, the total cost $T$ is a geodesic convex function of $\boldsymbol{\phi}$.

\begin{prop}
    Suppose $\boldsymbol{t} > \boldsymbol{0}$, Then $T(\boldsymbol{\phi})$ is geodesically convex in $\boldsymbol{\phi}$ with the geodesic function 
    \begin{equation*}
        \gamma_{\phi_1\phi_2}(t) = \boldsymbol{\phi}\left((1-t)\boldsymbol{f}(\boldsymbol{\phi}_1) + t \boldsymbol{f}(\boldsymbol{\phi}_2)\right).
    \end{equation*}
    %where $\boldsymbol{F}(\boldsymbol{\phi})$ represents the flow vector $\boldsymbol{f}$ corresponding to $\boldsymbol{\phi}$, and $\boldsymbol{\phi}(\boldsymbol{f})$ represents $\boldsymbol{\phi}$ corresponding to $\boldsymbol{f}$.
\end{prop}

%To the best of our knowledge, no previous work has revealed such property. 
When minimizing a convex function subject to linear inequality constraints, KKT conditions are necessary and sufficient for global optimality (see Proposition 4.4.1 in \cite{bertsekas1997nonlinear}).
When extended to general convex constraints, Slater's Constraint Qualification is required, i.e., there must exist a feasible point that satisfies all inequality constraints strictly (see Proposition 4.3.9 in \cite{bertsekas1997nonlinear}).
By substituting $\phi_{i0}(d,m)$ with $1 - \sum_{j \in \mathcal{V}}\phi_{ij}(d,m)$, problem \eqref{JointProblem_nodebased} satisfies the Slater's Qualification.
Recently, the sufficiency of KKT condition given Slater's Qualification is extended to Riemannian optimization \cite{jana2020convex}.
Therefore, when $\boldsymbol{t} > \boldsymbol{0}$, the KKT condition given by Lemma \ref{Lemma_Necessary} itself is sufficient for optimality without requiring condition \eqref{Condition_sufficient}.
On the other hand, when $\boldsymbol{t} > \boldsymbol{0}$ does not hold, the geodesic convexity of \eqref{JointProblem_nodebased} may no longer hold due to the existence of reflection points at $t_i^-(d,m) = 0$ or $t_i^+(d,m) = 0$, and the modification technique in Theorem \ref{Thm_Sufficient} can be adopted to eliminate the degenerate cases at these reflection points \cite{gallager1977minimum}.
