\section{Distributed and Adaptive Algorithm}
\label{Section: Algorithm}

In this section, we introduce a distributed algorithm that converges to the global optimal solution of \eqref{JointProblem_nodebased} specified by Theorem \ref{Thm_Sufficient}. 
The proposed algorithm is a variant of scaled gradient projection.
It uses carefully designed scaling matrices to attain better convergence property, and is adaptive to moderate changes of exogenous input rates.
It also allows asynchronous variable update for different nodes.
 %, which heuristically applies to case $b \neq 0$ subject to minor modification. 
%We allow nodes update their routing-computation strategies in an autonomous and asynchronous manner, and adapt to the changes of input rate and network topology.
%Bertsekas et al.\cite{bertsekas1984second} proposed a Newton-like scaled gradient projection method for optimal routing problem, Xi and Yeh\cite{xi2008node} then proposed a modification that guarantees convergence from arbitrary initial point.
Our method is based on \cite{xi2008node}, and further distinguishes data and result flows by extending the broadcasting protocol.% and enables piggybacking necessary information with the control messages. 

%\subsection{Algorithm overview and loop-free property}
\subsection{Algorithm overview}
%\noindent\textbf{Algorithm overview.}
{Existence of routing loops generates redundant flow circulation, wastes network resources and causes potential instability. %of a global strategy $\boldsymbol{\phi}$.
Therefore, we consider strategy $\boldsymbol{\phi}$ with \emph{loop-free} property.
For task $(d,m)$, we say $\boldsymbol{\phi}$ has a \emph{data loop} if there exists $i$ and $j$, such that $\mathcal{P}_{ij}^-(d,m)$ and $\mathcal{P}_{ji}^-(d,m)$ are both not empty, i.e., $i$ has a data path to $j$ and vice versa.
The concepts of \emph{result loop} are defined similarly with $\mathcal{P}_{ij}^+(d,m)$ and $\mathcal{P}_{ji}^+(d,m)$ being both not empty. % result flows.
We say strategy $\boldsymbol{\phi}$ is \emph{loop-free} if it has neither a data loop nor a result loop.\footnote{We allow loops concatenated by a data path and a result path of the same task, i.e., $\mathcal{P}_{ij}^-(d,m)$ and $\mathcal{P}_{ji}^+(d,m)$ are both not empty. This occurs in scenarios where the destination is the data source.}  
}
%{Loop-free is a fundamental requirement for $\boldsymbol{\phi}$ to be feasible and is guaranteed throughout the algorithm. Because given a slight increase in input rate, a loop may cause the on-loop flow to build up to infinity.} 

%We denote respectively by $\boldsymbol{\phi}^-_{i}(d,m)$ and $\boldsymbol{\phi}^+_{i}(d,m)$ node $i$'s strategy vector $\left[\phi^-_{ij}(d,m)\right]_{j \in \left\{0\right\} \cup V}$ and $\left[\phi^+_{ij}(d,m)\right]_{j \in V}$, %(recall that $\phi^-_{i0}(d,m)$ is the fraction of data to be computed locally)
%and by $\boldsymbol{\delta}^-_{i}(d,m)$ and $\boldsymbol{\delta}^+_{i}(d,m)$ the vectors of augmented marginals $\left[\delta^-_{ij}(d,m)\right]_{j \in \left\{0\right\} \cup V}$ and $\left[\delta^+_{ij}(d,m)\right]_{j \in V}$ (see \eqref{delta}).

We assume the network starts with a feasible and loop-free strategy ${\boldsymbol{\phi}}^0$, where the initial total cost is finite.
Let
\begin{equation*}
    \begin{aligned}
        \boldsymbol{\phi}^-_{i}(d,m) &\equiv \left[\phi^-_{ij}(d,m)\right]_{j \in \left\{0\right\} \cup \mathcal{V}}, 
        \\\boldsymbol{\phi}^+_{i}(d,m)&\equiv\left[\phi^+_{ij}(d,m)\right]_{j \in \mathcal{V}},
    \end{aligned}
\end{equation*}
and 
\begin{equation*}
    \begin{aligned}
        \boldsymbol{\delta}^-_{i}(d,m) &\equiv \left[\delta^-_{ij}(d,m)\right]_{j \in \left\{0\right\} \cup \mathcal{V}} ,
        \\\boldsymbol{\delta}^+_{i}(d,m) &\equiv \left[\delta^+_{ij}(d,m)\right]_{j \in \mathcal{V}}.
    \end{aligned}
\end{equation*}

At the $t$-th iteration, each node $i$ independently updates its strategy for data flow, i.e., $\boldsymbol{\phi}^-_{i}(d,m)$, as follows,
\begin{equation}
    \begin{aligned}
    &\boldsymbol{\phi}^-_i(d,m)^{t+1} = 
    \\ \Big[&\boldsymbol{\phi}^-_i(d,m)^{t} -
    \left(M^-_i(d,m)^t\right)^{-1} \boldsymbol{\delta}^-_{i}(d,m)^t \Big]^+_{M^-_i(d,m)^t, \mathcal{D}_i^-(d,m)^t}
%    \\ \boldsymbol{\phi}^+_i(d,m)^{t+1} &= \left[\boldsymbol{\phi}^+_i(d,m)^{t} -  \left(M^+_i(d,m)^t\right)^{-1} \cdot \boldsymbol{\delta}^+_{i}(d,m)^t \right]^+_{M^+_i(d,m)^t, \mathcal{D}_i^+(d,m)^t}.
\end{aligned}
\label{scaled_gradient_projection}
\end{equation}
where $M^-_i(d,m)^t$ is a positive semi-definite diagonal scaling matrix, $\mathcal{D}_i^-(d,m)^t$ is the feasible set of $\boldsymbol{\phi}^-_i(d,m)^{t+1}$, and operator $[\cdot]^+_{A,\mathcal{D}}$ denotes the vector projection scaled by matrix $A$ onto a convex set $\mathcal{D}$, that is,
\begin{align*}
    [\boldsymbol{v}_0]^+_{A,\mathcal{D}} = \arg\min_{\boldsymbol{v} \in \mathcal{D}} (\boldsymbol{v} - \boldsymbol{v}_0)^T A (\boldsymbol{v} - \boldsymbol{v}_0). %\label{projection}
\end{align*}
%Following \cite{xi2008node}, %the matrix inverse in \eqref{scaled_gradient_projection} could be avoided by the following equivalent form,
Formula \eqref{scaled_gradient_projection} is equivalent to solving the following QP (quadratic programming)\cite{xi2008node},
\begin{equation}
\begin{aligned}
    &\boldsymbol{\phi}^-_i(d,m)^{t+1} = \underset{\boldsymbol{v} \in \mathcal{D}_i^-(d,m)^t}{\arg\min} \boldsymbol{\delta}^-_{i}(d,m)^t \cdot (\boldsymbol{v} - \boldsymbol{\phi}^-_i(d,m)^{t}) 
    \\&\quad+ (\boldsymbol{v} - \boldsymbol{\phi}^-_i(d,m)^{t})^T M^-_i(d,m)^t (\boldsymbol{v} - \boldsymbol{\phi}^-_i(d,m)^{t}),
\end{aligned} \label{variable_update}    
\end{equation}
%and $\boldsymbol{\phi}^+_i(d,m)^{t+1}$ is updated similarly with ``$-$'' replaced by ``$+$'', where $M^-_i(d,m)^t$, $M^+_i(d,m)^t$ are symmetric and positive semi-definite scaling matrices 
%at $t$-th iteration, as the scale matrix of gradient 
%designed to achieve good convergence properties.
where the feaible set $\mathcal{D}_i^-(d,m)^t$ is given by constraints $\boldsymbol{\phi}_i^-(d,m) \geq \boldsymbol{0}$ and
\begin{equation*}
\begin{gathered}
        \sum\nolimits_{ j \in \{0\} \cup \mathcal{V}}  \phi_{ij}^-(d,m) = 1; \\ \phi_{ij}^-(d,m) = 0,  \quad \forall j \in \mathcal{B}_i^-(d,m)^t.
\end{gathered}
\end{equation*}

Here $\mathcal{B}_i^-(d,m)^t$ is the set of \emph{blocked nodes} of data flow for $(d,m)$ at $i$, to guarantee the feasibility and loop-free property.
The result strategy $\boldsymbol{\phi}^+_{i}(d,m)$ is updated in a similar manner as \eqref{variable_update} with ``-'' replaced with ``+''. %, where we omit the detailed expressions due to space limit. 
Note that $\phi_{dj}^+(d,m) \equiv 0$ for all $j \in \mathcal{V}$ %and $\mathcal{B}_d^-(d,m)^t \equiv V$, 
as destinations are sinks of result flows.

The proposed method is summarized in Algorithm \ref{alg:sgp}. 
We emphasize that our method is not purely gradient-based, as the gradients are replaced by $\boldsymbol{\delta}^-_{i}(d,m)$ and $\boldsymbol{\delta}^+_{i}(d,m)$ in \eqref{scaled_gradient_projection} (recall their definition in \eqref{delta}).
We next describe in detail the calculation of $\boldsymbol{\delta}^-_{i}(d,m)$, $\boldsymbol{\delta}^+_{i}(d,m)$, scaling matrices and blocked node sets.
We then give the asynchronous convergence result and analyze the algorithm complexity. %$\mathcal{B}_i^-(d,m)^t$, $\mathcal{B}_i^+(d,m)^t$.
%The proposed algorithm is summarized in Algorithm \ref{alg1}.

\begin{algorithm}[H]
\caption{Scaled Gradient Projection (SGP)}\label{alg:sgp}
\begin{algorithmic}
\STATE {\textbf{Initialize}}:
\STATE \hspace{0.5cm}Set $t \gets 0$, start with loop-free $\boldsymbol{\phi}^0$ with $T^0 < \infty$.
\STATE \hspace{0.5cm}Every node $i$ obtains $A_{ij}(T^0)$ and $A(T^0)$.
\STATE \textbf{At the end of slot $t$:}
\STATE \hspace{0.5cm}{Perform broadcast stage 1}: Compute $\partial T/\partial t_i^+(d,m)$ and \\\hspace{0.5cm}$h_i^+(d,m)$ for all $i$, $(d,m)$.
\STATE \hspace{0.5cm}{Perfrom broadcast stage 2}: Compute $\partial T/\partial r_i(d,m)$ and \\\hspace{0.5cm}$h_i^-(d,m)$ for all $i$, $(d,m)$.
\STATE \textbf{At the end of slot $t$, each node $i$:}
\STATE \hspace{0.5cm}Compute $\delta^-_{ij}(d,m)$ and $\delta^+_{ij}(d,m)$ using \eqref{delta}.
\STATE \hspace{0.5cm}Compute $\mathcal{B}^-_{ij}(d,m)$ and $\mathcal{B}^+_{ij}(d,m)$.
\STATE \hspace{0.5cm}Compute $M^+_i(d,m)$ and $M^-_i(d,m)$ using \eqref{scaling_matrix}.
\STATE \hspace{0.5cm}Solve the local optimization problem \eqref{variable_update}.
\STATE \hspace{0.5cm}Update $\boldsymbol{\phi}_i^-(d,m)$ and $\boldsymbol{\phi}_i^+(d,m)$.
\STATE \textbf{Update} {$t \gets t+1$}
\end{algorithmic}
\end{algorithm}

