\subsection{Proof of Lemma \ref{Lemma_Necessary}}
\label{Proof:Lem_Necessary}
The Lagrangian function of problem \eqref{JointProblem_nodebased} is given by
\begin{equation*}
    \begin{gathered}
L(\boldsymbol{\phi},\boldsymbol{\lambda},\boldsymbol{\mu}) = T(\boldsymbol{\phi}) - \sum_{i\in\mathcal{V}}\sum_{ (d,m)\in\mathcal{T}} \Bigg[
        \\ \lambda^-_{idm} \left( \sum_{j \in \{0\} \cup \mathcal{V}} \phi_{ij}^-(d,m) -1\right)
        \\ + \lambda^+_{idm} \left( \sum_{j \in \mathcal{V}} \phi_{ij}^+(d,m) - \mathbbm{1}_{i \neq d} \right)
        \\  + \left(\sum_{j\in\{0\}\cup\mathcal{V}}\mu^-_{ijdm}\phi^-_{ij}(d,m) + \sum_{j\in\mathcal{V}}\mu^+_{ijdm}\phi^+_{ij}(d,m)\right)\Bigg],
    \end{gathered}
\end{equation*}
where $\boldsymbol{\lambda} = [\lambda^-_{idm}, \lambda^+_{idm}]_{i,d,m}$ and $\boldsymbol{\mu} = [\mu^-_{ijdm},\mu^+_{ijdm}]_{i,j,d,m}$ with $\lambda^{\pm}_{idm} \in \mathbb{R}$ and $\mu^{\pm}_{ijdm} \geq 0$ are the Lagrangian multipliers corresponding to constraint \eqref{FlowConservation} and $\boldsymbol{\phi} \geq \boldsymbol{0}$, respectively.

Suppose $\boldsymbol{\phi}$ is a global optimal solution to \eqref{JointProblem_nodebased}, then there must exist a set of $(\boldsymbol{\lambda},\boldsymbol{\mu})$ such that \cite{bertsekas1997nonlinear}
\begin{gather*}
    \frac{\partial L}{\partial \phi^-_{ij}(d,m)} = 0, \quad \frac{\partial L}{\partial \phi^+_{ij}(d,m)} = 0,
    %\\\frac{\partial L}{\partial \lambda^-_{idm} = 0}, \quad \frac{\partial L}{\partial \lambda^+_{idm} = 0},
    \\\mu^-_{ijdm}\phi^-_{ij}(d,m) = 0, \quad \mu^+_{ijdm}\phi^+_{ij}(d,m) = 0.
\end{gather*}
By Section \ref{Section:condition}, for this set of $(\boldsymbol{\lambda},\boldsymbol{\mu})$, it holds that
\begin{equation*}
\begin{aligned}
   \frac{\partial L}{\partial \phi_{ij}^{\pm}(d,m)} &= \frac{\partial T}{\partial \phi^{\pm}_{ij}(d,m)} - \lambda^\pm_{idm} - \mu^{\pm}_{ijdm}.
\end{aligned}
\end{equation*}
Combining above with the complementary slackness $\mu^{\pm}_{ijdm}\phi^{\pm}_{ij}(d,m) = 0$ (i.e., when $\phi^{\pm}_{ij}(d,m) > 0$, it must hold that $\mu^{\pm}_{ijdm} = 0$), and notice the arbitrariness of $\mu^{\pm}_{ijdm}$ when $\phi^{\pm}_{ij}(d,m) = 0$, we know that 
\begin{equation*}
    \frac{\partial T}{\partial \phi^{\pm}_{ij}(d,m)} \begin{cases}
        = \lambda^{\pm}_{idm}, \quad \text{if } \phi^{\pm}_{ij}(d,m) > 0,
        \\> \lambda^{\pm}_{idm} \quad \text{if } \phi^{\pm}_{ij}(d,m) = 0.
    \end{cases}
\end{equation*}
Therefore, Lemma \ref{Lemma_Necessary} holds by taking 
\begin{equation*}
\begin{gathered}
    \lambda^{-}_{idm} = \min_{j \in \{0\}\cup\mathcal{N}_i} \partial T/\partial \phi_{ij}^-(d,m), \\ \lambda^{-}_{idm} = \min_{j \in \mathcal{N}_i} \partial T/\partial \phi_{ij}^+(d,m)
\end{gathered}
\end{equation*}
in the above.
