\subsection{Proof of Theorem \ref{Thm_Sufficient}}
\label{proof:thm_sufficient}

For simplicity, we consider the non-destination nodes in this proof. Namely, we assume $\sum_{j} \phi_{ij}^+ = 1$ for all $i$, while the derivation is applicable to destination nodes by enforcing those $\phi_{ij}^+\equiv0$.
%by (\ref{partial_D_r}), (\ref{SuffCond_1}), %and (\ref{FlowConservation1.1}),
By \eqref{partial_D_r} and \eqref{delta},  we have 
\begin{align*}
    \frac{\partial T}{\partial r_i(d,m)} &= \sum_{j \in \left\{0\right\} \cup \mathcal{N}_i} \phi_{ij}^-(d,m) \delta_{ij}^-(d,m) 
    \\ &= \sum_{j : \phi_{ij} > 0} \phi_{ij}^-(d,m) \lambda_{idm}^- 
    \\ &= \lambda_{idm}^-,
\end{align*}
where $\lambda^{-}_{idm} = \min_{j \in \{0\}\cup\mathcal{N}_i} \partial T/\partial \phi_{ij}^-(d,m)$ is the Lagrangian multiplier for the constraint $\sum_{j} \phi_{ij}^- = 1$. Thus when \eqref{Condition_sufficient} holds, we have for all $i$ and $(d,m)$,
\begin{align}
    \delta_{ij}^-(d,m) \geq \frac{\partial T}{\partial r_i(d,m)}, \forall j \in \left\{0 \right\} \cup \mathcal{N}_i. \label{SuffCond_alt1}
\end{align}
Similarly we have for all $i$ and $(d,m)$,
\begin{align}
    \delta_{ij}^+(d,m) \geq \frac{\partial T}{\partial t_i^+(d,m)}, \quad \forall j \in \mathcal{N}_i. \label{SuffCond_alt2}
\end{align}

To prove $ \boldsymbol{\phi}$ satisfying \eqref{Condition_sufficient} minimizes $$T = \sum_{(i,j) \in \mathcal{E}}D_{ij}(F_{ij}) + \sum_{i \in \mathcal{V}}C_i(G_i),$$ let $\boldsymbol{\phi}^* \neq \boldsymbol{\phi}$ be another feasible set of variable, and with corresponding packet rates link flows and computation workload $F_{ij}^*, \forall (i,j) \in \mathcal{E}$ and $G_i^*, \forall i \in \mathcal{V}$.
Given both $\boldsymbol{\phi}$ and $\boldsymbol{\phi}^*$ are both feasible routing/offloading strategies, we know $(F_{ij},G_i)$ and $(F_{ij}^*,G_i^*)$ are in the feasible set (a convex polytope) of the flow model problem (\ref{JointProblem}). 
\begin{align}
    \min_{f^-,f^+,g} \quad & T = \sum_{(i,j) \in \mathcal{E}} D_{ij}(F_{ij}) + \sum_{i \in \mathcal{V}}C_i(G_i) \label{JointProblem}
    \\ \text{such that} \quad &  \text{\eqref{flowconservation_f_domain} hold,} \nonumber
    \\ & g_i(d,m) \geq 0, \, f_{ij}^-(d,m) \geq 0, \,f_{ij}^+(d,m) \geq 0, \nonumber
\end{align}
Due to the convexity of the feasible set of \eqref{JointProblem}, for any $\mu \in [0,1]$, $\left( (1 - \mu) F_{ij} + \mu F_{ij}^* ,  (1 - \mu) G_i + \mu G_i^* \right)$ is also feasible for (\ref{JointProblem}), we then let
\begin{align*}
   T(\mu) &= \sum_{(i,j) \in \mathcal{E}}D_{ij}(  (1 - \mu) F_{ij} + \mu F_{ij}^* ) 
   \\ &+ \sum_{i \in \mathcal{V}}C_i((1 - \mu) G_i + \mu G_i^*). %\quad \mu \in [0,1].
\end{align*}
Since $T$ is convex in $f^-$, $f^+$ and $g$, we know $T(\mu)$ is convex in $\mu$. Thus combining with the arbitrary choice of $\boldsymbol{\phi}^*$, the sufficiency in Theorem \ref{Thm_Sufficient} is proved if $\frac{d T(\mu)}{d \mu}$ is non-negative at $\mu = 0$. That is, we will show the following is non-negative
\begin{equation}
\begin{aligned}
    \frac{d T(\mu)}{ d \mu} \bigg|_{\mu = 0} &= \sum_{(i,j) \in \mathcal{E}}D^\prime_{ij}(F_{ij}) (F_{ij}^* - F_{ij}) 
    %\\ &+ \sum_{i \in V}  C_i^\prime (G_i)(G_i^{*} - G_i) 
    \\ &+ \sum_{i \in \mathcal{V}} C^\prime_i(G_i) (G_i^{*} - G_i). 
    %\\ & \geq 0.
\end{aligned}    
\label{proof_obj}
\end{equation}

Starting with the data flow, multiply both side of (\ref{SuffCond_alt1}) by $\phi_{ij}^{-*}(d,m)$ and sum over $j \in \left\{ 0 \right\} \cup \mathcal{N}_i $, we have
\begin{equation}
\begin{gathered}
    w_{im}C^\prime_i(G_i) \phi_{i0}^{-*}(d,m) + \sum_{j \in \mathcal{N}_i} L_m^-D_{ij}^\prime(F_{ij}) \phi_{ij}^{-*}(d,m) 
    \\ \geq \frac{\partial T}{\partial r_i(d,m)} - \frac{\partial T}{\partial t_i^+(d,m)} \phi_{i0}^{-*}(d,m) 
    \\ - \sum_{j \in \mathcal{N}_i} \frac{ \partial T}{\partial r_j(d,m)} \phi_{ij}^{-*}(d,m),
\end{gathered}    
\label{proof_ineqToEq1}
\end{equation}
then multiply both side by $t_i^{-*}(d,m) = \sum_{j \in \mathcal{N}_i}f_{ji}^{-*}(d,m) + r_i(d,m)$, we have
\begin{align*}
     &w_{im}C^\prime_i(G_i) g_i^{*}(d,m) + L_m^-\sum_{j \in \mathcal{N}_i} D_{ij}^\prime(F_{ij}) f_{ij}^{-*}(d,m)
    \\ \geq &  t_i^{-*}(d,m) \frac{\partial T}{\partial r_i(d,m)} -  \frac{\partial T}{\partial t_i  ^+(d,m)} t_i^{-*}(d,m) \phi_{i0}^{-*}(d,m) 
    \\ - &\sum_{j \in \mathcal{N}_i} \frac{ \partial T}{\partial r_j(d,m)} t_i^{-*}(d,m) \phi_{ij}^{-*}(d,m),
\end{align*}
further sum over $(d,m) \in \mathcal{T}$ and $i \in \mathcal{V}$, the RHS of above  becomes
\begin{equation*}
\begin{gathered}
    \sum_{i \in \mathcal{V}} \sum_{(d,m) \in \mathcal{T}} w_{im}C^\prime_i(G_i) g_i^{*}(d,m) 
    \\ + \sum_{(i,j) \in \mathcal{E}} \sum_{(d,m) \in \mathcal{T}} L_m^- D_{ij}^\prime(F_{ij}) f_{ij}^{-*}(d,m)
    \\= \sum_{i\in\mathcal{V}} C^\prime_i(G_i) G_i^* + \sum_{(i,j) \in \mathcal{E}}D^\prime_{ij}(F_{ij})F^{-*}_{ij}
\end{gathered}
\end{equation*}
thus
\begin{equation}
\begin{aligned}
    &\sum_{i\in\mathcal{V}} C^\prime_i(G_i) G_i^* + \sum_{(i,j) \in \mathcal{E}}D^\prime_{ij}(F_{ij})F^{-*}_{ij}
    \\ &\geq \sum_{i \in \mathcal{V}} \sum_{(d,m) \in \mathcal{T}} t_i^{-*}(d,m) \frac{\partial T}{\partial r_i(d,m)} 
    \\ &- \sum_{i \in \mathcal{V}} \sum_{(d,m) \in \mathcal{T}}    \frac{\partial T}{\partial t_i^+(d,m)} t_i^{-*}(d,m) \phi_{i0}^{-*}(d,m)
    \\  &- \sum_{(d,m) \in \mathcal{T}} \sum_{i \in \mathcal{V}} \sum_{j \in \mathcal{N}_i } \frac{ \partial T}{\partial r_j(d,m)} t_i^{-*}(d,m) \phi_{ij}^{-*}(d,m),
\end{aligned}   
\label{proof_sum_1}
\end{equation}
where $F_{ij}^{-*} = \sum_{(d,m) \in \mathcal{T}} f_{ij}^{-*}(d,m)$.

Meanwhile, by the flow conservation \eqref{flowconservation_f_domain}, we know that for all $j \in \mathcal{V}, (d,m) \in \mathcal{T}$,
\begin{align*}
    \sum_{i \in \mathcal{N}_i} t_i^{-*}(d,m) \phi_{ij}^{-*}(d,m) = t_j^{-*}(d,m) - r_j(d,m).%, \quad \forall j \in V, \forall (d,m) \in S.
\end{align*}
Substitute above into the very last term in (\ref{proof_sum_1}) and cancel, we get
\begin{equation}
\begin{aligned}
    &\sum_{i\in\mathcal{V}} C^\prime_i(G_i) G_i^* + \sum_{(i,j) \in \mathcal{E}}D^\prime_{ij}(F_{ij})F^{-*}_{ij}
    \\  & \geq \sum_{i \in \mathcal{V}} \sum_{(d,m) \in \mathcal{T}} r_i(d,m)\frac{\partial T}{\partial r_i(d,m) } 
    \\ &- \sum_{i \in \mathcal{V}} \sum_{(d,m) \in \mathcal{T}} g_i^{*}(d,m) \frac{\partial T}{\partial t_i^+(d,m)}.
   % \\ = & \sum_{i \in V} \sum_{(d,m) \in S} r_i(d,m)\frac{\partial D}{\partial r_i(d,m) } - \sum_{i \in V} \sum_{(d,m) \in S} \gamma_m \gamma_i^m(d,m) t_i^{-*}(d,m) \phi_{i0}^{-*}(d,m)
\end{aligned}
\label{proof_sum_1_final}
\end{equation}

Next, about the flow of computation result, multiply both side of (\ref{SuffCond_alt2}) by $\phi_{ij}^{+*}(d,m)$ and sum over $j \in \mathcal{N}_i $, we have
\begin{equation}
\begin{aligned}
    &\sum_{j \in \mathcal{N}_i}L_m^+D_{ij}^\prime(F_{ij}) \phi_{ij}^{+*}(d,m) 
    \\ \geq & \frac{\partial T}{\partial t_i^+(d,m)} - \sum_{j \in \mathcal{N}_i} \frac{\partial T}{\partial t_j^+(d,m)} \phi_{ij}^{+*}(d,m).
\end{aligned}    
\label{proof_ineqToEq2}
\end{equation}

Multiply both side by $t_i^{+*}(d,m) = \sum_{j \in \mathcal{N}_i}f_{ji}^{+*}(d,m) + g_i^{*}(d,m)$, sum over $(d,m) \in \mathcal{T}$ and $j \in \mathcal{V}$, we get
\begin{equation}
\begin{aligned}
    &\sum_{(i,j) \in \mathcal{E}}D_{ij}^\prime(F_{ij}) F_{ij}^{+*} 
    \\ &\geq \sum_{i \in \mathcal{V}} \sum_{(d,m) \in \mathcal{T}} t_i^{+*}(d,m) \frac{\partial T}{\partial t_i^+(d,m)} 
    \\ &- \sum_{(d,m)\in \mathcal{T}} \sum_{i \in \mathcal{V}} \sum_{j \in \mathcal{N}_i} t_i^{+*}(d,m) \frac{\partial T}{\partial t_j^+(d,m)} \phi_{ij}^{+*}(d,m) .
\end{aligned}    
 \label{proof_sum_2}
\end{equation}

By \eqref{flowconservation_f_domain}, we have for all $ j \in \mathcal{V}, (d,m) \in \mathcal{T}$,
\begin{align*}
    \sum_{i \in \mathcal{N}_i} t_i^{+*}(d,m) \phi_{ij}^{+*}(d,m) = t_j^{+*}(d,m) - g_j^{*}(d,m). 
\end{align*}

Substituting above into the very last term in (\ref{proof_sum_2}) and canceling, we get
\begin{align}
    \sum_{(i,j) \in \mathcal{E}} D_{ij}^\prime(F_{ij}) F_{ij}^{+*} \geq \sum_{i \in \mathcal{V}} \sum_{(d,m) \in S} g_i^{*}(d,m) \frac{\partial T}{\partial t_i^+(d,m)}.
     \label{proof_sum_2_final}
\end{align}

Summing up both side of (\ref{proof_sum_1_final}) and (\ref{proof_sum_2_final}), we have
\begin{equation}
\begin{aligned}
     &\sum_{i \in \mathcal{V}} C^\prime_i(G_i)G_i^* + \sum_{(i,j) \in \mathcal{E}} D_{ij}^\prime(F_{ij}) F_{ij}^{*} 
     \\ & \geq \sum_{i \in \mathcal{V}} \sum_{(d,m) \in \mathcal{T}} \frac{\partial T}{\partial r_i(d,m)} r_i(d,m).
\end{aligned}    
 \label{proof_ineq}
\end{equation}

Note that the equality would always hold in (\ref{proof_ineqToEq1}) and (\ref{proof_ineqToEq2}) if we substitute $\boldsymbol{\phi}^*$ with $\boldsymbol{\phi}$ in the above reasoning, as a consequence of (\ref{partial_D_r}) and (\ref{partial_D_t}).
Thus we have the following analogue of (\ref{proof_ineq}),
\begin{equation}
\begin{aligned}
    &\sum_{i \in \mathcal{V}} C^\prime_i(G_i)G_i + \sum_{(i,j) \in \mathcal{E}} D_{ij}^\prime(F_{ij}) F_{ij} 
    \\& = \sum_{i \in \mathcal{V}} \sum_{(d,m) \in \mathcal{T}} \frac{\partial T}{\partial r_i(d,m)} r_i(d,m).
\end{aligned}    
\label{proof_eq}
\end{equation}

Abstracting (\ref{proof_eq}) from (\ref{proof_ineq}), we show (\ref{proof_obj}) and complete the proof.

\subsection{Proof of Theorem \ref{thm:stability}}
\label{Proof:thm_stability}

We prove Theorem \ref{thm:stability} based on the following lemma.
%, we only need to prove the following statement:

\begin{lem}
\label{lem:stability}
Let $\boldsymbol{r} \in \mathcal{D}_{\boldsymbol{r}}$ and $\boldsymbol{\phi} \in \mathcal{D}_{\boldsymbol{\phi}}(\boldsymbol{r})$ satisfies condition \eqref{Condition_sufficient} given input $\boldsymbol{r}$, then there exist a function $\epsilon(\delta)$ for $\delta > 0$, %defined on $\delta \in (0,\infty)$, 
such that $\lim_{\delta \to 0}\epsilon(\delta) = 0$, and the following holds:

For all $\Delta \boldsymbol{r}$ that $\left|\Delta \boldsymbol{r}\right| < \delta$ and $\left(\boldsymbol{r} + \Delta \boldsymbol{r}\right) \in \mathcal{D}_{\boldsymbol{r}}$, there exists a corresponding $\Delta\boldsymbol{\phi}$ that $\left|\Delta\boldsymbol{\phi}\right| < \epsilon(\delta)$, $\left(\boldsymbol{\phi} + \Delta\boldsymbol{\phi}\right) \in \mathcal{D}_{\boldsymbol{\phi}}\left(\boldsymbol{r} + \Delta \boldsymbol{r}\right)$, and $\left(\boldsymbol{\phi} + \Delta\boldsymbol{\phi}\right)$ satisfies condition \eqref{Condition_sufficient} given input $\left(\boldsymbol{r} + \Delta \boldsymbol{r}\right)$.
\end{lem}

Let \( \boldsymbol{r} \in \mathcal{D}_{\boldsymbol{r}} \) and \( \boldsymbol{\phi} \in F_{\text{suff}}(\boldsymbol{r}) \) be given. Let \( \{ \boldsymbol{r}^n \} \subset \mathcal{D}_{\boldsymbol{r}} \) be a sequence such that \( \boldsymbol{r}^n \to \boldsymbol{r} \). Define \( \delta_n = \|\boldsymbol{r}^n - \boldsymbol{r}\| \to 0 \).
By Lemma \ref{lem:stability}, for each \( n \), there exists \( \boldsymbol{\phi}^n \in F_{\text{suff}}(\boldsymbol{r}^n) \):
\[
\| \boldsymbol{\phi}^n - \boldsymbol{\phi} \| < \epsilon(\delta_n),
\]
and \( \lim_{n \to \infty} \epsilon(\delta_n) = 0 \). Hence, \( \boldsymbol{\phi}^n \to \boldsymbol{\phi} \).

Therefore, for every \( \boldsymbol{\phi} \in F_{\text{suff}}(\boldsymbol{r}) \) and every sequence \( \boldsymbol{r}^n \to \boldsymbol{r} \), we can construct a sequence \( \boldsymbol{\phi}^n \in F_{\text{suff}}(\boldsymbol{r}^n) \) such that \( \boldsymbol{\phi}^n \to \boldsymbol{\phi} \). This proves that \( F_{\text{suff}} \) is LHC at \( \boldsymbol{r} \).

\begin{proof}[proof of Lemma \ref{lem:stability}]

For analytical simplicity, we only prove for the case where $\Delta \boldsymbol{r}$ has only one non-zero element, that is, only $\Delta r_{i}(a,k) \neq 0$. General cases can be seen as a finite accumulations of this simple case.

Without loss of generality, we assume $|\mathcal{T}| = 1$ and assume a pure-routing scheme, i.e., the network only performs packet forwarding for only one task, without the need to conduct any computation. 
This simplifies the network formulation to Gallager's original setting \cite{gallager1977minimum}. 
Joint considering routing and computation is a naive extension of the pure routing case, as one can treat ``computing unit'' as one of network ``links'' .

Therefore, we omit the notation $(d,m)$ for simplicity.
We further assume all communication cost functions $D_{ij}(\cdot)$ are strictly convex.

Suppose $\boldsymbol{\phi}$ satisfies the sufficient condition \eqref{Condition_sufficient} with input rate $\boldsymbol{r}$, it is evident that $\boldsymbol{\phi}$ is loop-free.
When the input rate $r_i$ is increased by a sufficiently small $\Delta r_i$ ($\Delta r_i$ can be positive or negative, as long as the new input rate vector lies within stability region $\mathcal{D}_{\boldsymbol{r}}$. Without loss of generality, we assume $\Delta r_i > 0$), we apply Algorithm \ref{alg:sgp} one node at a time, starting from node $i$.
Consider the change of $[\delta_{ij}]$ for all $j$ when the forwarding strategy $\boldsymbol{\phi}$ is kept unchanged.
To break down the problem, consider the DAG (directed acyclic graph) constructed by $(i,j)\in\mathcal{E}$ such that $\phi_{ij} > 0$.

(1) If node $i$ is the destination node $d$, then $\delta_{ij}$ is not changed on any link.

(2) If node $i$ is one-hop away from $d$, then it must hold that $\phi_{id} = 1$ and $\phi_{ij} = 0$ for all other $j$. In this case, $\delta_{id} = D_{id}^\prime(f_{id})$, and $$\Delta \delta_{id} = D_{id}^\prime(f_{id} + \Delta r_i) - D_{id}^\prime(f_{id}) = \Delta r_i D^{\prime\prime}_{id}(f_{id}).$$
Therefore, we let $\delta^\prime_{id}$ be the marginal increase of $\delta_{id}$ due to the increase of $r_i$, and $$\delta^\prime_{id} = \frac{\Delta \delta_{id}}{\Delta r_i} = D^{\prime\prime}_{id}(f_{id}).$$
Moreover, let $\delta_i = \sum_{j} \phi_{ij} \delta_{ij}$, then $\delta^\prime_i = \sum_{j} \phi_{ij} \delta^\prime_{ij}$. In this case, $\delta_i^\prime = D^{\prime\prime}_{id}(f_{id})$.

(3) If node $i$ is more than one-hop away from $d$, then it holds that
\begin{equation}
\begin{aligned}
    &\delta_{ij}^\prime = D^{\prime\prime}_{ij}(f_{ij}) + \delta^\prime_j,
    \\& \delta_i^\prime =  \sum_{j} \phi_{ij} \delta^\prime_{ij}.
\end{aligned}
\label{proof_second_deri}
\end{equation}
We denote all paths from node $i$ to $d$ in the DAG by set $\mathcal{P}_i$, where each path $p \in \mathcal{P}_i$ is a sequence of nodes $(p_1,p_2,\cdots,p_{|p|})$ with $p_1 = i$, $p_{|p|} = d$ and $\phi_{p_k p_{k+1}} >0$ for $k = 1,\cdots,|p|-1$.
Therefore, by recursively applying \eqref{proof_second_deri} from node $d$ to node $i$ on the reverse direction for all path in $\mathcal{P}_i$, we have
\begin{equation}
\begin{aligned}
    \delta^\prime_i &= \sum_{p \in \mathcal{P}_i} \left(D^{\prime\prime}_{p_1p_2} + \left(D^{\prime\prime}_{p_2p_3} + \cdots \right)\phi_{p_2p_3}\right)\phi_{p_1p_2}
    \\ &= \sum_{p \in \mathcal{P}_i} \left(\sum_{k = 1}^{|p|-1} D^{\prime\prime}_{p_kp_{k+1}}\prod_{l = 1}^k \phi_{p_lp_{l+1}}\right)
\end{aligned}
\label{proof_delta_prime}
\end{equation}

Combining the above cases, we know that for any $i$, when $r_i$ in increased by a small amount $\Delta r_i$, the marginal cost $\delta_{ij}$ for an arbitrary $j$ is increased by
\begin{equation*}
    \Delta \delta_{ij} = \Delta r_i \left(D^{\prime\prime}_{ij} + \sum_{p \in \mathcal{P}_j} \left(\sum_{k = 1}^{|p|-1} D^{\prime\prime}_{p_kp_{k+1}}\prod_{l = 1}^k \phi_{p_lp_{l+1}}\right) \right).
\end{equation*}
Therefore, recall the algorithm update \eqref{variable_update}, and combined with the fact that $\boldsymbol{\phi}$ already satisfies \eqref{Condition_sufficient}. %suppose we use a sufficiently small stepsize $\alpha$, 
By the sensitivity of Lagrangian multipliers, the adjust amount $\Delta \phi_{ij} \equiv \phi^1_{ij} - \phi_{ij}$ is upper bounded by 
\begin{equation}
\label{proof_bound}
    \Delta \phi_{ij} \leq \alpha \Delta \delta_{ij}
\end{equation}
%Thus there exists a constant $C$ such that $\Delta \phi_{ij} \leq C \Delta r_i$.
where the finite constant $\alpha$ is given by the Lagrangian multiplier of problem \eqref{variable_update}.
Moreover, it is shown by \cite{xi2008node} that Algorithm \ref{alg:sgp} converges linearly to the optimal solution satisfying \eqref{Condition_sufficient}.
By adopting section order methods, e.g., \cite{bertsekas1984second}, the rate of convergence can be enhanced to super-linear.
%Therefore, for a given stepsize $\alpha$, when $\Delta r_i$ is sufficiently small, one step of the algorithm will lead to an optimal solution with the distance of at most $O(\Delta \boldsymbol{\phi})$.
Therefore, let $\boldsymbol{\phi}^*$ be the convergent solution of Algorithm \ref{alg:sgp} after introducing $\Delta r_i$, there exist a finite scalar $M$ that
\begin{equation}
\label{proof_distance_bound}
    {|\boldsymbol{\phi}^{t+1} - \boldsymbol{\phi}^*|} \leq M {|\boldsymbol{\phi}^{t} - \boldsymbol{\phi}^*|},
\end{equation}
and there exists a scalar $\mu < 1$ such that 
\begin{equation}
\label{proof_convergence_rate}
    \lim_{t \to \infty} \frac{|\boldsymbol{\phi}^{t+1} - \boldsymbol{\phi}^*|}{|\boldsymbol{\phi}^{t} - \boldsymbol{\phi}^*|} = \mu.
\end{equation}

%Let $\boldsymbol{\phi}^*$ be the convergent solution of Algorithm \ref{alg_GP} after introducing $\Delta r_i$, 
Combining \eqref{proof_bound}\eqref{proof_distance_bound}\eqref{proof_convergence_rate}, there exists a finite constant $C$ such that $| \boldsymbol{\phi}^* - \boldsymbol{\phi}| \leq C\Delta r_i$, i.e., $$\lim_{\Delta r_i \to 0}| \boldsymbol{\phi}^* - \boldsymbol{\phi}| = 0.$$

Therefore, there exist a function $\epsilon(\delta)$ for $\delta > 0$ continuous at $0$, %defined on $\delta \in (0,\infty)$, 
and for $\Delta r_i$ that $\left|\Delta r_i\right| < \delta$, the corresponding new optimal solution $\boldsymbol{\phi}^*$ satisfies $| \boldsymbol{\phi}^* - \boldsymbol{\phi}| \leq \epsilon(\delta)$.
To generalize to multiple applications or multiple non-zero input rate $r_i$ changes, the analysis above still holds, as the constant $C$ would be the sum of all applications and all $\Delta r_i$, however, still finite.
To generalize to computation placement, one only needs to consider each computation step as a special link that goes back to the computation node itself, with a link cost associated.
\end{proof}

