\begin{abstract}
\par In this paper we present an efficient active-set method for the solution of convex quadratic programming problems with general piecewise-linear terms in the objective, with applications to sparse approximations and risk-minimization. The algorithm is derived by combining a proximal method of multipliers (PMM) with a standard semismooth Newton method (SSN), and is shown to be globally convergent under minimal assumptions. Further local linear (and potentially superlinear) convergence is shown under standard additional conditions. The major computational bottleneck of the proposed approach arises from the solution of the associated SSN linear systems. These are solved using a Krylov-subspace method, accelerated by certain novel general-purpose preconditioners which are shown to be optimal with respect to the proximal penalty parameters. The preconditioners are easy to store and invert, since they  exploit the structure of the nonsmooth terms appearing in the problem's objective to significantly reduce their memory requirements. We showcase the efficiency, robustness, and scalability of the proposed solver on a variety of problems arising in risk-averse portfolio selection, $L^1$-regularized partial differential equation constrained optimization, quantile regression, and binary classification via linear support vector machines. We provide computational evidence, on real-world datasets, to demonstrate the ability of the solver to efficiently and competitively handle a diverse set of medium- and large-scale optimization instances.
\end{abstract}

\section{Introduction}
\subsection{Problem formulation}
\par In this paper we consider convex optimization problems of the following form:
\begin{equation}\label{primal problem} \tag{P}
\begin{split}
\underset{x \in \mathbb{R}^n}{\text{min}}&\quad \left\{c^\top x + \frac{1}{2}x^\top Q x + \sum_{i = 1}^l \left( \left(C x + d\right)_{i}\right)_+ + \delta_{\mathcal{K}}(x)\right\}, \\ 
\textnormal{s.t.} &\quad \ A x = b,
\end{split}
\end{equation}
\noindent where $c \in \mathbb{R}^n$, $Q \in \mathbb{R}^{n \times n}$ is a positive semi-definite matrix, $C \in \mathbb{R}^{l\times n}$, $d \in \mathbb{R}^l$, $A \in \mathbb{R}^{m\times n}$ is a linear constraint matrix with $b\in \mathbb{R}^m$ a given right-hand side, and $\mathcal{K}$ is a closed convex set $\mathcal{K} \triangleq \{x \in \mathbb{R}^n \vert\ x \in \left[a_l,a_u\right]\}$, with $a_l,\ a_u \in \mathbb{R}^n$, such that $(a_l)_i \in \mathbb{R}\cup\{-\infty\},\ (a_u)_i \in \mathbb{R}\cup \{+\infty\}$, for all $i = 1,\ldots,n$. Additionally, $(\cdot)_+ \equiv \max\{\cdot,0\}$, while $\delta_{\mathcal{K}}(\cdot)$ is an indicator function for the set $\mathcal{K}$, that is, $\delta_{\mathcal{K}}(x) = 0$ if $x \in \mathcal{K}$, and $\delta_{\mathcal{K}}(x) = \infty$ otherwise.
\par For simplicity, we introduce some additional notation and equivalently write \eqref{primal problem} as
\begin{equation*} 
\begin{split}
\underset{x \in \mathbb{R}^n}{\text{min}} & \left\{f(x) +  h(Cx+d)  + \delta_{\mathcal{K}}(x)\right\},\\
\textnormal{s.t.} &\  Ax = b.
\end{split}
\end{equation*}
\noindent where we define $f(x) \triangleq c^\top x + \frac{1}{2}x^\top Q x$, and $h(w) \triangleq \sum_{i=1}^{l} (w_i)_+$.
\begin{remark} \label{remark: l1 norm reformulation}
\par Let us notice that the model in \eqref{primal problem} can readily accommodate terms of the form of $\|Cx + d\|_1$ where $C \in \mathbb{R}^{l\times n}$, and $d \in \mathbb{R}^l$. Indeed, letting $c = c - C^\top \mathds{1}_l$ and adding the constant term $-\mathds{1}_l^\top d$ in the objective of \eqref{primal problem}, we notice that
\[\|Cx + d\|_1 \equiv -\mathds{1}_l^\top (Cx + d) + \sum_{i=1}^l \left(2(Cx + d)_i\right)_+, \]
where $\mathds{1}_l \triangleq (1,\ldots,1)^\top \in \mathbb{R}^l$. Similarly, any piecewise-linear term of the form 
\[\sum_{i=1}^l\max\left\{\left(C_1 x+ d_1\right)_i, \left(C_2 x+ d_2\right)_i\right\},\]
\noindent where $C_1,\ C_2 \in \mathbb{R}^{l\times n}$ and $d_1,\ d_2 \in \mathbb{R}^l$, can also be readily modeled. Specifically, setting $c = c + C_2^\top\mathds{1}_l$ and adding the constant term $d_2^\top \mathds{1}_l$ in the objective yields
\[ \mathds{1}_l^\top \left(C_2 x + d_2\right) + \sum_{i=1}^l \left(\left(C_1 x + d_1 - C_2x - d_2\right)_i \right)_+ \equiv \sum_{i = 1}^l \max\left\{\left(C_1 x + d_1\right)_i,\left(C_2 x + d_2\right)_i \right\}.\]
\noindent Finally, it is important to note that model \eqref{primal problem} allows for multiple piecewise-linear terms of the form $\max\{Cx + d,0_l\}$, $\|Cx + d\|_1$ or $\max\left\{C_1 x+ d_1, C_2 x+ d_2\right\}$, since we can always adjust $l$ to account for more than one terms. Hence, one can observe that \eqref{primal problem} is very general and can be used to model a plethora of very important problems that arise in practice. 
\end{remark}
\par Let $F \triangleq [A^\top\ -C^\top]^\top$ and $\hat{b} \triangleq [b^\top\ d^\top]^\top$. Using Fenchel duality, we can verify (see Appendix \ref{Appendix: derivation of dual}) that the dual of \eqref{primal problem} is
\begin{equation} \label{dual problem} \tag{D}
\begin{split}
\underset{x \in \mathbb{R}^n, y \in \mathbb{R}^{m+l}, z \in \mathbb{R}^n}{\text{max}} &\  \hat{b}^\top y - \frac{1}{2} x^\top Q x - \delta^*_{\mathcal{K}}(z) - h^*(y_{m+1:m+l}),\\
\textnormal{s.t.}\qquad \ \ &\ c + Qx -F^\top y + z = 0_n.
\end{split}
\end{equation}
\noindent Throughout the paper we make use of the following blanket assumption.
\begin{assumption} \label{assumption: solution of the QP}
Problems \eqref{primal problem} and \eqref{dual problem} are both feasible and $A$ has full row rank.
\end{assumption}
\noindent If $C = 0_{0,n}$, using \cite[Proposition 2.3.4]{BertsekasNedicOzdaglar} we note that Assumption \ref{assumption: solution of the QP} implies that there exists a primal-dual triple $(x^*,y^*,z^*)$ solving \eqref{primal problem}--\eqref{dual problem}. If the primal-dual pair \eqref{primal problem}--\eqref{dual problem} is feasible, it must remain feasible for any $C \in \mathbb{R}^{l\times n}$, since in this case \eqref{primal problem} can be written as a convex quadratic problem by appending appropriate (necessarily feasible) linear inequality constraints. Thus, Assumption \ref{assumption: solution of the QP} suffices to guarantee that the solution set of \eqref{primal problem}--\eqref{dual problem} is non-empty.
\par  In light of the discussion in Remark \ref{remark: l1 norm reformulation}, we observe that \textbf{problem \eqref{primal problem} models a plethora of very important problems arising in several application domains} spanning, among others, operational research, machine learning, data science, and engineering. More specifically, \eqref{primal problem} can model linear and convex quadratic programming instances, regularized (fused) lasso instances (often arising in signal or image processing and machine learning, e.g., see \cite{SIREV:Chenetal,SIREV:DeSimone_etal,bookVapnik,JRSS:Zou}), or portfolio allocation problems \cite{JBanFin:AlexColYi} arising in finance. Furthermore, various optimal control problems can be tackled in the form of \eqref{primal problem}, such as those arising from $L^1$-regularized partial differential equation (PDE) constrained optimization, assuming that a \emph{discretize-then-optimize} strategy is adopted (e.g., see \cite{ESAIM:GerdDaniel}). Additionally, various risk-minimization problems with linear random cost functions can be modeled by \eqref{primal problem} (e.g., see \cite{MathFin:LiNg,JRisk:RockUry,Prod:Silva_etal}). Nonetheless, even risk-minimization problems with nonlinear random cost functions, which are typically solved via Gauss-Newton schemes (e.g., see \cite{MathProg:Burke}), often require the solution of sub-problems of the form of \eqref{primal problem}. Finally, continuous relaxations of integer programming problems with applications in operational research (e.g., \cite{MathProg:Laz}) often take the form of \eqref{primal problem}. Given the multitude of problems requiring easy access to (usually accurate) solutions of \eqref{primal problem}, the derivation of efficient, robust, and scalable solution methods is of paramount importance and has naturally attracted a lot of attention in the literature. 
\subsection{Existing solution methods}
\par There is a large variety of first-order methods capable of finding an approximate solution to \eqref{primal problem}. For example, one could employ proximal (sub-)gradient (e.g., see \cite{SIAM:Beck}) or splitting schemes (e.g., see \cite{SciComp:DengYin}). While such solution methods are very general, easy to implement, and require very little memory, they are usually able to find only highly approximate solutions, not exceeding 2- or 3-digits of accuracy. If a more accurate solution is needed, then one has to resort to an approach that utilizes second-order information. 
\par There are three major classes of second-order methods for problems of the form of \eqref{primal problem}. Those include globalized (smooth, semismooth, quasi or proximal) Newton methods (e.g., see \cite{MathOR:Han,CAM:MartQi,COAP:Stella_etal}), variants of the proximal point method (e.g., see \cite{COAP:Marchi,IEEE_CDC:Dhingra_etal,MathProgComp:Hermans_etal,SIAMOPT:Leeetal,SIAMOpt:Lietal}), or interior point methods (IPMs) applied to a reformulation of \eqref{primal problem} (e.g., see \cite{SIREV:DeSimone_etal,IPMs:FountoulakisEtAl2013,arXiv:GondPougkPears,NLAA:PearsonPorcStoll}). \par Most globalized Newton-like approaches or proximal point variants studied in the literature are developed for composite programming problems in which either $C = 0_{0,n}$ (e.g., see \cite{NLAA:ChenQi,COAP:Marchi,COAP:GillRobi,MathProg:Itoetal,SIAMOpt:Lietal}) or $\mathcal{K} = \mathbb{R}^n$ and the general $\max\{\cdot,0\}$ terms are substituted by separable $\ell_1$ terms (e.g., see \cite{IEEE_CDC:Dhingra_etal,InverseProbs:HansRaasch,SIAMOpt:Lietal2}). Nonetheless, there have been developed certain globalized Newton-like schemes, specialized to the case of $L^1$-regularized PDE-constrained optimization (see \cite{OptEng:MannelRund,CAA:Porcellietal}), in which both $\ell_1$ term as well as box constraints are explicitly handled. We should notice, however, that globalized Newton-like schemes applied to \eqref{primal problem} require additional assumptions (on top of Assumption \ref{assumption: solution of the QP}) to guarantee convergence or stability of the related Newton linear systems arising as sub-problems. Typically, superlinear convergence of Newton-like schemes is observed ``close to a solution". Under additional assumptions, global convergence can be achieved via appropriate line-search or trust-region strategies (e.g., see the developments in \cite{SIAMOpt:Christofetal,MathOR:Han,MathProg:Itoetal,SIAMOpt:Themelis_etal} and the references therein). 
\par The potential convergence and stability issues arising within Newton-like schemes can be alleviated by combining Newton-like methods with proximal point variants. Solvers based on the proximal point method can achieve superlinear convergence, assuming their penalty parameters increase indefinitely at a suitable rate (e.g., see \cite{MathOpRes:Rock,SIAMJCO:Rock}). 
For problems \eqref{primal problem}--\eqref{dual problem}, the sub-problems arising within proximal methods are (possibly nonsmooth) convex optimization instances, and are typically solved by means of semismooth Newton strategies. The associated SSN linear systems are better conditioned than their (possibly regularized) interior-point counterparts (e.g., see \cite{NLAA:BergGondMartPearPoug,SIREV:DeSimone_etal,IPMs:FountoulakisEtAl2013,arXiv:GondPougkPears,IPMs:WaltzMoralNocedOrban}); however, convergence is expected to be slower, as the method does not enjoy the polynomial worst-case complexity of interior-point methods. Nevertheless, these better conditioned linear systems can, in certain cases, allow one to achieve better computational and/or memory efficiency, especially if the nonsmooth terms are appropriately handled. 
\par Various such solvers have been developed and analyzed in the literature. For example, the authors in \cite{SIAMOpt:ZhaoSunToh} developed a dual augmented Lagrangian scheme combined with an SSN method for the solution of semidefinite programming problems and obtained very promising results. This scheme was then utilized for the solution of linear programming problems in \cite{SIAMOpt:Lietal}, and for lasso-regularized problems in \cite{SIAMOpt:Lietal2}. A similar dual augmented Lagrangian-based solver (ALM) was recently developed for square-root Lasso problems in \cite{WangTangSciComp}. Nonetheless, those aforementioned dual ALM solvers are brittle, in that slight alterations in the structure of the problem can significantly hinder their employability and efficiency. For example, a computationally attractive extension of \cite{SIAMOpt:Lietal} to convex quadratic (or, generally, non-separable) programming is by no means obvious and requires a different algorithmic strategy than the dualization approach followed by the authors. Furthermore, there is a \textbf{wide gap in the current literature of proximal-SSN methods concerning the efficient solution of the associated SSN linear systems}. While the convergence results appearing in the literature enable the use of inexact linear system solves (e.g., enabling the use of iterative linear algebra, such as Krylov subspace solvers), no general preconditioning strategies have been proposed or analyzed and the question of exploiting efficient linear algebra in this context is still open.
\subsection{Contributions}
\par In this paper, we develop an active-set method for \eqref{primal problem}--\eqref{dual problem} by employing an appropriate proximal method of multipliers (PMM) using a standard backtraking-linesearch semismooth Newton (SSN) strategy for solving the associated PMM sub-problems. The SSN linear systems are approximately solved by means of Krylov subspace methods, using certain novel general-purpose preconditioners. Unlike most proximal point methods given in the literature (e.g., see the primal approaches in \cite{SIAMOPT:Leeetal,IEEE_DC:Patrinos_etal}, the dual approaches in \cite{SIAMOpt:Lietal2,SIAMOpt:Lietal} or the primal-dual approaches in \cite{COAP:Marchi,COAP:GillRobi,MathOpRes:Rock}), the proposed method introduces  proximal terms for each primal and dual variable of the problem, and this results in Newton linear systems which are easy to precondition and solve. We dualize each of the two nonsmooth terms of the objective in \eqref{primal problem}, which contributes to the simplification of the resulting SSN linear systems, and paves the way for readily analyzing the convergence of the proposed algorithm. Our contributions are summarized as follows:
\begin{itemize}
    \item[$\bullet$] We are able to directly apply the theory developed in \cite{SIAMOpt:Lietal} to show that the proposed outer proximal method of multipliers is globally convergent under mere feasibility assumptions, and locally superlinearly convergent under standard additional assumptions. Importantly, we should mention that the theory in \cite{SIAMOpt:Lietal} was developed to analyze the convergence of a proximal semismooth Newton scheme designed for linear programming. Nonetheless, in this work we showcase that the proposed active-set scheme can be analyzed using this theory, and without requiring any additional assumptions other than those employed in \cite{SIAMOpt:Lietal} in the context of linear programming, despite our model \eqref{primal problem} being significantly more general. We also note the inherent difference of our approach compared to the dual augmented Lagrangian schemes developed in \cite{SIAMOpt:Lietal2,SIAMOpt:Lietal,WangTangSciComp,SIAMOpt:ZhaoSunToh}, which enables the efficient solution of problems with non-separable (smooth or nonsmooth) terms in the objective function of \eqref{primal problem}.
    \par Additionally, by introducing an appropriate augmented Lagrangian penalty function (see Section \ref{sec: PAL penalties}), we obtain continuously differentiable PMM sub-problems. As a result, we are able to apply a standard globally convergent (at a local superlinear rate) backtracking-linesearch semismooth Newton scheme (e.g., see \cite{SIAMOpt:ZhaoSunToh}) for their solution. Thus, our active-set scheme is readily theoretically supported, and covers a very wide range of problems not currently addressed by similar methods in the literature, unless \eqref{primal problem} is reformulated without exploiting its inherent structure.
    \item[$\bullet$] The price to pay for the strong theoretical properties of the proposed approach is that the difficulty arising from the nonsmooth terms is hidden in the solution of the associated SSN linear systems. Nonetheless, we identify a principled way of exploiting the resulting active-set structure, that occurs by utilizing the Clarke subdifferential within SSN, to create novel, robust, and highly efficient preconditioners for the solution of these linear systems by means of Krylov subspace solvers. Specifically, we derive and analyze highly effective preconditioning strategies which we show to be optimal with respect to the penalty parameters of the PMM; that is, the conditioning of the preconditioned linear systems does not deteriorate as we increase the penalty parameters of the PMM (which, in turn, accelerates the convergence of the PMM). Additionally, the preconditioners are versatile and general (i.e., not problem-dependent), and are very manageable in terms of memory requirements, giving a strong computational edge of the proposed approach compared to alternative second-order methods. The developed linear algebra kernel of our method showcases the advantages of utilizing active-set schemes compared to alternative (state-of-the-art) interior point methods for similar problems; such a study was missing from the field of augmented Lagrangian methods, and we argue that it should be capitalized more heavily in similar augmented Lagrangian-type approaches appearing in the literature. To the best of our knowledge, aside from the work in \cite{CAA:Porcellietal}, which is specialized to the case of $L^1$-regularized PDE constrained optimization, most proximal Newton-like schemes utilizing Krylov subspace methods do so without employing any (non-trivial) preconditioner (e.g., see \cite{NLAA:ChenQi,SIAMOpt:Lietal2,IEEE_DC:Patrinos_etal,WangTangSciComp}). 
    \item[$\bullet$] We provide extensive computational evidence to support that the proposed approach exhibits a significantly better practical convergence than that predicted by the theory, over a very wide range of applications. Specifically, we showcase the robustness and the efficiency of our approach over a plethora of instances arising from risk-averse portfolio selection problems, $L^1$-regularized partial differential equation constrained optimization, quantile regression as well as linear classification via support vector machines. In each of these cases, we compare our approach to a robust regularized interior point method (see \cite{arXiv:GondPougkPears,COAP:PougkGond}) which is available on GitHub, and showcase its efficiency not only in terms of CPU time and memory requirements, but also in terms of total iterations required to obtain a sufficiently accurate solution. Indeed, we demonstrate that while our approach requires more iterations compared to the alternative polynomially convergent interior point method, the discrepancy in terms of iteration count is not particularly significant. This is reflected in the computational efficiency of our approach, in terms of CPU time. At the same time, we demonstrate that both second-order solvers are significantly more robust and efficient compared to a state-of-the-art alternating direction method of multipliers \cite{osqp} (ADMM), since we are interested in finding sufficiently accurate solutions in our numerical experiments, which prevent first-order schemes from being competitive.
       \item[$\bullet$]The method is extremely versatile and can solve a plethora of very important applications (as we showcase in Section \ref{sec: applications}), by explicitly exploiting the structure of the nonsmooth terms appearing in the objective of \eqref{primal problem}. Additionally, it deals with general box constraints, without requiring the introduction of auxiliary variables to deal with upper and lower bounds separately, something that is required when utilizing conic-based solvers. As a result, the associated linear systems solved within SSN have significantly smaller dimensions, compared to linear systems arising within interior point methods suitable for the solution of problems like \eqref{primal problem} (e.g., see \cite{SIREV:DeSimone_etal,arXiv:GondPougkPears,NLAA:PearsonPorcStoll}), potentially making the proposed approach a more attractive alternative for very large-scale instances.
\end{itemize}
\par Before closing this section, we should mention that the algorithm developed in this paper arose in an attempt to consolidate two of our previously developed methodologies laid out in two technical reports (\cite{arxiv:Pougk_etal1,arxiv:Pougk_etal2}); the former report studies \eqref{primal problem} by assuming that the nonsmooth terms are separable, while the latter studies \eqref{primal problem} in its full generality. However, these previous approaches dealt with certain non-smooth terms of \eqref{primal problem} explicitly. As a result, the associated PMM sub-problems of the developed algorithms were nonsmooth, and that resulted in limited theoretical support of the inner SSN scheme utilized to tackle these sub-problems. This issue was overcome in this consolidated work, by transferring the difficulty to the SSN linear systems, and then utilizing our versatile iterative linear algebra kernel (and associated preconditioning strategy) to ensure that this new and improved version of the active-set schemes developed in \cite{arxiv:Pougk_etal1,arxiv:Pougk_etal2} is equally scalable but also more robust and better theoretically supported.
\par To summarize, in Section \ref{sec: PAL penalties} we derive a proximal method of multipliers and briefly discuss its convergence properties. Then, in Section \ref{sec: SSN method} we present a well-studied globally convergent backtracking-linesearch semismooth Newton scheme used to approximately solve the PMM sub-problems, noticing its local superlinear convergence properties under no additional assumptions. Next, in Section \ref{sec: solution of linear systems}, we propose \emph{novel} general-purpose preconditioners for the associated SSN linear systems and analyze their effectiveness. In Section \ref{sec: applications}, our approach is extensively tested on a wide variety of optimization instances. Finally, we derive some conclusions in Section \ref{sec: Conclusions}.

\paragraph{Notation.} Given a vector $x$ in $\mathbb{R}^n$, $\|x\|$ denotes the Euclidean norm. Letting $R \succ 0_{n,n}$ be a symmetric positive definite matrix, we denote $\|x\|_R^2 = x^\top R x$. Given a closed set $\mathcal{K} \subset \mathbb{R}^n$, we write $\Pi_{\mathcal{K}}(x) \triangleq \arg\min\{\|x-z\|\ \vert\ z \in \mathcal{K}\}$, while for any $R \succ 0_{n,n}$ we write $\textnormal{dist}_R(z,\mathcal{K}) \triangleq \inf_{z'\in \mathcal{K}}\|z-z'\|_R$ (with $\textnormal{dist}_I(z,\mathcal{K}) \equiv \textnormal{dist}(z,\mathcal{K})$). Given a proper and closed convex function $p \colon \mathbb{R}^n \rightarrow \mathbb{R}\cup\{+\infty\}$, we define $\textbf{prox}_p (u) \triangleq \arg\min_x \left\{ p(x) + \frac{1}{2}\|u-x\|^2\right\}$. Given an arbitrary rectangular matrix $A$, $\sigma_{\max}(A)$ denotes its maximum singular value. For an arbitrary square matrix $B$, $\lambda(B)$ is the set of eigenvalues of $B$ while $\lambda_{\max}(B)$ (resp., $\lambda_{\min}(B)$) denotes its maximum (resp., minimum) eigenvalue. Given an index set  $\mathcal{D}$, $|\mathcal{D}|$ denotes its cardinality. Given a rectangular matrix $A \in \mathbb{R}^{m \times n}$ and an index set $\mathcal{B} \subseteq \{1,\ldots,n\}$, we denote the columns of $A$, the indices of which belong to $\mathcal{B}$, as $A_{\mathcal{B}}$. Given a square matrix $Q \in \mathbb{R}^{n\times n}$, we denote the subset of columns and rows of $Q$, the indices of which belong to $\mathcal{B}$, as $\left(Q\right)_{\mathcal{B},\mathcal{B}}$. We denote by $\textnormal{Diag}(Q)$ the diagonal matrix with diagonal elements equal to those of $Q$. Given a matrix $A \in \mathbb{R}^{m\times n}$, and two index sets $\mathcal{B}_1 \subseteq \{1,\ldots,m\}$ and $\mathcal{B}_2 \subseteq \{1,\ldots,n\}$, we denote the subset of rows and columns of $A$, the indices of which belong to $\mathcal{B}_1,\ \mathcal{B}_2$ respectively, as $\left(A\right)_{\mathcal{B}_1,\mathcal{B}_2}$. Finally, given an arbitrary vector $d$ with $n$ components as well as some indices $1\leq i_1 \leq i_2 \leq n$, we denote by $d_{i_1:i_2}$ the vector $(d_{i_1},d_{i_1+1},\ldots,d_{i_2})$. To avoid confusion, indices $i$ are always used to denote entries of vectors or matrices, while $k$ and $j$ are reserved to denote iteration counters (outer (PMM) and inner (SSN), respectively).
\section{A primal-dual proximal method of multipliers} \label{sec: PAL penalties}
\par In what follows, we derive the proximal augmented Lagrangian penalty function corresponding to the primal problem \eqref{primal problem}. Using the latter, we derive a primal-dual PMM for solving the pair \eqref{primal problem}--\eqref{dual problem}. The convergence of this PMM scheme is subsequently analyzed, assuming that we are able to find sufficiently accurate solutions to its associated sub-problems. In the next section, we briefly present a standard semismooth Newton scheme for the solution of these sub-problems, with global and local superlinear convergence guarantees. 
\subsection{Derivation of the PMM} \label{subsec: derivation of the PMM}
\par We begin by deriving the Lagrangian associated to \eqref{primal problem}. First, we define the function \[\varphi(x) \triangleq f(x)  + h(Cx+d) + \delta_{\mathcal{K}}(x) + \delta_{\{0_m\}}\left(b-Ax\right).\]
\noindent Following the dualization strategy proposed in \cite[Chapter 11]{Springer:RockWets}, we let
\[\hat{\varphi}(x,u',w',v') \triangleq f(x) + h(Cx+d+w') + \delta_{\mathcal{K}}(x+v') + \delta_{\{0_m\}}\left(b-Ax + u'\right),\]
\noindent for which it holds that $\varphi(x) =\hat{\varphi}(x,0_m,0_l,0_n)$. Then, by letting $y = [y_1^\top\ y_2^\top]^\top$, the Lagrangian associated to \eqref{primal problem} reads:
\begin{equation*}
\begin{split}
\ell (x,y,z) &\triangleq \ \inf_{u',w',v'} \left\{\hat{\varphi}(x,u',w',v') - y_1^\top  u' -y_2^\top w' - z^\top  v'\right\} \\ &=\ f(x)  - \sup_{u'} \left\{y_1^\top  u' -\delta_{\{0_m\}}\left(b-Ax + u'\right) \right\}  \\&\qquad -\sup_{w'}\left\{y_2^\top w' -h\left(Cx+d+w'\right)\right\} - \sup_{v'} \left\{z^\top v' - \delta_{\mathcal{K}}(x+v') \right\}\\
&=\ f(x)  -y_1^\top(Ax-b) +y_2^\top(Cx+d) -h^*(y_2) +   z^\top  x - \delta^*_{\mathcal{K}}(z),
\end{split}
\end{equation*}
\noindent where we used the definition of the Fenchel conjugate. Before we proceed with the derivation of the augmented Lagrangian associated to $\ell(\cdot)$, let us observe that the Fenchel conjugate of $h(\cdot)$ is $h^*(u) = \delta_{\mathcal{C}}(u)$, where $\mathcal{C} \triangleq \left\{u \in \mathbb{R}^l \big\vert v_i \in [0,1],\ i \in \{1,\ldots,l\}\right\}.$ Given a penalty parameter $\beta > 0$, the augmented Lagrangian corresponding to \eqref{primal problem} reads:
\begin{equation} \label{final augmented lagrangian of the primal}
\begin{split}
\mathcal{L}_{\beta}(x; y, z) &\triangleq\  f(x)  - y_1^\top (Ax-b) + \frac{\beta}{2}\|Ax-b\|^2 \\
&\qquad +(Cx + d)^\top \Pi_{\mathcal{C}}\left(y_2 + \beta(Cx+d)\right) - \frac{1}{2\beta}\left\|y_2-\Pi_{\mathcal{C}}\left(y_2 + \beta(Cx+d)\right)\right\|^2\\
&\qquad -\frac{1}{2\beta}\|z\|^2 + \frac{1}{2\beta}\left\|z+\beta x -\beta \Pi_{\mathcal{K}}\left(\beta^{-1}z+ x\right)\right\|^2.
\end{split}
\end{equation}
\noindent A detailed derivation of the augmented Lagrangian penalty function given in \eqref{final augmented lagrangian of the primal} can be found in Appendix \ref{Appendix: derivation of the augmented Lagrangian}.
\par Assume that at iteration $k\geq 0 $ we have the estimates $(x_k,y_k,z_k)$ as well as the penalty parameters $\beta_k,\ \rho_k$, such that $\rho_k \triangleq \frac{\beta_k}{\tau_k}$, where $\{\tau_k\}_{k = 0}^{\infty}$ is a non-increasing positive sequence, i.e. $\tau_k > 0$ for all $k \geq 0$. We define the continuously differentiable function 
\begin{equation} \label{eqn: proximal Lagrangian penalty}
\phi(x) \equiv\  \phi_{\rho_k,\beta_k}(x;x_k,y_k,z_k) \triangleq  \mathcal{L}_{\beta_k}(x;y_k,z_k) + \frac{1}{2\rho_k}\|x-x_k\|^2.
\end{equation}
\noindent Using the previous notation, we need to find $x^*$ such that
\[\left(\nabla \phi(x^*)\right)^\top (x - x^*) \geq 0,\qquad \forall\ x \in \mathbb{R}^n,\]
\noindent where it can be shown (see Appendix \ref{Appendix: differentiability of augmented Lagrangian}) that
\begin{equation*}
\begin{split}
\nabla \phi(x) &= \nabla f(x) - A^\top y_{1_k} + \beta_kA^\top(Ax-b) + C^\top \Pi_{\mathcal{C}}\left(y_{2_k} + \beta_k\left( Cx+d\right) \right)\\
&\qquad  + (z_k + \beta_k x) - \beta_k \Pi_{\mathcal{K}}(\beta_k^{-1}z_k + x) + \rho_k^{-1}(x-x_k).
\end{split}
\end{equation*}
\noindent We now describe the primal-dual PMM in Algorithm \ref{primal-dual PMM algorithm}.
\renewcommand{\thealgorithm}{PD-PMM}

\begin{algorithm}[!ht]
\caption{Primal-dual proximal method of mutlipliers}
    \label{primal-dual PMM algorithm}
    \textbf{Input:}  $(x_0,y_0,z_0) \in \mathbb{R}^n \times \mathbb{R}^{m+l} \times \mathbb{R}^n$, $\beta_0,\ \beta_{\infty},\ \tau_{\infty} > 0$, $\{\tau_k\}_{k=0}^{\infty}$ such that $\tau_k \searrow \tau_{\infty} > 0$.
\begin{algorithmic}
\State Choose a sequence of positive numbers $\{\epsilon_k\}$ such that $\epsilon_k \rightarrow 0$. 
\For {($k = 0,1,2,\ldots$)}
\State Find $x_{k+1}$ such that:
\begin{equation} \label{primal-dual PMM main sub-problem}
\left\|\nabla \phi(x_{k+1})\right\|  \leq \epsilon_k.
\end{equation}
   \begin{flalign}  \label{primal-dual PMM y-update}
\ \ \ \ \ y_{k+1} &= \  \begin{bmatrix}
    y_{1_k} - \beta_k (A x_{k+1} - b)\\
    \Pi_{\mathcal{C}}\left(y_{2_k} + \beta_k (C x_{k+1}+ d) \right)
\end{bmatrix}.&&
\end{flalign} 
   \begin{flalign}  \label{primal-dual PMM z-update}
\ \ \ \ \ z_{k+1} &= \  (z_k + \beta_k x_{k+1}) - \beta_k\Pi_{\mathcal{K}}\big(\beta_k^{-1}z_k + x_{k+1} \big).&&
\end{flalign} 
\begin{flalign} \ \ \ \ \ \beta_{k+1} &\nearrow \beta_{\infty} \leq \infty, \quad \rho_{k+1} = \frac{\beta_{k+1}}{\tau_{k+1}}.&&
\end{flalign}
\EndFor
\State \Return $(x_k,y_k,z_k)$.
\end{algorithmic}
\end{algorithm}
\par Notice that we allow step \eqref{primal-dual PMM main sub-problem} to be computed inexactly. In Section \ref{subsection: PMM convergence analysis} we will provide precise conditions on the error sequence guaranteeing that Algorithm \ref{primal-dual PMM algorithm} achieves global convergence, and additional conditions for achieving a local linear or superlinear rate (where the local superlinear convergence requires that $\beta_k \rightarrow \infty$). Further conditions on the starting point and on the starting penalty parameter $\beta_0$, required to guarantee a global linear convergence rate, are also discussed.  

\subsection{Convergence analysis} \label{subsection: PMM convergence analysis}
\par In this section we provide conditions on the error sequence $\{\epsilon_k\}$ in \eqref{primal-dual PMM main sub-problem} that guarantee the convergence of Algorithm \ref{primal-dual PMM algorithm}, potentially at a global linear or local superlinear rate. The analysis is derived by applying the results shown in \cite[Section 2]{SIAMOpt:Lietal} or \cite{RockafellarGeneralizedPMM} (or by an extension of the analyses in \cite{MathOpRes:Rock,SIAMJCO:Rock}) after connecting Algorithm \ref{primal-dual PMM algorithm} to an appropriate proximal point iteration. As before, we let $F = [A^\top\ -C^\top]^\top$ and $\hat{b} = [b^\top\ d^\top]^\top$ and define the maximal monotone operator $T_{\ell} \colon \mathbb{R}^{2n+m+l} \rightrightarrows \mathbb{R}^{2n+m+l}$, associated to \eqref{primal problem}--\eqref{dual problem}:
\begin{equation*} \label{maximal monotone operator associated to primal-dual problem}
\begin{split}
T_{\ell}(x,y,z) &\triangleq \Bigg\{(u',v',w')\ \bigg\vert\  u' \in  \nabla f(x) - F^\top y + z,\  v' \in Fx -\hat{b} + \begin{bmatrix} 0_m\\\partial h^*(y_2) \end{bmatrix},\ w'+ x \in \partial\delta^*_{\mathcal{K}}(z)\Bigg\}.
\end{split}
\end{equation*}
\noindent  The inverse of this operator reads
\begin{equation*} \label{inverse of maximal monotone operator associated to primal-dual problem}
\begin{split}
T^{-1}_{\ell}(u',v',w') &\triangleq \arg\max_{y,z}\min_x\left\{\ell(x,y,z) + u'^\top x - v'^\top y -w'^\top z\right\}.
\end{split}
\end{equation*}
\noindent Notice that Assumption \ref{assumption: solution of the QP} implies that $T^{-1}_{\ell}(0) \neq \emptyset$. Following the result in \cite{SIAMOpt:Lietal}, and since $f$ is convex quadratic while $h$ is piecewise linear, we note that $T_{\ell}$ is in fact a polyhedral multifunction (see \cite{RobinsonMathProgStud} for a detailed discussion on the properties of such multifunctions). In light of this property of $T_{\ell}$ we note that the following specialized \emph{metric subregularity} condition (see \cite{Springer:DonRock} for a definition) holds automatically without any additional assumptions.
\begin{lemma}\label{lemma: error condition for polyhedral multifucntion}
For any $r > 0$, there exists $\kappa > 0$ such that
\begin{equation} \label{eqn: error condition for polyhedral multifunction}
\textnormal{dist}\big(p,T_{\ell}^{-1}(0)\big) \leq \kappa\ \textnormal{dist}\big(0,T_{\ell}(p)\big),\quad \forall\ p \in \mathbb{R}^{2n+m},\ \textnormal{with }\textnormal{dist}\big(p,T_{\ell}^{-1}(0)\big) \leq r.
\end{equation}
\end{lemma}
\begin{proof}
\noindent The reader is referred to \cite[Lemma 2.4]{SIAMOpt:Lietal} as well as \cite{RobinsonMathProgStud}.
\end{proof}
\par Next, let some sequence of positive definite matrices $\{R_k\}_{k=0}^{\infty}$ be given with $R_k \triangleq \tau_k I_n \oplus I_{m+l} \oplus I_n$, for all $k \geq 0$, where $\tau_k$ is defined in Algorithm \ref{primal-dual PMM algorithm} and $\oplus$ denotes the direct sum of two matrices. We define the single-valued proximal operator $P_k \colon \mathbb{R}^{2n + m + l} \mapsto \mathbb{R}^{2n+m + l}$, associated with $T_{\ell}$:
\begin{equation} \label{proximal operator}
P_k \triangleq \big(R_k + \beta_k T_{\ell}\big)^{-1} R_k.
\end{equation}
\noindent In particular, under our assumptions on the matrices $R_k$, we have that (e.g. see \cite{SIAMJCO:Rock}) for all $(u_1,v_1,w_1),\ (u_2,v_2,w_2) \in \mathbb{R}^{2n+m+l}$, the following inequality (non-expansiveness) holds
\begin{equation} \label{non-expansiveness of P_k}
\left\|(u_1,v_1,w_1)-P_k(u_2,v_2,w_2)\right\|_{R_k} \leq \left\|(u_1,v_1,w_1)-(u_2,v_2,w_2)\right\|_{R_k}. \end{equation}
\noindent Obviously, we can observe that if $(x^*,y^*,z^*) \in T_{\ell}^{-1}(0)$, then $P_k(x^*,y^*,z^*) = (x^*,y^*,z^*)$. We are now able to connect Algorithm \ref{primal-dual PMM algorithm} with the proximal point iteration produced by \eqref{proximal operator}.
\begin{Proposition} \label{proposition: connection to PMM}
Let $\{(x_k,y_k,z_k)\}_{k=0}^{\infty}$ be a sequence of iterates produced by Algorithm \textnormal{\ref{primal-dual PMM algorithm}}. Then, for every $k \geq 0$ we have that
\begin{equation} \label{connection of PMM with PPA error}
\left\|(x_{k+1},y_{k+1},z_{k+1})-P_k(x_k,y_k,z_k)\right\|_{R_k} \leq \frac{\beta_k}{\min\{\sqrt{\tau_k},1\}}\left\|\nabla \phi(x_{k+1})\right\|.
\end{equation}
\end{Proposition}
\begin{proof}
\noindent From \eqref{eqn: proximal Lagrangian penalty}, we observe that 
$$\nabla \phi(x_{k+1}) = \nabla \mathcal{L}_{\beta_k}(x_{k+1};y_k,z_k) + \frac{1}{2\rho_k}(x_{k+1}-x_k).$$
\noindent Thus, by utilizing \cite[Proposition 7]{MathOpRes:Rock}, we deduce
\begin{equation*}\label{connection of PPM with PPA eqn}
\left(\nabla \phi(x_{k+1}),0_{m+l},0_n\right)  +
\beta_k^{-1}\left( \tau_k(x_k - x_{k+1}),y_k - y_{k+1},z_k - z_{k+1}\right) \in\ T_{\ell}(x_{k+1},y_{k+1},z_{k+1}).
\end{equation*}
\noindent Subtracting $P_k(x_k,y_k,z_k)$ from both sides, taking norms, and using the non-expansiveness of $P_k$ (see \eqref{non-expansiveness of P_k}), yields \eqref{connection of PMM with PPA error} and concludes the proof.
\end{proof}
\par Now that we have established the connection of Algorithm \ref{primal-dual PMM algorithm} with the proximal point iteration governed by the operator $P_k$ defined in \eqref{proximal operator}, we can directly provide conditions on the error sequence in \eqref{primal-dual PMM main sub-problem}, to guarantee global (possibly linear) and local linear (potentially superlinear) convergence of Algorithm \ref{primal-dual PMM algorithm}. To that end, we will make use of certain results, as reported in \cite[Section 2]{SIAMOpt:Lietal}. Firstly, we provide the global convergence result for the algorithm.
\begin{theorem}
Let Assumption \textnormal{\ref{assumption: solution of the QP}} hold. Let $\{(x_k,y_k,z_k)\}_{k=0}^{\infty}$ be generated by Algorithm \textnormal{\ref{primal-dual PMM algorithm}}. Furthermore, assume that we choose a sequence $\{\epsilon_k\}_{k=0}^{\infty}$ in \eqref{primal-dual PMM main sub-problem}, such that
\begin{equation} \label{eqn: error condition for global convergence}
\epsilon_k \leq \frac{\min\{\sqrt{\tau_k},1\}}{\beta_k}\delta_k,\quad 0 \leq \delta_k,\quad \sum_{k=0}^{\infty} \delta_k < \infty.
\end{equation}
\noindent Then, $\{(x_k,y_k,z_k)\}_{k=0}^{\infty}$ is bounded and converges to a primal-dual solution of \eqref{primal problem}--\eqref{dual problem}.
\end{theorem}
\begin{proof}
\noindent The proof is omitted since it is a direct application of \cite[Theorem 2.3]{SIAMOpt:Lietal}. 
\end{proof}
\par Next, we discuss local linear (and potentially superlinear) convergence of Algorithm \ref{primal-dual PMM algorithm}. To that end, let $r > \sum_{k = 0}^{\infty} \delta_k$, where $\delta_k$ is defined in \eqref{eqn: error condition for global convergence}. Then, from Lemma \ref{lemma: error condition for polyhedral multifucntion} we know that there exists $\kappa > 0$ associated with $r$ such that
\begin{equation} \label{eqn: specific kappa and r for error condition}
 \textnormal{dist}\big((x,y,z),T_{\ell}^{-1}(0)\big) \leq \kappa\ \textnormal{dist}\big(0,T_{\ell}(x,y,z)\big),
 \end{equation}
\noindent for all $(x,y,z) \in \mathbb{R}^{2n+m}$ such that $\textnormal{dist}\big((x,y,z),T_{\ell}^{-1}(0)\big) \leq r$. 
\begin{theorem} \label{thm:local convergence} Let Assumption \textnormal{\ref{assumption: solution of the QP}} hold, and assume that $(x_0,y_0,z_0)$ is chosen to satisfy \[\textnormal{dist}_{R_0}\big((x_0,y_0,z_0),T_{\ell}^{-1}(0)\big) \leq r - \sum_{k = 0}^{\infty} \delta_k,\]
\noindent where $\{\delta_k\}_{k=0}^{\infty}$ is given in \eqref{eqn: error condition for global convergence}. Let also $\kappa$ be given as in \eqref{eqn: specific kappa and r for error condition} and assume that we choose a sequence $\{\epsilon_k\}_{k=0}^{\infty}$ in \eqref{primal-dual PMM main sub-problem} such that
\begin{equation} \label{eqn: error condition for superlinear convergence}
\epsilon_k \leq \frac{\min\{\sqrt{\tau_k},1\}}{\beta_k} \min\big\{\delta_k, \delta_k' \|(x_{k+1},y_{k+1},z_{k+1}) - (x_k,y_k,z_k)\|_{R_k}\big\},
\end{equation}
\noindent where $0 \leq \delta_k$, $\sum_{k=0}^{\infty} \delta_k < \infty$, and $0 \leq \delta_k' < 1$, $\sum_{k = 0}^{\infty} \delta_k' < \infty$. Then, for all $k \geq 0$ we have that
\begin{equation*} \label{eqn: superlinear convergence error decay}
\begin{split}
\textnormal{dist}_{R_{k+1}}\left((x_{k+1},y_{k+1},z_{k+1},T_{\ell}^{-1}(0)\right) & \leq \mu_k \textnormal{dist}_{R_k}\left( x_{k},y_{k},z_{k},T_{\ell}^{-1}(0)\right),
\end{split}
\end{equation*}
\[\mu_k \triangleq (1-\delta_k')^{-1}\left(\delta_k' + (1+\delta_k')\frac{\kappa \gamma_k}{\sqrt{\beta_k^2 + \kappa^2\gamma_k^2}}\right), \qquad \lim_{k\rightarrow \infty} \mu_k = \mu_{\infty} \triangleq \frac{\kappa \gamma_{\infty}}{\sqrt{\beta_{\infty}^2 + \kappa^2\gamma_{\infty}^2}},\]
\noindent where $\gamma_k \triangleq \max\{\tau_k,1\}$ and $\gamma_{\infty} = \max\{\tau_{\infty},1\}$ (noting that $\mu_{\infty} = 0,\ \textnormal{if }\beta_{\infty} = \infty$).
\end{theorem}
\begin{proof}
\noindent The proof is omitted since it follows by direct application of \cite[Theorem 2.5]{SIAMOpt:Lietal} (see also \cite[Theorem 2]{SIAMJCO:Rock}).
\end{proof}
\begin{remark}
Following \textnormal{\cite[Remarks 2, 3]{SIAMOpt:Lietal}}, we can choose a non-increasing sequence $\{\delta_k'\}_{k=0}^{\infty}$ and a large enough $\beta_0$ such that $\mu_0 < 1$, which in turn implies that $\mu_k \leq \mu_0 < 1$, yielding a global linear convergence of both $\textnormal{dist}\big((x_{k},y_k,z_k),T_{\ell}^{-1}(0)\big)$ as well as $\textnormal{dist}_{R_k}\big((x_{k},y_k,z_k),T_{\ell}^{-1}(0)\big)$, assuming that the starting point of the algorithm satisfies the assumption stated in Theorem \textnormal{\ref{thm:local convergence}}. On the other hand, as is implicitly mentioned in Theorem \textnormal{\ref{thm:local convergence}}, if $\beta_k$ is forced to increase indefinitely, we obtain a local superlinear convergence rate (notice that $\mu_{\infty} = 0$ if $\beta_{\infty} = \infty$).
\end{remark}

\section{Semismooth Newton method} \label{sec: SSN method}
\par In this section we briefly present a standard semismooth Newton (SSN) scheme suitable for the solution of problem \eqref{primal-dual PMM main sub-problem}, appearing in Algorithm \ref{primal-dual PMM algorithm}. 
To that end, we fix the estimates $(x_k,y_k,z_k)$ as well as the penalty parameters $\beta_k,\ \rho_k$. We set $x_{k_0} = x_k$, and at every iteration $j$ of SSN, we approximately solve a system of the following form:
\begin{equation} \label{Primal-dual SSN system}
J_{k_j}
d_x= -\nabla \phi(x_{k_j}),
\end{equation}
\noindent where $J_{k_j} \in \partial^C_x\left(\nabla \phi(x_{k_j})\right)$. The symbol $\partial_x^C(\cdot)$ denotes the \emph{Clarke subdifferential} of a function (see \cite{JWS:Clarke}) with respect to $x$, which can be obtained as the convex hull of the \emph{Bouligand subdifferential} (\cite{JWS:Clarke}). Any element of the Clarke subdifferential is a \emph{Newton derivative} (see \cite[Chapter 13]{arXiv:ClasValk}), since $\nabla \phi(x_{k_j})$ is a \emph{piecewise continuously differentiable} and \emph{regular function}. Using \cite[Theorem 14.8]{arXiv:ClasValk}, we obtain that for any interval $[l,u]$ on the real line (i.e., $l < u$):
\begin{equation*}
\partial_{w}^C \left(\Pi_{[l,u]}(w_i)\right)= \begin{cases} 
\{1\}, &\qquad \textnormal{if}\quad w \in (l,u),\\
\{0\}, &\qquad \textnormal{if}\quad w \notin [l,u],\\
[0,1], &\qquad \textnormal{if}\quad w \in \{l,u\}.
\end{cases}
\end{equation*}
\par For computational reasons, we always choose matrices $M_{k_j}$ from the Bouligand subdifferential. This choice will become apparent in the Section \ref{sec: solution of linear systems}. On the other hand, it is well-known (see \cite[Theorem 4]{CAM:MartQi}) that an inexact semismooth Newton scheme using the Bouligand subdifferential converges at a local linear rate (assuming that the linear systems are solved up to an appropriate accuracy), if the equation $\nabla \phi(x) = 0_n$ is \emph{BD-regular} at the optimum $(x_k^*)$ (that is, each element of the Bouligand subdifferential of $\nabla\phi(x_k^*)$ is nonsingular). Note, however, that since we employ the semismooth Newton scheme to solve the sub-problems arising from Algorithm \ref{primal-dual PMM algorithm}, we obtain that the resulting nonsmooth equations are indeed BD-regular for every outer iteration $k \geq 0$. Thus, assuming that the associated linear systems are solved up to a sufficient accuracy (see \cite[Theorem 4]{CAM:MartQi}), we obtain local linear convergence rate of the resulting inexact semismooth Newton scheme. If, additionally, the solution accuracy of the associated linear systems is increased at a suitable rate, the resulting local rate can be superlinear. 
\par We complete the derivation of the SSN by introducing backtracking line-search to ensure global convergence. Then, under no additional assumptions, one can show that SSN is globally convergent.  Algorithm \ref{primal-dual SNM algorithm} outlines a semismooth Newton method for the solution of \eqref{primal-dual PMM main sub-problem}. We assume that the associated linear systems are approximately solved by means of a Krylov subspace method. An analysis of the effect of errors arising from the use of Krylov methods within SSN applied to nonsmooth equations can be found in \cite{NLAA:ChenQi}. 
\renewcommand{\thealgorithm}{SSN}
\begin{algorithm}[!ht]
\caption{Semismooth Newton method}
    \label{primal-dual SNM algorithm}
    \textbf{Input:} $\epsilon_k > 0$, $\mu \in \left(0,\frac{1}{2}\right)$, $\delta \in (0,1)$, $\gamma \in (0,1]$, $\bar{\eta} \in (0,1)$, $x_{k_0} = x_k$,  $y_{k_0} = y_k$.
\begin{algorithmic}
\For {($j = 0,1,2,\ldots$)}
\State Choose $J_{k_j} \in \partial^C_x\left(\nabla \phi(x_{k_j})\right)$, and solve
\[J_{k_j}
d_x= -\nabla \phi(x_{k_j}),\]
\State such that $\left\| J_{k_j} d_x + \nabla \phi(x_{k_j})\right\| \leq   \min\left\{\bar{\eta},\left\|\nabla\phi(x_{k_j})\right\|^{1+\gamma}\right\}.$ 
\State (Line-search) Set $\alpha_j = \delta^{m_j}$, where $m_j$ is the first non-negative integer for which:
\[\phi\left(x_{k_j} + \delta^{m_j}d_x\right) \leq  \phi(x_{k_j}) + \mu \delta^{m_j}\left(\nabla \phi(x_{k_j}) \right)^\top d_x\]
%\[\hat{\phi}\left(x_{k_j} + \delta^{m_j}d_x, y_{k_j} + \delta^{m_j}d_y\right)  \leq \hat{\phi}\left(x_{k_j},y_{k_j}\right)  + \mu \delta^{m_j}\left(\widehat{F}_{\beta_k,\rho_k,\zeta_k}\left(x_{k_j},y_{k_j}\right)\right)^\top d. \]
\State $x_{k_{j+1}} = x_{k_j} + \alpha_j d_x$.
\If {$\left(\left\|\nabla \phi(x_{k_{j+1}})\right\| \leq \epsilon_k\right)$}
\State \Return $x_{k_{j+1}}$.
\EndIf
\EndFor
\end{algorithmic}
\end{algorithm}
\par Below we provide a theorem characterizing the convergence of Algorithm \ref{primal-dual SNM algorithm}.
\begin{theorem} \label{thm: SSN convergence}
    Let $\{x_{k_j}\}_{j = 0}^{\infty}$ be the sequence of iterates generated by Algorithm \textnormal{\ref{primal-dual SNM algorithm}}. Then, this sequence converges to the unique optimal solution $x_k^*$ of $\min_{x} \phi(x)$, and $\|x_{k_{j+1}} - x_k^*\| = \mathcal{O}\left(\|x_{k_{j}} - x_k^*\|^{1+\gamma}\right)$. 
\end{theorem}
\begin{proof}
    The proof is omitted since it follows by a trivial extension of the results given in \cite[Proposition 3.3, Theorems 3.4-3.5]{SIAMOpt:ZhaoSunToh}.
\end{proof}
