\section{Appendix}
\subsection{Derivation of the dual problem} \label{Appendix: derivation of dual}
\par Assume that notation introduced in Section \ref{subsec: derivation of the PMM}. Let $y = [y_1^\top\ y_2^\top]^\top \in \mathbb{R}^{m+l}$. The dual of \eqref{primal problem} is $ \sup_{y,z}\inf_x \left\{ \ell(x,y,z)\right\}.$  We have
\begin{equation*}
\begin{split}
\inf_{x}\left\{\ell(x,y,z)\right\} =&\ -\sup_x \left\{\left(F^\top y-z\right)^\top x -f(x) \right\} + y^\top \hat{b} - \delta_{\mathcal{K}}^*(z)  -h^*(y_2)\\
=&\ -f^*(F^\top y - z) + y^\top \hat{b} - \delta_{\mathcal{K}}^*(z)-h^*(y_2)\\
=&\ -\frac{1}{2}x^\top Q x - \delta_{\{0\}}\left(c + Qx - F^\top y + z\right) + y^\top \hat{b} - \delta_{\mathcal{K}}^*(z) -h^*(y_2),
\end{split}
\end{equation*}
\noindent where we used the definition of the convex conjugate and the definition of $f(\cdot)$, which yields $f^*(F^\top y - z) = \frac{1}{2}x^\top Q x + \delta_{\{0\}}\left(c + Qx - F^\top y + z\right).$ In turn, we observe that this is exactly the dual problem \eqref{dual problem}.

\subsection{Derivation of the augmented Lagrangian} \label{Appendix: derivation of the augmented Lagrangian}
Let $\beta > 0$ be some penalty parameter. The augmented Lagrangian corresponding to \eqref{primal problem} reads:
\begin{equation*} 
\begin{split}
\mathcal{L}_{\beta}(x; y, z) &\triangleq\ \sup_{u',v'} \bigg\{\ell(x,u',v') - \frac{1}{2\beta}\|u'-y\|^2 - \frac{1}{2\beta}\|v'-z\|^2 \bigg\} \\
&=\ f(x) - \inf_{u'} \left\{u'^\top  \left(Fx -\hat{b}\right) + h^*(u_{m+1:m+l}) + \frac{1}{2\beta}\|u'-y\|^2 \right\} \\&\quad \ - \inf_{v'} \left\{-v'^\top x + \delta^*_{\mathcal{K}}(v') + \frac{1}{2\beta}\|v'-z\|^2 \right\} \\
&=\ f(x) -y_1^\top (Ax-b) + \frac{\beta}{2}\|Ax-b\|^2 \\&\quad \ - \inf_{w'}\left\{-w'^\top(Cx+d) + \delta_{\mathcal{C}}(w') + \frac{1}{2\beta}\|w'-y_2\|^2\right\} \\&\quad \ - \inf_{v'} \left\{-v'^\top x + \delta^*_{\mathcal{K}}(v') + \frac{1}{2\beta}\|v'-z\|^2 \right\}.
\end{split}
\end{equation*}
\noindent where $\mathcal{C} \triangleq \left\{w \in \mathbb{R}^l \big\vert w_i \in [0,1],\ j = 1,\ldots,l \right\}.$ Let us now solve each of the two minimization problems appearing in the last expression. For the first expression, we use the fact that if $p_1(x) = p_2(x) + r^\top x,$ where $p_1,\ p_2$ are two proper closed convex functions, then $\textbf{prox}_{p_1}(x) = \textbf{prox}_{p_2}(x-r).$ Thus, we obtain 
\[ \arg\min_{w'}\left\{-w'^\top(Cx+d) + \delta_{\mathcal{C}}(w') + \frac{1}{2\beta}\|w'-y_2\|^2\right\} = \Pi_{\mathcal{C}}\left(y_2 + \beta(Cx+d)\right).\]
\noindent For the second minimization problem, we proceed as before to obtain that 
\[ \arg\min_{w'}\left\{-v'^\top x + \delta^*_{\mathcal{K}}(v') + \frac{1}{2\beta}\|v'-z\|^2 \right\} = \textbf{prox}_{\beta \delta_{\mathcal{K}}^*}\left(z+\beta x\right).\]
\noindent Then, by using the \emph{Moreau Identity} (see \cite{BSMF:Moreau}):
\begin{equation} \label{Moreau Identity}
\textbf{prox}_{\beta p}(u') + \beta \textbf{prox}_{\beta^{-1}p^*}(\beta^{-1}u') = u',
\end{equation}
\noindent and by performing some manipulations, we arrive at the final expression for the augmented Lagrangian given in \eqref{final augmented lagrangian of the primal}.
\subsection{Differentiability of the augmented Lagrangian} \label{Appendix: differentiability of augmented Lagrangian}
\par In order to find the gradient of the augmented Lagrangian, we need to use the gradient expression of the Moreau envelope of a given proper closed convex function $p$. Specifically, given some $\beta > 0$, the Moreau envelope of $p$ reads
\[ e_{\beta p}(x) = \inf_{w} \left\{p(w) + \frac{1}{2\beta}\|w-x\|^2\right\},\]
\noindent and it can be shown that $\nabla e_{\beta p}(x) = \frac{1}{\beta}\left(x - \textbf{prox}_{\beta p}(x)\right).$ We proceed by computing the gradient of 
\[ \inf_{w'}\left\{-w'^\top(Cx+d) + \delta_{\mathcal{C}}(w') + \frac{1}{2\beta}\|w'-y_2\|^2\right\},\]
\noindent noting that the gradient of the second Moreau envelope (implicitly) appearing in the augmented Lagrangian can be computed similarly (using, additionally, the Moreau identity). We notice that
\begin{equation*}
\begin{split}
 &\inf_{w'}\left\{-w'^\top(Cx+d) + \delta_{\mathcal{C}}(w') + \frac{1}{2\beta}\|w'-y_2\|^2\right\} \\ &\quad =  \inf_{w'}\left\{\delta_{\mathcal{C}}(w') + \frac{1}{2\beta}\left\|w'-\left(y_2 + \beta(Cx+d)\right)\right\|^2\right\} -\frac{\beta}{2}\|Cx+d\|^2 - y_2^\top(Cx+d).
 \end{split}
 \end{equation*}
 \noindent Thus, using the expression of the gradient of the second (shifted) Moreau envelope alongside the chain rule, we obtain that
\begin{equation*}
\begin{split}&\nabla_x\left(\inf_{w'}\left\{\delta_{\mathcal{C}}(w') + \frac{1}{2\beta}\left\|w'-\left(y_2 + \beta(Cx+d)\right)\right\|^2\right\} -\frac{\beta}{2}\|Cx+d\|^2 - y_2^\top(Cx+d)\right)\\ &\quad = -C^\top \Pi_{\mathcal{C}}\left(y_2 + \beta(Cx+d)\right). 
\end{split}
 \end{equation*}
 \noindent Proceeding in a similar manner for the second Moreau envelope, we arrive at the expression for the gradient of the proximal augmented Lagrangian penalty function given in Section \ref{subsec: derivation of the PMM}.


\subsection{Termination criteria} \label{Appendix: termination criteria}
\par Let $\mathcal{C} = \left\{x \in \mathbb{R}^l \vert\ x_i \in [0,1],\ i \in \{1,\ldots,l\}\right\}$. We write the optimality conditions for \eqref{primal problem}--\eqref{dual problem} as
\begin{equation} \label{optimality conditions for P-D}
c + Qx - A^\top y_1 + C^\top y_2 + z = 0_{n},\qquad Ax = b,\qquad y_2 = \Pi_{\mathcal{C}}\left(y_2 
+ Cx + d\right),\qquad x = \Pi_{\mathcal{K}}(x + z),
\end{equation}
\noindent and the termination criteria for Algorithm \ref{primal-dual PMM algorithm} (given a tolerance $\epsilon > 0$) are set as
\begin{equation} \label{termination criteria for PD-PMM}
\max\left\{\frac{\|c + Qx - A^\top y_1 + C^\top y_2 + z\|}{1+\|c\|}, \frac{\left\|\begin{matrix} Ax - b \\ y_2 - \Pi_{\mathcal{C}}(y_2 + Cx+d) \end{matrix}\right\|}{1+\left\|\begin{matrix} b\\d\end{matrix}\right\|}, \left\|x - \Pi_{\mathcal{K}}(x + z)\right\| \right\} \leq \epsilon.
\end{equation}
