%		\end{itemize}
%	\end{lemma}
	\begin{proof}
		The first claim follows from Eq.~\eqref{eq: Drkm leq computing}.
		 %the definitions of $D^\dag_r( k, m)$ and $D_r( k, m)$ given in Eqs.~\eqref{eq: Drkm eq} and~\eqref{eq: Drkm leq}, respectively, and the fact that $\{f\in B(m) \colon  \deg(f)  = k \}\subset \{ f \in B(m) \colon  \deg(f)  \le k \}$. 
		 To prove the second claim, we observe that the restriction of $f'\in B(m')$ with $\deg(f')\le k$ to a vector space of dimension $m$ can be identified with a function $f\in B(m)$ with $\deg(f)\le k$ whose $r$-degree is less or equal to $D_r(k, m)$.
	\end{proof}
	% (i.e., elements of the spaces $\tildeboole(s,t,m)$)
	\begin{remark}
		In general, determining $D_r(k, m)$ is a challenging problem, as we will now explain. The affine general linear group acts on the set of affine spaces of a given dimension, preserving the degree of functions. Consequently, the relative degrees are affine invariants of $\boole(m)$. This allows us to utilize the classification of Boolean functions to determine some of these parameters. Each linear subspace of dimension $r$ ($r$-space) of $\mathbb{F}_2^m$ has $2^{m-r}$ cosets, and the number of $r$-spaces is given by the Gaussian binomial coefficient $\binogauss(m, r)$. Considering the computational cost $r2^{r}$ of determining the degree of a Boolean function in $r$ variables~\cite[pp. 33-34]{Carlet2021}, the work factor required to compute the $r$-degree of Boolean functions in $\boole(s, t, m)$ through brute force is as follows:
	\begin{equation}\label{eq: working factor}
			W( r, s, t ,m) =  |\tildeboole(s,t,m)| \times  2^{m-r} \binogauss(m,r)\times r2^{r},\quad   
		\binogauss(m,r)=\prod_{i=0}^{r-1} \frac{2^m - 2^{i}}{2^r - 2^i}.
	\end{equation}
	\end{remark}
