	It is clear that the linear map $\res\colon \boole(2, 2, m )\to \B_V(2,2)$ is surjective, since any element of $\B_V(2,2)\subset \boole(2, 2, m )$ is a fixed point of $\res$. By the rank-nullity theorem, its kernel, denoted by $\Ker$, has dimension $\binom{m}{2}-\binom{\dim V}{2}$. The kernel of $\res$ plays a crucial role in speeding up the search for abnormal functions. Let $f\in\tildeboole(3,t,m)$ such that $\deg( f_{a,V}) \leq 2 $, for some flat $a+V$ of $\F_2^m$. If the quadratic part of $f_{a,V}$ is cancelled by some quadric $q_0\in \boole(2,2,m)$, then, it is also cancelled by every element of $q_0 + \Ker$.  Based on this idea, we propose Algorithm~\ref{SIEVING} that determines all quadratic forms $q$ for a given function $f$ such that $f+q$ is abnormal. It applies a sieving procedure to eliminate all the quadrics in the set $Q(f)$ such that the relative degree of $h+q$ on some affine $\lceil m/2 \rceil$-space is less or equal to one.

	\def\abnormal(#1){$\textsc{sieving}(#1)$}

	\begin{algorithm}[H]
		\caption{$\text{SIEVING}(f)$}
		\begin{algorithmic}[1]
			\Require A member $f$ of $\tildeboole(3,t,m)$.
			\Ensure The set  $Q(f)=\{ q\in \boole(2, 2, m )\colon f+q \mbox{ is abnormal} \}$.
			\State Define $Q(f):=\boole(2, 2, m )$. 
			\For{all $\lceil m/2 \rceil$-vector spaces $V$ }
			%\State $W$ := supplementary of $V$ 
			\For{all  $a$  in $\F_2^m / V$ } 
			\State $\rho \gets f_{a,V} \mod \B_V(0, 1)$
			\If{$\deg( \rho) \leq 2 $}
			\State choose $q_0\in\boole(2, 2, m )$ s.t. $\res( q_0 ) = \rho $
			\State remove all $q\in q_0 + \Ker$ from $Q(f)$ 
			\EndIf
			\EndFor
			\EndFor
			\State \Return $Q(f)$
		\end{algorithmic}
		\label{SIEVING}
	\end{algorithm}

