	Recall that all 6-bit functions are normal and only a few examples of abnormal bent functions have been found in dimensions greater than or equal to 10~\cite{BENT, LeanderMcGuire2009}. However, the existence of an abnormal 8-bit bent function has been an open question for 30 years. As mentioned in~\cite{KIT}, one could use a classification of 8-bit bent functions to determine whether any are abnormal. In this section, we propose a more efficient method that does not require such a classification. Specifically, we combine the sieving procedure from the previous section with techniques from~\cite{MENG}, which construct bent functions from their restrictions, to establish that all bent functions in $\boole(8)$ are either normal or weakly normal.

	\subsection{Decomposition of a bent function into two near-bent functions}
	In this section, we provide the necessary definitions for the procedure (described in the following section) used to prove that all 8-bit bent functions are normal or weakly normal. We begin with the notion of Walsh coefficients, several useful equalities, and a spectral characterization of Boolean bent functions based on them.

	\begin{definition}
		The \emph{Walsh coefficient} of $f\in \boole(m)$ at $a \in \fdm$ is defined by
		$$\walsh f (a)=\sum_{x \in \fdm} (-1)^{f(x)+a\cdot x}.$$
		The set of Walsh coefficients of $f\in \boole(m)$ is called the \emph{Walsh spectrum} of $f$. The Walsh coefficients satisfy~\emph{Parseval's identity}:
		\begin{equation}
			\label{PARSEVAL}
			\sum_{a\in \fdm} \walsh f(a)^2 = 2^{2m} 
		\end{equation}
		and \emph{Poisson's formula}:
		\begin{equation}
			\label{POSSON}
			\sum_{v\in V}(-1)^{f(v+b)+c\cdot v}=\frac{1}{|V^\perp|}\sum_{a\in V^\perp} \walsh f(a+c) (-1)^{b\cdot c},
		\end{equation}
		where $b,c \in \fdm$, $V$ is a linear subspace of $\fdm$ and $V^\perp$ is the \emph{orthogonal complement} of $V$ defined by $$V^\perp=\{ a\in\F_2^m\colon a\cdot v=0 \mbox{ for all } v\in V \}.$$
	\end{definition}

	The following well-known result provides a spectral characterization of bent functions through their Walsh coefficients.

	\begin{theorem}\cite{ROTHAUS1976,Dillon1974}
		Let $f\in\boole(m)$ be a Boolean function. The following statements are equivalent:
		\begin{enumerate}
			\item The function $f$ is bent on $\F_2^m$.
			\item The Walsh coefficients of $f$ satisfy $$\walsh f (a)\in \{\pm 2^{m/2}\}, \mbox{ for all } a\in\F_2^m.$$
		\end{enumerate}
	\end{theorem}

From this statement, it follows immediately that bent functions on $\F_2^m$ exist if and only if $m$ is even. Using the Walsh coefficients of a given bent function, one can always construct another Boolean function, known as its dual. 

\begin{definition}
	Let $f\in\boole(m)$ be bent. Then, the function $\tilde{f}\in\boole(m)$ defined by $(-1)^{\tilde f(a)}= 2^{-m/2}\walsh f(a)$ for all $a\in\F_2^m$ is called the \emph{dual} of $f$. 
\end{definition}

It is well-known that the dual of a bent function is bent~\cite{ROTHAUS1976}. Moreover, by Poisson's formula if $f$ is bent and abnormal  then its dual bent function $\tilde f$ is abnormal too~\cite{CHARPIN}. Now, we present an algebraic decomposition of a given bent function into two near-bent functions with special spectral properties. But first, we give a definition of a near-bent function. 

\begin{definition}
	For even $m$, a Boolean function $g\in\boole(m-1)$ is called \emph{near-bent} if the Walsh spectrum of $g$ is equal to $\{0,\pm 2^{m/2}\}$.
\end{definition}
	The following facts will be used later while constructing a bent function from suitably chosen near-bent functions.
\begin{remark}
	1. Note that for a Boolean function $f\in\boole(m)$, the set $\{ |\walsh  f (a) | \colon a\in\F_2^m \}|$ is invariant under EA-equivalence. Indeed, applying an affine permutation to the input results in a permutation of the Walsh coefficients, while adding an affine function can only alter their signs. As a result, bentness and near-bentness are preserved under EA-equivalence.

	\noindent 2. By Parseval's identity, every near-bent function $g\in\boole(m-1)$ has exactly $2^{m-2}$ Walsh coefficients that are equal to zero. Moreover, the algebraic degree of a near-bent function $g$ in $m-1$ variables is at most $m/2$. For a detailed discussion, we refer to~\cite[Section 6.2.2]{Carlet2021}. 

	\noindent 3. We observe that bent and near-bent functions have only a few special value distributions. Observe that for any Boolean function  $f\in\boole(k)$ it holds that $\walsh f(0)=2^k-2\operatorname{wt}(f)$, thus $\operatorname{wt}(f)=2^{k-1}-\frac{1}{2}\walsh f(0)$. If $k$ is even and $f$ is bent, then 
	\begin{equation}\label{eq: bent weight}
		\operatorname{wt}(f)=2^{k-1}\pm 2^{k/2-1},
	\end{equation}
	since $\walsh f(a)\in\{\pm 2^{k/2}\}$ holds for all $a\in\F_2^m$. If $k$ is odd and $f$ is near-bent, then $\operatorname{wt}(f)=2^{k-1}$ or 
	\begin{equation}\label{eq: near-bent weight}
		\operatorname{wt}(f)=2^{k-1}\pm 2^{(k+1)/2-1},
	\end{equation}
	since $\walsh f(a)\in\{0,\pm 2^{(k+1)/2}\}$ holds for all $a\in\F_2^m$ in this case. 
\end{remark}

	Any Boolean function $f \in \boole(m)$ can be written as a \emph{concatenation} of two Boolean functions $g,h\in\boole(m-1)$, which we denote by $f=(g||h)$ and formally define as follows: 
	\begin{equation}\label{eq: concat}
		\begin{split}
			f(x_1,\ldots,x_{m-1},x_m) :=& (g||h)(x_1,\ldots,x_{m-1},x_m)\\
			= &(x_m+1)g(x_1,\ldots,x_{m-1}) + x_m h(x_1,\ldots,x_{m-1}).
		\end{split}
	\end{equation}





	%For even $m$, a Boolean function in $\boole(m)$ having Walsh spectrum $\{\pm 2^{m/2}\}$ is called bent function.  \textbf{it should be iff theorem!}

	It is clear that the Walsh coefficient of $f=(g||h)\in\boole(m)$ at $(a,\alpha)\in\F_2^m =\F_2^{m-1}\times\F_2$ is given by

	\begin{equation}
		\label{WALSH}
		\walsh f(a,\alpha ) = \walsh g(a) + (-1)^\alpha\,\walsh h(a). 
	\end{equation}
	The following result gives a necessary and sufficient condition for the concatenation $f=(g||f)\in\boole(m)$ of two Boolean functions $(g||f)\in\boole(m-1)$ to be bent. 
	\begin{theorem}\cite{ZhengZhang2000}
		A Boolean function $f=(g||h)\in\boole(m)$ is  bent  if and only if the functions $g,h\in\boole(m-1)$ are near-bent and satisfy 
		\begin{equation}\label{eq: complementary near-bent}
			\forall a\in \F_2^{m-1},\quad \walsh g(a)=0 \Longleftrightarrow  \walsh h(a)\ne 0. 
		\end{equation}
	\end{theorem}  
	Note that near-bent functions $g$ and $h$ satisfying the condition given in Eq~\eqref{eq: complementary near-bent} are called \emph{complementary}. 
	More precisely, if  $f=(g||h)\in\boole(m)$ is bent, then from the definition of the dual and the form of the Walsh coefficient of $f=(g||h)$ given in Eq.~\eqref{WALSH}, one can deduce that:
	\begin{align}
		\hfill \text{if } \walsh g(a) = 2^m, & \quad \mbox{ then } \walsh h(a) = 0 \text{ and } \tilde{f}(a, \alpha) = 0; \label{eq: (i)} \\ 
		\hfill \text{if } \walsh g(a) = -2^m, & \quad \mbox{ then } \walsh h(a) = 0 \text{ and } \tilde{f}(a, \alpha) = 1;  \label{eq: (ii)} \\
		\hfill \text{if } \walsh g(a) = 0, & \quad \mbox{ then } \walsh h(a) = \pm 2^m \text{ and } \tilde{f}(a, 0) + \tilde{f}(a, 1) = 1. \label{eq: (iii)}
	\end{align}

