	\begin{remark}
	In the remaining part of the paper, we consider \( r \in \{1,2,3\} \), 
	as it suffices to reduce the analysis of normality of bent functions in $m=8$ variables to Boolean functions in 7, 6, and 5 variables, respectively. We note that for $m\ge8$ one can consider higher values of $r$ without loss of generality.
	\end{remark}

	Given a bit-word $\lambda$ of length $r$, we denote $\lambda'$ the left prefix of $\lambda$ i.e.  $\lambda'b =\lambda$ for some bit $b$. With this notation, we introduce the following definition.


		\begin{definition}
		Let $m$ even, and let $g\in\boole(m - 1 )$ be a near-bent function. For a bit string $\lambda$ of length $r \in \{1,2,3\}$, we define the set of \emph{candidate functions} $C_\lambda(g)$, where each member $\phi \in \boole( m-r )$ 
		satisfies the following conditions:
		\begin{enumerate}
			\item $\forall t\in\fdmr,\quad \walsh g( t, \lambda') =+2^{m/2} \Rightarrow  \phi(t) = 0$; 
			\item $\forall t\in\fdmr,\quad \walsh g( t, \lambda') =-2^{m/2} \Rightarrow \phi(t) = 1$; 
			\item  The Walsh spectrum of $\phi$ is included  in the set $W_{ r  }$, which is defined in Eq.~\eqref{eq: Wr}.
		\end{enumerate}
		Members of the set $C_\lambda(g)$ are referred to as \emph{$\lambda$-candidates for $g$}.
		\end{definition}

	\begin{remark}
	Note that any $\lambda$-restriction of a bent expansion of $g$ is in  $C_\lambda(g)$
	but the converse is generally false. 
	\end{remark}

	All bent-expansions of $g\in\boole(m-1)$ can be derived from $C_0(g)$, a set obtained in \cite{MENG} through a bottom-up construction. This process involves merging $C_{0j}(g)$ by concatenating elements $\phi_L \in C_{0j0}(g)$ and $\phi_R \in  C_{0j1}(g)$, forming the functions $(\phi_L || \phi_R)$, while retaining only those that qualify as $0j$-candidates.  However, this method is inefficient, as for certain functions, the size of the corresponding $C_{ij}(g)$-sets can become excessively large. 

	In the following, we introduce our improvements that optimize this procedure by reducing the search space and improving computational efficiency.

	\begin{lemma}
		Let $\zeta\in\boole(m-1)$ be the indicator of Walsh zeroes of $g\in\boole(m-1)$. Let $\lambda$ be a bit string of length $r \in \{1,2,3\}$. If $\phi\in\boole( m - r )$ is a $\lambda$-restriction of a bent expansion of $g$, then the Boolean
		function defined by
		\begin{equation}
			v\mapsto \phi'( v ) = \phi(v) + \zeta(\lambda, v)
		\end{equation}
		is also $\lambda$-candidate for $g$.
	\end{lemma}
	\begin{proof}
		It is a consequence of Eq.~\eqref{eq: (iii)}.
	\end{proof}
	For an $r$-bit word $\lambda$, we denote by $A_\lambda(g)$ the set of Boolean functions $\phi \in \boole(m - r)$ such that both $\phi$ and $\phi'$ are $\lambda$-candidates. Its elements are called \emph{$\lambda$-admissible functions} for $g$. The cardinality of the set $A_\lambda(g)$ set may be very large, and we only have a trivial estimate:
	\begin{equation}
		\# A_\lambda( g ) \leq 2^{m_\lambda},
	\end{equation} 
	where $m_\lambda$ denotes the number of Walsh coefficients
	equal to 0 in the affine space $ \fdmr\times \{\lambda\}$.

	The following lemma will be used to minimize the size of the dictionary $\mathcal{D}$ in Algorithm \ref{EXPAND}, which serves as a lookup table that organizes and stores admissible functions $L$ based on their corresponding keys $\kappa$ (that we define in a moment). Its primary role is to facilitate efficient retrieval of functions $L$ that share the same key during the later stages of this algorithm.
	\begin{lemma}%[twist]
		Let $m$ be even, and let $g \in \boole(m-1)$ be near-bent. Without loss of generality, we may assume that
		$$
		\# A_{00}( g ) \leq 2^{m-3}. 
		$$
	\end{lemma}
	\begin{proof}
		Since $m_{00} + m_{01} = 2^{m-2}$, we know that one of these numbers is at most $2^{m-3}$. If it is $m_{00}$, there is nothing to do. Otherwise, we can translate $g$ by $x_{m-1}$, and the result follows.
	\end{proof}

	\begin{remark}
	Note that for the case we are interested in, i.e., $m = 8$, we have $\#A_{00}(g) \leq 2^{32}$.  
	\end{remark}

    For an $(m-2)$-bit function $\phi$, where $m$ is even, we define the \emph{key} $\kappa(\phi)$ of $\phi$ as the position $a \in \mathbb{F}_2^{m-2}$ such that $\walsh \phi(a) \equiv 2^{m/2 - 1} \mod 2^{m/2}$. The following lemma enables us to propose an efficient implementation of the ideas in \cite{MENG}.
	\begin{lemma}%[key]
		Let $m$ be even. If $\phi\in\boole(m-1)$ is 0-admissible for the near-bent function $g\in\boole(m-1)$, then $\phi$ is the concatenation $(\phi_L|| \phi_R)$, where $\phi_L$ is $00$-admissible, $\phi_R$ is $01$-admissible, and
		$$
		\kappa( \phi_L ) =  \kappa( \phi_R ).
		$$
	\end{lemma}
	\begin{proof}
		We know that $\phi_L$ and $\phi_R$ take values in $W_{m-2} = \{0,\pm 2^{m/2 - 1}, \pm 2^{m/2} \}$,
		and 
		$$\walsh \phi ( a ) = \walsh \phi_L  (a)  \pm \walsh  \phi_R (a) \in W_{m-1} = \{0,\pm 2^{m/2} \}.$$
		This completes the proof.
	\end{proof}

    \subsection{Main result}
	Using the ideas above, we propose the following algorithm, which can be used not only to check whether a given near-bent function is bent-expandable but also to find its bent expansions directly. In the following, we analyze the bent expansions of abnormal near-bent functions $g \in \boole(m-1)$ for $m = 8$, which were constructed in the previous section.
	\begin{algorithm}[H]
		\caption{$\text{EXPANSION}(g)$}
		\begin{algorithmic}[1]
			\Require A near-bent function $g$ in $\boole(m-1)$. %{\color{blue} Sasha: Looks like everything below is independent on $g$, what shouldn't be the case}
			%{\color{magenta} admissibily depend on $g$}
			\Ensure Print all bent expansions of $g$.
			\State Initialize a dictionary   $\mathcal{D}$.
			\State $A_{00}(g)$:= the set of $00$-admissible functions for $g$
			\For{all $L$ in $A_{00}(g)$}
			\State $\kappa$:= key($L$)
			\State add entry ($\kappa$,$L$) in $\mathcal{D}$
			\EndFor
			\State $A_{010}(g)$:= the set of $010$-admissible functions for $g$
			\State $A_{011}(g)$:= the set of $011$-admissible functions for $g$
			\For{all $(\phi_{010}, \phi_{011})$ in  $A_{010}(g) \times A_{011}(g)$  }
			\State $R$ := $(\phi_{010}||\phi_{011} )$
			\If  {$R$ is 01-admissible for $g$}
			\State $\kappa$ := key($R$)
			\For{all $L$ with key  $\kappa$} 
			\If{$(L||R)$ is 0-admissible for $g$}
			%\State $\Phi$ := $( L || R || L' ||  R' )$
			\State $\Phi_0$ := $( L || R )$ 
			\State $\Phi_1$ := $(  L' ||  R' )$ 
			\If{$(  \Phi_0 ||  \Phi_1 )$ is bent}
			\State print its dual!
			\EndIf
			\EndIf
			\EndFor
			\EndIf
			\EndFor
		\end{algorithmic}
		\label{EXPAND}
	\end{algorithm}

    The set of all abnormal functions obtained using the sieving procedure described in Algorithm~\ref{SIEVING} contains $4\,987$ near-bent functions. We identify $1\,309$ representatives up to extended-affine equivalence using Magma with the method described in Section~\ref{sec 2: intro}. Consequently, we apply Algorithm~\ref{EXPAND} to determine which of these near-bent functions are bent-expandable and, in turn, to identify all bent expansions. It appears that only 30 of these representatives are bent-expandable. These are listed in Appendix~\ref{appendix}.

    At the end, we collect $\approx 2^{24}$ bent functions (all of which are available on the web page of the project~\cite{project_normal}). Applying Algorithm~\ref{ABNORMAL}, we check that all of them are normal or weakly normal. Thus, we obtain the main result of this paper:

    \begin{theorem}
        All the bent functions of $\boole(8)$ are normal or weakly normal.
    \end{theorem}



