\subsection{Model-Driven Long-term IREE Correction}

According to the rate stability conditions of Lyapunov theory\cite{neely2022stochastic}, we propose some queuing-based constraints and reformulate Problem~\ref{prob:utility} as following.

\begin{Prob}[Recursive Utility Maximization for Given $\tau$]
\label{prob:final}
For any given time slot $\tau$, the transient utility for the entire wireless network with $N_{BS}$ BSs can be maximized via the following recursive version.
\begin{eqnarray}
\underset{ \scriptsize \makecell{ \{B_{n,\tau},P_{n,\tau}^{a} \} , \kappa_{\tau}, \\ 
h_{\tau}, \nu^{\zeta}_{\tau}, \nu^{\kappa}_{\tau}, \nu^{\eta}_{\tau} } }{\textrm{maximize}} && \makecell[l] { (1 - \kappa_{\tau})\min\{C_{Tot}(\tau),  D_{Tot}(\tau)\} \\ - \eta_{IREE}^{\tau} P_T (\tau), } \nonumber \\
\textrm{subject to} && \eqref{eqn:convection-diffusion} - \eqref{eqn:total_pow_def}, \eqref{constraint:max_bandwidth} - \eqref{def:kappa}, \nonumber \\
&& (1 - \kappa_{\tau} - h_{\tau}) \min\{C_{Tot}(\tau),D_{Tot}(\tau)\} \nonumber \\
&& + \nu^{\zeta}_{\tau} Q^{\zeta}_{\tau}  = \zeta_{\min} D_{Tot}(\tau), \label{constraint:h_linear} \\
&& \xi(\tau) + \nu^{\kappa}_{\tau} Q^\kappa_{\tau} = \kappa_{\tau} / \mathcal{T}, \label{constraint:js_linear} \\
&& \frac{\eta_{IREE}^{\tau}}{1 - \kappa_{\tau}} 
+ \frac{\nu^{\eta}_{\tau} Q^{\eta}_{\tau}}{P_T(\tau)} = \frac{\eta^{\mathcal{T}}_{IREE}}{1 - \kappa}, \label{constraint:eta_linear} \\
&& \nu^{\zeta}_{\tau}, \nu^{\kappa}_{\tau}, \nu^{\eta}_{\tau} \in [0,2], h_{\tau} \in [0,1], \label{constraint:correction_factor} 
\end{eqnarray}
where $\nu^{\zeta}_{\tau}$, $\nu^{\kappa}_{\tau}$ and $\nu^{\eta}_{\tau}$ are the correction factors. $h_{\tau}$ is the traffic auxiliary variable which reflects how well the traffic requirement \eqref{constraint:zeta} can be met. $Q^{\zeta}_{\tau}$, $Q^\kappa_{\tau}$ and $Q^{\eta}_{\tau}$ are the virtual queues for the recursive error of $\zeta$, $\kappa_{\tau}$ and $\eta_{IREE}^{\tau}$ given by,
\begin{small}
\begin{eqnarray}
\label{eqn:queues}
\left \{
\begin{aligned}
Q^{\zeta}_{\tau} =&  
\sum_{t=0}^{\tau-1} [  (1 - \kappa_{t} - h_{t}) \min\{C_{Tot}(t),D_{Tot}(t)\}  \\
& - \zeta_{\min} D_{Tot}(t) ], \\
Q^\kappa_{\tau} =& \sum_{t=0}^{\tau-1} ( \xi(t)- \kappa_{t}/ \mathcal{T} ), \\
Q^{\eta}_{\tau} =& \sum_{t=0}^{\tau-1} P_T(t) \Big ( \frac{\eta^{t}_{IREE}}{1 - \kappa_{t}} 
- \frac{\eta^{\mathcal{T}}_{IREE}}{1 - \kappa} \Big).
\end{aligned}
\right.
\end{eqnarray}
\end{small}
\end{Prob}

\begin{Lem}
\label{lem:prob_equivalent}
The optimal solution of Problem~\ref{prob:final} will converge to the optimal solution of Problem~\ref{prob:utility}, if  \eqref{constraint:h_linear}, \eqref{constraint:js_linear}, \eqref{constraint:eta_linear} and \eqref{constraint:correction_factor} holds.
\end{Lem}
\IEEEproof Please refer to Appendix~\ref{appendix:prob_equivalent} for the proof.
\endIEEEproof

The reason that Lemma~\ref{lem:prob_equivalent} holds is that the correction factors are constantly correcting $\{B_{n,\tau}, P_{n,\tau}^{a}\}$ and $\kappa_{\tau}$ at each moment, so that the cumulative error of $\zeta$, $\kappa_{\tau}$ and $\eta_{IREE}^{\tau}$, i.e., $Q^{\zeta}_{\tau}$, $Q^\kappa_{\tau} $ and $Q^\eta_{\tau} $ approaches $0$. The distributed augmented Lagrangian function for Problem~\ref{prob:final} is given by\footnote{For simplicity, the convex constraints \eqref{constraint:max_bandwidth}, \eqref{constraint:max_power} and \eqref{constraint:correction_factor}  are omitted.},
\begin{small}
\begin{eqnarray}
\label{eqn:lagrangian_function}
&&\Lambda \big( \{B_{n,\tau}, P_{n,\tau}^{a}\}, \kappa_{\tau}, h_{\tau}, \nu^{\kappa}_{\tau}, \nu^{\eta}_{\tau}, \nu^{\zeta}_{\tau}, \omega^{\kappa}_{\tau}, \omega^{\eta}_{\tau}, \omega^{\zeta}_{\tau} \big ) \nonumber \\
&=& (1-\kappa_{\tau}) \min\left \{ C_{Tot}(\tau) , D_{Tot}(\tau)\right \} -\eta_{IREE}^{\tau} P_{T}(\tau) \nonumber \\ 
&-& \omega^{\kappa}_{\tau} \left (\xi(\tau) + \nu^{\kappa}_{\tau} Q^\kappa_{\tau} - \frac{\kappa_{\tau}}{\mathcal{T}} \right ) - \frac{\rho^{\kappa}}{2} \left (\xi(\tau) + \nu^{\kappa}_{\tau} Q^\kappa_{\tau} - \frac{\kappa_{\tau}}{\mathcal{T}} \right )^{2}  \nonumber \\
&-& \omega^{\eta}_{\tau} \Big [P_T(\tau) \eta_{IREE}^{\tau} - (1 - \kappa_{\tau} ) \Big( \frac{P_T(\tau) \eta^{\mathcal{T}}_{IREE} }{1 - \kappa} - \nu^{\eta}_{\tau} 
Q^{\eta}_{\tau}  \Big) \Big ]  \nonumber \\
&-& \frac{\rho^{\eta}}{2} \Big [P_T(\tau) \eta_{IREE}^{\tau} - (1 - \kappa_{\tau} ) \Big( \frac{P_T(\tau) \eta^{\mathcal{T}}_{IREE} }{1 - \kappa} - \nu^{\eta}_{\tau} 
Q^{\eta}_{\tau}  \Big) \Big ]^{2} \nonumber \\
&-& \omega^{\zeta}_{\tau} \Big [ (1-\kappa_{\tau }- h_{\tau}   )\min\left \{ C_{Tot}(\tau) , D_{Tot}(\tau)\right \} + \nu_{\tau}^{\zeta }Q_{\tau}^{\zeta} \nonumber \\
&-& \zeta_{\min} D_{Tot}(\tau)\Big ]  - \frac{\rho^{\zeta}}{2} \Big [ (1-\kappa_{\tau }- h_{\tau}   ) \nonumber \\
&\times& \min\left \{ C_{Tot}(\tau) , D_{Tot}(\tau)\right \} + \nu_{\tau}^{\zeta }Q_{\tau}^{\zeta} -\zeta_{\min} D_{Tot}(\tau)\Big ]^2, 
\end{eqnarray}
\end{small}
where $\omega^{\kappa}_{\tau}, \omega^{\eta}_{\tau},\omega^{\zeta}_{\tau}$ are the Lagrange dual variables and $\rho^{\kappa}, \rho^{\eta}, \rho^{\zeta} \in \mathbb{R}^+$ denote positive penalty parameters. Please note that in \eqref{eqn:lagrangian_function} we make some equivalent transformations on \eqref{constraint:eta_linear} to ensure the quadratic nature of $\kappa_{\tau}$.

Inspection of the augmented Lagrangian function reveals that $\Lambda$ is quadratic with respect to $\kappa_{\tau}$, $h_{\tau}$, $\nu^{\kappa}_{\tau}$, $\nu^{\eta}_{\tau}$, and $\nu^{\zeta}_{\tau}$. The dual variables $\omega^{\kappa}_{\tau}$, $\omega^{\eta}_{\tau}$, and $\omega^{\zeta}_{\tau}$ can be iteratively updated using standard ADMM techniques \cite{yang2022survey}. However, the non-convexity of the problem complicates the derivation of the optimal $\{B_{n,\tau}, P_{n,\tau}^{a}\}$, which we will discuss in the next section.


% a detailed solution is deferred to Section~\ref{sect:data_driven}.

% Following the solution of Problem~\ref{prob:final}, $\eta_{IREE}^{\tau}$, $\kappa$, and $\eta_{IREE}^{\mathcal{T}}$ require updating. While $\eta_{IREE}^{\tau}$ is directly updated according to its definition in \eqref{eqn:transient_iree}, updating $\kappa$ and $\eta_{IREE}^{\mathcal{T}}$ necessitates complete spatial-temporal information of $\{B_{n,\tau}, P_{n,\tau}^{a}\}$ and $\{D(\mathcal{L}, \tau)\}$, as specified in \eqref{def:kappa} and \eqref{def:long_iree}. To address this, we leverage the ergodic property of traffic patterns and update $\kappa$ and $\eta_{IREE}^{\mathcal{T}}$ using data from a sufficiently long past time period $[\tau-\Delta \mathcal{T}, \tau]$. 



