&&- \Bar{B}_{n,\tau} ) \log_2 \Bigg (1 + \frac{ \Bar{P}_{n,\tau}^{a}/B_{\max} }{ \gamma \sigma^2  \Vert \mathcal{L}_m - \mathcal{L}_n \Vert_2^{\alpha} + \beta \sigma^2 } \Bigg)  \Bigg \Vert_2 \nonumber \\
&&\overset{(a)}{\leq} B_{\max} \Bigg \Vert \sum_{n=1}^{N_{BS}} \Bigg [ \frac{ \hat{P}_{n,\tau}^{a}/B_{\max} }{ \gamma \sigma^2  \Vert \mathcal{L}_m - \mathcal{L}_n \Vert_2^{\alpha} + \beta \sigma^2 } \nonumber \\
&&- \frac{ \Bar{P}_{n,\tau}^{a}/B_{\max} }{ \gamma \sigma^2  \Vert \mathcal{L}_m - \mathcal{L}_n \Vert_2^{\alpha} + \beta \sigma^2 } \Bigg ]  \Bigg \Vert_2 +\Bigg \Vert \sum_{n=1}^{N_{BS}} (\hat{B}_{n,\tau} - \Bar{B}_{n,\tau} ) \Bigg \Vert_2  \nonumber \\
&&\times \sum_{n=1}^{N_{BS}} \log_2 \Bigg (1 + \frac{ \Bar{P}_{n,\tau}^{a}/B_{\max} }{ \gamma \sigma^2  \Vert \mathcal{L}_m - \mathcal{L}_n \Vert_2^{\alpha} + \beta \sigma^2 } \Bigg)  \nonumber \\
&&\overset{(b)}{\leq} B_{\max} \Bigg \Vert \sum_{n=1}^{N_{BS}} \Bigg [ \frac{ \hat{P}_{n,\tau}^{a}/B_{\max} }{ \gamma \sigma^2  \Vert \mathcal{L}_m - \mathcal{L}_n \Vert_2^{\alpha} + \beta \sigma^2 } \nonumber \\
&&- \frac{ \Bar{P}_{n,\tau}^{a}/B_{\max} }{ \gamma \sigma^2  \Vert \mathcal{L}_m - \mathcal{L}_n \Vert_2^{\alpha} + \beta \sigma^2 } \Bigg ]  \Bigg \Vert_2 + \frac{ N_U^{\tau} N_{BS} P_{\max} }{ \beta \sigma^2 B_{\max} }  \epsilon_2 \nonumber \\
&&\overset{(c)}{\leq} \frac{ N_U^{\tau} N_{BS} P_{\max} }{ \beta \sigma^2 B_{\max} }  \epsilon_2 + \frac{ N_U^{\tau} }{ \beta \sigma^2 }  \epsilon_3.
\end{eqnarray}
where step (a) is obtained through the triangle inequality and the properties of the log function. Step (b) and step (c) hold since $\Bar{P}_{n,\tau}^{a} 
\leq P_{\max}$, $\gamma \sigma^2  \Vert \mathcal{L}_m - \mathcal{L}_n \Vert_2 \geq 0$ and \eqref{eq:time_error}. Hence, we have,
\begin{eqnarray} 
\label{eq:}
&&\Vert C_{T}(\mathcal{L}_m, \tau) - D(\mathcal{L}_m, \tau) \Vert_2\nonumber \\
&\leq& \Vert C_{T}(\mathcal{L}_m, \tau) - C_{S}(\mathcal{L}_m, \tau) \Vert_2  \nonumber \\
&&+ \Vert C_{S}(\mathcal{L}_m, \tau) - D(\mathcal{L}_m, \tau) \Vert_2 \nonumber \\
&\leq& \epsilon_1 +  \frac{ N_U^{\tau} }{ \beta \sigma^2 } \left (\frac{ N_{BS} P_{\max} }{B_{\max} }  \epsilon_2 +  \epsilon_3 \right ).
\end{eqnarray}




