\begin{corollary}\label{main-c}
\emph{Let $\{p_i, \rho_i\}_{i=1}^m$ be an ensemble of $m<+\infty$ quantum states in $\S(\H)$. Then
\begin{equation}\label{main-c+}
 \chi(\{p_i, \rho_i\}_{i=1}^m)\leq \varepsilon_{av}\log m+\sum_{i=1}^m p_ih(\varepsilon_i)\leq \varepsilon_{av}\log m+h(\varepsilon_{av}),
\end{equation}
where $\varepsilon_i\doteq\frac{1}{2}\|\rho_i-\bar{\rho}(\mu)\|_1$ and $\varepsilon_{av}\doteq\sum_{i=1}^m p_i\varepsilon_i$ -- the mean distance from the states $\{\rho_i\}_{i=1}^m$ to the average state $\bar{\rho}(\mu)$}.
\end{corollary}\medskip

Inequality (\ref{main-c+}) refines the upper bounds for the Holevo quantity depending on $\varepsilon_{av}$ and the number $m$ of ensemble states  obtained in \cite{HUB}.

\subsection{On improvements of the  bound in Proposition \ref{main_b} using information about the operators $[\rho_i-\bar{\rho}(\mu)]_{\pm}$}

The upper bound on the Holevo quantity presented in Proposition \ref{main_b} can be improved by optimizing the proof of this proposition  with the use of information about the operators $[\rho_i-\bar{\rho}(\mu)]_{\pm}$, $i\in I$ ($[\rho_i-\bar{\rho}(\mu)]_{+}$ and $[\rho_i-\bar{\rho}(\mu)]_{-}$ are the positive and negative parts of the operator $\rho_i-\bar{\rho}(\mu)$). \smallskip

\begin{proposition}\label{main++} \emph{Let $\mu=\{p_i, \rho_i\}_{i\in I}$ be an ensemble of quantum states in $\S(\H)$ with the average state $\bar{\rho}(\mu)$ such that either $S(\bar{\rho}(\mu))<+\infty$ or $H(\{p_i\}_{i\in I}\})<+\infty$. Then %either$S(\bar{\rho})<+\infty$ or
\begin{equation}\label{main+++}
 \chi(\mu)\leq \varepsilon_{av}C(\mu)H\left(\left\{\frac{p_i\varepsilon_i}{\varepsilon_{av}}\right\}_{i\in I}\right)+\sum_{i\in I}p_ih(\varepsilon_i)-\varepsilon_{av}D(\mu),
\end{equation}
where $\varepsilon_i\doteq\frac{1}{2}\|\rho_i-\bar{\rho}(\mu)\|_1$,  $\varepsilon_{av}\doteq\sum_{i\in I}p_i\varepsilon_i$, $H(\cdot)$ is the Shannon entropy, $h(\cdot)$ is the binary entropy and}
$$
C(\mu)=\frac{1}{2}\sup_{i,j\in I}\|\varepsilon^{-1}_i[\rho_i-\bar{\rho}(\mu)]_{+}-\varepsilon^{-1}_j[\rho_j-\bar{\rho}(\mu)]_{+}\|_1
$$
$$
D(\mu)=\frac{\log e}{2}\sum_{i\in I}p_i\|\varepsilon^{-1}_i[\rho_i-\bar{\rho}(\mu)]_{-}-\bar{\rho}(\mu_-)\|^2_1
$$
$$
\left(\bar{\rho}(\mu_-)\doteq\varepsilon^{-1}_{av}\sum_{i\in I}p_i[\rho_i-\bar{\rho}(\mu)]_{-}=\bar{\rho}(\mu_+)\doteq\varepsilon^{-1}_{av}\sum_{i\in I}p_i[\rho_i-\bar{\rho}(\mu)]_{+}\right),
$$
\smallskip

\emph{The second term in (\ref{main+++}) can be replaced by $h(\varepsilon_{av})$. }
\end{proposition}\medskip

%We will denote the state $\bar{\rho}$ by  $\bar{\rho}(\mu)$ for brevity.

\emph{Proof.} It suffices to upgrade the proof of Proposition \ref{main_b} (based on inequality (\ref{main+})) by noting that
\begin{equation}\label{one-in+}
\chi(\mu_{-})\geq D(\mu)
\end{equation}
and that
\begin{equation}\label{two-in+}
\chi(\mu_{+})\leq C(\mu)H\left(\left\{\frac{p_i\varepsilon_i}{\varepsilon_{av}}\right\}_{i\in I}\right),
\end{equation}
where $\mu_{-}$ and $\mu_{+}$ are the ensembles introduced before Theorem \ref{main}.
The inequality (\ref{one-in+})  is a corollary of the well-known lower bound for the quantum relative entropy \cite{H-SCI,Wilde}.
The inequality (\ref{two-in+})  follows from Audenaert's  upper bound on the Holevo quantity \cite{Aud}. $\Box$

\begin{example}\label{two} Consider the ensemble $\hat{\mu}=\{p_i,\rho_i\}_{i=1}^3$ in $\S(\H_2)$, where
$p_1=p_2=p_3=1/3$ and $\rho_1$, $\rho_2$, $\rho_3$ are pure states corresponding to the vectors
$$
\left[\begin{array}{c}
  1 \\
  0
\end{array}\right],\qquad \left[\begin{array}{c}
  -1/2 \\
  \sqrt{3}/2
\end{array}\right]\qquad \left[\begin{array}{c}
  -1/2 \\
  -\sqrt{3}/2\end{array}\right],
$$
Then $\bar{\rho}(\hat{\mu})=I_2/2$ and  $\varepsilon_1=\varepsilon_2=\varepsilon_3=1/2$. Hence, in this case
the upper bound (\ref{main_b+}) is equal to $(1/2)\log 3+\log 2\approx1.24$ (we assume that $\log=\ln$),
which is essentially greater than $\chi(\hat{\mu})=\log2\approx 0.69$.

Since $\hat{\mu}_+=\hat{\mu}$ and $\hat{\mu}_-=\{q_i,\sigma_i\}_{i=1}^3$, where
$q_1=q_2=q_3=1/3$ and $\sigma_1=I_2-\rho_1$, $\sigma_2=I_2-\rho_2$, $\sigma_3=I_2-\rho_3$, we have
$$
C(\hat{\mu})=\sqrt{1-1/4}=\sqrt{3}/2\quad\textrm{ and }\quad D(\hat{\mu})=1/2.
$$
So, the upper bound (\ref{main+++}) gives more accurate estimate $(\sqrt{3}/4)\log 3+\log 2-1/4\approx 0.92$.\smallskip

Note, finally, that inequality  (\ref{main+}) provides a sharp upper bound on $\chi(\hat{\mu})$. Indeed,  since $\chi(\hat{\mu}_+)=\chi(\hat{\mu}_-)=\log 2$,
we have
$$
\chi(\hat{\mu})=\log2=(1/2)(\chi(\hat{\mu}_+)-\chi(\hat{\mu}_-))+h(1/2).
$$
\end{example}

