From Theorem \ref{the:stogradient}, the stochastic gradient used in the SGD update is
\[
\nabla \tilde{\mathcal{L}}(u) = \tilde{\mathcal{G}}_S(u) = A(u - \bar{u}) - \frac{1}{\sqrt{S}}\xi,
\]
where $ \xi$ is a mean-zero Gaussian error term in $ \mathcal{H}_u $ with covariance operator $\mathcal{C}_\text{noise} = \mathcal{C}_0\mathcal{Q}$. 
Since random variable \( \xi \) is centered, the expected value of \( \tilde{\mathcal{G}}_S(u)\)  is \(A(u - \bar{u})\), which equals to \( \mathbb{E}[\nabla \tilde{\mathcal{L}}(u)] = A(u - \bar{u}) \).

We now characterize the covariance operator of \(\operatorname{Cov}(\nabla \tilde{\mathcal{L}}(u))\), which is:
\[
\operatorname{Cov}(\nabla \tilde{\mathcal{L}}(u)) = \frac{1}{\sqrt{S}}\mathcal{C}_0\mathcal{Q}.
\]
Then eigenvalues \( \{ \phi_i \}^M_{i = 1} \) of \(\operatorname{Cov}(\nabla \tilde{\mathcal{L}}(u))\) satisfy
\[
\operatorname{Cov}(\nabla \tilde{\mathcal{L}}(u))e_i = \phi_ie_i = \frac{1}{S}c_iq_ie_i,
\]
indicating
\[
\phi_i = \frac{1}{S}c_iq_i.
\]

That is, by calculate the eigenvalues of covariance \( \operatorname{Cov}(\nabla \tilde{\mathcal{L}}(u)) \), the eigenvalues \( \{q_i\}^M_{i = 1} \) of operator \( \mathcal{Q} \) is then calculated by
\[
\mathcal{Q} = \sum^M_{i = 1}q_i e_i \otimes e_i 
=  \sum^M_{i = 1}\frac{S\phi_i}{c_i}e_i \otimes e_i.
\]
Substituting \( \{q_i\}^M_{i = 1} \) into the bounds for \( S \) in Eqs.~\eqref{eq:ScSGD} and \eqref{eq:SpcSGD}, we obtain
\begin{itemize}
	\item for the cSGD-iVI case, we derive
	\[
	S < \sqrt{\frac{M^\prime}{\sum^M_{i = 1}\frac{\bm{a}_{\text{max}}\bm{a}_i - \bm{a}^2_i}{q_i}}} =
	\sqrt{\frac{M^\prime}{\sum^M_{i = 1}\frac{\bm{a}_{\text{max}}\bm{a}_i - \bm{a}^2_i}{\frac{S\phi_i}{c_i}}}} = 	\sqrt{S\frac{M^\prime}{\sum^M_{i = 1}\frac{\bm{a}_{\text{max}}c_i\bm{a}_i - c_i\bm{a}^2_i}{\phi_i}}}.
	\]
	That is
	\[
	S < \frac{M^\prime}{\sum^M_{i = 1}\frac{\bm{a}_{\text{max}}c_i\bm{a}_i - c_i\bm{a}^2_i}{\phi_i}},
	\]
    where \( M^\prime = M + \sum_{i=1}^Ma_ic_i \), and \( \bm{a}_i = a_i+\frac{1}{c_i} \).

	\item for the pcSGD-iVI case, we derive
	\[
	S < \sqrt{\frac{M^\prime}{\sum^M_{i = 1}\bigg(\frac{\tau_{\text{max}}\bm{a}_i}{t_i\frac{S\phi_i}{c_i}} - \frac{\bm{a}^2_i}{\frac{S\phi_i}{c_i}}\bigg)}} 
	=  \sqrt{\frac{M^\prime}{\frac{1}{S}\sum^M_{i = 1}\bigg(\frac{\tau_{\text{max}}c_i\bm{a}_i}{t_i\phi_i} - \frac{c_i\bm{a}^2_i}{\phi_i}\bigg)}}.
	\]
	That is
	\[
	S < \frac{M^\prime}{\sum^M_{i = 1}\bigg(\frac{\tau_{\text{max}}c_i\bm{a}_i}{t_i\phi_i} - \frac{c_i\bm{a}^2_i}{\phi_i}\bigg)},
	\]
    where \( M^\prime = M + \sum_{i=1}^Ma_ic_i \), and \( \bm{a}_i = a_i+\frac{1}{c_i} \).
\end{itemize}

This completes the specification of \( \mathcal{Q} \) through observable quantities \( \{ q_i, \phi_i\}_{i=1}^M \), allowing evaluation of scale bounds for both cSGD-iVI and pcSGD-iVI.

