\end{figure}

Applying the inequality $\sqrt{1 + x} \leq 1 + x/2$ valid for $x \geq 0$ yields
\begin{equation}
\label{eq:drift}
L' \leq \lvert L - b\lvert N\rvert\rvert + \frac{b^2 \chi^2_{m-1}}{2\lvert L - b\lvert N\rvert\rvert}.
\end{equation}
The typical magnitude of $\lvert N\rvert$ is constant and the typical magnitude of $\chi^2_{m-1}$ is on the order of $m$.   If $L$ is larger than about $bm$, the drift is typically negative.

\begin{claim}
\label{claim:drift}
Assume $m \geq 4$. Conditioned on $L \geq 2b m$, $L'$ is stochastically dominated by $L - b\typeB$ where $\typeB$ is independent of $L$, has mean at least $0.25$, and has constant subexponential norm, in the sense that $\Pr[|\typeB| \geq t ] \leq O \left( \exp\left( -\Omega(t) \right) \right)$ for all $t > 0$.
\end{claim}
For now, we defer the proof of \Cref{claim:drift}.

To handle the cases when $L$ is small or $\lvert N\rvert$ is atypically large, we can use the simple bound that $\norm{\vecy'}$ is still at most $\norm{\vecy} + b\norm{\veca}$ by the triangle inequality so
\begin{equation}
\label{eq:worstdrift}
L' \leq L + b\typeA, \qquad\text{where $\typeA$ is of type $\sqrt{\chi^2_m}$}.
\end{equation}

We will refer to the corresponding random variables as in \eqref{eq:worstdrift} and \Cref{claim:drift} as being of type $\typeA$ and type $\typeB$, respectively. By standard properties of the $\chi^2_m$ distribution and Jensen's inequality, type $\typeA$ is of mean at most $\sqrt{m}$ and has subgaussian norm $\Omega(\sqrt{m})$.

Let $L_0, L_1, \dots$ be a stochastic process that evolves according to~\eqref{eq:process} (with fixed $b$).

\begin{claim}
\label{claim:evolution}
If $L_0$ is at most $8bm$ then for every $t^\star \geq Km$, $L_{t^\star}$ is at most $4bm$ except with probability $O(2^{-\Omega(m)})$.
\end{claim}
\begin{proof}
Let $A_1, A_2, \dots$ and $B_1, B_2, \dots$ be sequences of independent type-$\typeA$ and type-$\typeB$ random variables, respectively.  The drift $L_t - L_{t-1}$ is stochastically dominated by $bA_t$ if $L_{t-1} < 2bm$ and by $-bB_t$ otherwise.

Let $T$ be the last time $T \leq Km$ at which $L_T < 2bm$, if such a time exists. By~\Cref{claim:drift} and~\eqref{eq:worstdrift}, $L_{t^\star}$ is then stochastically dominated by $2bm + b(A_T - B_{T+1} - \cdots - B_{t^\star})$.  Otherwise, $L_t$ is stochastically dominated by $L_0 - bB_1 - \cdots - bB_{t^\star}$.  By a union bound over the possible choices of $T$,
\begin{align*}
\Pr[L_{t^\star} > 4bm] &\leq \Pr[L_0 - bB_1 - \cdots - bB_{t^\star} > 4bm] + \sum_{t=1}^{t^\star} \Pr\left[ bA_t - bB_{t+1} - \cdots - bB_{t^\star} > 2bm \right] \\
&\leq \Pr\left[B_1 + \cdots + B_{t^\star} \leq 4m \right] + \sum_{t=0}^{\infty} \Pr\left[A_1 - B_1 - \cdots - B_t > 2m\right].
\end{align*}
As the type-$\typeB$ random variables have mean at least $0.25$ and are subexponential, the first probability is at most $2^{-m}$ provided $t^* > Km$. As for the $t$th term in the sum, by union and tail bounds,
\begin{align*}
\Pr\left[ A_1 - B_1 - \cdots - B_t > 2m \right]
&\leq \Pr\left[ A_1 > m + t/8 \right] + \Pr\left[B_1 + \cdots + B_t < -m + t/8\right] \\
&\leq \exp \left( -\Omega \left(\sqrt{m} + t/\sqrt{m} \right)^2 \right) + \exp \left( -\Omega(m + t) \right) \\
&\leq 2 \exp\left( -\Omega(m + t) \right). 
\end{align*}
By convergence of the geometric series, the sum over $t$ is also bounded by $O\left(\exp \left( -\Omega(m) \right) \right)$.
\end{proof}

\begin{proof}[Proof of \Cref{thm:cool}]
Apply Claim~\ref{claim:evolution} to $L = \norm{\vecy}$. At the end of the first stage $L$ is at most $4Bm = 8(B/2)m$ except with probability $O(2^{-\Omega(m)})$.  Assuming it is, at the end of the second stage $L$ is at most $4(B/2)m = 8(B/4)m$ except with probability $O(2^{-\Omega(m)})$, and so on.  At the very end $L$ is at most $4m$ as desired. The cumulative failure probability is at most $O(\log B)2^{-\Omega(m)}$.
\end{proof}

We now proceed to prove~\Cref{claim:drift}.
\begin{proof}[Proof of Claim~\ref{claim:drift}]
Set
\[ \typeB = \begin{cases}
\lvert N\rvert - \chi^2_{m-1}/(2m), &\text{if $\lvert N\rvert \leq m$} \\
-\sqrt{m^2 + \chi^2_{m-1}}, &\text{otherwise}.
\end{cases}
\]
Stochastic domination follows from~\eqref{eq:drift} and~\eqref{eq:worstdrift}, as we can decompose the type $\typeA$ random variable into its component in the direction of $\vecy$ (i.e., $N$) and its $m-1$ independent other components. By standard facts and Cauchy-Schwarz, the mean of $\typeB$ is at least
\begin{align*}
\E[\typeB] &= \E[\lvert N \rvert] - \frac{\E\left[\chi_{m-1}^2\right]}{2m}  - \E \left[\left(
\sqrt{m^2 + \chi_{m-1}^2} + \lvert N \rvert - \frac{\chi^2_{m-1}}{2m} \right) \one\left[ \lvert N\rvert > m \right] \right]  \\
&\geq \sqrt\frac{2}{\pi} - \frac{m-1}{2m}
- \left(\sqrt{m^2 + \E\left[\chi_{m-1}^2 \right]} + \sqrt{\E\left[ N^2 \right]}  + \sqrt{ \frac{\E \left[ \chi_{m-1}^4 \right]}{4m^2}}\right) \sqrt{\Pr \left[ \lvert N \rvert > m \right]} \\
&\geq 0.29 - (2m + 2) \cdot 2\exp\left(-m^2/4 \right) \\
&\geq 0.25.
\end{align*}
For the subexponential norm, by union and large deviation bounds,
\begin{align*}
\Pr\left[ \lvert \typeB\rvert \geq t \right] &\leq \Pr\left[ \lvert N\rvert \geq t\right] + \Pr\left[\frac{\chi_{m-1}^2}{2m} \geq t\right] + \Pr\left[\text{$\sqrt{m^2 + \chi_{m-1}^2} \geq t$ and $\lvert N\rvert > m$}\right] \\
&\leq 2\exp\left(-t^2/2 \right) + \exp\left(-t/2 \right) +  \Pr\left[\text{$\sqrt{m^2 + \chi_{m-1}^2} \geq t$ and $\lvert N\rvert > m$}\right] \\
&= O(\exp(-t/2)) +  \Pr\left[\text{$\sqrt{m^2 + \chi_{m-1}^2} \geq t$ and $\lvert N\rvert > m$}\right].
\end{align*}
To bound the right-hand term, we consider two cases. If $t < m^2$, then
\[ \Pr\left[ \text{$\sqrt{m^2 + \chi_{m-1}^2} \geq t$ and $\lvert N\rvert > m$} \right] \leq \Pr[|N| > m] \leq O \left( \exp\left(-m^2/4 \right) \right) \leq O(\exp(-\Omega(t))).\]
If $t \geq m^2$,
\begin{align*} \Pr\left[\text{$\sqrt{m^2 + \chi_{m-1}^2} \geq t$ and $\lvert N\rvert > m$} \right] &\leq \Pr\left[\chi_{m-1}^2 \geq t^2 - m^2 \right]
\\&\leq \exp\left(-\Omega\left(t^2/m - m\right)\right)
\\&\leq \exp\left(-\Omega\left(tm - m\right)\right)
\\&\leq \exp\left(-\Omega\left(t\right) \right).
\end{align*}
Therefore, in all cases, $\Pr[|\typeB| \geq t] \leq O(\exp(-\Omega(t)))$.
 \hfill\qedhere
\end{proof}

\paragraph{Limiting behavior} In the limit $m \to \infty$ under the scaling $U = L/bm$, $dt = 1/m$,~\eqref{eq:drift} is approximated by the stochastic differential equation
\[ dU = \Bigl(-\mu + \frac{1}{2U}\Bigr)dt + \sigma dW, \]
where $\mu = \sqrt{2/\pi}$ and $\sigma = \sqrt{1 - 2/\pi}$ are the statistics of $\lvert N\rvert$, and $W$ is the Wiener process.  The drift pushes $U$ towards the fixed point
\[ U = \frac{1}{2\mu} = \sqrt\frac{\pi}{8} \approx 0.627. \]

\begin{conjecture}[Online threshold conjecture]
\label{online threshold conjecture}
For every $\delta$ and $B$ there exists a sufficiently small $\alpha$ and $\epsilon$ so that every online algorithm fails to find $\vecx \in ([-B, B] \cap \Z)^{n}$ such that $\norm{\matA\vecx}/(\sqrt{m} \norm{\vecx}) < (\sqrt{\pi/8} - \delta) \sqrt{\alpha}/B$ for at least an $\epsilon$ fraction of $\alpha n$ by $n$ matrices $A$ for all sufficiently large $n$.
\end{conjecture}

\subsection{Kernel Rounding}\label{subsection-kernel-rounding}

    \begin{figure}[H]
    \centering
    \fbox{
    \begin{minipage}{0.95\textwidth}
    \begin{center}
    Algorithm $\kernelround$
    \end{center}
\textbf{Input}: $\matA \sim \Norm(0,1)^{m \times n}$ where $m < n$.
\begin{enumerate}
    \item Sample a random $\vecx$ such that $\matA\vecx = \zero$ according to the Haar measure. 
    \item Scale $\vecx$ to have length $\sqrt{\chi^2_n} \cdot \frac{B}{\sqrt{4K \ln^+ B}}$.
    \item Define the rounded vector $\vecz = \round{\vecx}_B$.
\end{enumerate}
\textbf{Output}: The vector $\vecz \in ([-B, B] \cap \Z)^n$.
    \end{minipage}
    }
    \caption{Kernel Rounding Algorithm for $\problem$, as analyzed in \Cref{thm:roundkernel}.}
    \label{fig:kernel-round}
\end{figure}



The rounding function is applied entrywise as
\[ \lceil x \rfloor_B = \begin{cases}
\lceil x \rfloor, &\text{if $\lvert x\rvert \leq B$}, \\
B \sign{x}, &\text{otherwise,}
\end{cases}
\]
where $\round{x}$ denotes rounding $x \in \R$ to the nearest integer (and tie-breaking arbitrarily). We will let
$\ln^+$ denote the function $\max\{\ln, 1\}$. $K \geq 2$ is a (constant) parameter that controls the tradeoff between approximation quality and failure probability in the regime $B = \Omega(n^{1/4})$.

\begin{theorem}
\label{thm:roundkernel}
For $\matA \sim \Norm(0,1)^{m \times n}$, the algorithm $\kernelround$ outputs a vector $\vecz \in ([-B, B] \cap \Z)^n$ such that
\[ \frac{\norm{\matA \vecz}_2}{\norm{\vecz}_2} = O\left( \frac{\sqrt{m K \ln^+ B}}{B} \right),\]
except with probability $2^{-\Omega(m)} + \min\left\{ O\left(2^{-\Omega\left(n(K \ln B)^2/B^4\right)}\right), 2nB^{-K} \right\}$.
\end{theorem}

As the space spanned by the rows of $\matA$ is a random $m$-dimensional subspace of $\R^n$, the marginal distribution of $\vecx$ is identically $\Norm(0,B^2/(4 K \ln^+ B))^n$.  We analyze the conditional distribution of $\langle \veca, \vecx\rangle$ for a single row $\veca$ of $\matA$.

\begin{claim}
\label{claim:kernel}
Suppose $\veca \sim \Norm(0,1)^n$. Conditioned on $\vecx$ and $\langle \veca, \vecx\rangle = 0$, the random variable $\langle \veca, \lceil \vecx \rfloor_B \rangle$ is a centered normal of variance at most $\norm{\{\vecx\}_B}^2$, where $\{x\}_B = x - \lceil x \rfloor_B$ is applied coordinate-wise.
\end{claim}
We emphasize that $\{x\}_B$ can be arbitrarily large when considering $|x| > B$.

\begin{claim}
\label{claim:roundstats}
If $N \sim \Norm(0,1)$, then the random variable
\[\left\{ \frac{B}{\sqrt{4K \ln^+ B}} \cdot  N\right\}_B^2\] 
has mean at most $1/4 + O(B^{-K+2})$ and subexponential norm $O(B^2/(K\ln^+ B))$.
\end{claim}

\begin{proof}[Proof of~\Cref{thm:roundkernel}]
The quantity $\norm{\{\vecx\}_B}^2$ is a sum of $n$ independent
\[\left\{ \frac{B}{\sqrt{4K \ln^+ B}} \cdot  N\right\}_B^2\] 
random variables where $N \sim \Norm(0,1)$. By~\Cref{claim:roundstats} and Bernstein's inequality~\cite[Theorem~2.8.1]{vershynin-book}, $\norm{\{\vecx\}_B}^2$ is $O(n)$ except with probability $O(2^{-\Omega(n(K \ln B)^2/B^4)})$, which is meaningful whenever $B = O(n^{1/4})$. When $B$ is large relative to $n$, by a Gaussian tail bound and a union bound, none of the $n$ entries of $\vecx$ exceed $B$ in absolute value and so $\norm{\{\vecx\}_B}^2 \leq n/4$ except with probability $2n \cdot B^{-K}$.

By~\Cref{claim:kernel}, conditioned on $\vecx$, the entries of $\matA \lceil \vecx \rfloor_B$ are $m$ independent normals of variance $O(n)$ with the same exceptional probability. By Hoeffding's inequality $\norm{\matA \round{\vecx}_B}^2$ itself is bounded by $O(mn)$ except with additional probability $2^{-\Omega(m)}$.

Lastly, we lower bound $\norm{\round{\vecx}_B}$. Each entry of $\lceil \vecx \rfloor_B$ is of magnitude at least $B/\left(4\sqrt{K \ln^+ B}\right)$ with constant probability.  By a large deviation bound,
\[\norm{\lceil \vecx \rfloor_B} \geq \Omega\left( \frac{B \sqrt{n} }{\sqrt{K \ln^+ B} } \right),\]
except with probability $2^{-\Omega(n)}$. By a union bound, the target ratio becomes
\[ \frac{\norm{\matA \round{\vecx}_B}}{\norm{\round{\vecx}_B}} \leq O\left(\frac{\sqrt{mn}}{B \sqrt{n} / \left(\sqrt{K \ln^+ B} \right) }\right) = O\left( \frac{\sqrt{m K \ln^+ B}}{B} \right). \]
\end{proof}

\begin{proof}[Proof of~\Cref{claim:kernel}]
$\langle \veca, \lceil \vecx \rfloor_B\rangle = \langle \veca, \vecx\rangle -\langle \veca, \{\vecx\}_B\rangle$.  Conditioned on $\vecx$ and $\langle \veca, \vecx\rangle = 0$,  $\veca$ is jointly normal and centered (but not independent), so $\langle \veca, \{\vecx\}_B\rangle$ is also centered normal. Conditioning on $\inner{\veca, \vecx} = 0$ implies that $\inner{\veca, \round{\vecx}_B}$ is centered normal too.

To derive its variance, we first calculate the conditional covariances of the entries of $\veca$ given $\vecx$.  Unconditionally, the entries $a_i$ of $\veca$ are independent standard normal.  They decompose as 
\[ a_i = \frac{x_i}{\norm{\vecx}^2} \langle \veca, \vecx\rangle + a_i^\perp, \]
where $a_i^\perp$ is a centered normal independent of $\langle \veca, \vecx\rangle$ given $\vecx$. By independence and expanding out the expression,
\begin{align*}
\Cov(a_i, a_j \mid \vecx, \langle \veca, \vecx \rangle = 0) &= \Cov\left(a_i^\perp, a_j^\perp \mid \vecx, \langle \veca, \vecx \rangle = 0\right) \\
&= \Cov\left(a_i^\perp, a_j^\perp \mid \vecx\right) \\
&= \E\left[ \left(a_i - \frac{x_i}{\norm{\vecx}^2}\langle \veca, \vecx \rangle \right) \left(a_j - \frac{x_j}{\norm{\vecx}^2}\langle \veca, \vecx \rangle \right)\ \Big|\ \vecx \right] \\
&= \one[i = j] -\frac{x_ix_j}{\norm{\vecx}^2}.
\end{align*}
By the variance of sum formula,
\begin{align*}
\Var\left(\langle \veca, \{\vecx\}_B\rangle \mid \vecx, \langle \veca, \vecx \rangle = 0 \right)
&= \sum_i \{x_i\}_B^2 - \sum_{i, j} \{x_i\}_B\{x_j\}_B \cdot \frac{x_ix_j}{\norm{\vecx}^2} \\
&= \norm{\{\vecx\}_B}^2 - \biggl(\frac{\langle \vecx, \{\vecx\}_B\rangle}{\norm{\vecx}}\biggr)^2 \\
&\leq \norm{\{\vecx\}_B}^2.
\end{align*}
Once again, conditioned on $\vecx$ and $\inner{\veca, \vecx} = 0$, this implies that the variance of $\inner{\veca, \round{\vecx}_B}$ is also at most $\norm{\{\vecx\}_B}^2$. 
\hfill\qedhere
\end{proof}

\begin{proof}[Proof of \Cref{claim:roundstats}]
Let $L = B/\sqrt{4K\ln^+ B}$. Then by Cauchy-Schwarz and standard tail bounds,
\begin{align*} 
\E\left[ \{LN\}_B^2 \right]  &\leq \E\left[ \left(LN - \lceil LN \rfloor \right)^2 \cdot \one[LN \leq B] \right] + \E \left[ \left(LN - B \right)^2 \cdot \one[LN > B] \right] \\ 
&\leq \frac14 + \sqrt{\E \left[ (LN - B)^4 \right] } \sqrt{\Pr\left[ LN > B \right]} \\
&\leq \frac14 + O\left(B^2 \exp\left(-B^2/4L^2\right)\right)
\\&\leq \frac{1}{4} + O\left(B^{2-K}\right).
\end{align*}
For every $t > 1/2$,
\[ \Pr\left[ \{LN\}_B^2 \geq t \right] = \Pr\left[ \lvert LN\rvert \geq B + \sqrt{t} \right]
\leq 2 \exp\left( - \frac{(B + \sqrt{t})^2}{2L^2} \right)
= 2 \exp \left( - \left(\frac{B/\sqrt{t} + 1}{L \sqrt{2} }\right)^2 \cdot t \right).
\]
The parenthesized expression squared is at least $1/(2L^2)$, so $\{LN\}_B^2$ is subexponential of norm $O(L^2)$. 
\end{proof}

\section{Hardness}
\subsection{Overlap Gap Property}
\label{sec:hardness}

We study the typical structure of the solution space of~\eqref{eq:sbp} under the parametrization $m = \alpha n$ for fixed $\alpha, \kappa, B$ and large $n$.  Gamarnik et al.~\cite{DBLP:conf/focs/GamarnikK0X22} showed that when the solution $\vecx$ is restricted to the Boolean cube $\{\pm 1\}^n$ the multi-overlap gap property holds in the regime $\alpha \gg \kappa^2 \log 1/\kappa$.  We establish the following extension.

\begin{theorem}
\label{thm:ogp}
For all $\alpha, \kappa, B$ with 
$\kappa \ll 1/B$ and $\alpha \gg (B\kappa)^2 \log 1/B\kappa$ there exists $\beta$ and $r$ such that for all sufficiently large $n$, for all replicas $\vecx_1, \dots, \vecx_r$ such that 
\begin{equation}
\label{eq:ogp}
1 - \beta \leq \frac{\langle\/\vecx_i, \vecx_j\rangle}{\norm{\vecx_i} \norm{\vecx_j}} \leq 1 - \beta + \beta/2r \qquad\text{for all $i \neq j$},    
\end{equation}
at least one $\vecx_i$ fails to satisfy~\eqref{eq:sbp} except with probability $\exp -\Omega(\alpha r n)$.
\end{theorem}

This theorem can be interpreted as evidence for $\problem$ being hard in the regime $\alpha \gg B^2 \kappa^2 \log 1/\kappa$. 

In the algorithmic study of random disordered systems, algorithmic efficiency is predicted by ``replica symmetry'' of the solution space.  Under the replica symmetric model, the uniform distribution over solutions of $\norm{\matA \vecx} \leq \kappa m$ is approximated by a product distribution $P$ over $\{\pm 1\}^n$ with different biases across coordinates.  

Assuming $P$ has sufficient entropy, the overlap $\langle\/\vecx, \vecx'\rangle / \norm{\vecx} \norm{\vecx'}$ between two random solutions ought to be bounded away from 1.  Let $B(t)$ be the ``bouquet'' of vectors $\vecx_1, \dots, \vecx_r$ in which the first $t$ coordinates are sampled identically from $P$ and the rest are sampled independently from $P$.  By the law of large numbers all pairwise overlaps in $B(t)$ will typically concentrate around some value $1 - \beta(t)$.  As $\beta(0)$ is bounded away from zero, $\beta(n)$ is zero, and $\beta$ is $O(1/n)$-Lipschitz, by the intermediate value theorem $\beta(t)$ is bound to hit the interval $(\beta - \beta/2r, \beta)$ for some $t$, contradicting Theorem~\ref{thm:ogp}.

While is difficult to justify the accuracy of the replica symmetric model, and algorithmic easiness may persist even under replica symmetry breaking, the underlying logic can be used to rigorously rule out certain natural classes of algorithms.  In \Cref{sec:onlinehard} we prove that a natural extension of \Cref{thm:ogp}, known as the ensemble (multi) overlap gap property, rules out online algorithms under a certain stability restriction in the claimed regime.  Before stating this extension it is instructive to see the proof of \Cref{thm:ogp}.

\subsection{Proof of the Overlap Gap Property}
\label{sec:ogpproof}

The proof goes by a first moment (annealed) estimate.  Claim~\ref{claim:cover} is used to count the number of forbidden configurations $\vecx_1, \dots, \vecx_r$.  \Cref{claim:determinant}, together with the explicit formula for the multivariate Gaussian PDF, is used to bound the probability of any such configuration simultaneously solving~\eqref{eq:sbp}.  For the parameter regime of interest the expected number of configuration, which is the product of these two numbers, is close to zero.

\begin{claim}
\label{claim:angle}
Assuming $t \leq 1/12B$
 the number of nonzero $B$-bounded points  $\vecx \in \Z^n$ that are within angle $\arctan t$ of some fixed $\vecx_0$ is at most $O((1 + \ln B)/t) \cdot \exp O(n t^2 B^2 \ln 1/t B)$.
\end{claim}

\begin{claim}
\label{claim:ball}
For $\rho \leq 1/2$ an $n$-dimensional ball of radius $\sqrt{\rho n}$ contains at most $\exp O(n \rho \log 1/\rho)$ integer points.
\end{claim}
\begin{proof}
The number of integer points within distance $\sqrt{\rho n}$ of $\vecy$ is at most~\cite[Lemma 1]{mazo-odlyzko}
\[ \exp(s \rho n) \prod_i \sum_k \exp(-s(k - y_i)^2) \]
for every $s > 0$. The summation is minimized at $y_i = 0$ giving an upper bound of
\[ \exp(s \rho n) \biggl( \sum_k \exp(-sk^2)\biggr)^n \leq \exp(s \rho n) \biggl(1 + \frac{2e^{-s}}{1 - e^{-s}}\biggr)^n \]
Setting $s = \ln 1/\rho$ produces the desired bound.  
\end{proof}

\begin{claim}
\label{claim:cover}
Assume $t \leq 1$ and $\norm{\vecx_0} = 1$.  The union of balls with centers $(1 + t)^i \vecx_0$ and radii $\sqrt{5} t(1 + t)^i$ where $i$ ranges over the integers covers all nonzero $\vecx$ within angle  $\arctan t$ of $\vecx_0$.
\end{claim}

\begin{center}
