\begin{algorithm}[b]
\DontPrintSemicolon
\SetKwInput{KwIn}{Input}
\SetKwInput{KwOut}{Output}

\KwIn{
  $x_1,\,t_1$  — hidden state \& timestep for branch 1\;
  $x_2,\,t_2$  — hidden state \& timestep for branch 2\;

  $B_1=(\texttt{attn\_norm}_1,\texttt{attn}_1,\texttt{ff\_norm}_1,\texttt{ff}_1)$,\;
  $B_2=(\texttt{attn\_norm}_2,\texttt{attn}_2,\texttt{ff\_norm}_2,\texttt{ff}_2)$\;

  \texttt{mask}\(_1\), \texttt{mask}\(_2\) — optional local-window masks\;
  \texttt{rope}\(_1\), \texttt{rope}\(_2\) — rotary position embeddings\;

  $\alpha_1,\alpha_2\in\{0,1\}$ — flags: use \emph{joint} attention for each branch
}
\KwOut{$x_1',\,x_2'$ — updated hidden states}

\BlankLine
\textbf{/* 1. Normalization \& gating coefficients */}\;
$(\hat{x}_1,\;g^{\text{msa}}_1,\;s^{\text{ff}}_1,\;e^{\text{ff}}_1,\;g^{\text{ff}}_1)
 \leftarrow B_1.\texttt{attn\_norm}(x_1, t_1)$\;
$(\hat{x}_2,\;g^{\text{msa}}_2,\;s^{\text{ff}}_2,\;e^{\text{ff}}_2,\;g^{\text{ff}}_2)
 \leftarrow B_2.\texttt{attn\_norm}(x_2, t_2)$\;

\BlankLine
\textbf{/* 2. Joint or independent multi-head attention */}\;
$(a_1,\,a_2)\leftarrow
    \textsc{JointAttention}(B_1.\texttt{attn},\,B_2.\texttt{attn},
    \hat{x}_1,\hat{x}_2,\texttt{mask}_1,\texttt{mask}_2,
    \texttt{rope}_1,\texttt{rope}_2,\alpha_1,\alpha_2)$\;

\BlankLine
\textbf{/* 3. Residual connection with MSA gating */}\;
$x_1 \leftarrow x_1 + g^{\text{msa}}_1 \odot a_1$\;
$x_2 \leftarrow x_2 + g^{\text{msa}}_2 \odot a_2$\;

\BlankLine
\textbf{/* 4. Feed-forward branch — stream 1 */}\;
$\tilde{x}_1 \leftarrow
  B_1.\texttt{ff\_norm}(x_1)\odot(1+e^{\text{ff}}_1)
  +s^{\text{ff}}_1$\;
$f_1 \leftarrow B_1.\texttt{ff}(\tilde{x}_1)$\;
$x_1 \leftarrow x_1 + g^{\text{ff}}_1 \odot f_1$\;

\BlankLine
\textbf{/* 5. Feed-forward branch — stream 2 */}\;
$\tilde{x}_2 \leftarrow
  B_2.\texttt{ff\_norm}(x_2)\odot(1+e^{\text{ff}}_2)
  +s^{\text{ff}}_2$\;
$f_2 \leftarrow B_2.\texttt{ff}(\tilde{x}_2)$\;
$x_2 \leftarrow x_2 + g^{\text{ff}}_2 \odot f_2$\;

\BlankLine
\Return $(x_1,\,x_2)$\;
\caption{\textbf{JointDiTBlock} — single block of a diffusion transformer operating on two sequences with optional joint cross-attention. Element-wise multiplication is denoted by \(\odot\).}
\label{alg:joint_dit_block}
\end{algorithm}

\begin{algorithm}[t]
\DontPrintSemicolon
\SetKwInput{KwIn}{Input}
\SetKwInput{KwOut}{Output}

\KwIn{
  Attention modules $\texttt{attn}_1$, $\texttt{attn}_2$ with $QKV$ projections\;
  Hidden states $x_1 \in \mathbb{R}^{B \times L_1 \times d}$, $x_2 \in \mathbb{R}^{B \times L_2 \times d}$\;
  Optional rotary embeddings: \texttt{rope}$_1$, \texttt{rope}$_2$\;
  Optional local window masks: \texttt{mask}$_1$, \texttt{mask}$_2$\;
  Joint attention flags: $\alpha_1, \alpha_2 \in \{0,1\}$
}
\KwOut{
  Attention outputs $o_1 \in \mathbb{R}^{B \times L_1 \times d}$, $o_2 \in \mathbb{R}^{B \times L_2 \times d}$
}

\BlankLine
\textbf{1. Project input to QKV:} \\
$(q_1, k_1, v_1) \gets \texttt{attn}_1.\textsc{toQKV}(x_1)$ \\
$(q_2, k_2, v_2) \gets \texttt{attn}_2.\textsc{toQKV}(x_2)$

\BlankLine
\textbf{2. Apply rotary embeddings (if provided):} \\
\If{\texttt{rope}$_1$ exists}{
  $(q_1, k_1) \gets \textsc{ApplyRoPE}(q_1, k_1, \texttt{rope}_1)$
}
\If{\texttt{rope}$_2$ exists}{
  $(q_2, k_2) \gets \textsc{ApplyRoPE}(q_2, k_2, \texttt{rope}_2)$
}

\BlankLine
\textbf{3. Construct joint token pools:} \\
\eIf{$\alpha_1 = 1$}{
  $q_1^\star \gets [q_1; q_2]$,\quad $k_1^\star \gets [k_1; k_2]$,\quad $v_1^\star \gets [v_1; v_2]$
}{
  $(q_1^\star, k_1^\star, v_1^\star) \gets (q_1, k_1, v_1)$
}

\eIf{$\alpha_2 = 1$}{
  $q_2^\star \gets [q_2; q_1]$,\quad $k_2^\star \gets [k_2; k_1]$,\quad $v_2^\star \gets [v_2; v_1]$
}{
  $(q_2^\star, k_2^\star, v_2^\star) \gets (q_2, k_2, v_2)$
}

\BlankLine
\textbf{4. Split heads and apply masks:} \\
$(q_1^\star, k_1^\star, v_1^\star) \gets \textsc{SplitHeads}(q_1^\star, k_1^\star, v_1^\star)$ \\
$(q_2^\star, k_2^\star, v_2^\star) \gets \textsc{SplitHeads}(q_2^\star, k_2^\star, v_2^\star)$

\BlankLine
\If{$\texttt{mask}_1 \neq \varnothing \wedge \alpha_1 = 1$}{
  $M_1 \gets \textsc{CustomDiagMask}(L_1, L_2, \texttt{mask}_1)$
}
\Else{
  $M_1 \gets \varnothing$
}

\If{$\texttt{mask}_2 \neq \varnothing \wedge \alpha_2 = 1$}{
  $M_2 \gets \textsc{CustomDiagMask}(L_2, L_1, \texttt{mask}_2)$
}
\Else{
  $M_2 \gets \varnothing$
}

\BlankLine
\textbf{5. Compute scaled dot-product attention:} \\
$o_1^\star \gets \textsc{SDPA}(q_1^\star, k_1^\star, v_1^\star, M_1)$ \\
$o_2^\star \gets \textsc{SDPA}(q_2^\star, k_2^\star, v_2^\star, M_2)$

\BlankLine
\textbf{6. Merge heads, trim to original length, and project:} \\
$o_1 \gets \textsc{MergeHeads}(o_1^\star)[:, :L_1]$,\quad $o_1 \gets \texttt{attn}_1.\textsc{outProj}(o_1)$ \\
$o_2 \gets \textsc{MergeHeads}(o_2^\star)[:, :L_2]$,\quad $o_2 \gets \texttt{attn}_2.\textsc{outProj}(o_2)$

\BlankLine
\Return $(o_1, o_2)$

\caption{\textbf{JointAttention} – Multi-head attention with optional joint token pooling.  
Concatenation $[\,\cdot\,; \cdot\,]$ is along the sequence dimension.  
\textsc{SDPA} denotes scaled dot-product attention.  
\textsc{CustomDiagMask} is a full+diagonal window mask, illustrated in Fig.~\ref{fig:architecture}.}
\label{alg:joint_attention}
\end{algorithm}

