\section*{Appendix}
The pseudocode for the sparsity-promoting dynamic mode decomposition (SPDMD) algorithm is provided below, and the associated MATLAB implementation is also included in the above repository.
% on \href{https://github.com/zc-zhang/Transient-Weather-Modes-SPDMD}{GitHub}.
% \begin{center}
%     \url{https://github.com/zc-zhang/Transient-Weather-Modes-SPDMD}.
% \end{center}
\begin{algorithm}[H]
\caption{Sparsity-Promoting DMD (SPDMD Algorithm) \cite{jovanovic2014sparsity}}
\label{algo:spdmd}
\begin{algorithmic}[1]
\Require Snapshot matrix \text{Data}, sparse weight $\gamma$ with $\gamma_{\min}$, $\gamma_{\max}$, $\gamma_{\texttt{grids}}$, parameters $\rho$, snapshot $N$, convergence tolerances $\epsilon_{\text{primal}}$, $\epsilon_{\text{dual}}$, ADMM iterations $k_{\text{max}}$
\Ensure Sparse amplitudes $\bfb_{r}$, Koopman modes ${\bm\Phi}_r$, Performance losses ${J}_{\text{sp}}$, ${J}_{\text{pol}}$, ${J}_{\text{loss}}$
\State $\bfY \gets \text{Data}(:, 1:N-1)$, $\bfY' \gets \text{Data}(:, 2:N)$ 
\Comment{Split data in Eq.~\eqref{eq:separate-data-Y}}
\State $\bfU$, $\bmSigma$, ${\bfV}^{\ast} \gets \mathtt{svd}(\bfY)$ \Comment{Perform SVD}
\State $r \gets \mathrm{rank}(\bmSigma)$ \Comment{Determine rank}
\State ${\bfU}_r \gets {\bfU}(:, 1:r)$, ${\bmSigma}_r \gets {\bmSigma}(1:r, 1:r)$, ${\bfV}_r \gets {\bfV}(:, 1:r)$ 
\Comment{Truncate}
\State $\tilde{\bfA} \gets \bfU_{r}^{\ast} \bfY^{\prime} \bfV_{r} \bmSigma_{r}^{-1}$ 
\Comment{Reduced-order matrix in Eq.~\eqref{eq:decomposition-tilde_A}}
\State $W$, $\bmLambda \gets \mathtt{eig}\big(\tilde{\bfA}\big)$ \Comment{Eigenvalues, eigenvectors}
\State ${\bm\Phi}_r \gets {\bfU}_r W$ 
\Comment{DMD modes}
\For{$i = 1$ to $N$} \Comment{Vandermonde matrix}
    \State $\bfT_r(:, i) \gets \operatorname{diag}(\bmLambda)^{i-1}$ 
    %\Comment{Column of eigenvalue powers $[\lambda_1^{i-1}, \dots, \lambda_r^{i-1}]^\top$}
\EndFor
\State $\mathbf{L} \gets {\bfU}_r\bfW, \mathbf{R} \gets \bfT_r, \mathbf{G} \gets {\bmSigma}_r{\bfV}_{r}^\top$ 
\Comment{Optimization variablies}
\State $\mathbf{P} \gets \mathbf{L}^{\top} \mathbf{L} \cdot \mathtt{conj}(\mathbf{R} \mathbf{R}^{\top})$, $\mathbf{d} \gets \operatorname{conj}\big(\operatorname{diag}(\mathbf{R} \mathbf{G}^{\top} \mathbf{L})\big)$, $\eta \gets \operatorname{trace}(\mathbf{G}^{\top} \mathbf{G})$ 
\Comment{QP in~\eqref{eq:QP-closed-form-solution}}
\State $\mathbf{P}_{\mathrm{chol}} \gets \operatorname{chol}(\mathbf{P})$ 
\Comment{Cholesky factorization}
\State $\bfb_{\text{init}} \gets \mathbf{P}_{\mathrm{chol}}^{-\top}\big(\mathbf{P}_{\mathrm{chol}}^{-1} \mathbf{d}\big)$ 
\Comment{Non-sparse amplitudes}
\State ${\bm\theta} \gets 0$, ${\bm\xi} \gets 0$, $k \gets 0$ 
\Comment{Initialize ADMM}
\State $\hat{\bm\xi}_{\text{prev}} \gets 0$ \Comment{Store previous $\hat{\bm\xi}$ for dual residual}
\While{$k < k_{\text{max}}$ and not converged} \Comment{Sparse optimization via ADMM}
    \State $\widehat{\bfb} \gets \left(\mathbf{L}^\top \mathbf{L} + \rho \bfI\right)^{-1} \left(\mathbf{L}^\top \mathbf{G} + \rho {\bm\xi} - {\bm\theta}\right)$ \Comment{Update amplitudes $\bfb$}
    %(approximates $\mathrm{L} \operatorname{diag}(\bfb) \mathrm{R} \approx \mathrm{L} \bfb$)
    \State $\hat{\bm\xi} \gets \operatorname{shrinkage}\left(\widehat{\bfb} + \frac{1}{\rho}{\bm\theta}, \frac{\gamma}{\rho}\right)$ 
    \Comment{Soft-thresholding for sparsity}
    \State ${\bm\theta} \gets {\bm\theta} + \rho \left(\widehat{\bfb} - \hat{\bm\xi}\right)$ 
    %\Comment{Update dual variable}
    \State Check $\left\|\widehat{\bfb} - \hat{\bm\xi}\right\|_2 \leq \epsilon_{\text{primal}}$, $\left\|\rho \left(\hat{\bm\xi} - \hat{\bm\xi}_{\text{prev}}\right)\right\|_2 \leq \epsilon_{\text{dual}}$ 
    %\Comment{Convergence check}
    \State $\hat{\bm\xi}_{\text{prev}} \gets \hat{\mathbf{z}}$, $k \gets k + 1$ 
    %\Comment{Update previous $\hat{\mathrm{z}}$ and counter}
\EndWhile
\State $\bfb_{r} \gets \hat{\bm\xi}$ 
\Comment{Set sparse amplitudes}
\State $\mathcal{S}^{c} \gets \operatorname{find}\big(\hat{\bm\xi} = 0\big)$ \Comment{Identify zero amplitudes}
\State Solve $\min_{\bfb_{\text{pol}}} \|\mathbf{G} - \mathbf{L} \operatorname{diag}(\bfb_{\text{pol}}) \mathbf{R}\|_{\text{F}}^2$ over non-zero indices in $\mathcal{S}^{c}$ \Comment{Polishing step}
\State ${J}_{\text{sp}} \gets \|\mathbf{G} - \mathrm{L} \operatorname{diag}(\bfb_r) \mathbf{R}\|_{\text{F}}^2$ \Comment{Performance losses}
\State ${J}_{\text{pol}} \gets \|\mathbf{G} - \mathbf{L} \operatorname{diag}(\bfb_{\text{pol}}) \mathbf{R}\|_{\text{F}}^2$
\State $\widehat{\mathbf{G}} \gets \operatorname{trace}(\mathbf{G}^\top \mathbf{G})$
\State ${J}_{\text{loss}} \gets 100 \sqrt{{J}_{\text{sp}} / \widehat{\mathbf{G}}}$ \Comment{Relative loss in percentage}

\State \Return $\bfb_r$, $\bm\Phi_r$, ${J}_{\text{sp}}$, ${J}_{\text{pol}}$, ${J}_{\text{loss}}$
\end{algorithmic}
\end{algorithm}
